typedef struct {
    int value;
} record;

void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

int main() {
    int max_size = 1000000; // predefined maximum size threshold
    int num_records = 10000;
    int min_value = 1, max_value = 100;

    record *records = NULL;
    long *offsets = NULL;
    int *keys = NULL;

    int total_allocated = 0;

    records = my_malloc(num_records * sizeof(record));
    if (records == NULL) return -1;

    offsets = my_malloc(2 * sizeof(long)); // two arrays
    if (offsets == NULL) {
        my_free(records);
        return -1;
    }

    keys = my_malloc(2 * sizeof(int));
    if (keys == NULL) {
        my_free(records);
        my_free(offsets);
        return -1;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    printf("Total allocated memory: %zu\n", total_allocated);

    // free all allocated memory
    my_free(keys);
    my_free(offsets);
    my_free(records);

    return 0;
}
