#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FILE_NAME 256
#define DEFAULT_OUTPUT_FILE "output.txt"

typedef struct {
    int line_count;
    double average_word_length;
    char *longest_line;
} file_stats_t;

void* process_file(void* args) {
    file_stats_t* stats = (file_stats_t*)args;
    FILE* file = fopen((char*)args, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    int line_count = 0;
    double total_word_length = 0.0;
    char longest_line[MAX_LINE_LENGTH];

    for (int i = 0; i < MAX_LINE_LENGTH; ++i) longest_line[i] = '\0';
    longest_line[MAX_LINE_LENGTH - 1] = '\0';

    while (fscanf(file, "%1023s", longest_line) == 1) {
        int word_count = 1;
        double line_word_length = strlen(longest_line);
        total_word_length += line_word_length;

        for (char* p = strtok(longest_line, " "); p; p = strtok(NULL, " ")) {
            if (strlen(p) > line_word_length) line_word_length = strlen(p);
            ++word_count;
        }

        stats->line_count++;
        total_word_length /= word_count;
    }

    fclose(file);
    stats->average_word_length = total_word_length;
    stats->longest_line = strdup(longest_line);

    return NULL;
}

int main(int argc, char* argv[]) {
    int c;
    file_stats_t stats;
    FILE* output_file = NULL;
    pthread_t thread;

    while ((c = getopt(argc, argv, "o:--manpage")) != -1) {
        switch (c) {
            case 'o':
                output_file = fopen(optarg, "w");
                if (!output_file) {
                    perror("Error opening output file");
                    return 1;
                }
                break;
            case '--manpage':
                printf("#!/usr/bin/man\n"
                       "#FORMAT std\n"
                       "#NAME process-file\n"
                       "#DESCRIPTION This program parses command line arguments and provides detailed usage information if no input file is provided.\n"
                       "#It reads the specified input file line by line, counts the number of lines, calculates the average word length for each line,\n"
                       "#identifies and reports the longest line based on character count, allows users to specify an output file to save the results using the '-o' option,\n"
                       "#and provides a comprehensive man page with detailed usage information.\n"
                       "#VERSION 1.0\n"
                       "#SEE ALSO process-file(1)\n");
                return 0;
            default:
                break;
        }
    }

    if (argc < 2) {
        fprintf(stderr, "Usage: %s [options] <input_file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    for (int i = 1; i < argc; ++i) {
        char* file_name = argv[i];

        if (access(file_name, F_OK | R_OK) != -1) {
            pthread_create(&thread, NULL, process_file, file_name);
            pthread_join(thread, NULL);

            if (!output_file) {
                printf("Lines: %d\n", stats.line_count);
                printf("Average word length: %.2f\n", stats.average_word_length);
                printf("Longest line: %s\n", stats.longest_line);
            } else {
                fprintf(output_file, "Lines: %d\n", stats.line_count);
                fprintf(output_file, "Average word length: %.2f\n", stats.average_word_length);
                fprintf(output_file, "Longest line: %s\n", stats.longest_line);
            }
        } else {
            perror("Error opening file");
            return 1;
        }
    }

    if (output_file) fclose(output_file);

    return 0;
}
