#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void process_log_file(const char* input_file_name, const char* output_file_name,
                       const char* filter_criteria, int include_timestamps) {
    FILE *input_file = fopen(input_file_name, "r");
    if (input_file == NULL) {
        printf("Error opening input file.\n");
        return;
    }

    FILE *output_file = fopen(output_file_name, "w");
    if (output_file == NULL) {
        printf("Error opening output file.\n");
        fclose(input_file);
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), input_file)) {
        // Process the line based on the filter criteria
        // For simplicity, assume a simple string match for now
        if (strstr(line, filter_criteria) != NULL) {
            fprintf(output_file, "%s", line);
            if (include_timestamps) {
                // Add timestamp to the output line
                time_t current_time = time(NULL);
                struct tm* current_tm = localtime(&current_time);
                char timestamp_str[32];
                strftime(timestamp_str, sizeof(timestamp_str), "[%Y-%m-%d %H:%M:%S]", current_tm);
                fprintf(output_file, "%s", timestamp_str);
            }
        }
    }

    fclose(input_file);
    fclose(output_file);
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        printf("Usage: %s <input_file> <output_file> <filter_criteria> <include_timestamps>\n", argv[0]);
        return 1;
    }

    process_log_file(argv[1], argv[2], argv[3], atoi(argv[4]));

    return 0;
}
