#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/time.h>
#include <pthread.h>

#define DNS_QUERY_RATE 10 // maximum DNS queries per minute
#define MAX_CACHE_SIZE 1000 // maximum cache size in entries
#define LOG_FILE "dns.log" // log file name

typedef struct {
    char hostname[256];
    struct in_addr ip;
    time_t expires_at; // cache expiration timestamp
} CacheEntry;

CacheEntry* cache = NULL; // DNS cache
int cache_size = 0; // current cache size
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER; // cache lock

// rate limiting variables
time_t last_query_time = 0; // last DNS query timestamp
int queries_made = 0; // number of DNS queries made this minute

void log_dns_resolution(const char* hostname, int success) {
    FILE* file = fopen(LOG_FILE, "a");
    if (!file) return;

    time_t now = time(NULL);
    fprintf(file, "[%ld] ", now);
    if (success) printf("SUCCESS: "); else printf("FAILURE: ");
    fwrite(hostname, 1, strlen(hostname), file);
    fclose(file);
}

int get_ip_address(const char* hostname, u_char* ip_addr) {
    // check rate limiting
    time_t current_time = time(NULL);
    int elapsed_minutes = (current_time - last_query_time) / 60;
    if (elapsed_minutes > 0) {
        queries_made = 0; // reset query count for new minute
        last_query_time = current_time; // update last query timestamp
    }

    pthread_mutex_lock(&cache_lock);
    int found_in_cache = 0;
    CacheEntry* entry = cache;
    while (entry && !found_in_cache) {
        if (!strcmp(entry->hostname, hostname)) {
            found_in_cache = 1;
            struct in_addr* ip_ptr = &entry->ip;
            memcpy(ip_addr, &(char*)&(*ip_ptr), sizeof(struct in_addr));
            entry->expires_at = current_time + 60; // refresh cache expiration
        }
        entry++;
    }

    if (!found_in_cache) {
        // perform DNS query
        int s = socket(AF_INET, SOCK_DGRAM, 0);
        if (s < 0) return -1;

        struct sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(53);

        inet_pton(AF_INET, "8.8.8.8", &(server_addr.sin_addr));
        sendto(s, hostname, strlen(hostname), 0, (struct sockaddr*)&server_addr, sizeof(server_addr));

        struct sockaddr_in from_addr;
        socklen_t from_len = sizeof(from_addr);
        int result = recvfrom(s, ip_addr, 4, 0, (struct sockaddr*)&from_addr, &from_len);

        close(s);
        if (result < 0) return -1; // DNS query failed

        pthread_mutex_unlock(&cache_lock); // release cache lock before updating cache
        CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
        strcpy(new_entry->hostname, hostname);
        memcpy(&new_entry->ip, ip_addr, sizeof(struct in_addr));
        new_entry->expires_at = current_time + 60; // set cache expiration

        pthread_mutex_lock(&cache_lock); // re-acquire cache lock
        if (cache_size < MAX_CACHE_SIZE) {
            cache[cache_size++] = *new_entry;
        } else {
            // cache full, remove oldest entry and add new one
            CacheEntry* old_entry = &cache[0];
            for (int i = 1; i < cache_size; i++) {
                old_entry = &cache[i];
            }
            free(old_entry);
            cache[--cache_size] = *new_entry;
        }

        pthread_mutex_unlock(&cache_lock); // release cache lock
    } else {
        pthread_mutex_unlock(&cache_lock); // release cache lock
    }

    return found_in_cache ? 0 : -1; // success or failure indication
}

