#include <stdio.h>
#include <stdlib.h>

void readIntegers(int* arr, int maxSize) {
    for (int i = 0; i < maxSize; i++) {
        scanf("%d", &arr[i]);
    }
}

void findLargest(int* arr, int size) {
    int maxVal = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > maxVal) {
            maxVal = arr[i];
        }
    }
    printf("Largest integer: %d\n", maxVal);
}

int main() {
    int maxSize = 10;
    int* arr = malloc(maxSize * sizeof(int));

    readIntegers(arr, maxSize);

    int size = 0;
    while (size < maxSize && scanf("%d", &arr[size]) == 1) {
        size++;
    }

    if (size >= maxSize) {
        arr = realloc(arr, size * sizeof(int));
    }

    findLargest(arr, size);

    free(arr);
    return 0;
}
