#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <string.h>

#define LOG_LEVELS 4
#define LOG_RATE 100 // log every 100 milliseconds

int log_level = 0; // current log level (debug, info, warning, error)
sem_t *log_sem; // semaphore for logging rate control

void set_log_level(int level) {
    if(level >= 0 && level < LOG_LEVELS) {
        log_level = level;
    }
}

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    if(log_level > 0 || (log_level == 0 && log_sem != NULL)) {
        // acquire lock for logging rate control
        sem_wait(log_sem);

        int buffer_len = sprintf(NULL, "LOG: %s", format) + 1; // get the length of the formatted string
        char *buffer = malloc(buffer_len);
        if(buffer) {
            vsnprintf(buffer, buffer_len, format, args);
            FILE *log_file = fopen("error_log.txt", "a");
            if(log_file) {
                fwrite(buffer, sizeof(char), strlen(buffer), log_file);
                fclose(log_file);
            }
            free(buffer);
        }

        // release lock for logging rate control
        sem_post(log_sem);
    }

    va_end(args);
}

void init_logging() {
    log_level = 0; // default log level is info
    log_sem = sem_open("/log-sem", O_CREAT, S_IRUSR | S_IWUSR, LOG_RATE);
    if(log_sem == SEM_FAILED) {
        perror("sem_open");
        exit(EXIT_FAILURE);
    }
}

void fini_logging() {
    sem_close(log_sem);
}
