bool validate_oauth2_token(const char *json_string) {
    json_object *token = json_object_from_string(json_string);

    if (!token || json_object_object_get_ex(token, "access_token", NULL) ||
       !json_object_object_get_ex(token, "expires_in", NULL) ||
       !json_object_object_get_ex(token, "token_type", NULL)) {
        return false;
    }

    char *token_type = json_object_get_string(json_object_object_get(token, "token_type"));
    int expires_in = json_object_get_int(json_object_object_get(token, "expires_in"));

    if (strcmp(token_type, "Bearer") != 0 || expires_in <= 0) {
        return false;
    }

    char *refresh_token = json_object_get_string(json_object_object_get(token, "refresh_token"));

    if (refresh_token && strlen(refresh_token) > 0)
        ; // You can add validation for the refresh token here
    else
        return true;

    json_object_put(token);
    return true;
}

