import java.util.logging.Logger;
import com.example.pokemonlibrary.Pokemon;

public class PokemonReporter {

    private static final Logger logger = Logger.getLogger(PokemonReporter.class.getName());

    public String reportPokemon(Pokemon pokemon) {
        if (pokemon == null || pokemon.getType() == null) {
            return "Invalid input. Please provide a valid Pokémon object.";
        }

        String report = "Name: " + getProductName(pokemon) + "\n";
        report += "Type: " + pokemon.getType().name() + "\n";

        report += determineWeaknessesAndResistances(pokemon);

        return report;
    }

    private String determineWeaknessesAndResistances(Pokemon pokemon) {
        StringBuilder report = new StringBuilder();
        switch (pokemon.getType()) {
            case FIRE:
                report.append("Weak against: Water, Rock\n");
                report.append("Resistant to: Bug, Steel\n");
                report.append("Advantage against: Grass, Ice\n");
                break;
            case WATER:
                report.append("Weak against: Electric, Grass\n");
                report.append("Resistant to: Fire, Steel\n");
                report.append("Advantage against: Fire, Water\n");
                break;
            // Add more cases for other types
        }
        return report.toString();
    }

    private String getProductName(Pokemon pokemon) {
        try {
            return pokemon.getName();
        } catch (Exception e) {
            logger.severe("Error fetching product name. Using fallback information.");
            return "Unknown";
        }
    }
}
