#include <semaphore.h>
#include <pthread.h>

typedef struct {
    int *data;
    int front;
    int rear;
    int capacity;
    sem_t empty;
    sem_t full;
} Queue;

void initQueue(Queue *q, int capacity) {
    q->capacity = capacity;
    q->data = (int *)malloc(capacity * sizeof(int));
    q->front = 0;
    q->rear = 0;
    sem_init(&q->empty, 0, capacity);
    sem_init(&q->full, 0, 0);
}

void enqueue(Queue *q, int item) {
    sem_wait(&q->full);
    q->data[q->rear] = item;
    if ((q->rear + 1) % q->capacity == q->front)
        sem_post(&q->empty);
    else
        q->rear = (q->rear + 1) % q->capacity;
    sem_post(&q->full);
}

int dequeue(Queue *q) {
    int item;
    sem_wait(&q->empty);
    item = q->data[q->front];
    if ((q->front + 1) % q->capacity == q->rear)
        sem_post(&q->full);
    else
        q->front = (q->front + 1) % q->capacity;
    sem_post(&q->empty);
    return item;
}

void destroyQueue(Queue *q) {
    free(q->data);
    sem_destroy(&q->empty);
    sem_destroy(&q->full);
}
