#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <iostream>

class SandeshClient {
public:
    SandeshClient(boost::asio::io_service& io_service)
        : client_(io_service),
          stats_() {}

    void send_request(const std::string& url, int num_retries = 3) {
        boost::asio::deadline_timer timer(client_.io_service(), 
                                            boost::posix_time::milliseconds(1000));
        timer.async_wait([this, &url, num_retries](const boost::system::error_code& ec) {
            if (!ec) {
                make_request(url);
            } else if (num_retries > 0) {
                send_request(url, --num_retries);
            }
        });
    }

private:
    void make_request(const std::string& url) {
        boost::asio::ip::tcp::resolver resolver(client_.io_service());
        boost::asio::ip::tcp::endpoint endpoint = *resolver.resolve(url, "https");
        boost::asio::ip::tcp::streamsocket stream_socket = client_.connect(endpoint);

        boost::asio::write(stream_socket, "GET / HTTP/1.0\r\nHost: example.com\r\n\r\n");

        boost::asio::deadline_timer timer(client_.io_service(), 
                                            boost::posix_time::milliseconds(500));
        timer.async_wait([this](const boost::system::error_code& ec) {
            if (!ec) {
                stats_.successful_requests++;
            } else {
                if (ec == boost::asio::errc::timed_out) {
                    stats_.failed_requests++;
                } else {
                    stats_.internal_errors++;
                }
            }
        });
    }

    boost::asio::io_service client_;
    struct RequestStats {
        int successful_requests = 0;
        int failed_requests = 0;
        int internal_errors = 0;
    } stats_;
};

int main() {
    boost::asio::io_service io_service;
    SandeshClient client(io_service);

    for (int i = 0; i < 10; ++i) {
        client.send_request("example.com");
    }

    boost::this_thread::sleep_for(boost::chrono::seconds(1));

    std::cout << "Total requests: " << 10 << "\n";
    std::cout << "Successful requests: " << client.stats_.successful_requests << "\n";
    std::cout << "Failed requests due to timeouts: " << client.stats_.failed_requests << "\n";
    std::cout << "Internal errors: " << client.stats_.internal_errors << "\n";

    return 0;
}
