using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class AsyncHttpClient
{
    public static List<Task<HttpResponseMessage>> ProcessRequests(List<string> requests, int connectionTimeout, int maxConcurrencyLevel)
    {
        var tasks = new List<Task<HttpResponseMessage>>();
        var threadPool = new LimitedConcurrencyLevelTaskScheduler(maxConcurrencyLevel);
        var httpClient = new HttpClient { Timeout = TimeSpan.FromMilliseconds(connectionTimeout) };

        foreach (var request in requests)
        {
            Task<HttpResponseMessage> task;
            try
            {
                task = Task.Run(() => MakeRequestAsync(httpClient, request));
            }
            catch (Exception ex)
            {
                // Handle exception and provide feedback on the completion status of each request
                Console.WriteLine($"Error processing {request}: {ex.Message}");
                continue;
            }

            tasks.Add(task);
        }

        return tasks;
    }

    private static async Task<HttpResponseMessage> MakeRequestAsync(HttpClient client, string request)
    {
        using (var response = await client.GetAsync(request))
        {
            response.EnsureSuccessStatusCode();
            // Process the response as needed
            Console.WriteLine($"Completed {request} successfully");
            return response;
        }
    }
}
