public class MapLoader
{
    private readonly HttpClient _httpClient;
    private readonly JsonSerializer _serializer;
    private readonly string _mapApiUrl;
    private readonly int _tileResolution;
    private readonly int _zoomLevel;
    private readonly float _panningSensitivity;

    public MapLoader(string configFilePath)
    {
        _httpClient = new HttpClient();
        _serializer = JsonSerializer.Create();

        var config = JsonConvert.DeserializeObject<MapConfig>(File.ReadAllText(configFilePath));

        _mapApiUrl = config.MapApiUrl;
        _tileResolution = config.TileResolution;
        _zoomLevel = config.ZoomLevel;
        _panningSensitivity = config.PanningSensitivity;
    }

    public void LoadTerrainData(IGameEngine gameEngine)
    {
        try
        {
            var response = _httpClient.GetAsync(_mapApiUrl).Result;

            if (response.IsSuccessStatusCode)
            {
                var terrainData = response.Content.ReadAsJsonAsync<TerrainData>().Result;

                // Process terrain data and load into the game engine
                foreach (var tile in terrainData.Tiles)
                {
                    gameEngine.LoadTerrainTile(tile.X, tile.Y, tile.Heightmap);
                }
            }
            else
            {
                Console.WriteLine($"Failed to retrieve terrain data: {response.StatusCode}");
            }
        }
        catch (HttpRequestException ex)
        {
            Console.WriteLine("Network failure: " + ex.Message);
        }
    }

    public void LoadCachedTerrainData(IGameEngine gameEngine)
    {
        var cachedTerrainData = File.ReadAllText("terrain_data.json");

        if (!string.IsNullOrEmpty(cachedTerrainData))
        {
            var data = JsonConvert.DeserializeObject<TerrainData>(cachedTerrainData);

            // Process terrain data and load into the game engine
            foreach (var tile in data.Tiles)
            {
                gameEngine.LoadTerrainTile(tile.X, tile.Y, tile.Heightmap);
            }
        }
    }
}

public class MapConfig
{
    public string MapApiUrl { get; set; }
    public int TileResolution { get; set; }
    public int ZoomLevel { get; set; }
    public float PanningSensitivity { get; set; }
}

public class TerrainData
{
    public int TileCount { get; set; }
    public List<TerrainTile> Tiles { get; set; }
}

public class TerrainTile
{
    public int X { get; set; }
    public int Y { get; set; }
    public byte[] Heightmap { get; set; }
}
