using System;
using System.Collections.Generic;
using System.Xml.XPath;

public class XmlParser
{
    public List<XElement> ParseXml(string xml, string nodeName, int maxExecutionTime)
    {
        XPathDocument doc = new XPathDocument(new StringReader(xml));
        XPathNavigator nav = doc.CreateNavigator();

        nav.PreserveWhitespace = true;
        XPathExpression expression = nav.Compile("//" + nodeName);
        XPathNodeIterator iterator = nav.Select(expression);

        List<XElement> elements = new List<XElement>();

        Stopwatch timer = new Stopwatch();
        timer.Start();

        while (iterator.MoveNext())
        {
            XElement element = new XElement(iterator.Current.Name);
            XPathNavigator childNav = iterator.Current.MoveToFirstChild();

            while (childNav.MoveToNextAttribute())
            {
                if (childNav.Name.NamespaceURI.Length > 0)
                    element.Add(new XAttribute(childNav.LocalName, childNav.Value));
                else
                    element.Add(new XAttribute(childNav.Name, childNav.Value));
            }

            while (childNav.MoveToFirstChild())
            {
                XElement childElement = new XElement(childNav.Name);

                while (childNav.MoveToNextAttribute())
                {
                    if (childNav.Name.NamespaceURI.Length > 0)
                        childElement.Add(new XAttribute(childNav.LocalName, childNav.Value));
                    else
                        childElement.Add(new XAttribute(childNav.Name, childNav.Value));
                }

                while (childNav.MoveToFirstChild())
                {
                    XElement grandChildElement = new XElement(childNav.Name);

                    while (childNav.MoveToNextAttribute())
                    {
                        if (childNav.Name.NamespaceURI.Length > 0)
                            grandChildElement.Add(new XAttribute(childNav.LocalName, childNav.Value));
                        else
                            grandChildElement.Add(new XAttribute(childNav.Name, childNav.Value));
                    }

                    childElement.Add(grandChildElement);
                }

                element.Add(childElement);
            }

            elements.Add(element);
        }

        timer.Stop();

        if (elements.Count == 0)
            throw new Exception("No elements found with the given name.");

        return elements;
    }
}
