import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class StringProcessor {

    public Map<String, String> processStrings(List<String> stringList) {
        Map<String, String> result = new HashMap<>();
        MessageDigest md5 = null;
        try {
            md5 = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            // Handle exception
        }

        for (String s : stringList) {
            if (s.trim().isEmpty() || isNonPrintable(s)) {
                continue; // skip non-printable or whitespace strings
            }
            byte[] bytes = s.getBytes();
            try {
                md5.update(bytes);
                String md5Hash = bytesToHex(md5.digest());
                result.put(md5Hash, s);
            } catch (IOException e) {
                // Handle exception
            }
        }
        return result;
    }

    private boolean isNonPrintable(String s) {
        for (char c : s.toCharArray()) {
            if (!Character.isLetterOrDigit(c) && !Character.isWhitespace(c)) {
                return true; // non-printable character found
            }
        }
        return false; // no non-printable characters found
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            result.append(String.format("%02x", b));
        }
        return result.toString();
    }
}
