public class StateLoader {
    private static final String[] ALLOWED_DIRECTORIES = {"directory1", "directory2"};
    private static final int MAX_CACHE_SIZE = 100;
    private static Map<String, MoSTState> cache = new LinkedHashMap<>();
    private static Logger logger = LoggerFactory.getLogger(StateLoader.class);

    public MoSTState loadState(String filePath) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
            File file = new File(filePath);
            if (!isValidDirectory(file.getParentFile().getPath())) {
                return null;
            }
            MoSTState state = (MoSTState) ois.readObject();
            long checksum = getChecksumFromMetadata(file);
            if (state instanceof MoSTState && checksum == state.getChecksum()) {
                return state;
            } else {
                logger.error("Invalid state object or mismatched checksum");
                return null;
            }
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Error loading state", e);
            return null;
        }
    }

    private boolean isValidDirectory(String directoryPath) {
        for (String allowedDir : ALLOWED_DIRECTORIES) {
            if (directoryPath.startsWith(allowedDir)) {
                return true;
            }
        }
        return false;
    }

