function asyncReadFiles(dirPath, fileExtensions, maxBytes) {
  const files = [];
  let bytesRead = 0;

  return new Promise((resolve, reject) => {
    fs.readdir(dirPath, (err, fileNames) => {
      if (err) reject(err);
      else {
        fileNames.forEach((fileName) => {
          const filePath = path.join(dirPath, fileName);
          fs.stat(filePath, (err, stats) => {
            if (err) reject(err);
            else {
              const isMatchedExtension = fileExtensions.some((ext) =>
                path.extname(fileName).toLowerCase().includes(ext.toLowerCase())
              );
              if (isMatchedExtension && bytesRead + stats.size <= maxBytes) {
                fs.readFile(filePath, 'utf8', (err, content) => {
                  if (err) reject(err);
                  else {
                    files.push({ fileName, content });
                    bytesRead += stats.size;
                  }
                });
              } else {
                // File not matched or exceeded the byte limit
              }
            }
          });
        });
      }
    }).then(() => resolve(files));
  });
}
