function runModuleTests(moduleName, testCases, setupFunction) {
  let testResults = [];
  let moduleInstance = null;

  try {
    setupFunction();

    for (const testCase of testCases) {
      console.log(`Running test case ${testCase.name} for module ${moduleName}`);

      try {
        require(moduleName);

        const startTime = new Date().getTime();
        const result = testCase();

        if (result instanceof Promise) {
          await result;
        }

        const endTime = new Date().getTime();
        const executionTime = endTime - startTime;

        if (executionTime > 5000) {
          throw new Error(`Test case ${testCase.name} timed out after 5 seconds`);
        }

        testResults.push({ name: testCase.name, outcome: result ? 'pass' : 'fail' });
      } catch (error) {
        console.error(`Error running test case ${testCase.name}:`, error);
        testResults.push({ name: testCase.name, outcome: 'fail' });
      } finally {
        blueslip.reset();
      }
    }
  } catch (error) {
    if (error.name === 'ReferenceError') {
      // Handle setup failure
      console.error(`Setup failed for module ${moduleName}:`, error);
    } else {
      throw error;
    }
  } finally {
    blueslip.reset();
  }

  return { allPassed: testResults.every(result => result.outcome === 'pass'), results: testResults };
}
