  for (const widget of widgets) {
    const id = `widget-${widget.id}`;
    const config = widget.config || {};
    html += `
      <div class="widget" id="${id}">
        ${widget.component}
      </div>
    `;
  }

  // Dynamic layout adjustment based on number of widgets
  if (widgets.length > 1) {
    html = `<div class="sidebar">${html}</div>`;
    for (let i = 0; i < widgets.length; i++) {
      const widgetDiv = document.getElementById(`widget-${widgets[i].id}`);
      widgetDiv.style.gridRow = `${i + 1} / ${widgets.length}`;
    }
  } else {
    html = `<div class="single-widget">${html}</div>`;
  }

  return html;
}
