function collectAndSimulateGraph(dataStream) {
  let vertices = [];
  let edges = [];
  let paused = false;

  function collectData() {
    if (paused) return;

    const vertexData = dataStream.next();
    if (!vertexData) return;

    const { id, properties } = vertexData;
    vertices.push({ id, properties });

    for (const edge of dataStream.edges()) {
      edges.push({
        from: edge.from,
        to: edge.to,
        properties: edge.properties
      });
    }
  }

  function resume() {
    paused = false;
    collectData();
  }

  function pause() {
    paused = true;
  }

  function finalizeGraph() {
    const graph = new Graph();

    for (const vertex of vertices) {
      graph.addVertex(vertex.id, JSON.stringify(vertex.properties));
    }

    for (const edge of edges) {
      graph.addEdge(edge.from, edge.to, JSON.stringify(edge.properties));
    }
  }

  dataStream.on('data', collectData);
  dataStream.on('end', finalizeGraph);
}
