['```
function copyBufferedData(chunks, bytesToCopy) {
  const buffers = [];
  let bytesRead = 0;
  let totalBytesAvailable = 0;

  for (const chunk of chunks) {
    totalBytesAvailable += chunk.length;
  }

  const bytesCopied = Math.min(bytesToCopy, totalBytesAvailable);
  let copiedBuffer = Buffer.alloc(Math.min(bytesCopied, bytesToCopy));

  for (let i = 0; i < chunks.length; i++) {
    const chunk = chunks[i];
    if (bytesRead + chunk.length <= bytesCopied) {
      chunk.copy(copiedBuffer, bytesRead, bytesRead + chunk.length);
      buffers.push({ chunk: chunk, bytesRead: bytesRead + chunk.length });
      bytesRead += chunk.length;
    } else {
      const remainingBytes = bytesCopied - bytesRead;
      chunk.copy(copiedBuffer, bytesRead, bytesRead + remainingBytes);
      buffers.push({ chunk: chunk, bytesRead: bytesRead + remainingBytes });
      break;
    }
  }

  if (bytesRead < bytesCopied) {
    return null;
  }

  let logEnabled = false;

  for (const bufferData of buffers) {
    if (logEnabled) {
      console.log(`Copied data from chunk at position ${bufferData.bytesRead} to ${bufferData.bytesRead + bufferData.chunk.length}`);
    }
  }

  return copiedBuffer;
}
