function paginate(selector, container, pageSize) {
  const elements = Array.from(container.querySelectorAll(selector));
  let currentPage = 0;
  let pages = Math.ceil(elements.length / pageSize);

  const loadMoreElements = () => {
    if (currentPage >= pages - 1) return;
    const start = currentPage * pageSize;
    const end = (currentPage + 1) * pageSize;
    const newElements = elements.slice(start, end);
    container.appendChild(...newElements.map((element) => element.cloneNode(true)));
    currentPage++;
  };

  const handleScroll = () => {
    const scrollPosition = container.scrollTop + container.offsetHeight;
    if (scrollPosition >= elements.length * pageSize) {
      loadMoreElements();
    }
  };

  container.addEventListener("scroll", handleScroll);

  return { loadMoreElements, currentPage };
}
