const fs = require('fs');
const path = require('path');

class ScriptLoader {
  constructor() {
    this.scripts = {};
    this.dependencies = [];
  }

  loadScript(script, callback) {
    const scriptPath = path.resolve(__dirname, `../scripts/${script}.js`);
    fs.stat(scriptPath, (err, stats) => {
      if (err || !stats.isFile()) {
        return callback(new Error(`File not found: ${script}`));
      }
      this.dependencies.push(script);
      this.loadScriptDependencies(script, callback);
    });
  }

  loadScriptDependencies(script, callback) {
    const dependencies = this.scripts[script];
    if (!dependencies) {
      return callback();
    }
    const promises = dependencies.map((dep) => {
      return new Promise((resolve, reject) => {
        this.loadScript(dep, (err) => {
          if (err) {
            reject(err);
          } else {
            resolve();
          }
        });
      });
    });
    Promise.all(promises).then(() => {
      callback();
    }).catch((err) => {
      callback(err);
    });
  }

  executeScripts() {
    this.scripts = {};
    this.dependencies.forEach((script) => {
      const scriptPath = path.resolve(__dirname, `../scripts/${script}.js`);
      fs.readFile(scriptPath, 'utf8', (err, content) => {
        if (err) {
          console.error(`Error loading script: ${script}`);
          return;
        }
        try {
          this.scripts[script] = eval(content);
        } catch (e) {
          console.error(`Error executing script: ${script}`);
          throw e;
        }
      });
    });
  }

  executeAllScripts() {
    this.executeScripts();
    const promises = Object.keys(this.scripts).map((script) => {
      return new Promise((resolve, reject) => {
        try {
          eval(`this.scripts.${script}.main()`);
          resolve();
        } catch (e) {
          reject(e);
        }
      });
    });
    Promise.all(promises).then(() => {
      console.log('All scripts executed successfully');
    }).catch((err) => {
      console.error('Error executing one or more scripts:', err);
    });
  }
}

module.exports = ScriptLoader;
