import java.util.*;

public class Main {

    public static int countUniqueSubstrings(List<String> list) {
        TrieNode root = new TrieNode();
        long startTime, endTime;

        for (String str : list) {
            startTime = System.nanoTime();
            insertIntoTrie(root, str);
            endTime = System.nanoTime();
            System.out.println("Time taken to insert: " + (endTime - startTime) + " ms");
        }

        int count = 0;
        for (int i = 0; i < list.size(); i++) {
            for (int j = i + 1; j < list.size(); j++) {
                startTime = System.nanoTime();
                count += getUniqueSubstrings(root, list.get(i), list.get(j));
                endTime = System.nanoTime();
                System.out.println("Time taken to generate unique substrings: " + (endTime - startTime) + " ms");
            }
        }

        return count;
    }

    private static int getUniqueSubstrings(TrieNode root, String str1, String str2) {
        TrieNode node = root;
        for (int i = 0; i < Math.min(str1.length(), str2.length()); i++) {
            char c1 = str1.charAt(i);
            char c2 = str2.charAt(i);
            if (c1 != c2) {
                int count = 0;
                getUniqueSubstringsHelper(node, c1, str1.substring(i));
                getUniqueSubstringsHelper(node, c2, str2.substring(i));
                return count;
            }
            while (i < str1.length() && i < str2.length()) {
                if (node.children[Character.getNumericValue(c1)] == null) {
                    node.children[Character.getNumericValue(c1)] = new TrieNode();
                }
                node = node.children[Character.getNumericValue(c1)];
            }
        }
        return 1;
    }

    private static int getUniqueSubstringsHelper(TrieNode root, char c, String str) {
        int count = 0;
        while (true) {
            if (root.children[Character.getNumericValue(c)] == null) {
                break;
            }
            root = root.children[Character.getNumericValue(c)];
            for (int i = 1; i <= root.count; i++) {
                count++;
            }
        }
        return count;
    }

    private static void insertIntoTrie(TrieNode root, String str) {
        TrieNode node = root;
        for (char c : str.toCharArray()) {
            if (node.children[Character.getNumericValue(c)] == null) {
                node.children[Character.getNumericValue(c)] = new TrieNode();
            }
            node = node.children[Character.getNumericValue(c)];
        }
        node.count++;
    }

    private static class TrieNode {
        int count;
        TrieNode[] children;

        public TrieNode() {
            this.count = 0;
            this.children = new TrieNode[2];
        }
    }
