use reqwest::{Client,blocking::ClientBuilder};
use tokio::task;
use std::sync::Arc;
use std::ops::Drop;

async fn make_request(url: &str) -> Result<String, reqwest::Error> {
    let client = Arc::new(ClientBuilder::new().build()?);

    let mut builder = client.get(url);

    if let Some(token) = get_token() {
        builder.header("Authorization", format!("Bearer {}", token));
    }

    let resp = builder.send().await?;
    Ok(resp.text().await?)
}

async fn handle_request(url: &str, retry_count: u32) -> Result<(), reqwest::Error> {
    for _ in 0..retry_count {
        match make_request(url).await {
            Ok(_) => return Ok(()),
            Err(e) if e.is_timeout() => continue,
            Err(_) => return Err(e),
        }
    }
    Err(reqwest::Error::Timeout)
}

async fn start_requests(urls: Vec<String>, retry_count: u32) -> Result<(), reqwest::Error> {
    let client = Arc::new(ClientBuilder::new().build()?);
    let token = get_token();

    task::spawn(async move {
        for url in urls {
            handle_request(&url, retry_count).await?;
        }
    });

    Ok(())
}

fn main() {
    // Usage example
    let mut urls = vec!["https://example.com/req1".to_string(), "https://example.com/req2".to_string()];
    start_requests(urls, 3).unwrap();
}
