['```rust
use std::process::{exit, Command};
use std::time::{Instant, Duration};
use std::mem;
use crossbeam::channel;
use rustc_driver::{catch_with_exit_code, CompileOptions};
use rustc_errors::{early_error, ErrorGuarantee};
use synclazy::{SyncLazy, LazyInitError};

fn compile_rust() -> i32 {
    let start_time = Instant::now();

    let mut child = Command::new("rustc")
        .arg("--crate-type=lib")
        .current_dir("/path/to/your/project") // replace with your project path
        .spawn()
        .expect("Failed to spawn rustc process");

    let (tx, rx) = channel();
    let hook = SyncLazy::new(|_| {
        Box::new(|output| tx.send(output).unwrap())
            as Box<dyn Fn(String) + '_>
    });

    let mut options = CompileOptions::new();
    options.hook = Some(hook);

    let start_rss = mem::size_of_process() as usize;
    let mut exit_code = child.wait().unwrap().code();

    if let Err(err) = catch_with_exit_code(child, &mut options) {
        early_error(ErrorGuarantee::Fatal, err);
    }

    let end_time = Instant::now();
    let duration = end_time.duration_since(start_time).unwrap();
    let cpu_usage = duration.as_secs_f64();

    println!("Compilation took: {:.2}s", cpu_usage);

    let end_rss = mem::size_of_process() as usize;
    let rss_peak = (end_rss - start_rss) / 1024; // convert to KiB

    println!("Peak memory usage: {} KiB", rss_peak);

    exit_code
}
