                last_modified = NOW(), user_agent = :user_agent;
        ");
        $metricsStmt->execute([':id' => $sessionId, ':metric1' => 'value1', ':metric2' => 'value2', ':user_agent' => $_SERVER['HTTP_USER_AGENT']]);

        // Update additional tables
        $additionalTables = array('table1', 'table2');
        foreach ($additionalTables as $tableName) {
            $stmt = $db->prepare("UPDATE `$tableName` SET last_modified = NOW(), user_agent = :user_agent WHERE session_id = :id");
            $stmt->execute([':id' => $sessionId, ':user_agent' => $_SERVER['HTTP_USER_AGENT']]);
