import os
import gzip
import zlib
import logging
import json

def process_log_file(file_path):
    try:
        if file_path.endswith('.gz'):
            with gzip.open(file_path, 'rt') as f:
                for line in f:
                    yield line.strip()
        elif file_path.endswith('.zlib'):
            with open(file_path, 'rb') as f:
                data = zlib.decompress(f.read())
                for line in data.decode().splitlines():
                    yield line.strip()
        else:
            with open(file_path, 'rt') as f:
                for line in f:
                    yield line.strip()
    except (FileNotFoundError, PermissionError):
        logging.error(f"Failed to access file {file_path}")
    except Exception as e:
        logging.error(f"An error occurred: {e}")

def extract_unique_identifier(log_file):
    last_entry = None
    try:
        for entry in process_log_file(log_file):
            last_entry = json.loads(entry)
            break
    except (JSONDecodeError, TypeError):
        pass
    return last_entry.get('unique_identifier')

def store_config(config_file, unique_identifier):
    with open(config_file, 'w') as f:
        json.dump({'last_unique_identifier': unique_identifier}, f)

if __name__ == '__main__':
    config_file = 'config.json'
    log_file_path = input("Enter the path to the log file: ")

    try:
        unique_identifier = extract_unique_identifier(log_file_path)
        store_config(config_file, unique_identifier)
    except Exception as e:
        logging.error(f"An error occurred: {e}")
