Octree::OctreeNode* initializeOctree(int featureSize, int numLeafNodes, int initialDataCapacity) {
    OctreeNode* root = new OctreeNode();
    root->isLeaf = false;

    int octreeDepth = 0;
    while (1 << octreeDepth < numLeafNodes) {
        octreeDepth++;
    }

    for (int i = 0; i < (1 << octreeDepth); i++) {
        int index = i;
        OctreeNode* node = root;

        for (int j = 0; j < octreeDepth; j++) {
            int childIndex = index & ((1 << (octreeDepth - 1)) - 1);
            index >>= (octreeDepth - 1);

            if (!node->children[childIndex]) {
                node->children[childIndex] = new OctreeNode();
                node->children[childIndex]->isLeaf = false;
            }

            node = node->children[childIndex];
        }
    }

    return root;
}

