#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <pthread.h>

typedef struct {
    int timestamp;
    float weight;
    int id;
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    Transaction* transactions[2000]; // 10,000 per second / 5 seconds = 2000
    int numTransactions;
    float totalWeight;
    int maxWeightedSum;
    int lastId;
} SlidingWindow;

void* processTransaction(void* arg) {
    SlidingWindow* window = (SlidingWindow*)arg;
    Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));

    // Initialize transaction data

    pthread_mutex_lock(&window->lock);
    window->numTransactions++;
    window->totalWeight += transaction->weight;

    int i;
    for(i = 0; i < window->numTransactions - 1; i++) {
        if(abs(transaction->timestamp - window.transactions[i]->timestamp) > 1) {
            // Remove old transactions
            free(window.transactions[i]);
            break;
        }
    }
    for(int j = i; j < window.numTransactions - 1; j++) {
        window.transactions[j] = window.transactions[j + 1];
    }
    window.transactions[window.numTransactions - 1] = transaction;

    if(transaction->weight > (float)window.maxWeightedSum) {
        window.maxWeightedSum = transaction->weight;
        window.lastId = transaction->id;
    }
    pthread_mutex_unlock(&window->lock);

    return NULL;
}

int main() {
    SlidingWindow* window = (SlidingWindow*)malloc(sizeof(SlidingWindow));
    pthread_mutex_init(&window->lock, NULL);
    // Initialize other metrics here

    pthread_t thread[10];
    for(int i = 0; i < 10; i++) {
        pthread_create(&thread[i], NULL, processTransaction, window);
    }

    // Wait for all transactions to be processed
    for(int i = 0; i < 10; i++) {
        pthread_join(thread[i], NULL);
    }

    printf("Max weighted sum: %f\n", window->maxWeightedSum);
    printf("Transaction ID: %d\n", window->lastId);
    printf("Average transaction weight: %f\n", window->totalWeight / (float)window.numTransactions);

    free(window);
    return 0;
}
