class CharacterAttackManager {
public:
    std::string selectAttack(const std::vector<Attack>& attacks, const std::chrono::time_point<std::chrono::high_resolution_clock>& lastAttackTimestamp) {
        auto now = std::chrono::high_resolution_clock::now();
        int elapsedMs = std::chrono::duration_cast<std::chrono::milliseconds>(now - lastAttackTimestamp).count();

        // Find the earliest available attack
        Attack selectedAttack;
        for (const auto& attack : attacks) {
            if (attack.cooldownDuration > elapsedMs) {
                selectedAttack = attack;
                break;
            }
        }

        return selectedAttack.id;
    }

    void updateAttackProperties(const std::vector<Attack>& updatedAttacks) {
        // Update internal state with the new attack properties
        attacks_ = updatedAttacks;
    }

private:
    std::vector<Attack> attacks_;
};

