        Console.WriteLine("Random double: " + _doubleRandom.Next((long)(_doubleRandom.Min * Math.Pow(2, 31)), (long)(_doubleRandom.Max * Math.Pow(2, 31)) + 1));
    }

    public void ResetIntegerRange(int min, int max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        _integerRandom = new Random();
        _integerRandom.Min = min;
        _integerRandom.Max = max;
    }

    public void ResetFloatRange(float min, float max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        _floatRandom = new Random((int)DateTime.Now.Ticks);
        _floatRandom.Min = min;
        _floatRandom.Max = max;
    }

    public void ResetDoubleRange(double min, double max)
    {
        if (min > max)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        _doubleRandom = new Random((int)DateTime.Now.Ticks);
        _doubleRandom.Min = min;
        _doubleRandom.Max = max;
    }

    public override string ToString()
    {
        return $"Integer: [{_integerRandom.Min}, {_integerRandom.Max}]\nFloat: [{_floatRandom.Min}, {_floatRandom.Max}]\nDouble: [{_doubleRandom.Min}, {_doubleRandom.Max}]";
    }
}
