function asyncReduce(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    const result = initialValue;
    let completedCount = 0;

    function processChunk(chunk) {
      if (chunk.length === 0) {
        resolve(result);
      } else {
        chunk.forEach((num) => {
          callback(num).then((value) => {
            result += value;
            completedCount++;
            if (completedCount === arr.length) {
              resolve(result);
            }
          }).catch((error) => {
            reject(error);
          });
        });
      }
    }

    const chunks = [];
    for (let i = 0; i < arr.length; i += 1000) {
      chunks.push(arr.slice(i, i + 1000));
    }

    if (chunks.length === 0) {
      resolve(result);
    } else {
      processChunk(chunks[0]);
      let chunkIndex = 1;
      const timeoutId = setInterval(() => {
        if (chunkIndex < chunks.length) {
          processChunk(chunks[chunkIndex++]);
        } else {
          clearInterval(timeoutId);
        }
      }, 100);
    }
  });
}
