#include <string.h>
#include <stdio.h>
#include <stdlib.h>

char* append_slash(char *str, int size_limit, char **buf) {
    if (strlen(str) + 1 > size_limit) return NULL;

    if (*buf == NULL || strlen(*buf) + strlen(str) + 2 >= size_limit) {
        *buf = malloc(size_limit);
        if (*buf == NULL) return NULL;
    }

    strcpy(*buf, str);
    (*buf)[strlen(*buf)] = '/';
    (*buf)[strlen(*buf) + 1] = '\0';

    return *buf;
}

void reset_buffer(char **buf) {
    free(*buf);
    *buf = NULL;
}

void log_append_slash(char *str, int size_limit, char *buf) {
    printf("append_slash called with str '%s', size_limit %d, buf '%s'\n", str, size_limit, buf);
    if (buf == NULL) printf("Returned NULL\n");
    else printf("Returned pointer to buffer\n");
}

int main() {
    char *str = "path";
    int size_limit = 10;
    char *buf = NULL;

    while (1) {
        buf = append_slash(str, size_limit, &buf);
        log_append_slash(str, size_limit, buf);

        if (buf == NULL) {
            break;
        }

        reset_buffer(&buf);
    }

    return 0;
}
