#define MAX_LINE_LENGTH 1024
#define MAX_INT_VALUE 1000000

void process_line(char *line, int *avg) {
    char *token = strtok(line, " ");
    int sum = 0;
    int count = 2;

    while (token && count--) {
        int num = atoi(token);
        sum += num;
        token = strtok(NULL, " ");
    }

    *avg = sum / count;
}

int main() {
    FILE *file = fopen("data.txt", "r");
    if (!file) {
        fprintf(stderr, "Error opening file\n");
        return 1;
    }

    json_object *json_obj = json_object_new_object();
    json_object_object_add(json_obj, "averages", json_object_array_new());

    char line[MAX_LINE_LENGTH];
    int avg;

    while (fgets(line, MAX_LINE_LENGTH, file)) {
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }

        char *dyn_line = malloc(len + 1);
        strcpy(dyn_line, line);

        process_line(dyn_line, &avg);
        json_object_array_add(json_obj->object->values, json_object_new_int(avg));
        free(dyn_line);
    }

    fclose(file);

    // Send data to the external service
    char *json_str = json_object_to_json_string(json_obj);
    FILE *out_file = fopen("output.txt", "w");
    fprintf(out_file, "%s\n", json_str);
    fclose(out_file);

    free(json_obj->object->values);
    free(json_obj);

    return 0;
}
