#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/kdf.h>
#include <stdlib.h>
#include <string.h>

#define DEFAULT_PBKDF2_ITERATIONS 100000

typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char* iv;
} aes_context;

aes_context* init_aes_cipher(const char* password, const unsigned char* custom_iv, int num_iterations) {
    aes_context* cipher_ctx = (aes_context*)malloc(sizeof(aes_context));
    if (!cipher_ctx) {
        ERR_error_string(ERR_get_error(), NULL);
        return NULL;
    }

    unsigned char* salt = (unsigned char*)malloc(16);
    if (!salt) {
        ERR_error_string(ERR_get_error(), NULL);
        free(cipher_ctx);
        return NULL;
    }

    // Generate a random IV
    if (!custom_iv) {
        RAND_bytes(salt, 16);
    } else {
        memcpy(salt, custom_iv, 16);
    }

    int key_len = PBKDF2_sha256_key_length();
    unsigned char* derived_key = (unsigned char*)malloc(key_len);
    if (!derived_key) {
        ERR_error_string(ERR_get_error(), NULL);
        free(salt);
        free(cipher_ctx);
        return NULL;
    }

    // Set the IV length
    cipher_ctx->iv = custom_iv ? custom_iv : salt;

    int iterations = num_iterations ? num_iterations : DEFAULT_PBKDF2_ITERATIONS;
    PBKDF2_sha256(password, strlen(password), salt, 16, derived_key, key_len, iterations);

    // Create the AES-256-CBC cipher context
    cipher_ctx->ctx = EVP_Cipher_CTX_new();
    if (!cipher_ctx->ctx) {
        ERR_error_string(ERR_get_error(), NULL);
        free(salt);
        free(derived_key);
        free(cipher_ctx);
        return NULL;
    }

    // Set the key and IV
    if (1 != EVP_Cipher_Init_ex(cipher_ctx->ctx, "AES-256-CBC", NULL, derived_key, key_len, cipher_ctx->iv, 16)) {
        ERR_error_string(ERR_get_error(), NULL);
        free(salt);
        free(derived_key);
        EVP_CIPHER_CTX_free(cipher_ctx->ctx);
        free(cipher_ctx);
        return NULL;
    }

    return cipher_ctx;
}

void cleanup_aes_cipher(aes_context* cipher_ctx) {
    if (!cipher_ctx) {
        return;
    }

    EVP_CIPHER_CTX_free(cipher_ctx->ctx);
    free(cipher_ctx->iv);
    free(cipher_ctx);

    ERR_error_string(ERR_get_error(), NULL);
}
