#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define TIMEOUT 60 // seconds
#define CPU_THRESHOLD 50 // %
#define MEM_THRESHOLD 1000 // MB

int run_command_in_background(const char *command, int timeout) {
    pid_t child_pid;
    int status;
    struct timespec timeout_ts;

    if (fork() == 0) { // child process
        // Set up new process group to prevent signals from parent
        setpgid(getpid(), getpid());
        // Execute command in background
        system(command);

        // Monitor CPU and memory usage
        while (1) {
            FILE *fp = fopen("/proc/self/stat", "r");
            if (!fp)
                break;
            char buffer[1024];
            fgets(buffer, sizeof(buffer), fp);
            fclose(fp);
            int cpu_usage = atoi(strtok(buffer, "+"));
            int mem_usage = atoi(strtok(NULL, "+")) / 1024; // MB
            if (cpu_usage > CPU_THRESHOLD || mem_usage > MEM_THRESHOLD) {
                warn("Command '%s' is consuming high resources!", command);
            }
        }

        // Exit after timeout or command completion
        nanosleep(&timeout_ts, NULL);
    } else { // parent process
        child_pid = waitpid(child_pid, &status, 0);

        if (child_pid < 0 || WIFEXITED(status) || WEXITSTATUS(status)) {
            return 0; // command execution failed or timed out
        }
        // Log command execution success
        log("Command '%s' executed successfully in %d seconds.", command, timeout);
        return 1;
    }

    return -1; // command execution failed (child process didn't exit)
}
