        directoryPath = Path.Normalize(directoryPath);

        if (!Directory.Exists(directoryPath))
        {
            throw new DirectoryNotFoundException($"The specified directory '{directoryPath}' does not exist.");
        }

        string webConfigFile = Path.Combine(directoryPath, "web.config");

        // Check for the existence and validity of the web.config file
        if (!File.Exists(webConfigFile) || !IsValidWebConfig(webConfigFile))
        {
            LogError($"Invalid or missing web.config file at '{directoryPath}'.");
            return;
        }

        try
        {
            ProcessStartInfo startInfo = new ProcessStartInfo("iisreset", "/start " + Path.GetFileName(directoryPath));
            startInfo.CreateNoWindow = true;
            startInfo.UseShellExecute = false;

            // Start the web application using the Process class
            using (Process process = Process.Start(startInfo))
            {
                if (!process.WaitForExit(10000)) // Wait for 10 seconds
