int is_oauth_token_valid(char *json_string) {
    json_object *jobj = json_object_from_json_string(json_string);

    if (!jobj) {
        return 0; // invalid JSON, return false
    }

    if (!json_object_object_test(jobj, "access_token") || !json_object_get_type(jobj->object["access_token"]) == json_type_string) {
        json_object_put(jobj); // free memory
        return 0;
    }

    char *token = (char *)json_object_get_string(jobj->object["access_token"]);
    if (!token[0]) {
        json_object_put(jobj);
        return 0; // access token is empty, return false
    }

    if (!json_object_object_test(jobj, "expires_in") || !json_object_get_type(jobj->object["expires_in"]) == json_type_int) {
        json_object_put(jobj);
        return 0;
    }

    int expires_in = json_object_get_int(jobj->object["expires_in"]);
    if (expires_in > 3600) {
        json_object_put(jobj);
        return 0; // expires_in is too large, return false
    }

    if (!json_object_object_test(jobj, "token_type") || !json_object_get_type(jobj->object["token_type"]) == json_type_string) {
        json_object_put(jobj);
        return 0;
    }

    char *token_type = (char *)json_object_get_string(jobj->object["token_type"]);
    if ((strcmp(token_type, "Bearer") != 0) && (strcmp(token_type, "Mac") != 0)) {
        json_object_put(jobj);
        return 0; // invalid token type, return false
    }

    if (json_object_object_test(jobj, "refresh_token")) {
        char *refresh_token = (char *)json_object_get_string(jobj->object["refresh_token"]);
        if (!refresh_token[0] || strlen(refresh_token) > 512) {
            json_object_put(jobj);
            return 0; // refresh token is invalid, return false
        }
    }

    json_object_put(jobj); // free memory

    return 1; // token is valid
}
