using System;
using System.Security.Cryptography;
using System.Text;

public static byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv, byte[] sharedSecretKey)
{
    using (var aes = Aes.Create())
    {
        aes.Key = key;
        aes.IV = iv;

        foreach (var segment in SplitCiphertext(ciphertext))
        {
            try
            {
                using (var cipherStream = new MemoryStream(segment))
                using (var decryptor = aes.CreateDecryptor())
                {
                    byte[] decryptedSegment;
                    using (var memoryStream = new MemoryStream())
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor))
                    {
                        byte[] buffer = new byte[16];
                        int bytesRead;
                        while ((bytesRead = cipherStream.Read(buffer, 0, buffer.Length)) > 0)
                        {
                            cryptoStream.Write(buffer, 0, bytesRead);
                        }
                        decryptedSegment = memoryStream.ToArray();
                    }

                    if (decryptedSegment.Length < segment.Length - 16)
                    {
                        throw new Exception("Decryption error: padding not valid");
                    }

                    using (var hmac = new HMACSHA256(sharedSecretKey))
                    {
                        byte[] macBytes = new byte[hmac.HashSize / 8];
                        Array.Copy(decryptedSegment, decryptedSegment.Length - macBytes.Length, macBytes);
                        byte[] recalculatedMac;
                        using (var memoryStream = new MemoryStream())
                        using (var cryptoStream = new CryptoStream(memoryStream, hmac))
                        {
                            cryptoStream.Write(decryptedSegment, 0, decryptedSegment.Length - macBytes.Length);
                            recalculatedMac = memoryStream.ToArray();
                        }
                        if (!VerifyMac(macBytes, recalculatedMac))
                        {
                            throw new Exception("Integrity check failed");
                        }
                    }

                    return decryptedSegment;
                }
            }
            catch (Exception ex)
            {
                throw new Exception($"Decryption error: {ex.Message}");
            }
        }
    }
}

private static byte[][] SplitCiphertext(byte[] ciphertext)
{
    List<byte[]> segments = new List<byte[]>();
    using (var ms = new MemoryStream(ciphertext))
    {
        while (ms.Length > 0)
        {
            int segmentLength = Aes.Create().BlockSize;
            if (ciphertext.Length - segmentLength < 0)
                break;

            byte[] segment = new byte[segmentLength];
            ms.Read(segment, 0, segmentLength);
            segments.Add(segment);
        }
    }
    return segments.ToArray();
}

private static bool VerifyMac(byte[] expectedMac, byte[] recalculatedMac)
{
    return CalculateHmac(expectedMac).CompareTo(recalculatedMac) == 0;
}

private static byte[] CalculateHmac(byte[] inputBytes)
{
    using (var hmac = new HMACSHA256(sharedSecretKey))
    {
        return hmac.ComputeHash(inputBytes);
    }
}
