const { promises: fs } = require('fs');
const axios = require('axios');
const log = require('log4js').getLogger();

function uploadFile(url, expectedMimeType) {
  const retryAttempts = 3;
  const backoffTimeMs = 500;

  return new Promise((resolve, reject) => {
    (async () => {
      try {
        const response = await axios.get(url, {
          responseType: 'stream',
        });

        if (!response.data.type || !response.data.type.includes(expectedMimeType)) {
          throw new Error(`Invalid MIME type. Expected ${expectedMimeType}, got ${response.data.type}`);
        }

        let chunkedFileStream = fs.createWriteStream('temp-file', { flags: 'w' });
        response.data.pipe(chunkedFileStream);

        await new Promise((resolve, reject) => {
          chunkedFileStream.on('finish', () => resolve());
          chunkedFileStream.on('error', (err) => reject(err));
        });

        log.info(`File uploaded successfully at ${new Date().toISOString()}`);
        resolve(url);
      } catch (error) {
        const delay = Math.min(backoffTimeMs * Math.pow(2, error.retryCount || 0), 30000); // exponential backoff

        setTimeout(async () => {
          try {
            await uploadFile(url, expectedMimeType);
          } catch (e) {
            reject(e);
          }
        }, delay);

        log.error(`Upload failed. Retrying in ${delay}ms`);
      }
    })().catch((error) => {
      if (error.retryCount >= retryAttempts) {
        reject(error);
      } else {
        setTimeout(async () => {
          try {
            await uploadFile(url, expectedMimeType);
          } catch (e) {
            reject(e);
          }
        }, backoffTimeMs * Math.pow(2, error.retryCount || 0));
      }
    });
  });
}
