#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <signal.h>
#include <string.h>
#include <time.h>

struct log_entry {
    time_t timestamp;
    int exit_status;
    char* command;
    double cpu_usage;
    double mem_usage;
};

void handle_timeout(int sig) {
    kill(getpid(), SIGINT);
}

int execute_command(char* command, unsigned int timeout) {
    pid_t child_pid = fork();

    if (child_pid == 0) {
        struct rlimit rl;
        rl.rlim_cur = RLIMIT_CPU;
        rl.rlim_max = RLIMIT_CPU;
        setrlimit(RLIMIT_CPU, &rl);

        signal(SIGXCPU, handle_timeout);
        time_t start_time = time(NULL);
        int status = system(command);

        if (status == -1) {
            perror("System call failed");
            kill(getpid(), SIGINT);
        } else if (time(NULL) - start_time > timeout) {
            kill(getpid(), SIGINT);
        }

        exit(status);
    } else if (child_pid > 0) {
        int status = waitpid(child_pid, NULL, WNOHANG);

        if (status == -1) {
            perror("Wait failed");
            return -1;
        } else if (status > 0) {
            return 0;
        }
    } else {
        printf("Fork failed\n");
        return -1;
    }

    return 0;
}

void log_command_result(struct log_entry* entry, int status) {
    FILE* log_file = fopen("/path/to/log/file", "a+");

    if (log_file != NULL) {
        fprintf(log_file, "%ld %d %s %.2f %.2f\n", entry->timestamp, entry->exit_status, entry->command, entry->cpu_usage, entry->mem_usage);
