        for (int i = 0; i < rand() % 10 + 1; i++) {
            char vertex_id[20];
            sprintf(vertex_id, "V%d", i);

            fprintf(file, "CREATE (:Vertex {id: '%s', prop1: '%s', prop2: '%s'})\n", vertex_id, random_string(), random_string());
