        for (int i = 0; i < rand() % 10 + 1; i++) {
            char edge_id[20];
            sprintf(edge_id, "E%d", i);

            fprintf(file, "CREATE (:Edge {id: '%s', from: '%s', to: '%s'})\n", edge_id, random_vertex(), random_vertex());
        }

        fclose(file);
    } else {
        printf("File operation failed\n");
        return -1;
    }

    return 0;
}

char* random_string() {
    static char buffer[20];
    for (int i = 0; i < 10; i++) {
        buffer[i] = (char)(rand() % 26 + 97);
    }
    buffer[10] = '\0';

    return buffer;
}

