    let data = cache.get("plugin1_data").await?;
    if let Some(data) = data {
        Ok(format!("Plugin 1 result: {}", data))
    } else {
        // Make API request to fetch the data
        let response = reqwest::get("https://api.example.com/plugin1_data")
            .await?
            .text()
            .await?;
