use std::fs;
use std::io;
use log;

fn init_logging_config(config_file: &str) -> Result<(), io::Error> {
    let config_contents = fs::read_to_string(config_file)?;
    let logging_config: serde_yaml::Value = serde_yaml::from_str(&config_contents)?;

    // Get the log directory path from the configuration
    let log_dir = logging_config["log_directory"].as_str().unwrap_or("logs");

    // Create the log directory if it doesn't exist
    if !fs::create_dir_all(log_dir).is_ok() {
        log::error!("Failed to create log directory: {}", log_dir);
        return Err(io::Error::new(io::ErrorKind::Other, "Failed to create log directory"));
    }

    log::info!("Log directory created: {}", log_dir);

    // Check if the log directory is accessible
    let mut perms = fs::metadata(log_dir).unwrap().permissions();
    if !perms.execute() {
        perms.set_execute(true)?;
        log::info!("Adjusted permissions to allow execution in log directory");
    }

    Ok(())
}
