import json
from threading import Lock
class ConfigurableObject:
    _registry = {}
    _version_registry = {}
    _lock = Lock()

    def __init_subclass__(cls, id):
        cls._registry[id] = cls
        if not hasattr(cls, 'get_version'):
            cls.get_version = lambda: 1

    @classmethod
    def register_factory(cls, id, factory):
        with cls._lock:
            cls._registry[id] = factory

    @classmethod
    def create_instance(cls, id, json_config=None, defaults=None):
        if id not in cls._registry:
            raise ValueError(f"Factory ID '{id}' is not registered.")
        factory = cls._registry[id]
        config = factory(json_config, defaults)
        return config

    @classmethod
    def get_version(cls, id):
        return cls._version_registry.get(id, 1)

class ConfigurableObjectError(Exception): pass

class JSONConfigurableObject:
    def __init__(self, json_config=None, defaults=None):
        self.json_config = json_config or {}
        self.defaults = defaults or {}

    @classmethod
    def from_json(cls, json_string, id):
        try:
            json_config = json.loads(json_string)
        except json.JSONDecodeError as e:
            raise ConfigurableObjectError(f"Invalid JSON: {e}")

        config = cls.create_instance(id, json_config, cls.defaults.get(id, {}))
        return config

    def to_json(self):
        return json.dumps(self.json_config)

class UserConfig(JSONConfigurableObject): pass
class DatabaseConfig(JSONConfigurableObject): pass
class LoggingConfig(JSONConfigurableObject): pass']

