NFAPI_RX_FRAME_T** initialize_rx_frames(int num_frames) {
    NFAPI_RX_FRAME_T** rx_frames = NULL;
    int total_frames = 0;

    for (int i = 0; i < num_frames; i++) {
        NFAPI_RX_FRAME_T* frame = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T));
        if (!frame) {
            printf("Memory allocation failed.\n");
            while (i > 0) {
                free(rx_frames[i - 1]->rx_stream_tag);
                free(rx_frames[i - 1]);
                i--;
            }
            return NULL;
        }

        frame->rrc_rx_frame_tag = i;
        frame->snr = (float)rand() / RAND_MAX;

        // Dynamically allocate and initialize RX_STREAM_TAG
        int stream_tag_len = 10; // Set the length of the stream tag dynamically if needed
        char* stream_tag = (char*)malloc(stream_tag_len);
        if (!stream_tag) {
            printf("Memory allocation for stream tag failed.\n");
            free(frame->rx_stream_tag);
            free(frame);
            i--;
            continue;
        }
        frame->rx_stream_tag = stream_tag;

        rx_frames = (NFAPI_RX_FRAME_T**)realloc(rx_frames, sizeof(NFAPI_RX_FRAME_T*) * ++total_frames);
        if (!rx_frames) {
            printf("Memory allocation for array failed.\n");
            free(frame->rx_stream_tag);
            free(frame);
            i--;
            continue;
        }
        rx_frames[total_frames - 1] = frame;
    }

    return rx_frames;
}
