typedef struct {
    int count;
    char* type;
} Config;

Config config = {3, ".txt"}; // default configuration

// Function to generate a new filename with a modified extension
char* process_filename(char* original) {
    int len = strlen(original);
    if (len > 256) {
        return NULL; // handle filenames that are longer than 256 characters
    }

    char* result = malloc(512); // ensure the new filename does not exceed 512 characters
    strcpy(result, original);

    int i;
    for (i = 0; i < len && !strchr(original, '.'); i++); // find the last occurrence of a dot

    if (i == len) {
        strcat(result, config.type); // append default file type
    } else {
        char* ext = malloc(i - strlen(original));
        strncpy(ext, original + i, i - strlen(original));
        free(original);
        strcat(result, ext);
        free(ext);
    }

    time_t now = time(NULL);
    char timestamp[50];
    strftime(timestamp, 50, "%Y-%m-%d_%H-%M-%S", localtime(&now));
    strcat(result, "_"); // add a separator
    strcat(result, timestamp);

    return result;
}

int main() {
    // Example usage:
    char* filenames[] = {"file1.txt", "file2.jpg", "file3"};
    int num_files = sizeof(filenames) / sizeof(char*);

    FILE* log_file = fopen("log.txt", "w");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    for (int i = 0; i < num_files; i++) {
        char* processed_filename = process_filename(filenames[i]);
        if (!processed_filename) {
            // handle error
        } else {
            fprintf(log_file, "Original filename: %s\n", filenames[i]);
            fprintf(log_file, "Processed filename: %s\n", processed_filename);
            free(processed_filename);
        }
    }

    fclose(log_file);

    return 0;
}
