#define MAX_FILE_NAME_LENGTH 255
#define MAX_INPUT_SIZE 1000

void processFileWithCrypto(char* filename, char commandLineOption) {
    // Generate timestamp and unique identifier for the new file name
    time_t now = time(NULL);
    char timestamp[16];
    sprintf(timestamp, "%02d%02d%02d%02d%02d%02d", (int)(now / 31536000) % 100, (int)((now / 2592000) % 100), (int)((now / 86400) % 100), (int)((now / 3600) % 24), (int)((now / 60) % 60), (int)(now % 60));
    char uniqueIdentifier[128];
    size_t uniqueIdentifierLength = strlen(filename) * 2 + 1;
    for (size_t i = 0; i < uniqueIdentifierLength; i++) {
        uniqueIdentifier[i] = (rand() & 0x7f) == 0 ? (char)(rand() % 26 + 65) : (char)((rand() & 0x7f) + 48);
    }
    char newFileName[MAX_FILE_NAME_LENGTH];
    sprintf(newFileName, "%s.%s%s", filename, timestamp, uniqueIdentifier);

    // Perform cryptographic operation
    if (commandLineOption == 'e') {
        // Encrypt using OpenSSL
        unsigned char* cipher = malloc(MAX_INPUT_SIZE * sizeof(unsigned char));
        int cipherLength = 0;
        while (1) {
            int num;
            scanf("%d", &num);
            if (num == -1)
                break;
            cipher[cipherLength++] = num;
            if (cipherLength >= MAX_INPUT_SIZE)
                break;
        }
        // Encrypt and print the largest integer in the array
        unsigned char* maxPointer = malloc(sizeof(unsigned char));
        int maxVal = 0;
        for (int i = 0; i < cipherLength; i++) {
            if (cipher[i] > maxVal) {
                maxVal = cipher[i];
                *maxPointer = maxVal;
            }
        }
        printf("%d\n", *maxPointer);
    } else {
        // Decrypt using OpenSSL
        // ...
    }

    free(cipher);
    free(maxPointer);
}
