#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <arpa/inet.h>
#include <unistd.h>

// Define error codes
#define DNS_RESOLUTION_ERROR 1
#define PORT_VALIDATION_ERROR 2
#define IP_ADDRESS_OUT_OF_RANGE 3

// Structure to represent a network port
typedef struct {
    int port;
    char status; // 'O' for open or 'C' for closed
} Port;

// Helper function to report duplicate ports
void reportDuplicatePorts(Port* ports, int numPorts) {
    printf("Duplicate port found: ");
    for (int i = 0; i < numPorts; i++) {
        if (ports[i].port != i + 1) {
            printf("%d ", ports[i].port);
        }
    }
    printf("\n");
}

// Function to manage network resource
int manageNetworkResource(char* hostname, char* commandOption) {
    // Resolve hostname to IP address using system's DNS resolver API
    struct addrinfo hints, *result;
    int status;
    const char* node = hostname;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM; // TCP
    hints.ai_protocol = IPPROTO_TCP; // TCP

    getaddrinfo(node, NULL, &hints, &result);
    if (status == 0) {
        freeaddrinfo(result);
        return DNS_RESOLUTION_ERROR;
    }

    struct sockaddr_in* ip4_addr = (struct sockaddr_in*) result->ai_addr;
    char* ip_address = inet_ntop(AF_INET, &ip4_addr->sin_addr, NULL, INET6_ADDRSTRLEN);
    if (!ip_address) {
        freeaddrinfo(result);
        return DNS_RESOLUTION_ERROR;
    }

    // Validate IP address format and range
    if (inet_pton(AF_INET, ip_address, NULL) != 1 || inet_pton(AF_INET6, ip_address, NULL) != 1) {
        free(ip_address);
        return IP_ADDRESS_OUT_OF_RANGE;
    }
    free(ip_address);

    // Read ports from file and validate uniqueness and range
    FILE* portFile = fopen("ports.txt", "r");
    if (portFile == NULL) {
        return PORT_VALIDATION_ERROR;
    }

    int numPorts = 0;
    Port* ports = (Port*) malloc(sizeof(Port));
    while (fscanf(portFile, "%d\n", &ports[numPorts].port) != EOF) {
        numPorts++;
        if (numPorts > 1 && ports[numPorts - 2].port == ports[numPorts - 1].port) {
            reportDuplicatePorts(ports, numPorts);
            return PORT_VALIDATION_ERROR;
        }
        if (ports[numPorts - 1].port < 1 || ports[numPorts - 1].port > 65535) {
            return PORT_VALIDATION_ERROR;
        }
        // Dynamically allocate memory for the port list
        Port* newPorts = (Port*) realloc(ports, sizeof(Port) * (numPorts + 1));
