initialize_fsa_states_params* initialize_fsa_states(int* states, int num_states, struct FSA* fsa, int last_state, struct NFAPI_RX_FRAME_T** frames, int num_frames) {
    if (num_states <= 0 || num_frames <= 0) return NULL;

    // Allocate memory for the new state list
    int* new_states = malloc(num_states * sizeof(int));
    if (!new_states) {
        free(new_states);
        return NULL;
    }

    // Initialize the new state list
    memcpy(new_states, states, num_states * sizeof(int));
    free(states);

    // Update the FSA's current state pointer to reflect the new list's head
    fsa->current_state = new_states[0];

    // Allocate memory for the array of initialized frames
    struct NFAPI_RX_FRAME_T** new_frames = malloc(num_frames * sizeof(struct NFAPI_RX_FRAME_T*));
    if (!new_frames) {
        free(new_states);
        return NULL;
    }

    // Initialize the array of initialized frames
    memcpy(new_frames, frames, num_frames * sizeof(struct NFAPI_RX_FRAME_T*));
    for (int i = 0; i < num_frames; i++) {
        new_frames[i]->next = &new_frames[i+1];
    }

    free(frames);

    // Return the newly created state list and array of initialized frames
    return (initialize_fsa_states_params*)malloc(sizeof(initialize_fsa_states_params));
