import os
import gzip
import shutil
from io import BytesIO
from zipfile import ZipFile
from hashlib import md5
from functools import lru_cache
from itertools import groupby
from operator import itemgetter
from collections import defaultdict
from threading import Lock, Thread
from queue import Queue

REPORT_FORMAT = 'text/plain'
COMPRESSION_LEVEL = 9
MAX_FILE_SIZE = 10240

class Logger:
    def __init__(self, log_file):
        self.log_file = log_file

    def log(self, filename, content, error=None):
        with open(self.log_file, 'a') as f:
            if error:
                print(f"Error processing file '{filename}': {error}", file=f)
            else:
                print(f"Processed file '{filename}' with content:\n{content.strip()}\n", file=f)

class Reporter:
    def __init__(self, report_file):
        self.report_file = report_file

    @lru_cache(maxsize=None)
    def checksum(self, content):
        return md5(content.encode()).hexdigest()

    def generate_report(self, sorted_files):
        with gzip.open(self.report_file, 'wb') as f:
            for file in sorted_files:
                if len(file['content']) > MAX_FILE_SIZE:
                    buffer = BytesIO()
                    ZipFile(buffer, 'w', compression=COMPRESSION_LEVEL).write(file['content'])
                    content = buffer.getvalue()
                else:
                    content = file['content']

                f.write(content)
                f.write(b'\n---\n')
            f.write(self.checksum(b'').encode())

def sort_files(directory):
    lock = Lock()
    queue = Queue()

    def process_file(filename):
        with open(os.path.join(directory, filename), 'r') as f:
            content = f.read().strip()

        if len(content) > MAX_FILE_SIZE:
            buffer = BytesIO()
            ZipFile(buffer, 'w', compression=COMPRESSION_LEVEL).write(content.encode())
            content = buffer.getvalue()

        sequence_number = None
        try:
            for line in reversed(list(f)):
                if not line.strip():
                    continue

                sequence_number = int(line.split()[-1].strip())

                break
        except ValueError:
            pass

        yield filename, content, sequence_number

    def process_directory(directory):
        files = defaultdict(dict)

        for filename in os.listdir(directory):
            file_path = os.path.join(directory, filename)
            if not os.path.isfile(file_path):
                continue

            if len(filename) > 256:
                raise ValueError(f"Invalid filename: {filename}")

            thread = Thread(target=queue.put_nowait, args=(process_file(filename),))
            thread.start()

        while True:
            try:
                result = queue.get(block=False)
                for file in result:
                    files[file[0]].update(file[1:])

                if not queue.empty():
                    continue

                for filename, sorted_content in groupby(sorted(files.items()), key=itemgetter(0)):
                    yield {'filename': filename, 'content': b''.join(content.encode() for _, content in sorted_content)}

            except Queue.Empty:
                break

def main(directory):
    reporter = Reporter('report.txt')
    logger = Logger('log.txt')

    for file in sort_files(directory):
        if not file['sequence_number']:
            raise ValueError(f"Invalid sequence number in file '{file['filename']}'")

        with open(os.path.join(directory, f"{file['filename']}.sorted"), 'w') as f:
            f.write(file['content'])

        logger.log(file['filename'], file['content'])

    reporter.generate_report([{'content': f.read().encode()} for f in [open(os.path.join(directory, f"{f}.sorted"), 'r') for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f)) and len(f) <= 256]])

if __name__ == "__main__":
    import sys
    main(sys.argv[1])
```']

