        if(record_size < sizeof(record)) {
            // handle record size threshold exceeded error
            printf("Error: Record exceeds size threshold\n");
            free(records);
            free(offsets);
            free(keys);
            return NULL;
        }
    }

    for(int i = 0; i < total_records; i++) {
        offsets[i] = (long)i;
