#define MAX_QUEUE_SIZE 1000

void manageThreadSafeQueueAndFindMax(int* arr, int n) {
    sem_t queue_sem;
    if (sem_init(&queue_sem, 0, 1) != 0) {
        perror("sem_init");
        exit(EXIT_FAILURE);
    }

    // Create a dynamically allocated array to store the queue
    int* queue = (int*)malloc(MAX_QUEUE_SIZE * sizeof(int));

    for (int i = 0; i < n; i++) {
        sem_wait(&queue_sem); // Wait for access to the queue

        if (i >= MAX_QUEUE_SIZE) { // If the queue is full, resize it
            int* temp_queue = (int*)realloc(queue, (MAX_QUEUE_SIZE * 2) * sizeof(int));
            queue = temp_queue;
            MAX_QUEUE_SIZE *= 2;
        }

        queue[i] = arr[i]; // Add elements to the queue

        sem_post(&queue_sem); // Release access to the queue
    }

    for (int i = 0; i < n; i++) {
        sem_wait(&queue_sem);
        printf("%d ", queue[i]);
        sem_post(&queue_sem);
    }
    printf("\n");

    int max_val = *std::max_element(queue, queue + n);

    // Find the maximum value in the queue
    void findMax() {
        printf("Maximum value: %d\n", max_val);
    }

    findMax();

    sem_destroy(&queue_sem); // Release resources

    free(queue); // Free memory
}

int main() {
    int arr[] = {1, 2, 3, -4, 5, 6};
    int n = sizeof(arr) / sizeof(arr[0]);

    manageThreadSafeQueueAndFindMax(arr, n);

    return 0;
}
