        int val = array->values[i];
        if (mode == 1) { // find max
            printMaxInteger(array);
        } else if (mode == 2) { // calculate sum
            int sum = 0;
            for (size_t j = 0; j < array->count; j++) {
                sum += array->values[j];
            }
            printf("Sum: %d\n", sum);
        }
    }

    pthread_join(thread);
    fclose(file);
}

int main(int argc, char* argv[]) {
