#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *elements;
    pthread_mutex_t lock;
    pthread_cond_t not_empty, not_full;
    int capacity, size, front, rear, enqueue_time, dequeue_time;
} Queue;

Queue* init_queue(int capacity) {
    Queue* q = (Queue*)malloc(sizeof(Queue));
    q->capacity = capacity;
    q->size = 0;
    q->front = q->rear = -1;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_empty, NULL);
    pthread_cond_init(&q->not_full, NULL);
    return q;
}

void enqueue(Queue* q, int element, int priority) {
    pthread_mutex_lock(&q->lock);

    while (q->size == q->capacity) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }

    if (priority > 0) {
        int i = q->rear + 1;
        while (i != q->front) {
            if (q->elements[i % q->capacity] <= element) break;
            i = (i+1) % q->capacity;
        }
        q->rear = i;
    } else {
        q->rear = (q->rear + 1) % q->capacity;
    }

    q->size++;
    q->elements[q->rear] = element;

    pthread_mutex_unlock(&q->lock);
    pthread_cond_signal(&q->not_empty);

    if (priority > 0) {
        q->enqueue_time += 1;
    }
}

int dequeue(Queue* q, int timeout) {
    pthread_mutex_lock(&q->lock);

    while (q->size == 0) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }

    if (timeout > 0) {
        struct timespec ts;
        ts.tv_sec = timeout / 1000;
        ts.tv_nsec = (timeout % 1000) * 1000000;
        pthread_cond_timedwait(&q->not_full, &q->lock, &ts);
    }

    int element = q->elements[q->front];
    q->size--;
    q->front = (q->front + 1) % q->capacity;

    pthread_mutex_unlock(&q->lock);

    if (timeout > 0) {
        q->dequeue_time += 1;
    }
}

int get_stats(Queue* q) {
    return q->size;
}
