#define MAX_CONNECTIONS 100
#define TIMEOUT 30000 // in milliseconds

typedef struct {
    int max_connections;
    int current_connections;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    struct connection* connections[MAX_CONNECTIONS];
} pool;

typedef struct {
    char* server;
    int failed_attempts;
    pthread_mutex_t attempts_mutex;
    pthread_cond_t attempts_cond;
} server_info;

pool* create_pool(int max_connections) {
    pool* p = (pool*)malloc(sizeof(pool));
    p->max_connections = max_connections;
    p->current_connections = 0;
    pthread_mutex_init(&p->mutex, NULL);
    pthread_cond_init(&p->cond, NULL);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        p->connections[i] = NULL;
    }
    return p;
}

void destroy_pool(pool* p) {
    for (int i = 0; i < p->max_connections; i++) {
        if (p->connections[i]) {
            free(p->connections[i]);
        }
    }
    pthread_mutex_destroy(&p->mutex);
    pthread_cond_destroy(&p->cond);
    free(p);
}

server_info* create_server(char* server) {
    server_info* s = (server_info*)malloc(sizeof(server_info));
    s->server = server;
    s->failed_attempts = 0;
    pthread_mutex_init(&s->attempts_mutex, NULL);
    pthread_cond_init(&s->attempts_cond, NULL);
    return s;
}

void destroy_server(server_info* s) {
    free(s->server);
    pthread_mutex_destroy(&s->attempts_mutex);
    pthread_cond_destroy(&s->attempts_cond);
    free(s);
}

int get_active_connections(pool* p) {
    int active = 0;
    pthread_mutex_lock(&p->mutex);
    for (int i = 0; i < p->max_connections; i++) {
        if (p->connections[i]) {
            active++;
        }
    }
    pthread_mutex_unlock(&p->mutex);
    return active;
}

// Function to handle connection setup and management
int connect_to_pool(pool* p, server_info* s) {
    // TO DO: Implement actual database connection logic here
    printf("Connecting to %s...\n", s->server);
    if (/* Connection setup fails */) {
        printf("Failed to connect to %s.\n", s->server);
        return -1; // Error code for failed connection
    }
    pthread_mutex_lock(&p->mutex);
    int idx = 0;
    while (idx < p->max_connections && p->connections[idx]) {
        idx++;
    }
    if (idx >= p->max_connections) {
        printf("Connection pool is full. Cannot add more connections.\n");
        pthread_mutex_unlock(&p->mutex);
        return -1; // Error code for connection pool full
    }
    p->connections[idx] = s;
    p->current_connections++;
    pthread_mutex_unlock(&p->mutex);
    return 0; // Success
}

// Function to handle disconnection from the pool
void disconnect_from_pool(pool* p, server_info* s) {
    // TO DO: Implement actual database connection closure logic here
    printf("Disconnecting from %s...\n", s->server);
    pthread_mutex_lock(&p->mutex);
    int idx = 0;
    for (idx = 0; idx < p->max_connections; idx++) {
        if (p->connections[idx] == s) {
            break;
        }
    }
    if (idx >= p->max_connections) {
        printf("Server not found in the connection pool.\n");
        pthread_mutex_unlock(&p->mutex);
        return;
    }
    for (int i = idx; i < p->max_connections - 1; i++) {
        p->connections[i] = p->connections[i + 1];
    }
    p->connections[p->max_connections - 1] = NULL;
    p->current_connections--;
    pthread_mutex_unlock(&p->mutex);
}

int main() {
    pool* p = create_pool(MAX_CONNECTIONS);
    server_info* s1 = create_server("Server 1");
    server_info* s2 = create_server("Server 2");

    connect_to_pool(p, s1);
    connect_to_pool(p, s2);

    int active_connections = get_active_connections(p);
    printf("Number of active connections: %d\n", active_connections);

    disconnect_from_pool(p, s2);

    active_connections = get_active_connections(p);
    printf("Number of active connections after disconnection: %d\n", active_connections);

    destroy_server(s1);
    destroy_server(s2);
    destroy_pool(p);

    return 0;
}

