class RandomValueGenerator {
public:
    void initialize() {
        int_min = 0;
        int_max = 10000;
        float_min = -1.0f;
        float_max = 1.0f;
        double_min = DBL_MIN;
        double_max = DBL_MAX;
    }

    void setIntegerRange(int min, int max) {
        if (min > max)
            throw std::runtime_error("Invalid integer range");
        int_min = min;
        int_max = max;
    }

    void setFloatRange(float min, float max) {
        if (min > max)
            throw std::runtime_error("Invalid float range");
        float_min = min;
        float_max = max;
    }

    void setDoubleRange(double min, double max) {
        if (min > max)
            throw std::runtime_error("Invalid double range");
        double_min = min;
        double_max = max;
    }

    int generateRandomInteger() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<int> dis(int_min, int_max);
        return dis(gen);
    }

    float generateRandomFloat() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_real_distribution<float> dis(float_min, float_max);
        return dis(gen);
    }

    double generateRandomDouble() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_real_distribution<double> dis(double_min, double_max);
        return dis(gen);
    }

    void printRanges() {
        std::cout << "Integer range: [" << int_min << ", " << int_max << "]\n";
        std::cout << "Float range: [" << float_min << ", " << float_max << "]\n";
        std::cout << "Double range: [" << double_min << ", " << double_max << "]\n";
    }

    void insertAfter(std::forward_list<std::string>& list, const std::string& before, const std::string& after) {
        auto it = list.begin();
        for (; it != list.end() && *it != before; ++it);
        if (it == list.end())
            list.push_back(after);
        else
            list.insert_after(it, after);
    }
};

