void log_performance_metrics(const char *message, double cpu_usage, size_t memory_consumption, size_t io_operations) {
    LogEntry *entry;

    pthread_mutex_lock(&log_mutex);

    if ((time(NULL) - last_log_time) < (1.0 / LOG_RATE_LIMIT)) {
        pthread_mutex_unlock(&log_mutex);
        return; // logging rate limit exceeded
    }

    entry = (LogEntry *)malloc(sizeof(LogEntry));
    entry->level = MAX_LOG_LEVEL;
    entry->message = strdup(message);
    entry->cpu_usage = cpu_usage;
    entry->memory_consumption = memory_consumption;
    entry->io_operations = io_operations;

    log_entries = realloc(log_entries, sizeof(LogEntry) * (log_entry_count + 1));
    log_entries[log_entry_count++] = entry;

    last_log_time = time(NULL);

    pthread_mutex_unlock(&log_mutex);
}

