#define MAX_FILENAME_LENGTH 255
#define UNIQUE_IDENTIFIER_MAX_LENGTH 32

typedef enum {
    CATEGORY_UNKNOWN,
    CATEGORY_DOCUMENT,
    CATEGORY_IMAGE,
    CATEGORY_AUDIO,
    CATEGORY_VIDEO
} Category;

typedef enum {
    PRIORITY_LOW,
    PRIORITY_MEDIUM,
    PRIORITY_HIGH
} Priority;

char* extractMetadata(const char* filename);
Category getCategoryId(const char* metadata);
Priority getPriorityId(const char* metadata);
void renameFile(const char* originalFilename, const char* newFilename);

int processFilenames(char** filenames, int count) {
    pthread_t threads[count];
    pthread_attr_t attr;
    pthread_attr_init(&attr);

    for(int i = 0; i < count; i++) {
        // Extract metadata from the filename
        const char* metadata = extractMetadata(filenames[i]);

        if(metadata == NULL) {
            // Handle error, log failed operation
            printf("Error processing file %s\n", filenames[i]);
            continue;
        }

        Category categoryId = getCategoryId(metadata);
        Priority priorityId = getPriorityId(metadata);

        // Generate a unique identifier based on category and priority
        char* identifier = (char*)malloc(UNIQUE_IDENTIFIER_MAX_LENGTH + 1);
        snprintf(identifier, UNIQUE_IDENTIFIER_MAX_LENGTH, "%s-%d", categoryId == CATEGORY_UNKNOWN ? "Unknown" : categoryToName(categoryId), priorityId);

        // Create the new filename by appending the unique identifier to the original name
        char* newFilename = (char*)malloc(MAX_FILENAME_LENGTH + 1);
        strncat(newFilename, filenames[i], strlen(filenames[i]) - strlen(metadata));
        strncat(newFilename, identifier, UNIQUE_IDENTIFIER_MAX_LENGTH);

        // Rename the file
        renameFile(filenames[i], newFilename);

        free(identifier);
        free(newFilename);
    }

    pthread_attr_destroy(&attr);
    return 0;
}

// Function to extract metadata from the filename
char* extractMetadata(const char* filename) {
