import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class MD5Hasher {
    private static final String DEFAULT_HASH_ALGORITHM = "MD5";
    private static final int DEFAULT_CACHE_SIZE = 1000;

    private Map<String, byte[]> cache = new HashMap<>();
    private int cacheSize = DEFAULT_CACHE_SIZE;
    private String hashAlgorithm = DEFAULT_HASH_ALGORITHM;

    public MD5Hasher() {
        // Initialize cache with a reasonable size
        for (int i = 0; i < cacheSize; i++) {
            cache.put("", null);
        }
    }

    public String computeHash(String input) throws Exception {
        try {
            MessageDigest md = MessageDigest.getInstance(hashAlgorithm);
            byte[] hashBytes = computeHashBytes(input, md);
            return bytesToHex(hashBytes);
        } catch (NoSuchAlgorithmException e) {
            throw new Exception("Unsupported hash algorithm: " + hashAlgorithm, e);
        }
    }

    private byte[] computeHashBytes(String input, MessageDigest md) throws Exception {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }

        byte[] bytes = input.getBytes();
        byte[] hashBytes = md.digest(bytes);

        // Store the computed hash in the cache
        cache.put(input, hashBytes);

        return hashBytes;
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();

        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }

    public void clearCache() {
        cache.clear();
    }
}
