void* append_slash(char* str, size_t size_limit, void* buffer, logger_t logger) {
    // Validate size limit and check if string fits within the limit
    size_limit = (size_limit > 0) ? size_limit : (size_t)-1;
    size_t max_size = sizeof(wchar_t) * MB_CUR_MAX;
    if (size_limit > max_size || strlen(str) + 2 > size_limit) {
        logger("Error: String length exceeds size limit", "append_slash", 0);
        return NULL;
    }

    // Append slash to the end of the string
    char* new_str = buffer ? (char*)buffer : malloc(strlen(str) + 2);
    if (!new_str) {
        logger("Error: Memory allocation failed", "append_slash", 1);
        return NULL;
    }
    strcpy(new_str, str);
    strcat(new_str, "/");

    // Reset the external buffer
    free(buffer);

    return new_str;
}
