int connect_and_manage_session(const char* host, int port) {
    int sockfd = socket(AF_INET, SOCK_STREAM | SOCK_NONBLOCK, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return 0;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    inet_pton(AF_INET, host, &server_addr.sin_addr);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (connect(sockfd, (struct sockaddr*) &server_addr, sizeof(server_addr)) >= 0) {
            break; // connection established
        }
        sleep(RECONNECT_INTERVAL / 1000); // wait for reconnection
        retries++;
    }

    if (retries == MAX_RETRIES) {
        close(sockfd);
        perror("max retries exceeded");
        return 0;
    }

    pthread_t monitor_thread = pthread_self();
    pthread_create(&monitor_thread, NULL, monitor_bandwidth_usage, &sockfd);

    while (1) {
        // handle socket-related errors
        if (check_socket_error(sockfd)) {
            close(sockfd);
            perror("socket error");
            return 0;
        }

        // handle bandwidth throttling
        if (monitor_bandwidth_usage(sockfd) > BANDWIDTH_THRESHOLD) {
            throttle_bandwidth(sockfd, port);
        }
    }

    close(sockfd);

    return 1; // connection established and managed successfully
}

int check_socket_error(int sockfd) {
    int error = 0;
    socklen_t len = sizeof(error);
    getsockopt(sockfd, SOL_SOCKET, SO_ERROR, &error, &len);
    if (error > 0) {
        perror("socket error");
        return 1; // socket error detected
    }
    return 0; // no errors
}

