typedef struct {
    time_t timestamp;
    int event_type;
    char src_ip[16];
    char dst_ip[16];
    int src_port;
    int dst_port;
    size_t payload_size;
} Event;

// Data structure to store aggregated events
typedef struct {
    time_t start_time;
    time_t end_time;
    int count;
    size_t total_payload_size;
} AggregatedEvent;

AggregatedEvent *agg_events = NULL;
int agg_event_count = 0;
int current_agg_idx = -1;

void process_event(Event* event) {
    time_t now = time(NULL);
    if (event->timestamp > now - TIME_INTERVAL) {
        // Event is within the current aggregation interval
        AggregatedEvent* agg_evt = &agg_events[current_agg_idx];
        agg_evt->count++;
        agg_evt->total_payload_size += event->payload_size;
    } else {
        // New aggregation interval
        if (current_agg_idx >= 0) {
            // Previous aggregation interval has ended
            current_agg_idx = -1;
        }
        AggregatedEvent* new_agg_evt = (AggregatedEvent*)malloc(sizeof(AggregatedEvent));
        new_agg_evt->start_time = now;
        new_agg_evt->end_time = now;
        new_agg_evt->count = 1;
        new_agg_evt->total_payload_size = event->payload_size;
        agg_events = (AggregatedEvent**)realloc(agg_events, sizeof(AggregatedEvent*) * (agg_event_count + 1));
        agg_events[agg_event_count++] = new_agg_evt;
        current_agg_idx = agg_event_count - 1;
    }
}

void free_agg_events() {
    for (int i = 0; i < agg_event_count; i++) {
        free(agg_events[i]);
    }
    free(agg_events);
}
