// Crypto library for DES, AES in GCM mode
#include "des-crypto.h"
#include "aes-gcm-crypto.h"

// JSON parsing library
#include "json-parser.h"

// OAuth2 access token response validation
int validate_access_token(const char* json_string) {
    // Parse the JSON string
    json_t* root = json_parse(json_string);

    if (!root) {
        return 1; // Fail: Invalid or missing JSON
    }

    // Validate fields
    int has_token_type = json_object_get(root, "token_type") ? 1 : 0;
    int has_expires_in = json_integer_get(root, "expires_in");
    int has_access_token = json_string_get(root, "access_token");
    int has_refresh_token = json_object_get(root, "refresh_token") ? 1 : 0;

    // Check fields
    if (!has_token_type || !json_string_equal(json_object_get(root, "token_type"), "Bearer")) {
        return 2; // Fail: Invalid token type
    }
    if (has_expires_in && !json_integer_get_value(root, "expires_in") > 0) {
        return 3; // Fail: Invalid expires in value
    }

    // Success: Valid access token response
    return 0;
}

int main() {
    const char* json_string = "{\"access_token\":\"your_access_token\",\"token_type\":\"Bearer\",\"expires_in\":300,\"refresh_token\":\"your_refresh_token\"}";
    int result = validate_access_token(json_string);

    if (result == 0) {
        printf("Valid access token response\n");
    } else if (result == 1) {
        printf("Invalid or missing JSON: %d\n", result);
    } else if (result == 2 || result == 3) {
        printf("Invalid token type/token expires in value: %d\n", result);
    }

    return 0;
}
