    // Read configuration settings from file or environment variables
    FILE* conf = fopen("config.txt", "r");
    if (conf == NULL) {
        printf("Failed to open configuration file\n");
        return NULL;
    }

    int max_connections = 1000; // default value
    fgets((char*)&max_connections, sizeof(max_connections), conf);
