    connection* connections = (connection*)malloc(N * sizeof(connection));
    if (connections == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        connections[i].id = i;
        time_t timestamp = time(NULL);
        strcpy(connections[i].status, "active");

        // Validate connection data
        if (validate_connection(&connections[i])) {
            printf("Invalid connection data: %d\n", i);
            return NULL;
        }

        // Compress and marshal connection data
        char* compressed_data = compress_connection(&connections[i]);
        if (compressed_data == NULL) {
            printf("Failed to compress connection data\n");
            free(connections);
            return NULL;
        }

        // Send compressed data over socket
        int sockfd = create_socket();
        send(sockfd, compressed_data, strlen(compressed_data), 0);
        close(sockfd);

        // Log creation timestamp and size of each structure
        printf("Created connection %d at %lu with size %d\n", i, timestamp, sizeof(connection));
    }

    return connections;
}

