    if (N > MAX_SIZE || N < 1) return NULL; // validate input

    void* pool = malloc(MEMORY_POOL_SIZE);
    if (!pool) return NULL; // handle memory allocation failure

    int struct_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
    int total_size = N * struct_size;

    if (total_size > MEMORY_POOL_SIZE) {
        free(pool);
        pool = malloc(total_size + (sizeof(void*) * 2)); // allocate custom memory pool
        if (!pool) return NULL; // handle memory allocation failure
    }

    NFAPI_CRC_INDICATION_PDU_T* structs = pool;
