#include <pthread.h>

#define MAX_SIZE 1024
#define MAX_ITEMS 1000

typedef struct item {
    char* description;
    float priority;
    bool active;
} Item;

typedef struct entry {
    char* key;
    double value;
    Item* item;
} Entry;

Entry* update_entry(char* key, char* body) {
    pthread_mutex_lock(&mutex);

    // Allocate memory for the entry array
    size_t total_entries = (size_t)(rand() % MAX_ITEMS);
    size_t* timestamps = calloc(total_entries, sizeof(size_t));
    char** keys = calloc(total_entries, sizeof(char*));
    double* values = calloc(total_entries, sizeof(double));
    Item** items = calloc(total_entries, sizeof(Item*));

    // Initialize the entry array
    for (size_t i = 0; i < total_entries; i++) {
        timestamps[i] = time(NULL);
        keys[i] = malloc(MAX_SIZE);
        values[i] = rand() % 100.0;
        items[i] = malloc(sizeof(Item));
        items[i]->description = malloc(MAX_SIZE);
        items[i]->priority = (float)rand() / RAND_MAX;
        items[i]->active = true;

        // Check for unique keys, size threshold, and numerical value sum
        if (strlen(keys[i]) >= MAX_SIZE || values[i] > 100.0) {
            free(keys[i]);
            free(items[i]->description);
            free(items[i]);
            free(values);
            free(items);
            free(timestamps);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    // Update the existing entry
    for (size_t i = 0; i < total_entries; i++) {
        if (strcmp(keys[i], key) == 0) {
            values[i] = atof(body);
            break;
        }
    }

    Entry* updated_entry = malloc(sizeof(Entry));
    updated_entry->key = keys[0];
    updated_entry->value = values[0];
    updated_entry->item = items[0];

    pthread_mutex_unlock(&mutex);

    return updated_entry;
}

void delete_entry(char* key) {
    pthread_mutex_lock(&mutex);

    // Find and free the entry
    for (size_t i = 0; i < total_entries; i++) {
        if (strcmp(keys[i], key) == 0) {
            free(keys[i]);
            free(items[i]->description);
            free(items[i]);
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
    pthread_mutex_init(&mutex, NULL);

    // Test the update_entry function
    char* body = "50.0";
    Entry* updated_entry = update_entry("my_key", body);
    if (updated_entry) {
        printf("%s\n", updated_entry->key);
        printf("%.2f\n", updated_entry->value);
        printf("%s\n", updated_entry->item->description);
        free(updated_entry);
    }

    // Test the delete_entry function
    delete_entry("my_key");

    return 0;
}
