            strcpy(entries[i].item_ptr->description, body);
            entries[i].item_ptr->priority = atof(body);
            entries[i].item_ptr->active = true;

            return &entries[i];
        }
    }

    // If the entry does not exist in the cache, create a new one
    size_t i = 0;
    while (i < cache_size_limit && strcmp(keys[i], key) != 0) {
        i++;
    }
    if (i == cache_size_limit) {
        // Allocate memory for a new entry
        entries[i].key = malloc(strlen(key) + 1);
        strcpy(entries[i].key, key);
        entries[i].value = atof(body);
        entries[i].item_ptr = malloc(sizeof(item));
        strcpy(entries[i].item_ptr->description, body);
        entries[i].item_ptr->priority = atof(body);
        entries[i].item_ptr->active = true;

        return &entries[i];
    } else {
        // If the entry already exists in the cache, update it
        entries[i].key = malloc(strlen(key) + 1);
        strcpy(entries[i].key, key);
        entries[i].value = atof(body);
        entries[i].item_ptr = malloc(sizeof(item));
        strcpy(entries[i].item_ptr->description, body);
        entries[i].item_ptr->priority = atof(body);
        entries[i].item_ptr->active = true;

        return &entries[i];
    }
}

