void initialize_rx_frames(int num_frames) {
    NFAPI_RX_FRAME_T* frames = NULL;
    int i, alloc_size, error = 0;

    // Allocate memory for the structures
    alloc_size = sizeof(NFAPI_RX_FRAME_T) * num_frames;
    frames = malloc(alloc_size);
    if (!frames) {
        printf("Memory allocation failed!\n");
        return;
    }

    srand(time(NULL)); // Seed random number generator

    for (i = 0; i < num_frames; i++) {
        NFAPI_RX_FRAME_T* frame = &frames[i];
        frame->valid_tag = i + 1; // Assign a valid RRC_RX_FRAME_TAG
        frame->stream_tag = malloc(strlen("stream_tag") + 1);
        strcpy(frame->stream_tag, "stream_tag");
        frame->snr_value = (float)rand() / RAND_MAX;
    }

    if (num_frames > 0) {
        // Release any remaining memory for unallocated frames
        free(frames[num_frames - 1].stream_tag);
    }

    free(frames);

    return;
}

int main(int argc, char* argv[]) {
    int num_frames = atoi(argv[1]);
    initialize_rx_frames(num_frames);
    return 0;
}
