typedef void (*Logger)(const char*, int, const char*);

char* append_slash(const char* str, size_t size_limit, char* buffer, Logger logger, int concurrency) {
    if (size_limit > SIZE_MAX || !str) return NULL;
    size_t len = strlen(str);
    if (len + 1 > size_limit) {
        logger("Error: String too long", -1, "append_slash");
        return NULL;
    }
    if (!buffer) buffer = malloc(size_limit * sizeof(char));
    else memset(buffer, '\0', size_limit);

    strcat(buffer, str);
    strcat(buffer, "/");

    return buffer;
}

void log_function_call(const char* message, int error_code, const char* function_name) {
    printf("Logger: %s - Error code: %d - Function: %s\n", message, error_code, function_name);
}
