void process_directory(const char* dir_path) {
    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        // Handle error
        return;
    }

    struct dirent* ent;
    Metadata* metadata;
    char new_filename[256];
    int id = 1;

    while ((ent = readdir(dir)) != NULL) {
        metadata = parse_metadata(ent->d_name);

        if (metadata == NULL) {
            // Handle invalid metadata
            continue;
        }

        // Check available disk space before renaming
        struct stat statbuf;
        stat(buf, &statbuf);
        if (statbuf.st_blocks * 512 < 1024 * 1024) {
            // Handle insufficient disk space
            break;
        }

        sprintf(new_filename, "%s_%d", metadata->category, id);

        while (strlen(new_filename) + strlen(metadata->attribute) > 255) {
            strncat(new_filename, "_", 1);
            id++;
        }

        snprintf(new_filename + strlen(new_filename), 256 - strlen(new_filename), "%s_%d", generate_identifier(id, 6), metadata->priority);

        // Log renaming operation
        printf("Renaming '%s' to '%s'\n", ent->d_name, new_filename);

        // Rename the file using your existing file management system
    }

    closedir(dir);
}

int main() {
    process_directory("/path/to/directory");
    return 0;
