int find_largest(int* arr, int n) {
    int max = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

LTE_Phy_Layer_PDU* create_pdu_array(int N) {
    LTE_Phy_Layer_PDU* pdu_arr = (LTE_Phy_Layer_PDU*)custom_malloc(N * sizeof(LTE_Phy_Layer_PDU));
