typedef struct {
    int cellId;
    double signalStrength;
} LTE_MEASUREMENTS_REPORT;

void lteMeasurementsReportList_init(LTE_MEASUREMENTS_REPORT **list) {
    *list = NULL;
}

int lteMeasurementsReportList_insert(LTE_MEASUREMENTS_REPORT **list, LTE_MEASUREMENTS_REPORT *newMeasurement) {
    LTE_MEASUREMENTS_REPORT *head = *list;
    if (*list == NULL) {
        *list = newMeasurement;
    } else {
        for (LTE_MEASUREMENTS_REPORT *current = head; current->next != NULL; current = current->next) {
            if (newMeasurement->cellId > current->next->cellId) {
                newMeasurement->next = current->next;
                current->next = newMeasurement;
                return 1;
            }
        }
        newMeasurement->next = NULL;
        head->next = newMeasurement;
    }
    return 0;
}

LTE_MEASUREMENTS_REPORT *lteMeasurementsReportList_remove(LTE_MEASUREMENTS_REPORT **list, int cellId) {
    LTE_MEASUREMENTS_REPORT *head = *list;
    if (*list != NULL) {
        if ((*list)->cellId == cellId) {
            LTE_MEASUREMENTS_REPORT *temp = *list;
            *list = (*list)->next;
            temp->next = NULL;
            return temp;
        }
        for (LTE_MEASUREMENTS_REPORT *current = head; current->next != NULL; current = current->next) {
            if (current->next->cellId == cellId) {
                LTE_MEASUREMENTS_REPORT *temp = current->next;
                current->next = current->next->next;
                temp->next = NULL;
                return temp;
            }
        }
    }
    return NULL;
}

LTE_MEASUREMENTS_REPORT *lteMeasurementsReportList_find(LTE_MEASUREMENTS_REPORT **list, int cellId) {
    LTE_MEASUREMENTS_REPORT *head = *list;
    if (*list != NULL) {
        for (LTE_MEASUREMENTS_REPORT *current = head; current->next != NULL; current = current->next) {
            if (current->next->cellId == cellId) {
                return current->next;
            }
        }
    }
    return NULL;
}

void lteMeasurementsReportList_free(LTE_MEASUREMENTS_REPORT **list) {
    LTE_MEASUREMENTS_REPORT *head = *list;
    while (*list != NULL) {
        LTE_MEASUREMENTS_REPORT *temp = *list;
        *list = (*list)->next;
        free(temp);
    }
}

