#include <unistd.h>
#include <pthread.h>

#define MEMORY_POOL_SIZE 1024
#define MAX_PACKET_HEADER_SIZE 1024
#define COMPRESSION_THRESHOLD 0.8

typedef struct {
    uint64_t timestamp;
    uint32_t cell_id;
    uint16_t rb_id;
    uint16_t phy_stats_tag;
    float channel_quality_indicator;
} PHY_STATS_RECORD_T;

pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("memory_log.txt", "w");

void* phy_stats_record_allocator(int size, bool compress) {
    void* buffer = NULL;

    if (size > MEMORY_POOL_SIZE) {
        fprintf(log_file, "Requested memory allocation exceeds pool size.\n");
        return NULL;
    }

    if ((buffer = malloc(size)) == NULL) {
        fprintf(log_file, "Memory allocation failed. Insufficient resources.\n");
        return NULL;
    }

    if (compress && size > 0) {
        int compressed_size = compress_data(buffer, size);
        buffer = realloc(buffer, compressed_size);
    }

    pthread_mutex_lock(&log_mutex);
    fprintf(log_file, "Allocated %d bytes at address %p.\n", size, buffer);
    pthread_mutex_unlock(&log_mutex);

    return buffer;
}

void phy_stats_record_deallocator(void* ptr) {
    if (ptr == NULL) {
        return;
    }

    free(ptr);

    pthread_mutex_lock(&log_mutex);
    fprintf(log_file, "Deallocated %p.\n", ptr);
    pthread_mutex_unlock(&log_mutex);
}

int main() {
    int size = 0;

    printf("Enter the desired array size: ");
    scanf("%d", &size);

    // Ensure memory safety by validating the input size
    if (size > MEMORY_POOL_SIZE) {
        fprintf(log_file, "Buffer overflow detected. Reducing allocation to %d bytes.\n", MEMORY_POOL_SIZE);
        size = MEMORY_POOL_SIZE;
    }

    // Allocate memory for an array of structures
    void* ptr = phy_stats_record_allocator(size * sizeof(PHY_STATS_RECORD_T), false);

    if (ptr == NULL) {
        return -1;  // Allocation failed, exit the program
    }

    // Perform operations on the allocated data

    // Deallocate the memory when no longer needed
    phy_stats_record_deallocator(ptr);

    fclose(log_file);
    return 0;
}
