        int param_len = strlen(token);
        int query_len = strlen(token);
        if(strncmp(token, "param=", 6) == 0) {
            query_len -= 6;
            for(int i = 6; i < param_len; i++) {
                if((token[i] >= 'a' && token[i] <= 'z') || (token[i] >= 'A' && token[i] <= 'Z') || (token[i] >= '0' && token[i] <= '9') || token[i] == '-') continue;
                token[i] = '%';
                int val = token[i + 1];
                token[++i] = sprintf("%02x", val) ? '%' : '0';
                i++;
            }
        }
        char* value = (char*)malloc(param_len);
        strcpy(value, token);
        for(int j = param_len - 1; j >= 0; j--) {
            if((value[j] >= 'a' && value[j] <= 'z') || (value[j] >= 'A' && value[j] <= 'Z') || (value[j] >= '0' && value[j] <= '9') || value[j] == '-') continue;
            value[j] = '%';
            int val = value[j + 1];
            char* temp = (char*)malloc(3);
            sprintf(temp, "%02x", val);
            strcat(value, temp);
            free(temp);
        }
        if(strncmp(token, "param=", 6) == 0) {
            strcat(new_url, "?");
            strcat(new_url, value);
        } else {
            if(strlen(new_url) > 1 && new_url[strlen(new_url) - 1] != '/') {
                strcat(new_url, "/");
            }
            strcat(new_url, value);
        }
        free(value);
        token = strtok(NULL, "/+");
    }
    return new_url;
