char* appendQueryParameters(char* inputUrl) {
    // Find the last '/' character to determine the path segments
    char* pathEnd = strrchr(inputUrl, '/');

    if (!pathEnd) {
        return strdup(inputUrl);
    }

    // Extract the path and query strings
    char* path = strndup(inputUrl, pathEnd - inputUrl);
    char* queryStart = strchr(pathEnd, '?');
    char* query;
    size_t queryLen;

    if (queryStart) {
        query = queryStart + 1;
        queryLen = strlen(queryStart);
    } else {
        query = "";
        queryLen = 0;
    }

    // Encode the query string
    char* encodedQuery = malloc(strlen(query) * 3 + 1); // URL-encoded query can be up to twice as long
    size_t encodedQueryIndex = 0;

    for (size_t i = 0; i < queryLen; ++i) {
        if (strchr("%;/?<>{}|[]()^`", query[i])) { // Special characters that need encoding
            encodedQuery[encodedQueryIndex++] = '%';
            sprintf(&encodedQuery[encodedQueryIndex], "%02x", (unsigned char)query[i]);
        } else {
            encodedQuery[encodedQueryIndex++] = query[i];
        }
    }

    encodedQuery[encodedQueryIndex] = '\0';

    // Construct the new URL
    size_t urlLen = strlen(inputUrl);
    char* returnUrl = malloc(urlLen + strlen(encodedQuery) + 2); // Additional space for '?' and '\0'
    sprintf(returnUrl, "%s?%s", path, encodedQuery);

    free(path);
    free(encodedQuery);

    return returnUrl;
}

