char *append_query_params(char *url) {
    // Parse URL into path segments and query parameters
    char *path = strtok(url, "?");
    char *query = strtok(NULL, "?");

    // Check for valid input
    if (!path || !query)
        return NULL;

    // Allocate memory for the new URL string
    size_t len = strlen(path) + strlen(query) + 1;
    char *new_url = (char *)malloc(len);
    if (!new_url)
        return NULL;

    // Encode special characters in query parameters
    char *param = strtok(query, "&");
    while (param) {
        char *key = strtok(param, "=");
        char *value = param + strlen(key) + 1;
        param += strlen(key) + strlen("=") + 1;
        if (*param)
            param -= 2;

        // Encode special characters in key and value
        size_t new_len = strlen(key) + strlen(value) + 3;
        char *encoded_key = (char *)malloc(new_len);
        char *encoded_value = (char *)malloc(new_len);
        if (!encoded_key || !encoded_value)
            return NULL;

        sprintf(encoded_key, "%%%02x", (unsigned char)key[0]);
        sprintf(encoded_value, "%%%02x", (unsigned char)value[0]);

        // Build new query parameter
        size_t encoded_len = strlen(encoded_key) + strlen(encoded_value);
        char *encoded_param = (char *)malloc(encoded_len + 2);
        if (!encoded_param)
            return NULL;

        sprintf(encoded_param, "%s=%s", encoded_key, encoded_value);

        // Append to new URL string
        size_t pos = strlen(new_url);
        strcpy(&new_url[pos], "?" ? "" : ";");
        strcpy(&new_url[pos + 1], encoded_param);
        free(encoded_param);
        free(encoded_key);
        free(encoded_value);

        param = strtok(NULL, "&");
    }

    // Return the new URL string
    return new_url;
}
