#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_URL_LENGTH 1024
#define MAX_QUERY_PARAM 256
#define URL_ENCODING "UTF-8"

char* append_query_params(const char* url) {
    // Parse the URL to extract path segments and query parameters
    char* parsed_url = (char*)malloc(MAX_URL_LENGTH);
    strcpy(parsed_url, url);

    // Find the first '?' character in the URL string
    int pos = strcspn(parsed_url, "?");
    if (pos > 0) {
        parsed_url[pos] = '\0'; // Terminate the path segments at the '?' character

        // Extract query parameters from the remaining URL string
        char* query_params = &parsed_url[pos + 1];
        size_t param_count = 0;
        while (*query_params && isspace((unsigned int)*query_params)) {
            query_params++;
        }
        char* param_start = query_params;
        while (*query_params) {
            if (isspace((unsigned int)*query_params) || *query_params == '=') {
                // Encode the query parameter and append to a new string
                size_t encoded_len = strlen(param_start);
                char* encoded_param = (char*)malloc(encoded_len + 2); // Include space for '=' sign
                strcpy(encoded_param, param_start);
                if (*query_params == '=') {
                    encoded_param[encoded_len++] = '='; // Add the '=' sign
                }
                size_t i;
                for (i = 0; *query_params && !isspace((unsigned int)*query_params); query_params++) {
                    if (!isalnum((unsigned int)*query_params) || *query_params == '.') {
                        encoded_param[encoded_len++] = '%';
                        sprintf(&encoded_param[encoded_len], "%02X", (int)(unsigned char)*query_params);
                        encoded_len += 2;
                    } else {
                        encoded_param[encoded_len++] = *query_params;
                    }
                }
                encoded_param[encoded_len] = '\0';

                // Append the new query parameter to a buffer
                char* query_buffer = (char*)malloc(MAX_QUERY_PARAM);
                if (!param_count) {
                    strcpy(query_buffer, encoded_param);
                } else {
                    strcat(strcat(query_buffer, "&"), encoded_param);
                }
                free(encoded_param);

                param_start = query_params;
                param_count++;
            } else {
                query_params++;
            }
        }

        // Construct the new URL by appending query parameters
        char* new_url = (char*)malloc(MAX_URL_LENGTH);
        strcpy(new_url, parsed_url);
        strcat(new_url, "?");
        strcat(strcat(new_url, query_buffer), encoded_len ? "&" : "");

        free(parsed_url);
        free(query_buffer);

        return new_url;
    } else {
        // No '?' character found; return the original URL
        return strdup(url);
    }
}

int main() {
    const char* url = "http://example.com/path?a=1&b=2";
    char* new_url = append_query_params(url);
    printf("%s\n", new_url);
    free(new_url);

    return 0;
}
