#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_URL_LENGTH 2048
#define MAX_QUERY_PARAMS 256
#define CACHE_SIZE 128

typedef struct {
    char* key;
    char* value;
} CacheEntry;

typedef struct {
    CacheEntry entries[CACHE_SIZE];
    int size;
} Cache;

Cache cache = {{0}};

void append_query_param(char* url, char* param) {
    // URL-encode the parameter
    char* encoded_param = malloc(strlen(param) * 2 + 1);
    for (int i = 0; i < strlen(param); i++) {
        if (strchr("=&?", param[i]) != NULL) {
            sprintf(encoded_param, "%%%02x", param[i]);
            encoded_param += strlen(encoded_param);
        } else {
            strcpy(encoded_param + strlen(encoded_param), &param[i]);
        }
    }

    // Append the parameter to the URL
    char* new_url = malloc(strlen(url) + strlen(encoded_param) + 2);
    sprintf(new_url, "%s?%s", url, encoded_param);
    free(encoded_param);
    free(url);
    *new_url = '\0';
}

char* construct_url(char* path) {
    // Parse the URL path
    char* protocol = strtok(path, ":");
    char* domain = strtok(NULL, "/");
    char* path_segments[] = {strtok(NULL, "/"), NULL};

    // Construct the query parameters
    char* query_params[MAX_QUERY_PARAMS];
    int param_count = 0;
    for (int i = 0; path_segments[i] != NULL; i++) {
        if (strlen(path_segments[i]) > 1) {
            for (int j = 0; path_segments[i][j]; j++) {
                if (path_segments[i][j] == '=') {
                    query_params[param_count] = malloc(strlen(path_segments[i]) - j + 2);
                    strcpy(query_params[param_count], &path_segments[i][j + 1]);
                    param_count++;
                    break;
                }
            }
        }
    }

    // Cache the URL
    char* cached_key = malloc(strlen(protocol) + strlen(domain) + strlen(path) + 20);
    sprintf(cached_key, "%s://%s/%s?", protocol, domain, path);
    for (int i = 0; i < param_count; i++) {
        strcat(cached_key, query_params[i]);
        free(query_params[i]);
    }
    if (!cache_check(cache, cached_key)) {
        // Append the query parameters
        char* new_url = malloc(MAX_URL_LENGTH + 1);
        sprintf(new_url, "%s", protocol);
        strcat(new_url, "://");
        strcat(new_url, domain);
        strcat(new_url, "/");
        for (int i = 0; i < path_segments[0]; i++) {
            if (path_segments[i] != NULL) {
                strcat(new_url, path_segments[i]);
                strcat(new_url, "/");
            }
        }
        char* param_str = malloc(param_count * sizeof(char *));
        for (int i = 0; i < param_count; i++) {
            strcat(param_str, query_params[i]);
            free(query_params[i]);
        }
        strcat(new_url, param_str);
        free(param_str);

        // Update the cache
        CacheEntry entry;
        entry.key = cached_key;
        entry.value = new_url;
        cache_insert(cache, &entry);
    } else {
        // Retrieve the cached URL
        char* new_url = malloc(strlen(cached_key) + 1);
        strcpy(new_url, cache_get_value(cache, cached_key));
    }

    return new_url;
}

int main() {
    char* path = "https://example.com/path/to/resource?=param1&param2";
    char* url = construct_url(path);
    printf("%s\n", url);

    // Test the URL construction and caching
    for (int i = 0; i < 10; i++) {
        char* new_path = malloc(strlen(path) + 5);
        sprintf(new_path, "%s?new_param=%d", path, i);
        char* new_url = construct_url(new_path);
        printf("%s\n", new_url);
        free(new_url);
    }

    return 0;
}

// Cache functions
int cache_check(Cache cache, char* key) {
    for (int i = 0; i < cache.size; i++) {
        if (!strcmp(cache.entries[i].key, key)) {
            return 1;
        }
    }
    return 0;
}

void cache_insert(Cache cache, CacheEntry* entry) {
    // Check if the cache is full
    if (cache.size == CACHE_SIZE) {
        // Evict the least recently used item
        int i = 0;
        for (; i < cache.size; i++) {
            if (!strcmp(cache.entries[i].key, entry->key)) {
                break;
            }
        }
        free(cache.entries[i].value);
    }

    cache.entries[cache.size] = *entry;
    cache.size++;
}

char* cache_get_value(Cache cache, char* key) {
    for (int i = 0; i < cache.size; i++) {
        if (!strcmp(cache.entries[i].key, key)) {
            return cache.entries[i].value;
        }
    }
    return NULL;
}
