import java.net.URI;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;

public class URLConstructor {

    public static URI constructURL(String url) {
        try {
            URI originalURI = new URI(url);
            String path = originalURI.getPath();
            List<String> pathSegments = Arrays.asList(path.split("/"));
            Map<String, String> queryMap = new HashMap<>();

            for (String segment : pathSegments) {
                if (segment.startsWith("query=")) {
                    String[] keyValue = segment.substring(6).split(",");
                    for (String pair : keyValue) {
                        String[] keyValuePart = pair.split("=");

                        if (keyValuePart.length == 2) {
                            queryMap.put(keyValuePart[0], URLDecoder.decode(keyValuePart[1], "UTF-8"));
                        }
                    }
                }
            }

            StringBuilder newURIPath = new StringBuilder();
            for (String segment : pathSegments) {
                if (!segment.startsWith("query=")) {
                    newURIPath.append(segment).append("/");
                }
            }

            if (newURIPath.length() > 0) {
                newURIPath.deleteCharAt(newURIPath.length() - 1);
            }

            StringBuilder newURIPart = new StringBuilder();
            for (Map.Entry<String, String> entry : queryMap.entrySet()) {
                newURIPart.append("query=").append(entry.getKey()).append("=").append(entry.getValue()).append(",");
            }
            if (newURIPart.length() > 0) {
                newURIPart.deleteCharAt(newURIPart.length() - 1);
            }

            String newPath = newURIPath.toString();
            String query = newURIPart.toString();

            return new URI("path=" + newPath + "&query=" + query);

        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
