#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define a struct to represent a URL
typedef struct {
    char* protocol;
    char* host;
    int port;
    char* path;
    char* query;
} URL;

// Function to construct a new URL by appending query parameters based on the existing path segments of an input URL string
URL* construct_url(const char* input_url) {
    // Initialize the URL struct with default values
    URL* url = (URL*)malloc(sizeof(URL));
    url->protocol = NULL;
    url->host = NULL;
    url->port = 0;
    url->path = NULL;
    url->query = NULL;

    // Parse the input URL and extract its components
    char* token = strtok(input_url, "://");
    if (token) {
        url->protocol = strdup(token);
    }
    token = strtok(NULL, "/");
    if (token) {
        url->host = strdup(token);
    }
    token = strtok(NULL, ":");
    if (token) {
        int port = atoi(token);
        url->port = port;
    }

    // Extract the path and query parameters
    char* remaining = NULL;
    if (strtok(NULL, "?") == NULL) {
        remaining = strdup(input_url + strlen(url->protocol) + strlen(url->host) + strlen(url->path));
    } else {
