#define MAX_ENTRY_SIZE 1024
#define MAX_NUMERICAL_VALUE 1000.0
#define MAX_CACHE_SIZE (1 << 20) // 1MB

typedef struct item {
    char* description;
    float priority;
    bool active;
} item_t;

typedef struct entry {
    char* key;
    double numerical_value;
    item_t* item;
} entry_t;

// Thread-safe logging function
void log(const char* message) {
    int fd = open("log.txt", O_WRONLY | O_APPEND, 0666);
    write(fd, message, strlen(message));
    close(fd);
}

int update_cache_entry(char* key, char* body) {
    // Initialize memory allocation limit
    size_t cache_size_limit = MAX_CACHE_SIZE;

    // Initialize dynamic arrays
    size_t* timestamps;
    char** keys;
    double* numerical_values;
    item_t** items;
    int* error_codes;

    if (posix_malloctimes(timestamps, cache_size_limit / sizeof(size_t)) ||
        posix_malloc(keys, cache_size_limit / sizeof(char*)) ||
        posix_malloc(numerical_values, cache_size_limit / sizeof(double)) ||
        posix_malloc(items, cache_size_limit / sizeof(item_t*))) {
        log("Memory allocation failed\n");
        return -1;
    }

    // Initialize entry structures
    entry_t* entries;
    if (posix_mallocentries(entries, cache_size_limit / sizeof(entry_t))) {
        log("Memory allocation failed\n");
        return -1;
    }

    // Update existing cache entry using the HTTP PUT method
    int i = 0;
    while (entries[i].key != NULL) {
        if (!strcmp(key, entries[i].key)) {
            // Validate new data against size and numerical value limits
            if (strlen(body) > MAX_ENTRY_SIZE || atof(body) > MAX_NUMERICAL_VALUE) {
                log("Invalid request body\n");
                return -1;
            }
            // Update existing entry with new values
            entries[i].numerical_value = atof(body);
            break;
        }
        i++;
    }

    if (i == sizeof(entries) / sizeof(entry_t)) {
        log("Key not found in cache\n");
        return -1;
    }

    return 0;
}

int delete_cache_entry(char* key) {
    // Initialize memory allocation limit
    size_t cache_size_limit = MAX_CACHE_SIZE;

    // Initialize dynamic arrays
    size_t* timestamps;
    char** keys;
    double* numerical_values;
    item_t** items;
    int* error_codes;

    if (posix_malloctimes(timestamps, cache_size_limit / sizeof(size_t)) ||
        posix_malloc(keys, cache_size_limit / sizeof(char*)) ||
        posix_malloc(numerical_values, cache_size_limit / sizeof(double)) ||
        posix_malloc(items, cache_size_limit / sizeof(item_t*))) {
        log("Memory allocation failed\n");
        return -1;
    }

    // Initialize entry structures
    entry_t* entries;
    if (posix_mallocentries(entries, cache_size_limit / sizeof(entry_t))) {
        log("Memory allocation failed\n");
        return -1;
    }

    int i = 0;
    while (entries[i].key != NULL) {
        if (!strcmp(key, entries[i].key)) {
            // Reset entry with default values
            entries[i].numerical_value = 0.0;
            entries[i].item->description = "";
            entries[i].item->priority = 0.0f;
            entries[i].item->active = false;
            break;
        }
        i++;
    }

    if (i == sizeof(entries) / sizeof(entry_t)) {
        log("Key not found in cache\n");
        return -1;
    }

    return 0;
}
