#include <pthread.h>

// Structure to represent a command
typedef struct {
    char* command;
    int timeout;
} Command;

// Function to execute a command in a separate process group
void exec_command(Command cmd) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execlp("/bin/bash", "/bin/bash", "-c", cmd.command, NULL);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status)) {
            if (cmd.timeout != 0 && WEXITSTATUS(status) > cmd.timeout) {
                kill(getpid(), SIGKILL);
            }
        } else {
            kill(getpid(), SIGKILL);
        }
    } else {
        // Error forking the process
        perror("fork");
    }
}

// Function to generate and execute a series of commands
void execute_commands(int N, Command* commands) {
    for (int i = 0; i < N; i++) {
        exec_command(commands[i]);
    }
}

// Function to handle signal interruptions
void sig_handler(int signum) {
    printf("Signal received: %d\n", signum);
    // Handle the signal accordingly
    // For example, you can exit the program if a SIGINT is received
    if (signum == SIGINT) {
        printf("Exiting...\n");
        exit(0);
    }
}

// Function to create and manage the command list
void* create_command_list(int N, void** commands) {
    // Allocate memory for the command list
    *commands = malloc(N * sizeof(Command));
    if (*commands == NULL) {
        perror("malloc");
    } else {
        return *commands;
    }
}

// Function to manage concurrent access and modification of the command list
void* create_lock(void** lock) {
    // Initialize a mutex for locking
    pthread_mutex_init(lock, NULL);
    return *lock;
}

int main(int argc, char* argv[]) {
    int N = 5; // Number of commands
    Command* commands = NULL;
    void* command_lock = NULL;

    create_command_list(N, &commands);

    for (int i = 0; i < N; i++) {
        // Initialize a new command with the desired parameters
        Command cmd = {"command_name", 10}; // Replace "command_name" and 10 with your actual values
        commands[i] = cmd;
    }

    create_lock(&command_lock);

    execute_commands(N, commands);

    return 0;
}
