#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "validation.h"

// Forward declaration of struct NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate and populate a thread-safe list of NFAPI_CRC_INDICATION_PDU_T structures
void* generateNfarcrcList(int size) {
    // Initialize the list with NULL
    void* list = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (list == NULL) {
        return NULL;
    }

    // Initialize the head of the list to NULL
    NFAPI_CRC_INDICATION_PDU_T** head = &((NFAPI_CRC_INDICATION_PDU_T**)list);
    *head = NULL;

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (new_element == NULL) {
            free(list);
            return NULL;
        }

        // Randomly set RNTI and CRCFLAG
        rand_r(&i, &new_element->rnti);
        new_element->crcflag = rand() % 2;

        // Validate the CRC_INDICATION_REL8_TAG value
        if (!validate_crc_indication_rel8_tag(new_element->crc_indication_rel8_tag)) {
            free(list);
            return NULL;
        }

        // Check if the RNTI already exists in the list
        NFAPI_CRC_INDICATION_PDU_T** current = head;
        while (*current != NULL) {
            if ((*current)->rnti == new_element->rnti) {
                free(new_element);
                free(list);
                return NULL;
            }
            current = &((*current)->next);
        }

        // Add the new element to the list
        *head = malloc((size_t)(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * 2));
        ((NFAPI_CRC_INDICATION_PDU_T**)list)[i] = new_element;
    }

    free(list);
}

// Java method to calculate MD5 hash of a string
public String calculateMD5Hash(String input) {
    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] bytes = md.digest(input.getBytes());

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < bytes.length; i++) {
            sb.append(Integer.toHexString((bytes[i] & 0xFF) | 0x100));
        }

        return sb.toString();
    } catch (Exception e) {
        return null;
    }
}

