#define MAX_NFARCRC_LIST_SIZE 1024
#define CRCINDICATIONREL8_TAG_VALID_RANGE {0x0001, 0x0102}

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    CRCFLAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void* generateNfarcrcList(int size) {
    NFAPI_CRC_INDICATION_PDU_T* nfarcrc_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfarcrc_list) return NULL;

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* current = &nfarcrc_list[i];
        current->rx_ue_info = (RX_UE_INFORMATION_TAG){rand() % RAND_MAX};
        current->rnti = (RNTI)(rand() % RAND_MAX);
        while (current->rnti == nfarcrc_list[(i - 1) % size].rnti) {
            current->rnti = (RNTI)(rand() % RAND_MAX);
        }
        if (CRCINDICATIONREL8_TAG_VALID_RANGE.min <= current->crc_indication_rel8_tag && current->crc_indication_rel8_tag <= CRCINDICATIONREL8_TAG_VALID_RANGE.max)
            current->crcflag = (CRCFLAG){rand() % RAND_MAX};
        else {
            printf("Invalid CRC_INDICATION_REL8_TAG value. Skipping this entry.\n");
            return NULL;
        }
    }

    return nfarcrc_list;
}

int calculateMD5Hash(char* str) {
    unsigned char md5[16];
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, (unsigned char*)str, strlen(str));
    MD5Final(md5, &ctx);
    return 0;
}
