} ImageMetadata;

ImageMetadata* image_processing_pipeline(char* directory_path) {
    // Create a thread-safe queue to distribute tasks among worker threads
    pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t queue_signal = PTHREAD_COND_INITIALIZER;
    struct {
        pthread_mutex_t lock;
        int count;
        ImageMetadata** queue;
    } queue;

    queue.count = 0;
    queue.queue = (ImageMetadata**)malloc(sizeof(ImageMetadata*) * 10);

    // Initialize worker threads
    pthread_t* workers;
    int num_workers = 4;
    workers = (pthread_t*)malloc(num_workers * sizeof(pthread_t));

    for(int i = 0; i < num_workers; i++) {
        pthread_create(&workers[i], NULL, process_image, &queue);
    }

    // Process image files concurrently
    DIR* directory = opendir(directory_path);
    if(directory != NULL) {
        struct dirent* dir_entry;
        while((dir_entry = readdir(directory)) != NULL) {
            char file_path[256];
            sprintf(file_path, "%s/%s", directory_path, dir_entry->d_name);

            // Read image metadata
            ImageMetadata* img_metadata = read_image_metadata(file_path);

            if(img_metadata == NULL)
                continue;

            pthread_mutex_lock(&queue_lock);
            queue.queue[queue.count] = img_metadata;
            queue.count++;
            pthread_cond_signal(&queue_signal);
            pthread_mutex_unlock(&queue_lock);
        }
    }

    // Wait for worker threads to finish
    for(int i = 0; i < num_workers; i++) {
        pthread_join(workers[i], NULL);
    }

    free(workers);
    closedir(directory);

    return NULL;
