#include <exiflib/exif.h>

// Define a struct to hold image metadata
typedef struct {
    char exif_date[20];
    char camera_model[50];
    int image_size;
    int jpeg_quality;
    char tags[100];
    double gps_coordinates[2];
} ImageMetadata;

// Function to process image files and extract metadata
void advanced_image_processing_pipeline(const char* directory_path, const char* output_file) {
    // Initialize the JSON object
    json_object *metadata_json = json_object_new_object();

    // Create a thread-safe queue for concurrent processing
    pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t queue_condition = PTHREAD_COND_INITIALIZER;
    struct {
        ImageMetadata* image_metadata;
        int is_processed;
    } *image_queue[100];
    int queue_size = 0;

    // Initialize the worker threads
    pthread_t worker_threads[4];
    for (int i = 0; i < 4; i++) {
        pthread_create(&worker_threads[i], NULL, process_image_thread, NULL);
    }

    // Process each image file in the directory
    DIR* dir;
    struct dirent* ent;
    if ((dir = opendir(directory_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;

            // Extract metadata from the image file
            ImageMetadata* image_metadata = extract_image_metadata(ent->d_name);

            // Add the metadata to the queue
            pthread_mutex_lock(&queue_mutex);
            image_queue[queue_size++] = image_metadata;
            pthread_cond_signal(&queue_condition);
            pthread_mutex_unlock(&queue_mutex);
        }
    }

    // Wait for all threads to finish
    for (int i = 0; i < 4; i++) {
        pthread_join(worker_threads[i], NULL);
    }

    // Convert the metadata to JSON format
    json_object *metadata_json = json_object_new_object();
    for (int i = 0; i < queue_size; i++) {
        ImageMetadata* image_metadata = image_queue[i];
        json_object *image_json = json_object_new_object();

        json_object_object_add(image_json, "exif_date", json_string(image_metadata->exif_date));
        json_object_object_add(image_json, "camera_model", json_string(image_metadata->camera_model));
        json_object_object_add(image_json, "image_size", json_integer(image_metadata->image_size));
        json_object_object_add(image_json, "jpeg_quality", json_integer(image_metadata->jpeg_quality));
        json_object_object_add(image_json, "tags", json_string(image_metadata->tags));
        json_object_object_add(image_json, "gps_coordinates", json_real_array(image_metadata->gps_coordinates));

        json_object_object_add(metadata_json, ent->d_name, image_json);
    }

    // Write the JSON data to the output file
    FILE* output_file = fopen(output_file, "w");
    if (output_file) {
        json_object_to_file(stdout, metadata_json);
        fclose(output_file);
    }
}

