void log_info(int len) {
    // your logging library function call
}

char* modify_string(char* str, int limit, int trim) {
    if (!str) return NULL;

    int len = strlen(str);
    char* result = malloc(limit + 2);

    if (len > limit && !trim) {
        free(result);
        log_info(len);
        return NULL;
    }

    if (len <= limit) {
        strcpy(result, str);
        strcat(result, "/");
        log_info(strlen(result));
    } else if (trim) {
        strncpy(result, str, limit - 1);
        result[limit - 1] = '\0';
        log_info(limit - 1);
    }

    return result;
}
