#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CELLS 5000
#define MIN_INSTANCES 200
#define MAX_INSTANCES 1000

typedef struct {
    char sib1_message[256];
    int active_cell_measurements;
} RRM_CELL_INFO_T;

RRM_CELL_INFO_T *rrm_cells = NULL;
int rrm_instances = 0;
int rrm_current_size = 0;

void init_rrm() {
    if (rrm_instances == 0) {
        rrm_cells = (RRM_CELL_INFO_T *)malloc(MIN_INSTANCES * sizeof(RRM_CELL_INFO_T));
        rrm_instances = MIN_INSTANCES;
        rrm_current_size = MIN_INSTANCES;
    }
}

int add_cell(RRM_CELL_INFO_T *cell) {
    if (rrm_current_size >= rrm_instances) {
        // Dynamic allocation for more cells
        rrm_cells = (RRM_CELL_INFO_T *)realloc(rrm_cells, (rrm_instances + MIN_INSTANCES) * sizeof(RRM_CELL_INFO_T));
        rrm_instances += MIN_INSTANCES;
        rrm_current_size += MIN_INSTANCES;
    }
    if (rrm_instances < MAX_INSTANCES && rrm_current_size < MAX_INSTANCES) {
        // Add cell to the end
        memcpy(&rrm_cells[rrm_current_size], cell, sizeof(RRM_CELL_INFO_T));
        return rrm_current_size++;
    } else {
        printf("RRM is full. Cannot add more cells.\n");
        return -1;
    }
}

int remove_cell(int index) {
    if (index < 0 || index >= rrm_instances) {
        printf("Invalid cell index. Cannot remove cell.\n");
        return -1;
    }
    if (rrm_instances > MIN_INSTANCES) {
        // Shrink the array to its minimum size
        memmove(&rrm_cells[index], &rrm_cells[index + 1], (rrm_instances - index - 1) * sizeof(RRM_CELL_INFO_T));
        rrm_current_size--;
    } else {
        free(rrm_cells);
        rrm_cells = NULL;
        rrm_instances = 0;
        rrm_current_size = 0;
    }
    return 0;
}

int update_cell(int index, RRM_CELL_INFO_T *new_cell) {
    if (index < 0 || index >= rrm_instances) {
        printf("Invalid cell index. Cannot update cell.\n");
        return -1;
    }
    memcpy(&rrm_cells[index], new_cell, sizeof(RRM_CELL_INFO_T));
    return 0;
}

void log_rrm_state() {
    int successful_updates = 0;
    int failed_updates = 0;
    for (int i = 0; i < rrm_instances; i++) {
        printf("RRM Cell %d: Memory footprint = %ld, Active cell count = %d\n", i, sizeof(RRM_CELL_INFO_T), rrm_cells[i].active_cell_measurements);
        if (rrm_cells[i].sib1_message[0] != '\0') {
            successful_updates++;
        } else {
            failed_updates++;
        }
    }
    printf("Successful updates: %d\n", successful_updates);
    printf("Failed updates: %d\n", failed_updates);
}

int main() {
    init_rrm();

    // Example usage
    RRM_CELL_INFO_T cell1 = {"Hello", 5};
    add_cell(&cell1);

    RRM_CELL_INFO_T cell2 = {"World", 3};
    add_cell(&cell2);

    update_cell(0, &cell1);

    log_rrm_state();

    return 0;
}
