#define MAX_PATH 4096
#define MAX_IDENTIFIER 16
#define MAX_DEPTH 64

typedef enum {
    FILE_CREATE,
    FILE_DELETE,
    FILE_MODIFY
} FileOperation;

typedef struct {
    char *path;
    FileOperation operation;
} Command;

void execute_command(Command command) {
    if (command.operation == FILE_CREATE) {
        if (mkdir(command.path, S_IRWXU | S_IRWXG | S_IRWXO) < 0) {
            printf("Error: mkdir %s\n", command.path);
        }
    } else if (command.operation == FILE_DELETE) {
        if (rmdir(command.path) < 0) {
            printf("Error: rmdir %s\n", command.path);
        }
    } else if (command.operation == FILE_MODIFY) {
        if (rename(command.path, command.path) < 0) {
            printf("Error: rename %s to %s\n", command.path, command.path);
        }
    }
}

int main() {
    Command commands[] = {
        {"dir1/subdir1/file.txt", FILE_CREATE},
        {"dir2/file.txt", FILE_DELETE},
        {"dir3/subdir3/file.txt", FILE_MODIFY}
    };

    int num_commands = sizeof(commands) / sizeof(commands[0]);

    for (int i = 0; i < num_commands; i++) {
        execute_command(commands[i]);
    }

    return 0;
}

