char* manipulate_string(const char* str, size_t limit, int trim) {
    if (!str) return NULL; // handle null pointer gracefully

    size_t len = strlen(str);
    if (len <= limit) {
        char* result = malloc(len + 2); // ensure sufficient memory for trailing /
        strcpy(result, str);
        strcat(result, "/"); // append forward slash
        return result;
    }

    if (!trim) {
        return NULL; // string exceeds size limit and trim flag is not set
    }

    char* result = malloc(limit + 1); // ensure sufficient memory for truncated string
    strncpy(result, str, limit);
    result[limit] = '\0'; // null-terminate the truncated string
    return result;
}
