    // Create a thread-safe queue with specified capacity
    struct {
        int front, rear, size;
        pthread_mutex_t mutex;
    } *queue = (struct {int front, rear, size; pthread_mutex_t mutex;}) malloc(sizeof(struct {int front, rear, size; pthread_mutex_t mutex;}));
    if (!queue) return NULL;

    queue->front = queue->rear = 0;
    queue->size = capacity;
    pthread_mutex_init(&queue->mutex, NULL);

    // Create a thread-safe list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T **list = (NFAPI_CRC_INDICATION_PDU_T **) malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
