        }

        elt->CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag;
        int crcflag = rand() % 2; // Set CRCFLAG randomly for each structure
        elt->CRCFLAG = crcflag;

        list[i] = elt;
    }

    // Initialize a cache mechanism to store valid range of CRCINDICATIONREL8_TAG values
