void add_node(Node* node) {
    pthread_mutex_lock(&cluster->lock);
    if (!cluster->nodes->head) {
        cluster->nodes->head = node;
        cluster->nodes->tail = node;
    } else {
        cluster->nodes->tail->next = node;
        cluster->nodes->tail = node;
    }
    pthread_mutex_unlock(&cluster->lock);
}

// Schedule a task on the cluster
void schedule_task(Task* task) {
    pthread_mutex_lock(&cluster->lock);
    List<Node*> nodes = cluster->nodes;
    Node* node = NULL;
    for (Node* n = nodes->head; n; n = n->next) {
        if (!n->task_count || time() - n->last_execution_time > TASK_EXECUTION_INTERVAL) {
            node = n;
            break;
        }
    }
    if (!node) {
        // Handle the case where no available nodes are found
    }
    node->tasks->add(task);
    pthread_cond_signal(&node->cond);
    pthread_mutex_unlock(&cluster->lock);
}

