#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum task priority
#define MAX_TASK_PRIORITY 100

// Define the task execution frequency limit (5 tasks per minute)
#define TASK_EXECUTION_LIMIT 300

// Define the maximum number of nodes in the cluster
#define MAX_NODES 10

// Define the task queue size (1000 tasks per second)
#define TASK_QUEUE_SIZE 1000

// Task structure to store task information
typedef struct {
    int id;
    int priority;
    char *name;
    void (*function)(void *);
    void *data;
} Task;

// Node structure to store node information
typedef struct {
    int id;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    TaskQueue queue;
    int load;
} Node;

// Task queue structure
typedef struct {
    Task tasks[TASK_QUEUE_SIZE];
    int size;
    int head, tail;
} TaskQueue;

// Initialize the node and task structures
Node nodes[MAX_NODES];
TaskQueue taskQueues[MAX_NODES];

// Function to schedule and execute tasks across multiple nodes
void manageTasks(int numNodes) {
    for (int i = 0; i < numNodes; i++) {
        // Initialize the node and task queue
        nodes[i].id = i;
        nodes[i].load = 0;
        taskQueues[i].size = 0;
        taskQueues[i].head = taskQueues[i].tail = 0;

        // Create a separate thread for each node to execute tasks
        pthread_t thread;
        pthread_create(&thread, NULL, (void *)nodeThread, &nodes[i]);
    }
}

// Node thread function to execute tasks and manage node load
void *nodeThread(void *arg) {
    Node *node = arg;

    while (1) {
        // Dequeue a task from the task queue
        Task task;
        if (!dequeueTask(&task, &taskQueues[node->id].queue)) {
            continue;
        }

        // Check if the node is overloaded
        if (node->load + task.priority > TASK_EXECUTION_LIMIT) {
            // Drop the task if the node is overloaded
            printf("Node %d is overloaded, dropping task %d\n", node->id, task.id);
            continue;
        }

        // Execute the task
        task.function(task.data);

        // Update the node load and task queue size
        node->load += task.priority;
        taskQueues[node->id].size--;

        // Check if the task execution frequency limit is exceeded
        if (taskQueues[node->id].size > TASK_EXECUTION_LIMIT) {
            // Sleep for a short duration to avoid overwhelming the system
            usleep(100000);
        }
    }

    return NULL;
}

// Function to dequeue a task from the task queue
int dequeueTask(Task *task, TaskQueue *queue) {
    pthread_mutex_lock(&queue->mutex);

    if (queue->size == 0) {
        pthread_mutex_unlock(&queue->mutex);
        return 0;
    }

    *task = queue->tasks[queue->head];
    queue->head = (queue->head + 1) % TASK_QUEUE_SIZE;
    queue->size--;

    pthread_mutex_unlock(&queue->mutex);

    return 1;
}

// Function to enqueue a task in the task queue
void enqueueTask(Task task, TaskQueue *queue) {
    pthread_mutex_lock(&queue->mutex);

    // Check if the task queue is full
    if (queue->size == TASK_QUEUE_SIZE) {
        printf("Task queue %d is full, dropping task %d\n", queue->id, task.id);
        return;
    }

    // Enqueue the task in the task queue
    queue->tasks[queue->tail] = task;
    queue->tail = (queue->tail + 1) % TASK_QUEUE_SIZE;
    queue->size++;

    pthread_mutex_unlock(&queue->mutex);
}

// Function to adjust task distribution based on node health and load balancing
void rebalanceTasks(int numNodes) {
    // Calculate the average node load
    int totalLoad = 0;
    for (int i = 0; i < numNodes; i++) {
        totalLoad += nodes[i].load;
    }
    int avgLoad = totalLoad / numNodes;

    // Rebalance task distribution based on node health and load balancing
    for (int i = 0; i < numNodes; i++) {
        Node *node = &nodes[i];
        if (node->load > avgLoad) {
            // Move tasks from the overloaded node to other nodes
            int tasksToMove = node->load - avgLoad;
            while (tasksToMove--) {
                Task task;
                dequeueTask(&task, &taskQueues[node->id].queue);
                enqueueTask(task, &taskQueues[(i + 1) % numNodes]);
            }
        } else if (node->load < avgLoad) {
            // Move tasks from other nodes to the underloaded node
            int tasksToMove = avgLoad - node->load;
            for (int j = 0; j < numNodes; j++) {
                if (j != i && taskQueues[j].size > 0) {
                    Task task;
                    dequeueTask(&task, &taskQueues[j].queue);
                    enqueueTask(task, &taskQueues[i]);
                    tasksToMove--;
                    if (tasksToMove == 0) break;
                }
            }
        }
    }
}

// Function to serialize task execution states in case of system disruptions
void serializeTasks(int numNodes) {
    // Serialize the node and task queue structures
    for (int i = 0; i < numNodes; i++) {
        Node *node = &nodes[i];
        TaskQueue *queue = &taskQueues[i];

        // Serialize the node structure
        char buffer[sizeof(Node)];
        memcpy(buffer, node, sizeof(Node));

        // Serialize the task queue structure
        for (int j = 0; j < TASK_QUEUE_SIZE; j++) {
            Task task;
            if (!dequeueTask(&task, queue)) break;
            // Serialize the task structure
            char buffer[sizeof(Task)];
            memcpy(buffer, &task, sizeof(Task));
            // Store the serialized task in a file or database
        }
    }
}

// Function to monitor and report task execution statistics
void reportStats(int numNodes) {
    // Calculate the average task latency and success rate
    int totalLatency = 0;
    int totalSuccesses = 0;
    for (int i = 0; i < numNodes; i++) {
        Node *node = &nodes[i];
        TaskQueue *queue = &taskQueues[i];

        // Calculate the average task latency and success rate
        int nodeLatency = 0;
        int nodeSuccesses = 0;
        for (int j = 0; j < queue->size; j++) {
            Task task;
            dequeueTask(&task, queue);
            nodeLatency += task.latency;
            nodeSuccesses += task.success ? 1 : -1;
        }
        totalLatency += nodeLatency / queue->size;
        totalSuccesses += nodeSuccesses;

        // Print the node statistics
        printf("Node %d: Latency = %.2f, Success rate = %.2f%%\n", i, nodeLatency / (double)queue->size, 100.0 * nodeSuccesses / queue->size);
    }

    // Calculate the overall task latency and success rate
    int avgLatency = totalLatency / numNodes;
    int avgSuccesses = totalSuccesses;
    printf("Overall: Latency = %.2f, Success rate = %.2f%%\n", avgLatency, 100.0 * avgSuccesses / numNodes);
}

// Function to adaptively scale the number of nodes in the cluster
void adaptiveScaling(int numNodes) {
    // Calculate the average node load and task queue size
    int totalLoad = 0;
    int totalQueueSize = 0;
    for (int i = 0; i < numNodes; i++) {
        Node *node = &nodes[i];
        totalLoad += node->load;
        TaskQueue *queue = &taskQueues[i];
        totalQueueSize += queue->size;
    }
    int avgLoad = totalLoad / numNodes;
    int avgQueueSize = totalQueueSize / numNodes;

    // Adjust the number of nodes based on load and task queue size
    if (avgLoad > TASK_EXECUTION_LIMIT) {
        // Add more nodes to reduce the average node load
        for (int i = 0; i < 5; i++) {
            Node *newNode;
            pthread_create(&newNode, NULL, (void *)nodeThread, newNode);
            // Rebalance task distribution based on node health and load balancing
            rebalanceTasks(numNodes + 1);
            numNodes++;
        }
    } else if (avgQueueSize > TASK_QUEUE_SIZE) {
        // Remove nodes to reduce the average task queue size
        for (int i = 0; i < 5; i++) {
            Node *node = &nodes[numNodes - 1];
            pthread_join(node->thread);
            free(node);
            numNodes--;
        }
    }
}
