    size_t current_size;
    size_t max_size;
    pthread_mutex_t mutex;
} MEMORY_POOL_T;

MEMORY_POOL_T memory_pool = {
    .memory_blocks = (void**)malloc(MEMORY_POOL_SIZE),
    .current_size = 0,
    .max_size = MEMORY_POOL_SIZE,
    .mutex = PTHREAD_MUTEX_INITIALIZER
};

