    // Implement resetting the log here
}

// Dynamic memory allocator
PHY_STATS_RECORD_T* allocate_phy_stats_records(size_t count) {
    if (count > MAX_STRUCTS) {
        printf("Error: Requested %zu structures, but maximum allowed is %zu.\n", count, MAX_STRUCTS);
        return NULL;
    }

    void* ptr = malloc(count * sizeof(PHY_STATS_RECORD_T));
    if (!ptr) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    PHY_STATS_RECORD_T* structs = (PHY_STATS_RECORD_T*)ptr;

    // Initialize structures with random channel quality indicator
    for (size_t i = 0; i < count; i++) {
        structs[i].timestamp = time(NULL);
        structs[i].cell_id = rand();
        structs[i].rb_id = rand() % 16;
        structs[i].phy_stats_tag = rand() % 8;
        structs[i].channel_quality_indicator = (float)rand() / RAND_MAX;
    }

    log_memory_operation("allocate", count * sizeof(PHY_STATS_RECORD_T));
    return structs;
}

// Dynamic memory deallocator
void deallocate_phy_stats_records(PHY_STATS_RECORD_T* structs, size_t count) {
    if (structs == NULL || count <= 0) {
        printf("Error: Invalid input.\n");
        return;
    }

    free(structs);
    log_memory_operation("deallocate", count * sizeof(PHY_STATS_RECORD_T));
}

// Thread-safe memory pool management
void* allocate_from_pool(size_t size) {
    pthread_mutex_lock(&memory_pool.mutex);

    void* ptr = NULL;
    for (size_t i = 0; i < memory_pool.current_size; i++) {
        if (sizeof(void*) <= sizeof(PHY_STATS_RECORD_T)) {
            ptr = memory_pool.memory_blocks[i];
            break;
        }
    }

    if (!ptr) {
        ptr = malloc(size);
        log_memory_operation("allocate from pool", size);
    }

    pthread_mutex_unlock(&memory_pool.mutex);
    return ptr;
}

void deallocate_to_pool(void* ptr, size_t size) {
    pthread_mutex_lock(&memory_pool.mutex);

    memory_pool.memory_blocks[memory_pool.current_size++] = ptr;

    pthread_mutex_unlock(&memory_pool.mutex);
}

// Compression feature (optional)
void compress_structs(PHY_STATS_RECORD_T* structs, size_t count) {
    // Implement compression algorithm here
}

int main() {
    // Initialize memory pool and log
    // ...

    // Allocate structures with dynamic memory allocation
    PHY_STATS_RECORD_T* structs = allocate_phy_stats_records(100);

    // Use allocated structures...

    deallocate_phy_stats_records(structs, 100);
    // ...
}
