use std::error;
use std::fs;
use std::io;
use tokio::{sync::atomic::AtomicUsize, task};

enum AllocError {
    MemoryAllocationFailure,
}

impl error::Error for AllocError {}

impl std::fmt::Display for AllocError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "Memory allocation failure")
    }
}

impl std::error::Description for AllocError {
    fn description(&self) -> &str {
        "Memory allocation failed"
    }
}

async fn allocate_and_init_structures(n: usize) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, error::Error> {
    let mut vec = Vec::new();
    let alloc_error = AtomicUsize::new(0);

    for i in 1..=n {
        let mut pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_info_tag: RX_UE_INFORMATION_TAG {
                // Initialize with random value
                some_field: rand::random(),
            },
            rnti: RNTI::new(i as u16),
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG {
                crcflag: rand::random() % 2 == 0,
            },
        };

        if i % 100 == 0 {
            pdu.extended_info_tag = EXTENDED_INFO_TAG {
                some_field: "some_value".to_string(),
            };
        }

        match vec.push(pdu) {
            Ok(_) => {}
            Err(err) => {
                alloc_error.store(1);
                return Err(AllocError.into());
            }
        }
    }

    if alloc_error.load(std::atomic::Ordering::Relaxed) == 1 {
        return Err(AllocError.into());
    }

    Ok(vec)
}

async fn main() -> Result<(), io::Error> {
    let n = std::env::args().nth(1).unwrap_or("1000".to_string()).parse::<usize>().unwrap();
    let vec = allocate_and_init_structures(n).await?;

    // Release allocated resources
    drop(vec);

    Ok(())
}

