#include <iostream>
#include <string>
#include <map>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>

class DataPoint {
public:
    int timestamp;
    std::string sensorID;
    double measurementValue;
    std::map<std::string, std::string> metadataTags;

    DataPoint(int timestamp, const std::string& sensorID, double measurementValue)
        : timestamp(timestamp), sensorID(sensorID), measurementValue(measurementValue) {}
};

class DataPool {
public:
    static const int DEFAULT_POOL_SIZE = 1000;
    static const int MIN_POOL_SIZE = 10;

    std::vector<std::unique_ptr<DataPoint>> pool;
    std::mutex mutex;
    std::condition_variable cv;
    bool isShutdown;

    DataPool(int initialSize) : pool(initialSize), isShutdown(false) {}

    void allocate(size_t numElements) {
        if (numElements > pool.size()) {
            for (size_t i = 0; i < numElements - pool.size(); ++i) {
                std::unique_ptr<DataPoint> dp(new DataPoint(0, "", 0.0));
                pool.push_back(std::move(dp));
            }
        }
    }

    void deallocate(size_t numElements) {
        for (size_t i = 0; i < numElements && !pool.empty(); ++i) {
            pool.pop_back();
        }
    }

    ~DataPool() {
        cv.notify_all();
    }

    template<typename... Args>
    std::unique_ptr<DataPoint> get(Args&&... args) {
        std::unique_lock<std::mutex> lock(mutex);
        while (pool.empty()) {
            cv.wait(lock);
            if (isShutdown)
                return nullptr;
        }
        auto dp = std::move(pool.back());
        pool.pop_back();
        return dp;
    }

    void shutdown() {
        isShutdown = true;
        cv.notify_all();
    }
};

class DataLogger {
public:
    enum class Mode { SYNC, ASYNC };

    DataLogger(Mode mode) : mode(mode), logQueue("") {}

    void log(const std::string& message) {
        if (mode == DataLogger::Mode::SYNC)
            std::cout << message << std::endl;
        else
            logQueue += message + "\n";
    }

    std::string getLog() {
        return logQueue;
    }

private:
    Mode mode;
    std::string logQueue;
};

class DataManager {
public:
    DataPool dataPool;
    DataLogger logger;

    DataManager(int initialSize, DataLogger::Mode mode) : 
        dataPool(initialSize), logger(mode) {}

    void addDataPoint(const DataPoint& point) {
        auto dp = dataPool.get();
        if (dp)
            dp->timestamp = point.timestamp;
        else
            logger.log("Insufficient memory to store data points.");
    }

    ~DataManager() {
        while (!dataPool.pool.empty()) {
            auto dp = std::move(dataPool.pool.back());
            dataPool.pool.pop_back();
            delete dp.get();
        }
    }
};

int main() {
    DataManager manager(100, DataLogger::Mode::ASYNC);
    // simulate adding data points
    for (int i = 0; i < 500; ++i) {
        DataPoint point(i, "Sensor1", 10.5);
        manager.addDataPoint(point);
    }
    std::cout << manager.logger.getLog() << std::endl;
    return 0;
}
