#include <string.h>
#include <md5.h>

#define MAX_RECORDS 1000
#define MAX_METADATA_SIZE 1024
#define DEFAULT_TIMESTAMP "1970-01-01 00:00:00"
#define DEFAULT_PARAMETERS "Parameter1=Default1,Parameter2=Default2"

typedef struct {
    int id;
    char timestamp[64];
    char parameters[MAX_METADATA_SIZE];
} MetadataEntry;

MetadataEntry* create_metadata(int N) {
    MetadataEntry* metadata = (MetadataEntry*)malloc(N * sizeof(MetadataEntry));

    for (int i = 0; i < N; i++) {
        metadata[i].id = i;
        strcpy(metadata[i].timestamp, DEFAULT_TIMESTAMP);
        strcpy(metadata[i].parameters, DEFAULT_PARAMETERS);

        // Log creation details
        printf("Created Metadata Entry %d: Size=%zu, Content=\"%s\", Timestamp=\"%s\"\n",
               i, sizeof(MetadataEntry), metadata[i].parameters, metadata[i].timestamp);
    }

    return metadata;
}

void process_metadata(MetadataEntry* metadata, int N) {
    for (int i = 0; i < N; i++) {
        // Marshal metadata entry into expected format
        char* marshaled_entry = malloc(MAX_METADATA_SIZE * sizeof(char));
        sprintf(marshaled_entry, "{\"id\": %d, \"timestamp\": \"%s\", \"parameters\": \"%s\"}",
               metadata[i].id, metadata[i].timestamp, metadata[i].parameters);

        // Compute MD5 hash of serialized entry
        unsigned char md5_hash[MD5_DIGEST_LENGTH];
        MD5_CTX ctx;
        MD5_Init(&ctx);
        MD5_Update(&ctx, marshaled_entry, strlen(marshaled_entry));
        MD5_Final(md5_hash, &ctx);

        // Log processed metadata entry with MD5 hash
        printf("Processed Metadata Entry %d: Size=%zu, Content=\"%s\", Timestamp=\"%s\", MD5 Hash=\"%02x%02x%02x%02x%02x%02x\"\n",
               i, sizeof(MetadataEntry), marshaled_entry, metadata[i].timestamp, md5_hash[0], md5_hash[1], md5_hash[2], md5_hash[3], md5_hash[4], md5_hash[5]);

        free(marshaled_entry);
    }
}

int main() {
    int N;

    printf("Enter the number of records: ");
    scanf("%d", &N);

    if (N > MAX_RECORDS) {
        printf("Error: Exceeding maximum record size.\n");
        return 1;
    }

    MetadataEntry* metadata = create_metadata(N);

    process_metadata(metadata, N);

    free(metadata);

    return 0;
}
