int create_crc_indication_pdu_t(int N, unsigned int seed) {
    srand(seed);

    // Dynamically allocate memory for the array of structures
    struct NFAPI_CRC_INDICATION_PDU_T* pdu_array = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_array) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    for (int i = 0; i < N; i++) {
        // Initialize the structure with random values
        pdu_array[i].RX_UE_INFORMATION_TAG = rand();
        pdu_array[i].RNTI = rand();

        // Calculate CRC value and set CRCFLAG accordingly
        uint32_t crc_value = calculate_crc(pdu_array[i].RX_UE_INFORMATION_TAG, pdu_array[i].RNTI);
        pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (crc_value == 0) ? CRC_INDICATION_REL8_TAG_CRC_OK : CRC_INDICATION_REL8_TAG_CRC_ERROR;

        // Validate the consistency between CRCFLAG and calculated CRC value
        if (pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG != ((crc_value == 0) ? CRC_INDICATION_REL8_TAG_CRC_OK : CRC_INDICATION_REL8_TAG_CRC_ERROR)) {
            printf("Error: Invalid CRC indication.\n");
            // Handle error and free allocated memory
            for (int j = 0; j < i; j++) {
                free(&pdu_array[j]);
