typedef struct {
    int id;
    time_t timestamp;
    char* param1;
    char* param2;
} MetadataEntry;

MetadataEntry** create_metadata_array(int N) {
    MetadataEntry** metadata = (MetadataEntry**)malloc(N * sizeof(MetadataEntry*));

    for (int i = 0; i < N; i++) {
        MetadataEntry* entry = (MetadataEntry*)malloc(sizeof(MetadataEntry));

        entry->id = i;
        entry->timestamp = time(NULL);

        // Initialize parameters with default values
        entry->param1 = (char*)malloc(10 * sizeof(char));
        strcpy(entry->param1, "DefaultParam1");
        entry->param2 = (char*)malloc(10 * sizeof(char));
        strcpy(entry->param2, "DefaultParam2");

        metadata[i] = entry;
    }

    return metadata;
}

void log_metadata(MetadataEntry** metadata, int N) {
    for (int i = 0; i < N; i++) {
        MetadataEntry* entry = metadata[i];

        // Compute MD5 hash of the serialized metadata entry
        unsigned char md5[16];
        MD5(entry->param1, strlen(entry->param1), md5);
        char md5_str[33];
        sprintf(md5_str, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
                 md5[0], md5[1], md5[2], md5[3], md5[4], md5[5], md5[6], md5[7],
                 md5[8], md5[9], md5[10], md5[11]);

        // Log the metadata entry with its size, content, and creation timestamp
        printf("Metadata Entry %d:\n", i);
        printf("  ID: %d\n", entry->id);
        printf("  Timestamp: %ld\n", entry->timestamp);
        printf("  Parameters: Param1 - '%s', Param2 - '%s'\n", entry->param1, entry->param2);
        printf("  MD5 Hash: %s\n", md5_str);
    }
}

int process_metadata(MetadataEntry** metadata, int N) {
    // Initialize metrics
    int max_weighted_sum = 0;
    int max_id = -1;

    for (int i = 0; i < N; i++) {
        MetadataEntry* entry = metadata[i];

        // Filter transactions based on age and weighted sum
        if (entry->timestamp > time(NULL) - 3 && 
            entry->id >= 10 && 
            (entry->param1[0] == 'A' || entry->param2[0] == 'B')) {
            int weight = 5 * (entry->id % 2);

            if (weight > max_weighted_sum) {
                max_weighted_sum = weight;
                max_id = entry->id;
            }
        }
    }

    return max_id;
}
