['Here is the C# code for the `ParseAndValidateXml` function:

```csharp
using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public void ParseAndValidateXml(string xml, string nodeName)
    {
        XPathDocument doc = new XPathDocument(new StringReader(xml));
        XPathNavigator nav = doc.CreateNavigator();

        XPathExpression expression = nav.Compile("/" + nodeName);

        XPathNodeIterator iterator = nav.Select(expression);

        if (!iterator.MoveToFirstChild())
        {
            throw new XmlNotFoundException("Element " + nodeName + " not found.");
        }

        XPathNavigator childNav = iterator.Clone();
        while (childNav.MoveToNext())
        {
            if (childNav.Name != nodeName)
            {
                throw new XmlConflictException("Multiple elements named " + nodeName + " found.");
            }
        }

        // Validate XML content and attributes using predefined schemas or templates
    }
}

public class XmlNotFoundException : Exception
{
    public XmlNotFoundException(string message) : base(message) { }
}

public class XmlConflictException : Exception
{
    public XmlConflictException(string message) : base(message) { }
}
