#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_MAC_PDU_COUNT 1000
#define LOG_FILE "log_file.txt"

typedef struct {
    int tx_ue_information_tag;
    int preamble_type;
    double phy_stats_tag[4];
} MAC_FRAME_T;

void log_error(const char* message) {
    FILE *fp = fopen(LOG_FILE, "a");
    fprintf(fp, "%s\n", message);
    fclose(fp);
}

int retry_api_call(int attempts, void (*callback)(const MAC_FRAME_T*)) {
    for (int i = 0; i < attempts && !callback(); i++) {
        sleep(1); // simulate network delay
        printf("Attempt %d failed. Retrying...\n", i + 1);
    }
    return callback() ? 0 : -1;
}

void process_mac_frame_results(MAC_FRAME_T* frames, int count, void (*callback)(const MAC_FRAME_T*)) {
    for (int i = 0; i < count; i++) {
        callback(frames[i]);
    }
}

double get_execution_time() {
    return clock() / (double)CLOCKS_PER_SEC;
}

void monitor_performance(int count) {
    double execution_time = get_execution_time();
    printf("Execution time: %f seconds\n", execution_time);
    printf("Memory usage: %lu bytes\n", sizeof(MAC_FRAME_T) * count);
}

int populate_mac_frames(int* count, MAC_FRAME_T** frames) {
    int attempts = 0;
    for (int i = 0; i < MAX_MAC_PDU_COUNT; i++) {
        MAC_FRAME_T frame;
        frame.tx_ue_information_tag = i % 256;
        frame.preamble_type = i % 2;
        // simulate API call
        if (i % 3 == 0) {
            attempts++;
            int retry_status = retry_api_call(3, NULL);
            if (retry_status < 0) {
                log_error("API call failed after three retries.");
                return -1;
            }
        }
        (*frames)[*count] = frame;
        (*count)++;
    }
    monitor_performance(*count);
    return 0;
}

int main() {
    int count = 0;
    MAC_FRAME_T* frames = (MAC_FRAME_T*)malloc(MAX_MAC_PDU_COUNT * sizeof(MAC_FRAME_T));
    if (!populate_mac_frames(&count, &frames)) {
        printf("Populated %d MAC frames.\n", count);
        process_mac_frame_results(frames, count, NULL);
        free(frames);
        return 0;
    } else {
        log_error("Failed to populate MAC frames.");
        free(frames);
        return -1;
    }
}
