NFAPI_CRC_INDICATION_PDU_T* parse_crc_indication_pdu_file(const char* file_path, size_t max_entries_per_allocation) {
    FILE* file = fopen(file_path, "rb");
    if (!file) {
        // handle error
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    size_t total_entries = 0;

    size_t entries_allocated = 0;
    NFAPI_CRC_INDICATION_PDU_T** allocation_pointers = NULL;

    do {
        size_t bytes_to_read = sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_entries_per_allocation;
        void* buffer = malloc(bytes_to_read);
        if (!buffer) {
            // handle error
            fclose(file);
            return array;
        }

        if (fread(buffer, 1, bytes_to_read, file) != bytes_to_read) {
            // handle error
            free(buffer);
            fclose(file);
            return array;
        }

        NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*) buffer;

        for (size_t i = 0; i < max_entries_per_allocation; ++i) {
            if (!entry[i].RX_UE_INFORMATION_TAG || !entry[i].RNTI || !entry[i].CRC_INDICATION_REL8_TAG) {
                // handle error
                free(buffer);
                fclose(file);
                return array;
            }
        }

        for (size_t i = 0; i < max_entries_per_allocation; ++i) {
            if (array && total_entries + i >= array_size(array)) {
                reallocate_array(&array, &total_entries, array_size(array) * 2);
            }

            array[total_entries + i] = entry[i];

            for (size_t j = 0; j < max_entries_per_allocation - i - 1; ++j) {
                if (!entry[j].RX_UE_INFORMATION_TAG || !entry[j].RNTI || !entry[j].CRC_INDICATION_REL8_TAG) {
                    // handle error
                    free(buffer);
                    fclose(file);
                    return array;
                }
            }
        }

        free(buffer);

        total_entries += max_entries_per_allocation;

        if (ferror(file)) {
            // handle error
            fclose(file);
            return array;
        }
    } while (!feof(file));

    fclose(file);

    return array;
}

void reallocate_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* total_entries, size_t new_size) {
    *array = realloc(*array, sizeof(**array) * new_size);
    *total_entries = new_size - 1; // subtract 1 to account for the last allocated space
}

