    int SIB1_MESSAGE;
    int active_cells;
} LTE_ENB_CONFIG_RRC_T;

NFAPI_CRC_INDICATION_PDU_T* parse_file(const char* filename, int* num_entries) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file: %s\n", filename);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int i = 0;
    while (fread(&arr[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file) == 1 && i < MAX_ENTRIES) {
        i++;
    }
    fclose(file);

    if (feof(file)) {
        *num_entries = i;
    } else {
        printf("Error parsing file: %s\n", filename);
        free(arr);
        return NULL;
    }

    return arr;
}

LTE_ENB_CONFIG_RRC_T* init_config(int num_entries) {
    LTE_ENB_CONFIG_RRC_T* config = (LTE_ENB_CONFIG_RRC_T*)malloc(num_entries * sizeof(LTE_ENB_CONFIG_RRC_T));
    for (int i = 0; i < num_entries; i++) {
        config[i].SIB1_MESSAGE = i;
        config[i].active_cells = i + 1;
    }
    return config;
}

int main() {
    const char* filename = "example.txt";
    int num_entries;
    NFAPI_CRC_INDICATION_PDU_T* arr = parse_file(filename, &num_entries);

    if (!arr) {
        return 1;
    }

    LTE_ENB_CONFIG_RRC_T* config = init_config(num_entries);
    // Use the array and configuration
    free(arr);
    free(config);
    return 0;
}
