import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class SecureHasher {
    private static final int DEFAULT_CACHE_SIZE = 1000;
    private Map<String, String> cache;
    private MessageDigest md5;
    private MessageDigest sha256;

    public SecureHasher() {
        this.cache = new HashMap<>();
        this.md5 = getMessageDigest("MD5");
        this.sha256 = getMessageDigest("SHA-256");
    }

    public void setCacheSize(int size) {
        if (size < 0) {
            throw new IllegalArgumentException("Cache size must be a positive integer.");
        }
        this.cache.clear();
        this.cache = new HashMap<>(size);
    }

    public String getMD5(String input) {
        return getHash(input, md5);
    }

    public String getSHA256(String input) {
        return getHash(input, sha256);
    }

    private MessageDigest getMessageDigest(String algorithm) {
        try {
            return MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private String getHash(String input, MessageDigest digest) {
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hashString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) {
                hashString.append('0');
            }
            hashString.append(hex);
        }
        return hashString.toString();
    }

    public void clearCache() {
        this.cache.clear();
    }
}
