import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.*;

public class LogProcessor {
    public Map<String, Long> processLogEntries(String logFilePath) throws IOException {
        // Initialize map to store log level frequencies and total log entries per minute
        Map<String, Long> summaryReport = new HashMap<>();
        Map<String, Integer> logLevelCounts = new HashMap<>();

        try (BufferedReader br = new BufferedReader(new FileReader(logFilePath))) {
            String line;
            long entryCount = 0;
            long lastEntryTime = System.currentTimeMillis() / 1000 / 60; // Initialize to the current minute

            while ((line = br.readLine()) != null) {
                try {
                    LogEntry logEntry = deserializeLogEntry(line);

                    if (logEntry == null) {
                        continue; // Skip malformed or non-conforming entries
                    }

                    String logLevel = logEntry.getLogLevel();

                    // Update entry count and last entry time
                    entryCount++;
                    long currentEntryTime = System.currentTimeMillis() / 1000 / 60;
                    if (currentEntryTime > lastEntryTime) {
                        lastEntryTime = currentEntryTime; // Update last entry time

                        // Calculate total log entries per minute
                        int totalEntriesPerMinute = Math.toIntExact(entryCount - (lastEntryTime * 60));
                        summaryReport.put("entries_per_minute", totalEntriesPerMinute);

                        // Reset entry count and last entry time
                        entryCount = 1;
                    } else {
                        entryCount++;
                    }

                    // Update log level frequency counts
                    long newCount = logLevelCounts.getOrDefault(logLevel, 0L) + 1;
                    logLevelCounts.put(logLevel, newCount);
                } catch (Exception e) {
                    // Handle exceptions gracefully and skip malformed entries
                    System.out.println("Error processing log entry: " + e.getMessage());
                    continue;
                }
            }

            // Calculate final total log entries per minute
            int totalEntriesPerMinute = Math.toIntExact(entryCount - (lastEntryTime * 60));
            summaryReport.put("entries_per_minute", totalEntriesPerMinute);

            // Update log level frequencies in the summary report
            for (Map.Entry<String, Long> entry : logLevelCounts.entrySet()) {
                summaryReport.put(entry.getKey() + "_frequency", entry.getValue());
            }
        }

        return summaryReport;
    }

    private LogEntry deserializeLogEntry(String line) {
        // Implement custom deserialization logic for the LogEntry class
        // For demonstration purposes, assume a simple parsing mechanism
        String[] parts = line.split(":");
        if (parts.length < 3) {
            return null; // Skip malformed entries
        }

        LogEntry logEntry = new LogEntry(parts[0], parts[1]);
        return logEntry;
    }
}

class LogEntry {
    private final String logLevel;
    private final String message;

    public LogEntry(String logLevel, String message) {
        this.logLevel = logLevel;
        this.message = message;
    }

    public String getLogLevel() {
        return logLevel;
    }

    // Implement other getter methods as needed
}
