public class DataProcessor {
    private static final int BATCH_SIZE = 1000;
    private static final int REPORTING_INTERVAL = 60; // seconds

    private ExecutorService executor;
    private BlockingQueue<Transaction> queue;

    public DataProcessor() {
        this.executor = Executors.newCachedThreadPool();
        this.queue = new LinkedBlockingQueue<>();
    }

    public void startProcessing(TransactionValidator validator) {
        new Thread(() -> {
            while (true) {
                try {
                    processTransactions(validator);
                    Thread.sleep(REPORTING_INTERVAL * 1000); // send batch reports every REPORTING_INTERVAL seconds
                } catch (InterruptedException e) {
                    break;
                }
            }
        }).start();
    }

    private void processTransactions(TransactionValidator validator) {
        BlockingQueue<Transaction> tempQueue = new LinkedBlockingQueue<>();
        while (!queue.drainTo(tempQueue, BATCH_SIZE)) { // drain up to BATCH_SIZE transactions
            if (tempQueue.size() > 0) {
                try {
                    executor.submit(() -> {
                        TransactionBatch batch = new TransactionBatch();
                        while (!tempQueue.isEmpty()) {
                            Transaction transaction = tempQueue.take();
                            if (validator.isValid(transaction)) {
                                batch.addTransaction(transaction);
                            } else {
                                System.out.println("Invalid transaction: " + transaction);
                            }
                        }
                        generateReport(batch);
                    });
                } catch (InterruptedException e) {
                    break;
                }
            }
        }
    }

    private void generateReport(TransactionBatch batch) {
        // implement report generation logic here
    }

