import java.security.MessageDigest;
import java.util.*;

public class SHA256Processor {

    private static final int MAX_STRINGS = 10000;
    private static final int MAX_STRING_LENGTH = 1024;

    public Map<String, Tuple> processDataset(String filename) throws IOException {
        Map<String, Tuple> result = new HashMap<>();
        try (FileInputStream fis = new FileInputStream(filename);
             ObjectInputStream ois = new ObjectInputStream(new BufferedInputStream(fis))) {

            int stringCount = 0;
            while (true) {
                String str = (String) ois.readObject();
                if (str == null) break;

                if (isValidString(str)) {
                    String hash = getSHA256Hash(str);
                    result.put(hash, new Tuple(str, str.length()));
                    stringCount++;
                    if (stringCount >= MAX_STRINGS) break;
                }
            }

        } catch (EOFException e) {
            // End of file reached
        } catch (IOException | ClassNotFoundException e) {
            // Handle I/O or deserialization exceptions
        }

        return result;
    }

    private boolean isValidString(String str) {
        if (str.length() > MAX_STRING_LENGTH || str.trim().isEmpty()) return false;

        for (char c : str.toCharArray()) {
            if (!Character.isPrint(c)) return false;
        }

        return true;
    }

    private String getSHA256Hash(String str) throws IOException {
        try (MessageDigest md = MessageDigest.getInstance("SHA-256")) {
            byte[] bytes = str.getBytes();
            md.update(bytes);
            return new BigInteger(1, md.digest()).toString(16).toUpperCase();
        }
    }

    static class Tuple {
        String originalString;
        int length;

        public Tuple(String originalString, int length) {
            this.originalString = originalString;
            this.length = length;
        }
    }
}']

