import java.io.*;
import java.util.*;
import java.time.*;

public class LogProcessor {
    public static SummaryReport processLogs(Collection<LogFile> files) throws Exception {
        Map<String, Long> logLevelFrequency = new HashMap<>();
        Map<LocalDateTime, Long> minuteCounts = new HashMap<>();
        Map<LocalDateTime, Map<String, Long>> hourlyCounts = new HashMap<>();

        for (LogFile file : files) {
            try (
                    BufferedReader reader = new BufferedReader(new FileReader(file.getFile()));
                    LineNumberReader lineNumberReader = new LineNumberReader(reader);
            ) {
                String line;
                while ((line = reader.readLine()) != null) {
                    LogEntry logEntry = parseLogEntry(line);
                    if (logEntry == null) continue; // Skip malformed entries

                    updateFrequency(logLevelFrequency, logEntry.getLogLevel());
                    updateMinuteCounts(minuteCounts, logEntry.getTimestamp());
                    updateHourlyCounts(hourlyCounts, logEntry.getTimestamp());

                }
            }
        }

        return new SummaryReport(
                logLevelFrequency,
                minuteCounts,
                hourlyCounts
        );
    }

    private static LogEntry parseLogEntry(String line) {
        // TO DO: Implement your custom parsing logic here.
        // For simplicity, let's assume a basic format where each line starts with a log level (DEBUG/INFO/WARN/ERROR)
        // and followed by a timestamp in ISO 8601 format.
        if (!line.startsWith("[DEBUG|INFO|WARN|ERROR] ")) return null;
        String[] parts = line.split(" ");
        LogEntry entry = new LogEntry(parts[0].substring(1), LocalDateTime.parse(parts[2]));
        // TO DO: Add more parsing logic to extract additional log information (e.g., message, correlation ID).
        return entry;
    }

    private static void updateFrequency(Map<String, Long> frequencyMap, String logLevel) {
        frequencyMap.put(logLevel, frequencyMap.getOrDefault(logLevel, 0L) + 1);
    }

    private static void updateMinuteCounts(Map<LocalDateTime, Long> minuteCounts, LocalDateTime timestamp) {
        int minute = timestamp.toSecondOfDay() / 60;
        minuteCounts.computeIfAbsent(timestamp.truncatedTo(ChronoUnit.MINUTES), k -> 0L).incrementAndGet();
    }

    private static void updateHourlyCounts(Map<LocalDateTime, Map<String, Long>> hourlyCounts, LocalDateTime timestamp) {
        int hour = timestamp.toSecondOfDay() / (60 * 60);
        hourlyCounts.computeIfAbsent(timestamp.truncatedTo(ChronoUnit.HOURS), k -> new HashMap<>()).merge("count", 1L, Integer::sum);
    }
}

public class SummaryReport {
    public Map<String, Long> logLevelFrequency;
    public Map<LocalDateTime, Long> minuteCounts;
    public Map<LocalDateTime, Map<String, Long>> hourlyCounts;

    public SummaryReport(Map<String, Long> logLevelFrequency, Map<LocalDateTime, Long> minuteCounts, Map<LocalDateTime, Map<String, Long>> hourlyCounts) {
        this.logLevelFrequency = logLevelFrequency;
        this.minuteCounts = minuteCounts;
        this.hourlyCounts = hourlyCounts;
    }
}

public class LogEntry {
    public String logLevel;
    public LocalDateTime timestamp;

    public LogEntry(String logLevel, LocalDateTime timestamp) {
        this.logLevel = logLevel;
        this.timestamp = timestamp;
    }

    // Add getters and setters for the attributes.
}
