void log_string_size(const char *string, int action_taken) {
    printf("String size: %d bytes\n", strlen(string));
    switch (action_taken) {
        case APPEND_NEWLINE:
            printf("Appended newline character.\n");
            break;
        case TRUNCATE:
            printf("Truncated string to fit within the limit.\n");
            break;
        case RETURN_NULL:
            printf("Returned NULL due to exceeding size limit.\n");
    }
}

int process_file(const char *file_name, int size_limit, int trim_flag) {
    FILE *file = fopen(file_name, "r");
    if (file == NULL) {
        return -1; // File not found
    }

