        fclose(file);
        return -1; // Out of memory
    }

    PHY_LAYER_CELL_CONFIG_T *cell_config_array;
    int num_cells;

    if (initialize_cell_config(&cell_config_array, &num_cells) < 0) {
        free(frame_info_array);
        fclose(file);
        return -1; // Out of memory
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Process the line and check for errors
        if (strlen(line) > size_limit && !trim_flag) {
            log_string_size(line, RETURN_NULL);
            fclose(file);
            return 0; // File exceeded size limit without trimming
        }
        else if (strlen(line) > size_limit) {
            char *trimmed_line = malloc(size_limit + 1);
            strcpy(trimmed_line, line);
            trimmed_line[size_limit] = '\0';
            log_string_size(line, TRUNCATE);
            free(trimmed_line);
        }
        else {
            log_string_size(line, APPEND_NEWLINE);
        }
    }

    fclose(file);

    // Free allocated memory
    free(frame_info_array);
    free(cell_config_array);

    return num_entries;
}

int main() {
    int size_limit = 1024;
    int trim_flag = 0;

    process_file("input.txt", size_limit, trim_flag);

    return 0;
}
