        logLevelCounts.put(logLevel, count);

        long hourCount = hourlyCounts.computeOrDefault(logLevel + "_" + new Date().getHours(), 0L, k -> 1L);
        long minuteCount = minuteCounts.computeOrDefault(logLevel + "_" + new Date().getMinutes(), 0L, k -> 1L);

