import java.io.*;
import java.util.*;

public class LogProcessor {
    private Map<String, Integer> logLevels;
    private Map<Integer, Long> minuteCounts;
    private Map<Integer, Map<String, Long>> hourCounts;

    public LogProcessor() {
        this.logLevels = new HashMap<>();
        this.minuteCounts = new HashMap<>();
        this.hourCounts = new HashMap<>();

        for (int i = 0; i < 24; i++) {
            hourCounts.put(i, new HashMap<>());
        }
    }

    public SummaryReport processLogs(String[] files) throws IOException {
        SummaryReport report = new SummaryReport();

        for (String file : files) {
            try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(file));
                 GZIPInputStream gzip = new GZIPInputStream(bis)) {

                ObjectInputStream ois = new ObjectInputStream(gzip);
                LogEntry[] logEntries = (LogEntry[]) ois.readObject();

                for (LogEntry entry : logEntries) {
                    if (entry.isValid()) {
                        processLogEntry(entry, report);
                    }
                }

            } catch (IOException | ClassNotFoundException e) {
                // Handle exceptions gracefully
                System.out.println("Error processing file " + file + ": " + e.getMessage());
            }
        }

        return report;
    }

    private void processLogEntry(LogEntry entry, SummaryReport report) {
        String logLevel = entry.getLogLevel();

        if (!logLevels.containsKey(logLevel)) {
            logLevels.put(logLevel, 0);
        }

        logLevels.put(logLevel, logLevels.get(logLevel) + 1);

        int minute = entry.getMinute();
        long count = minuteCounts.computeIfAbsent(minute, k -> 0L) + 1;

        report.setMinuteCount(count);

        int hour = entry.getHour();

        Map<String, Long> hourMap = hourCounts.get(hour);
        if (!hourMap.containsKey(logLevel)) {
            hourMap.put(logLevel, 0L);
        }

        long hourCount = hourMap.computeIfAbsent(logLevel, k -> 0L) + 1;

        report.setHourCount(hour, logLevel, hourCount);
    }

    public static class SummaryReport {
        private int minuteCount;
        private Map<Integer, Long> hourCounts;

        public void setMinuteCount(long count) {
            this.minuteCount = (int) count;
        }

        public void setHourCount(int hour, String logLevel, long count) {
            if (!hourCounts.containsKey(hour)) {
                hourCounts.put(hour, new HashMap<>());
            }

            hourCounts.get(hour).put(logLevel, count);
        }

        public String toString() {
            StringBuilder sb = new StringBuilder("Log Summary:\n");
            sb.append("Log Levels: ");
            for (Map.Entry<String, Integer> entry : logLevels.entrySet()) {
                sb.append(entry.getKey()).append(": ").append(entry.getValue()).append(", ");
            }
            sb.append("\nMinute Count: ").append(minuteCount).append("\nHour Counts:");
            for (Map.Entry<Integer, Map<String, Long>> hourEntry : hourCounts.entrySet()) {
                int hour = hourEntry.getKey();
                Map<String, Long> logCounts = hourEntry.getValue();
                sb.append("\nHour ").append(hour);
                for (Map.Entry<String, Long> logEntry : logCounts.entrySet()) {
                    sb.append("\n  " + logEntry.getKey() + ": " + logEntry.getValue());
                }
            }
            return sb.toString();
        }
    }

    public class LogEntry implements Serializable {
        private String logLevel;
        private int minute;
        private int hour;

        public LogEntry(String logLevel, int minute, int hour) {
            this.logLevel = logLevel;
            this.minute = minute;
            this.hour = hour;
        }

        public boolean isValid() {
            // Implement logic to check if the log entry is valid
            return true; // Default to true
        }

        public String getLogLevel() {
            return logLevel;
        }

        public int getMinute() {
            return minute;
        }

        public int getHour() {
            return hour;
        }
    }
}
