typedef struct {
    char* password;
    struct connection* conn;
    void (*callback)(void);
} NFAPI_CRC_INDICATION_PDU_T;

struct connection {
    char title[64];
};

int parseFile(const char* filename, NFAPI_CRC_INDICATION_PDU_T** array, int* numEntries) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return 1; // error: cannot open file
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    NFAPI_CRC_INDICATION_PDU_T* structs = malloc((size_t) fileSize / sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structs == NULL) {
        fclose(file);
        return 2; // error: cannot allocate memory
    }

    int count = 0;
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        NFAPI_CRC_INDICATION_PDU_T* structData = &structs[count++];
        if (fscanf(file, "%[^,],%p,%x", structData->password, &structData->conn->title) != 3) {
            fclose(file);
            free(structs);
            return 3; // error: invalid data format
        }
    }

    fclose(file);

    *array = structs;
    *numEntries = count;

    return 0; // success
}

int verifyInput(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->password == NULL || strlen(pdu->password) == 0) {
        return 1; // error: empty password
    }
    if (pdu->conn->title[0] == '\0') {
        return 2; // error: no connection title
    }
    if (pdu->callback == NULL) {
        return 3; // error: no callback function
    }

    return 0; // success
}
