    int rnti;
    char* crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* read_file(const char* filename, const char* password, const struct connection_info* conn, void (*callback)(void*), size_t* num_structures) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file: %s\n", strerror(errno));
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 100); // Initialize array with some initial size
    size_t num_alloc = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        NFAPI_CRC_INDICATION_PDU_T* structure = &structures[num_alloc];

        if (sscanf(line, "%s %d %s", structure->rx_ue_information_tag = malloc(strlen(line) - strlen(line) + 1), &structure->rnti, structure->crc_indication_rel8_tag = malloc(strlen(line) - strlen(line) + 1)) != 3) {
            printf("Error parsing file: Invalid data format\n");
            fclose(file);
            free(structures);
            return NULL;
        }

        num_alloc++;
    }

    fclose(file);

    if (num_alloc > *num_structures) {
        *num_structures = num_alloc;
    }

    // Check for empty or NULL password
    if (!password || strlen(password) == 0) {
        printf("Error: Password cannot be empty or NULL\n");
        free(structures);
        return NULL;
    }

    // Check for connection title set
    if (!conn->title) {
        printf("Error: Connection must have a title set\n");
        free(structures);
        return NULL;
    }

    // Check for non-NULL callback function
    if (!callback) {
        printf("Error: Callback function cannot be NULL\n");
        free(structures);
        return NULL;
    }

    return structures;
}

int main() {
    const char* filename = "example.txt";
    const char* password = "";
    const struct connection_info conn = {"title"};
    void (*callback)(void*) = NULL;

    size_t num_structures;

    NFAPI_CRC_INDICATION_PDU_T* structures = read_file(filename, password, &conn, callback, &num_structures);

    if (structures) {
        // Process the array of structures
        for (size_t i = 0; i < num_structures; i++) {
            printf("RX UE Information Tag: %s\n", structures[i].rx_ue_information_tag);
            printf("RNTI: %d\n", structures[i].rnti);
            printf("CRC Indication Rel8 Tag: %s\n", structures[i].crc_indication_rel8_tag);

            if (callback) {
                callback(&structures[i]);
            }
        }

        free(structures);
    }

    return 0;
}
