public class MD5Hasher {

    private static final Logger LOGGER = LoggerFactory.getLogger(MD5Hasher.class);

    public String generateMD5Hash(String input) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(Integer.toHexString((b & 0xFF) | 0x100).substring(1,3));
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        MD5Hasher md5Hasher = new MD5Hasher();
        String input = "test-input";
        long startTime = System.currentTimeMillis();
        String hash = md5Hasher.generateMD5Hash(input);
        long endTime = System.currentTimeMillis();
        LOGGER.info("Generated MD5 hash for {} in {} ms: {}", input, (endTime - startTime), hash);
    }
}

