import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ServiceManager {

    private static final Logger logger = LoggerFactory.getLogger(ServiceManager.class);
    private ExecutorService executorService;

    public ServiceManager(int threadPoolSize) {
        executorService = Executors.newFixedThreadPool(threadPoolSize);
    }

    public void startAndStopService() {
        for (int i = 0; i < 10; i++) { // repeat 10 times
            try {
                Thread.sleep(Math.abs(new java.util.Random().nextInt()) % 1000); // random delay
                executorService.execute(() -> {
                    try {
                        // start service operation
                        logger.info("Service started");
                    } catch (Exception e) {
                        logger.error("Error starting service: {}", e.getMessage());
                    }
                });
                Thread.sleep(Math.abs(new java.util.Random().nextInt()) % 1000); // random delay
                executorService.execute(() -> {
                    try {
                        // stop service operation
                        logger.info("Service stopped");
                    } catch (Exception e) {
                        logger.error("Error stopping service: {}", e.getMessage());
                    }
                });
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                logger.error("Interrupted while managing service");
            }
        }
    }

}

