NFAPI_CRC_INDICATION_PDU_T* parse_file(const char* filename, int limit) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Error opening file\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(limit * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    sensor_data* data_array = (sensor_data*)malloc(limit * sizeof(sensor_data));

    int i = 0;
    char buffer[1024];
    while(fgets(buffer, sizeof(buffer), file) && i < limit) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        sscanf(buffer, "%63s %d %15s", pdu.RX_UE_INFORMATION_TAG, &pdu.RNTI, pdu.CRC_INDICATION_REL8_TAG);

        sensor_data data;
        sscanf(buffer + 64, "%d %f %c", &data.timestamp, &data.temperature, &data.status);

        array[i] = pdu;
        data_array[i] = data;
        i++;
    }

    fclose(file);

    // Validate unique keys and size threshold
    for (int j = 0; j < i; j++) {
        // Check if RNTI is unique
        int found = 0;
        for (int k = 0; k < i; k++) {
            if (k != j && array[k].RNTI == array[j].RNTI) {
                printf("Error: Duplicate RNTI\n");
                return NULL;
            }
        }

        // Check size threshold
        if (data_array[j].temperature > 100 || data_array[j].status != ' ') {
            printf("Error: Sensor reading exceeds size threshold\n");
            return NULL;
        }
    }

    int ret = i;

    // Free the memory
    free(data_array);
    free(array);

    return &array[0];
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* result = parse_file("file.txt", 1000);
    printf("%d\n", result ? result : -1);
    return 0;
}
