import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class HashGenerator {
    private static final int NUM_THREADS = 10; // number of threads to use
    private static final String HASH_ALGORITHM = "SHA-256"; // the hash algorithm to use

    public void generateHash(String input) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);
        long startTime = System.currentTimeMillis();

        try {
            MessageDigest md = MessageDigest.getInstance(HASH_ALGORITHM);
            byte[] messageBytes = input.getBytes("UTF-8");
            byte[] hashBytes = md.digest(messageBytes);

            String hash = bytesToHex(hashBytes);

            // track the time it took to generate the hash
            long endTime = System.currentTimeMillis();
            long duration = endTime - startTime;

            // log the hash generation details
            logHashGenerationDetails(input, hash, duration);
        } finally {
            executor.shutdownNow(); // shut down the thread pool when done
        }
    }

    private void logHashGenerationDetails(String input, String hash, long duration) {
        // use a logging framework to log the hash generation details
        // for example:
        org.slf4j.Logger logger = org.slf4j.LoggerFactory.getLogger(HashGenerator.class);
        logger.info("Generated SHA-256 hash for '{}' in {} ms: {}", input, duration, hash);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder hexString = new StringBuilder();
        for (byte aByte : bytes) {
            String hexadecimal = Integer.toHexString(0xFF & aByte);
            hexString.append((hexadecimal.length() == 1) ? "0" + hexadecimal : hexadecimal);
        }
        return hexString.toString();
    }
}
