#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_NFAPI_PDU_COUNT 1000
#define DYNAMIC_MAX_NFAPI_PDU_COUNT 2000
#define MEMORY_THRESHOLD_BYTES (1024 * 1024) // 1MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    unsigned char CRCFLAG:1;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfaPiPduArrayAllocator(size_t size) {
    return malloc(size);
}

void nfaPiPduArrayDeallocator(void* ptr, size_t size) {
    free(ptr);
}

void initNfaPiPdu(NFAPI_CRC_INDICATION_PDU_T* pDu, int rnti) {
    // Initialize CRCFLAG randomly
    srand(time(NULL));
    pDu->CRCFLAG = rand() & 1;
    pDu->RX_UE_INFORMATION_TAG = rand();
    pDu->RNTI = rnti;
    pDu->CRC_INDICATION_REL8_TAG = rand();
}

int validateNfaPiPdu(NFAPI_CRC_INDICATION_PDU_T* pDu) {
    // Validate structure integrity
    if (pDu == NULL || pDu->RX_UE_INFORMATION_TAG < 0 ||
        pDu->RNTI < 0 || pDu->CRC_INDICATION_REL8_TAG < 0)
        return -1;
    return 0;
}

int getUniqueRnti(pthread_mutex_t* mutex, int* rntis, int count) {
    pthread_mutex_lock(mutex);
    for (int i = 0; i < count; i++) {
        if (rntis[i] > MAX_NFAPI_PDU_COUNT) {
            return -1;
        }
        if (!findRnti(rntis, i, count)) {
            rntis[i]++;
            return 0;
        }
    }
    pthread_mutex_unlock(mutex);
    return -1; // No unique RNTI found
}

int findRnti(int* rntis, int idx, int count) {
    for (int i = 0; i < count; i++) {
        if (rntis[i] == idx)
            return 1;
    }
    return 0;
}

void* nfaPiPduArrayPopulator(void* ptr, size_t size, pthread_mutex_t* mutex) {
    NFAPI_CRC_INDICATION_PDU_T** pduArray = (NFAPI_CRC_INDICATION_PDU_T**)ptr;
    int rntis[MAX_NFAPI_PDU_COUNT];
    for (int i = 0; i < MAX_NFAPI_PDU_COUNT; i++)
        rntis[i] = 0;

    pthread_mutex_lock(mutex);
    for (int i = 0; i < DYNAMIC_MAX_NFAPI_PDU_COUNT; i++) {
        int rnti = getUniqueRnti(mutex, rntis, i + 1);
        if (rnti == -1) break;
        NFAPI_CRC_INDICATION_PDU_T* pDu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        initNfaPiPdu(pDu, rnti);
        pduArray[i] = pDu;
    }
    pthread_mutex_unlock(mutex);

    // Validate each structure and free duplicates
    for (int i = 0; i < DYNAMIC_MAX_NFAPI_PDU_COUNT; i++) {
        if (validateNfaPiPdu(pduArray[i]) == -1) {
            free(pduArray[i]);
            pduArray[i] = NULL;
            continue;
        }
        // Validate RNTI uniqueness
        for (int j = 0; j < i; j++) {
            if (pduArray[j]->RNTI == pduArray[i]->RNTI) {
                free(pduArray[i]);
                pduArray[i] = NULL;
                break;
            }
        }
    }

    // Monitor memory usage and implement resource recovery
    int totalMemoryUsage = 0;
    for (int i = 0; i < DYNAMIC_MAX_NFAPI_PDU_COUNT; i++) {
        if (pduArray[i] != NULL) {
            totalMemoryUsage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
    }

    // Log errors and debugging information
    FILE* logFile = fopen("nfaPiPdu.log", "a");
    fprintf(logFile, "Total memory usage: %d bytes\n", totalMemoryUsage);
    fclose(logFile);

    return pduArray;
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T** pduArray = (NFAPI_CRC_INDICATION_PDU_T**)nfaPiPduArrayAllocator(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * DYNAMIC_MAX_NFAPI_PDU_COUNT);
    void* ptr = nfaPiPduArrayPopulator(pduArray, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * DYNAMIC_MAX_NFAPI_PDU_COUNT, &mutex);

    // Use the populated pduArray for further processing
    return 0;
}
