#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>

#define MAX_NFAPI_PDU_COUNT 1000
#define DYNAMIC_MAX_NFAPI_PDU_COUNT 2000
#define MEMORY_THRESHOLD_BYTES (1024 * 1024)

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_array(int count) {
    return (NFAPI_CRC_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void init_array(NFAPI_CRC_INDICATION_PDU_T* array, int count) {
    for (int i = 0; i < count; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = (rand() % 1000);
        array[i].CRC_INDICATION_REL8_TAG = rand();
        array[i].CRCFLAG = rand() & 1;
    }
}

int find_duplicates(NFAPI_CRC_INDICATION_PDU_T* array, int count) {
    int duplicates = 0;
    for (int i = 0; i < count; i++) {
        for (int j = i + 1; j < count; j++) {
            if (array[i].RNTI == array[j].RNTI) {
                duplicates++;
                break;
            }
        }
    }
    return duplicates;
}

void validate_array(NFAPI_CRC_INDICATION_PDU_T* array, int count) {
    for (int i = 0; i < count; i++) {
        if (array[i].RX_UE_INFORMATION_TAG < 0 || array[i].RX_UE_INFORMATION_TAG > 255) {
            printf("Invalid RX UE INFORMATION TAG at index %d\n", i);
        }
        if (array[i].RNTI < 0 || array[i].RNTI > 1000) {
            printf("Invalid RNTI at index %d\n", i);
        }
        if (array[i].CRC_INDICATION_REL8_TAG < 0 || array[i].CRC_INDICATION_REL8_TAG > 255) {
            printf("Invalid CRC INDICATION REL8 TAG at index %d\n", i);
        }
        if (array[i].CRCFLAG != 0 && array[i].CRCFLAG != 1) {
            printf("Invalid CRC FLAG at index %d\n", i);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_array(int count, int* actual_count) {
    NFAPI_CRC_INDICATION_PDU_T* array = create_array(count);
    init_array(array, count);
    *actual_count = find_duplicates(array, count);
    validate_array(array, count);
    return array;
}

int main() {
