#define MAX_NF_CP_REQUESTS 1000
#define EPS_MOBILITY_STATE_INDICATOR_MIN 1
#define EPS_MOBILITY_STATE_INDICATOR_MAX 5

typedef struct {
    // UE context request details
    char ue_context_request[64];

    // MME ID
    uint32_t mme_id;

    // EPS Mobility Management Information
    int eps_mobility_state_indicator;
} NF_CP_SessionManagementRequests;

NF_CP_SessionManagementRequests* create_nf_cp_session_management_requests(int num_requests) {
    NF_CP_SessionManagementRequests* requests = (NF_CP_SessionManagementRequests*)calloc(num_requests, sizeof(NF_CP_SessionManagementRequests));

    if (!requests) {
        printf("Error: Failed to allocate memory for NF CP session management requests.\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < num_requests; i++) {
        requests[i].ue_context_request[0] = '\0'; // Initialize UE context request string
        requests[i].mme_id = rand() % 1000; // Randomly set MME ID

        // Set random EPS mobility state indicator
        requests[i].eps_mobility_state_indicator = rand() % (EPS_MOBILITY_STATE_INDICATOR_MAX - EPS_MOBILITY_STATE_INDICATOR_MIN + 1) + EPS_MOBILITY_STATE_INDICATOR_MIN;
    }

    return requests;
}

int validate_nf_cp_session_management_requests(NF_CP_SessionManagementRequests* requests, int num_requests) {
    for (int i = 0; i < num_requests; i++) {
        if (!requests[i].ue_context_request[0]) {
            printf("Error: UE context request string is empty at index %d.\n", i);
            return -1;
        }
        if (requests[i].mme_id <= 0) {
            printf("Error: MME ID is invalid at index %d.\n", i);
            return -1;
        }
        if (requests[i].eps_mobility_state_indicator < EPS_MOBILITY_STATE_INDICATOR_MIN || requests[i].eps_mobility_state_indicator > EPS_MOBILITY_STATE_INDICATOR_MAX) {
            printf("Error: EPS mobility state indicator is out of range at index %d.\n", i);
            return -1;
        }
    }

    return 0;
}

void log_nf_cp_session_management_requests(NF_CP_SessionManagementRequests* requests, int num_requests, const char* log_file_name) {
    FILE* log_file = fopen(log_file_name, "a");
    if (!log_file) {
        printf("Error: Failed to open log file.\n");
        return;
    }

    for (int i = 0; i < num_requests; i++) {
        fprintf(log_file, "UE context request: %s, MME ID: %u, EPS mobility state indicator: %d\n", requests[i].ue_context_request, requests[i].mme_id, requests[i].eps_mobility_state_indicator);
    }

    fclose(log_file);
}

void free_nf_cp_session_management_requests(NF_CP_SessionManagementRequests* requests, int num_requests) {
    for (int i = 0; i < num_requests; i++) {
        if (requests[i].ue_context_request[0]) {
            free(requests[i].ue_context_request); // Free dynamically allocated UE context request string
        }
    }

    free(requests);
}

NF_CP_SessionManagementRequests* adjust_nf_cp_session_management_requests(NF_CP_SessionManagementRequests* requests, int num_requests, double network_load) {
    if (network_load > 0.5) { // Adjust number of requests based on current network load
        num_requests = (int)(num_requests * 1.2); // Increase number of requests by 20%
    } else if (network_load < 0.3) {
        num_requests = (int)(num_requests * 0.8); // Decrease number of requests by 20%

    }

    return requests;
}

// Example usage:
int main() {
    int num_requests = 5; // Initial number of requests
    NF_CP_SessionManagementRequests* requests = create_nf_cp_session_management_requests(num_requests);

    if (!requests) {
        printf("Error: Failed to create NF CP session management requests.\n");
        return -1;
    }

    int result = validate_nf_cp_session_management_requests(requests, num_requests);
    if (result < 0) {
        printf("Error: Validation failed. Returning error code %d.\n", result);
        free_nf_cp_session_management_requests(requests, num_requests); // Free allocated resources
        return -1;
    }

    log_nf_cp_session_management_requests(requests, num_requests, "nf_cp_request_log.txt");

    requests = adjust_nf_cp_session_management_requests(requests, num_requests, 0.4);

    free_nf_cp_session_management_requests(requests, num_requests); // Free allocated resources

    return 0;
}
