// Hash table structure to manage device status
typedef struct {
    size_t capacity;
    size_t size;
    NetworkDeviceStatus** devices;
} HashTable;

HashTable* createHashTable(size_t capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->size = 0;
    table->devices = (NetworkDeviceStatus**)calloc(capacity, sizeof(NetworkDeviceStatus*));
    return table;
}

void destroyHashTable(HashTable* table) {
    for (size_t i = 0; i < table->size; ++i) {
        free(table->devices[i]);
    }
    free(table->devices);
    free(table);
}

NetworkDeviceStatus* createDevice(int deviceID, double uptime, double loadAverage, double temperature) {
    NetworkDeviceStatus* device = (NetworkDeviceStatus*)malloc(sizeof(NetworkDeviceStatus));
    device->deviceID = deviceID;
    device->uptime = uptime;
    device->loadAverage = loadAverage;
    device->temperature = temperature;
    return device;
}

void updateDevice(HashTable* table, int deviceID, double newLoadAverage) {
    for (size_t i = 0; i < table->size; ++i) {
        if (table->devices[i]->deviceID == deviceID) {
            table->devices[i]->loadAverage = newLoadAverage;
            return;
        }
    }
}

void computeAverageLoad(HashTable* table, double* averageLoad) {
    *averageLoad = 0.0;
    for (size_t i = 0; i < table->size; ++i) {
        *averageLoad += table->devices[i]->loadAverage;
    }
    *averageLoad /= table->size;
}

void initializeHashTable(HashTable* table, int deviceCount) {
    for (int i = 0; i < deviceCount; ++i) {
        int deviceID = // generate unique device ID
        double uptime = // compute uptime
        double loadAverage = // compute initial load average
        double temperature = // compute temperature

        NetworkDeviceStatus* device = createDevice(deviceID, uptime, loadAverage, temperature);
        table->devices[table->size] = device;
        table->size++;
    }
}

int main() {
    HashTable* table = createHashTable(1000); // initial capacity
    initializeHashTable(table, 100); // initialize with 100 devices

    double averageLoad = 0.0;
    computeAverageLoad(table, &averageLoad);

    printf("Average load: %.2f\n", averageLoad);

    updateDevice(table, 42, 0.5); // update device 42's load average

    destroyHashTable(table);
    return 0;
}
