#include <time.h>
#include <string.h>

#define MAX_NF_CP_REQUESTS 1000
#define LOG_FILE "nf_cp_requests.log"

typedef struct {
    int ue_context_request;
    int mme_id;
    int eps_mobility_state_indicator;
} UE_CONTEXT_REQUEST;

typedef struct {
    UE_CONTEXT_REQUEST ue_context;
    int eps_mobility_management_info;
} NF_CP_SESSION_MANAGEMENT_REQUEST;

void* nf_cp_allocate_request() {
    NF_CP_SESSION_MANAGEMENT_REQUEST* request = (NF_CP_SESSION_MANAGEMENT_REQUEST*)malloc(sizeof(NF_CP_SESSION_MANAGEMENT_REQUEST));
    if (!request) {
        fprintf(stderr, "Failed to allocate memory for NF CP session management request.\n");
        return NULL;
    }
    return request;
}

int validate_request(NF_CP_SESSION_MANAGEMENT_REQUEST* request) {
    // Check integrity of the request structure
    if (request->ue_context.ue_context_request < 0 || request->ue_context.ue_context_request > 1000) {
        return -1; // Invalid UE context request
    }
    if (request->ue_context.mme_id < 0 || request->ue_context.mme_id > 65535) {
        return -2; // Invalid MME ID
    }
    if (request->eps_mobility_management_info < 0 || request->eps_mobility_management_info > 100) {
        return -3; // Invalid EPS mobility management information
    }
    return 0; // Request is valid
}

NF_CP_SESSION_MANAGEMENT_REQUEST* nf_cp_populate_requests(int num_requests, FILE* log_file) {
    NF_CP_SESSION_MANAGEMENT_REQUEST* requests = (NF_CP_SESSION_MANAGEMENT_REQUEST*)malloc(num_requests * sizeof(NF_CP_SESSION_MANAGEMENT_REQUEST));
    if (!requests) {
        fprintf(stderr, "Failed to allocate memory for NF CP session management requests.\n");
        return NULL;
    }
    srand(time(NULL)); // Initialize random number generator

    for (int i = 0; i < num_requests; i++) {
        NF_CP_SESSION_MANAGEMENT_REQUEST* request = &requests[i];
        request->ue_context.ue_context_request = rand() % 1001;
        request->ue_context.mme_id = rand() % 65536;
        request->eps_mobility_state_indicator = rand() % 101;

        int error = validate_request(request);
        if (error) {
            fprintf(log_file, "Error validating NF CP session management request.\n");
            return NULL; // Failed to allocate or validate requests
        }
    }

    return requests;
}

void nf_cp_free_requests(NF_CP_SESSION_MANAGEMENT_REQUEST* requests, int num_requests) {
    for (int i = 0; i < num_requests; i++) {
        free(requests + i);
    }
    free(requests);
}
