    }

    return arr;
}

// Function to allocate memory and initialize LTE_ENB_CONFIG_RRC_T structures
LTE_ENB_CONFIG_RRC_T* allocate_lte_enb_config_rrc_t(int n) {
    // Allocate memory for array of pointers
    LTE_ENB_CONFIG_RRC_T* arr = (LTE_ENB_CONFIG_RRC_T*)malloc(n * sizeof(LTE_ENB_CONFIG_RRC_T));

