NFAPI_RX_FRAME_T* allocate_nfa_pi_rx_frame_t(int n) {
    // Allocate memory for array of pointers
    NFAPI_RX_FRAME_T* arr = (NFAPI_RX_FRAME_T*)malloc(n * sizeof(NFAPI_RX_FRAME_T));

    // Initialize array
    for (int i = 0; i < n; i++) {
        arr[i].rx_stream_tag = (char*)malloc(256); // assuming max stream tag length is 256
    }

    return arr;
}

// Function to generate metadata JSON file for each image
void generate_metadata_json_file(char* directory_path) {
    // Iterate through files in the directory
    DIR *dir = opendir(directory_path);
    struct dirent *ent;
    int i = 0;

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
            continue;
        }

        char file_path[256];
        strcpy(file_path, directory_path);
        strcat(file_path, "/");
        strcat(file_path, ent->d_name);

        // Generate metadata JSON file for each image
        FILE *fp = fopen(file_path, "r");
        if (fp == NULL) {
            continue;
        }

        int width, height;
        char* histogram, dominant_color;

        // Read image dimensions, color histogram, and dominant colors
        fread(&width, sizeof(int), 1, fp);
        fread(&height, sizeof(int), 1, fp);
        fread(histogram, sizeof(char), 256, fp);
        fread(&dominant_color, sizeof(char), 16, fp);

        // Generate metadata JSON file
        FILE *metadata_fp = fopen(strcat(directory_path, "/"), "w");
        fprintf(metadata_fp, "{\"filename\": \"%s\", \"dimensions\": [%d, %d], \"color histogram\": \"%s\", \"dominant color\": \"%s\"}", ent->d_name, width, height, histogram, dominant_color);
        fclose(metadata_fp);

        i++;
    }

    closedir(dir);
}

// Function to allocate memory for arrays and initialize sensor data
void allocate_sensor_data(int num_sensors) {
    // Allocate memory for array of long offset values
    long* offsets = (long*)malloc(num_sensors * sizeof(long));

    // Allocate memory for array of int keys
    int* keys = (int*)malloc(num_sensors * sizeof(int));

    // Allocate memory for array of float measurements
    float* measurements = (float*)malloc(num_sensors * sizeof(float));

    // Initialize sensor data
    for (int i = 0; i < num_sensors; i++) {
        offsets[i] = i;
        keys[i] = i;
        measurements[i] = (float)i / 10.0f;
    }
}

// Function to manage array of sensor_data structures
void manage_sensor_data(sensor_data* arr, int size) {
    // Validate that keys are unique and no sensor reading exceeds a specified size threshold
    for (int i = 0; i < size; i++) {
        if (arr[i].key != i) {
            printf("Error: Non-unique key at index %d.\n", i);
        }
    }
}
