pthread_mutex_t stats_lock = PTHREAD_MUTEX_INITIALIZER;
int current_tcp_packet_count = 0;
int delayed_tcp_packet_count = 0;

TCP_PACKET_STATS_T** get_tcp_packet_stats_array() {
    if (!tcp_packet_stats_array) {
        int size = MAX_TCP_PACKET_COUNT * sizeof(TCP_PACKET_STATS_T*);
        tcp_packet_stats_array = (TCP_PACKET_STATS_T**)malloc(size);
        for (int i = 0; i < MAX_TCP_PACKET_COUNT; i++) {
            tcp_packet_stats_array[i] = NULL;
        }
    }
    return tcp_packet_stats_array;
}

void put_tcp_packet_stats(TCP_PACKET_STATS_T* stats) {
    TCP_PACKET_STATS_T** array = get_tcp_packet_stats_array();
    pthread_mutex_lock(&stats_lock);
    if (current_tcp_packet_count < MAX_TCP_PACKET_COUNT) {
        int index = current_tcp_packet_count++;
        array[index] = stats;
    } else {
        // Dynamic scaling: reallocate and update
        int newSize = DYNAMIC_MAX_TCP_PACKET_COUNT * sizeof(TCP_PACKET_STATS_T*);
        void* new_array = realloc(array, newSize);
        if (new_array) {
            array = (TCP_PACKET_STATS_T**)new_array;
            for (int i = MAX_TCP_PACKET_COUNT; i < DYNAMIC_MAX_TCP_PACKET_COUNT; i++) {
                array[i] = NULL;
            }
            current_tcp_packet_count = DYNAMIC_MAX_TCP_PACKET_COUNT;
        } else {
            // Error: failed to reallocate
            printf("Error: failed to reallocate TCP packet stats array.\n");
            exit(1);
        }
    }
    pthread_mutex_unlock(&stats_lock);
}

