        this.priorityComparator = priorityComparator;
    }

    public void processTasks() {
        while (true) {
            Task task;
            try {
                task = AsynchronousTaskProcessor.taskQueue.take();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }

            // Process tasks based on the priority
            if (!processTask(task)) {
                break;
            }
        }
    }
}

