```
import requests
import json
from sqlite3 import connect

# Database connection
conn = connect('metadata.db')
cursor = conn.cursor()

def get_device_metadata():
    api_url = 'https://api.example.com/devices'
    response = requests.get(api_url)

    if response.status_code == 200:
        devices = json.loads(response.text)

        for device in devices:
            cursor.execute('INSERT OR REPLACE INTO metadata (device_id, status, operational_parameters) VALUES (?, ?, ?)', 
                           (device['id'], device['status'], json.dumps(device['operational_parameters'])))

    else:
        print(f'Failed to retrieve device metadata: {response.status_code}')

def update_metadata():
    cursor.execute('SELECT * FROM metadata')
    rows = cursor.fetchall()

    for row in rows:
        api_url = f'https://api.example.com/devices/{row[0]}'
        response = requests.get(api_url)

        if response.status_code == 200:
            device = json.loads(response.text)

            # Update database with new metadata
            cursor.execute('UPDATE metadata SET status = ?, operational_parameters = ? WHERE device_id = ?', 
                           (device['status'], json.dumps(device['operational_parameters']), row[0]))

        else:
            print(f'Failed to update device {row[0]}: {response.status_code}')

def commit_changes():
    conn.commit()

if __name__ == '__main__':
    get_device_metadata()
    update_metadata()
    commit_changes()
```

