#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    // metadata JSON file for each image
    // dimensions
    // color histogram
    // dominant colors
} IMAGE_METADATA_T;

void processDirectory(char* directoryPath) {
    DIR* dir = opendir(directoryPath);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", directoryPath);
        return;
    }

    while ((struct dirent* entry = readdir(dir))) {
        if (entry->d_type != DT_DIR) {
            char filePath[256];
            sprintf(filePath, "%s/%s", directoryPath, entry->d_name);
            FILE* file = fopen(filePath, "r");
            if (file == NULL) {
                printf("Error opening file: %s\n", filePath);
                continue;
            }

            IMAGE_METADATA_T image_metadata;
            // Read image dimensions
            int width, height;
            fscanf(file, "%d %d", &width, &height);
            image_metadata.dimensions = malloc(strlen("Dimensions") + 1);
            strcpy(image_metadata.dimensions, "Dimensions");
            image_metadata.dimensions_length = strlen(image_metadata.dimensions);

            // Read color histogram
            unsigned char* colors = (unsigned char*)malloc(256 * sizeof(unsigned char));
