**Java method to generate SHA-256 hashes**
```java
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;
import java.security.MessageDigest;
import java.nio.ByteBuffer;
import java.time.Instant;

public class HashGenerator {
    public static String generateSha256Hash(String input, byte[] secretKey) throws Exception {
        Mac mac = Mac.getInstance("SHA-256");
        SecretKeySpec keySpec = new SecretKeySpec(secretKey, "HmacSHA256");
        mac.init(keySpec);
        byte[] hashBytes = mac.doFinal(input.getBytes());
        return bytesToHex(hashBytes);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
