NFAPI_CRC_INDICATION_PDU_T *parse_file(char *filename, int *num_structures) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return NULL;  // failed to open file
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = NULL;
    int allocated_size = 0;

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu, sizeof(pdu), 1, file);
        if (ferror(file)) {
            fclose(file);
            return NULL;  // error reading file
        }
        if (feof(file)) {
            break;
        }

        if (allocated_size == 0) {
            pdu_array = malloc(sizeof(*pdu_array));
            allocated_size = 1;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *temp = realloc(pdu_array, (allocated_size + 1) * sizeof(*pdu_array));
            if (temp == NULL) {
                fclose(file);
                free(pdu_array);
                return NULL;  // failed to allocate memory
            }
            pdu_array = temp;
            allocated_size++;
        }

        pdu_array[allocated_size - 1] = pdu;

    }

    fclose(file);

    *num_structures = allocated_size;
    return pdu_array;
}

int verify_input(input_struct *input) {
    if (input->password == NULL || strlen(input->password) == 0) {
        return -1;  // password is empty or null
    }
    if (input->conn == NULL || input->conn->title == NULL) {
        return -2;  // connection has no title
    }
    if (input->callback == NULL) {
        return -3;  // callback function is null
    }

    return 0;  // all checks passed
}

