```python
import subprocess
import json
import paramiko

def modify_kickstart_config(config_file_path, placeholder_values):
    with open(config_file_path, 'r') as f:
        config_contents = f.read()

    for placeholder, value in placeholder_values.items():
        sed_cmd = f'sed -i "s/{placeholder}/{value}/g" {config_file_path}'
        try:
            subprocess.check_call(sed_cmd, shell=True)
        except subprocess.CalledProcessError as e:
            print(f"Sed command failed: {e}")
            # attempt to rollback changes
            with open(config_file_path, 'w') as f:
                f.write(config_contents)

    # add new line with encrypted password
    password = paramiko.generate_password(32)
    with open(config_file_path, 'a') as f:
        f.write(f"encrypted_password={paramiko.encrypt(password)}\n")
