import subprocess
import json

def modify_network_config_file(file_path, params):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            for key, value in params.items():
                command = f"awk -v '{key}={value}' '{content}' > temp"
                subprocess.run(command.split(), stdout=subprocess.PIPE)
                file.close()
                os.remove(file_path)
                os.rename('temp', file_path)
    except FileNotFoundError:
        print(f"File {file_path} not found")
    except Exception as e:
        raise Exception("Error modifying network config file") from e

