    TCP_CONNECTION_STATS_T* stats = (TCP_CONNECTION_STATS_T*)malloc(num_connections * sizeof(TCP_CONNECTION_STATS_T));
    if (!stats) {
        return NULL; // failed to allocate memory
    }

    for (int i = 0; i < num_connections; i++) {
        stats[i].BYTES_SENT = 0;
        stats[i].BYTES_RECEIVED = 0;
        stats[i].ACTIVE_TIME = time(NULL);
        stats[i].LAST_ACK_TIME = time(NULL);
    }

    return stats;
}

void parse_tcp_connection_stats_from_file(const char* filename, int num_connections, TCP_CONNECTION_STATS_T** stats) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Failed to open file: %s\n", filename);
        return; // failed to open file
    }

    for (int i = 0; i < num_connections; i++) {
        TCP_CONNECTION_STATS_T stat;
        fread(&stat, sizeof(TCP_CONNECTION_STATS_T), 1, file); // read one structure at a time

        if (ferror(file) || fgetc(file) != '\n') { // check for errors
            printf("Failed to parse file: %s\n", filename);
            fclose(file);
            return; // failed to parse file
        }

        (*stats)[i] = stat;
    }

    fclose(file);
}

