void* fetch_certificate(OAuthResponse response) {
    // implement OAuth request and certificate extraction logic
    SSL_CTX* ctx = SSL_CTX_new(TLS_client_method());
    SSL* ssl = SSL_new(ctx);

    // extract private key and certificate from response
    X509* cert = response.get_certificate();
    EVP_PKEY* priv_key = response.get_private_key();

    // validate certificate against known authorities
    if (!X509_verify(cert, priv_key)) {
        ERR_error_string(0);
        return NULL; // invalid certificate
    }

    // combine private key and certificate into a single PEM file
    FILE* pem_file = fopen("certificate.pem", "wb");
    if (!pem_file) return NULL; // failed to create PEM file

    i2d_X509(cert, pem_file);
    i2o_EVP_PKEY(priv_key, pem_file);

    fclose(pem_file);
    SSL_free(ssl);
    SSL_CTX_free(ctx);
    return "certificate.pem";
}
