        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageBytes = input.getBytes();
            byte[] digest = md.digest(messageBytes);

            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
