#include <stdlib.h>
#include <stdio.h>
#include "validation.h"
#include "service_api.h"

#define MAX_REQUESTS 1024
#define USER_ID_LENGTH 16
#define TIMESTAMP_MAX 2147483647
#define TIMESTAMP_MIN 0

typedef struct {
    char user_id[USER_ID_LENGTH];
    int timestamp;
    int status;
} USER_REQUEST_T;

void processUserRequestsQueue(USER_REQUEST_T* requests, size_t num_requests) {
    pthread_mutex_lock(&requests_mutex);

    for (size_t i = 0; i < num_requests; i++) {
        if (requests[i].timestamp > TIMESTAMP_MAX || requests[i].timestamp < TIMESTAMP_MIN) {
            // Invalid timestamp
            continue;
        }

        if (!validate_timestamp(requests[i].timestamp)) {
            // Invalid character sequence in timestamp
            continue;
        }

        if (strlen(requests[i].user_id) != USER_ID_LENGTH) {
            // Incorrect user ID length
            continue;
        }

        int prev_request_status = -1;
        for (size_t j = 0; j < i; j++) {
            if (!strcmp(requests[j].user_id, requests[i].user_id)) {
                // Duplicate user identifier
                break;
            } else if (requests[j].status != 0) {
                prev_request_status = requests[j].status;
                break;
            }
        }

        if (prev_request_status == -1) {
            // No duplicate or unprocessed request found
            process_request(&requests[i]);
        } else {
            // Process previous request first
            process_request(&requests[prev_request_status]);
        }
    }

    pthread_mutex_unlock(&requests_mutex);
}

void process_request(USER_REQUEST_T* request) {
    // Call service API library to process the request
    int api_return_code = service_api_process_request(request->user_id, request->timestamp);

    if (api_return_code < 0) {
        // API call failed; log error and retry
        log_error("API call failed with code %d", api_return_code);

        for (int i = 0; i < 3 && request->status == 0; i++) {
            sleep(1); // configurable delay

            api_return_code = service_api_process_request(request->user_id, request->timestamp);

            if (api_return_code >= 0) {
                break;
            }
        }

        if (request->status != 1) {
            log_error("Failed to process request after %d retries", i + 1);
        }
    } else {
        // API call successful; update request status
        request->status = api_return_code;

        // Log request processing time and success/failure status
        log_info("Processed request in %.2fs with status %s", request->timestamp, request->status ? "success" : "failure");
    }
}

void log_error(const char* message) {
    // Log error to file or database; implement logging mechanism here
    printf("%s\n", message);
}

int main() {
    // Initialize requests queue and service API library
    USER_REQUEST_T requests[MAX_REQUESTS];

    // Process user requests in the queue
    processUserRequestsQueue(requests, 1024);

    return 0;
}
