```java
import java.util.concurrent.*;
import java.util.logging.*;

public class AsyncTaskService {
    private static final Logger LOGGER = Logger.getLogger(AsyncTaskService.class.getName());
    private int maxWorkers;
    private int minWorkers;
    private ExecutorService executor;

    public AsyncTaskService(int maxWorkers, int minWorkers) {
        this.maxWorkers = maxWorkers;
        this.minWorkers = minWorkers;
        executor = new ThreadPoolExecutor(minWorkers, maxWorkers, 0, TimeUnit.MILLISECONDS, new LinkedBlockingQueue<Runnable>());
    }

    public void processTasks(List<Runnable> tasks) {
        for (Runnable task : tasks) {
            executor.submit(task);
        }
    }

    public void shutdown() {
        executor.shutdown();
    }
}
