        NFAPI_RX_FRAME_T* frame = &((NFAPI_RX_FRAME_T*)frames)[i];
        frame->frame_tag.SNR = -1; // Default SNR value
        frame->frame_tag.RSSI = -1; // Default RSSI value
        frame->frame_tag.TIMESTAMP = 0; // Initialize timestamp to 0
        frame->frame_tag.ANTENNA_GAIN = 0.0; // Initialize antenna gain to 0.0
    }

    return frames;
}

void nfapi_rx_frame_pool_destroy(void* pool) {
    free(pool);
}

NFAPI_RX_FRAME_T* nfapi_rx_frame_pool_allocate(NFAPI_RX_FRAME_T** cache, void* pool, int* free_frames_left) {
    NFAPI_RX_FRAME_T* frame = NULL;

    // Check cache for available frames
    if (*cache != NULL && *free_frames_left > 0) {
        frame = (*cache)[(*free_frames_left) - 1];
        (*free_frames_left)--;
    } else {
        frame = ((NFAPI_RX_FRAME_T*)pool) + (*free_frames_left);
        (*free_frames_left)++;
    }

    return frame;
}

void nfapi_rx_frame_pool_deallocate(NFAPI_RX_FRAME_T** cache, void* pool, int* free_frames_left, NFAPI_RX_FRAME_T* frame) {
    if (frame != NULL) {
        if (*cache == NULL || *free_frames_left >= 1024) {
            // Add to cache
            (*cache)[(*free_frames_left)] = frame;
            (*free_frames_left)++;
        } else {
            // Reclaim memory
            ((NFAPI_RX_FRAME_T*)pool)[(*free_frames_left)] = frame->frame_tag;
            (*free_frames_left)++;
        }
    }
}

void nfapi_rx_frame_pool_log(void* pool, int total_frames, int free_frames) {
    printf("Total frames: %d\n", total_frames);
    printf("Free frames: %d\n", free_frames);
}
