#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    int SNR;
    int RSSI;
    long TIMESTAMP;
    float ANTENNA_GAIN;
} RX_FRAME_TAG;

typedef struct {
    RX_FRAME_TAG tag;
    // Additional fields to be added
} NFAPI_RX_FRAME_T;

// Global variables
static NFAPI_RX_FRAME_T* frames = NULL;
static size_t frame_count = 0;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void init_pool(size_t max_frames, size_t max_memory) {
    // Initialize the pool with the requested number of frames
    frames = (NFAPI_RX_FRAME_T*)malloc(max_frames * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) {
        printf("Memory allocation failed\n");
        return;
    }

    frame_count = max_frames;
}

void destroy_pool() {
    // Free the allocated memory
    free(frames);
    frames = NULL;
    frame_count = 0;
}

NFAPI_RX_FRAME_T* get_frame() {
    pthread_mutex_lock(&mutex);

    // Check if there are available frames in the pool
    if (frame_count == 0) {
        pthread_cond_wait(&cond, &mutex);
    }

    NFAPI_RX_FRAME_T* frame = &frames[frame_count - 1];
    frame_count--;

    pthread_mutex_unlock(&mutex);
    return frame;
}

void release_frame(NFAPI_RX_FRAME_T* frame) {
    pthread_mutex_lock(&mutex);

    // Check if the released frame is being used
    if (frame->tag.SNR > 0) {
        // If the frame is being used, wait for it to be released again
        pthread_cond_wait(&cond, &mutex);
    }

    frame_count++;
    pthread_mutex_unlock(&mutex);
}

void log_usage() {
    // Log memory usage, frame utilization, and cache hit/miss ratios
    printf("Memory usage: %zu bytes\n", sizeof(NFAPI_RX_FRAME_T) * frame_count);
    printf("Frame utilization: %f%%\n", (frame_count / (double)max_frames) * 100);
    // Log cache hit/miss ratios
}

void* thread_func(void* arg) {
    int i = 0;

    while (1) {
        NFAPI_RX_FRAME_T* frame = get_frame();

        if (!frame) {
            break;
        }

        // Use the frame
        for (i = 0; i < 10; i++) {
            frame->tag.SNR++;
            frame->tag.RSSI++;
            frame->tag.TIMESTAMP++;
            frame->tag.ANTENNA_GAIN += 1.0 / 10.0;
        }

        release_frame(frame);
    }

    return NULL;
}

int main() {
    pthread_t thread[4];

    // Initialize the pool with a maximum of 1024 frames and 256 MB memory
    init_pool(1024, (2 * 1024 * 1024));

    for (int i = 0; i < 4; i++) {
        pthread_create(&thread[i], NULL, thread_func, NULL);
    }

    // Perform some operations on the frames
    for (i = 0; i < 10000; i++) {
        log_usage();
        sleep(1); // Wait for a second before logging again
    }

    // Destroy the pool
    destroy_pool();

    return 0;
}

