        if (!transaction) {
            break;
        }

        // Process transactions in batches
        for (int i = 0; i < BATCH_SIZE && transactions->size > i; i++) {
            transaction = thread_safe_dequeue(transactions);
            if (!transaction) {
                break;
            }
            processTransaction(transaction);
        }
    }
}

