#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_NFAPI_PDU_COUNT 1000
#define MAX_DYNAMIC_RESIZE_COUNT 10
#define MAX_THREAD_COUNT 5
#define LOG_FILE_MAX_SIZE 1048576

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_array(int count) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    FILE *log_file = fopen("nfaapi_log.txt", "w");

    int allocated_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;

    while (allocated_count < count && allocated_count < MAX_NFAPI_PDU_COUNT) {
        array = realloc(array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (allocated_count + MAX_DYNAMIC_RESIZE_COUNT));

        for (int i = 0; i < MAX_DYNAMIC_RESIZE_COUNT; i++) {
            array[allocated_count].ue_info.tag = (RX_UE_INFORMATION_TAG){.tag_value = rand() % RAND_MAX};
            array[allocated_count].rnti.rnti_value = rand() % RAND_MAX;
            array[allocated_count].crc_indication.crcflag = (CRCFLAG)(rand() % RAND_MAX);

            pthread_mutex_lock(&lock);
            if (fwrite(&array[allocated_count], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, log_file) != 1) {
                perror("Error writing to log file");
                return NULL;
            }
            pthread_mutex_unlock(&lock);
            allocated_count++;
        }
    }

    if (fseek(log_file, 0L, SEEK_END) == -1 || ftell(log_file) > LOG_FILE_MAX_SIZE) {
        fclose(log_file);
        return NULL;
    }

    rewind(log_file);
    fclose(log_file);

    pthread_mutex_unlock(&lock);
    return array;
}

void process_directory(const char* directory_path) {
    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        perror("Error opening directory");
        return;
    }

    struct dirent* entry = readdir(dir);
    while (entry != NULL) {
        char filename[256];
        sprintf(filename, "%s/%s_unique_id.txt", directory_path, entry->d_name);

        if (access(filename, F_OK) == -1) {
            printf("File not found: %s\n", filename);
            return;
        }

        int available_space = disk_usage(directory_path);
        if (available_space < strlen(filename)) {
            printf("Not enough space to rename file: %s\n", filename);
            return;
        }

        rename_directory_entry(entry->d_name, filename);
    }

    closedir(dir);
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    int count = 5000;
    NFAPI_CRC_INDICATION_PDU_T* array = nfapi_crc_indication_pdu_array(count);

    if (array != NULL) {
        process_directory("/path/to/directory");

        for (int i = 0; i < count; i++) {
            // Process each structure in the array
            printf("Processing %d-th NFAPI CRC indication PDU...\n", i + 1);
        }
    } else {
        printf("Failed to allocate memory\n");
    }

    return 0;
}

