#include <stdlib.h>
#include <string.h>

typedef struct {
    int SEQUENCE_NUMBER;
    char FRAME_TYPE[10];
    unsigned char *DATA_PAYLOAD;
} MAC_FRAME;

// Dynamic list of MAC_FRAME structures
typedef struct {
    MAC_FRAME **frames;
    int size;
    int capacity;
} MAC_FRAME_LIST;

MAC_FRAME_LIST* mac_frame_list_create(int initial_capacity) {
    MAC_FRAME_LIST* list = (MAC_FRAME_LIST*) malloc(sizeof(MAC_FRAME_LIST));
    list->size = 0;
    list->capacity = initial_capacity;
    list->frames = (MAC_FRAME**) calloc(initial_capacity, sizeof(MAC_FRAME*));
    return list;
}

void mac_frame_list_add(MAC_FRAME_LIST* list, MAC_FRAME* frame) {
    if (list->size >= list->capacity) {
        // Resize the list
        int new_capacity = list->capacity * 2 + 1;
        MAC_FRAME** new_frames = (MAC_FRAME**) realloc(list->frames, new_capacity * sizeof(MAC_FRAME*));
        list->frames = new_frames;
        list->capacity = new_capacity;
    }
    list->frames[list->size] = frame;
    list->size++;
}

MAC_FRAME* mac_frame_list_get_by_sequence_number(MAC_FRAME_LIST* list, int sequence_number) {
    for (int i = 0; i < list->size; i++) {
        if (list->frames[i]->SEQUENCE_NUMBER == sequence_number) {
            return list->frames[i];
        }
    }
    return NULL;
}

void mac_frame_list_remove_by_condition(MAC_FRAME_LIST* list, int (*condition)(MAC_FRAME*)) {
    for (int i = 0; i < list->size; i++) {
        if (condition(list->frames[i])) {
            // Remove the frame
            memmove(&list->frames[i], &list->frames[i + 1], (list->size - i - 1) * sizeof(MAC_FRAME*));
            list->size--;
            i--; // Decrement i to re-check the same frame again
        }
    }
}

void mac_frame_list_free(MAC_FRAME_LIST* list) {
    for (int i = 0; i < list->size; i++) {
        free(list->frames[i]->DATA_PAYLOAD);
        free(list->frames[i]);
    }
    free(list->frames);
    free(list);
}
