public class FileProcessor {

    public static String processFiles(List<String> filePaths) {
        StringBuilder report = new StringBuilder();
        for (String filePath : filePaths) {
            try {
                File file = new File(filePath);
                if (!file.isFile()) continue;
                long fileSize = Files.size(Paths.get(file.getAbsolutePath()));
                Date lastModified = new Date(file.lastModified());
                report.append("File: ").append(filePath).append("\n");
                report.append("  Size: ").append(fileSize).append(" bytes\n");
                report.append("  Last modified: ").append(formatDate(lastModified)).append("\n");
            } catch (IOException e) {
                report.append("Error processing file: ").append(filePath).append(" - ").append(e.getMessage()).append("\n");
            }
        }
        return report.toString();
    }

    private static String formatDate(Date date) {
        SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        return format.format(date);
    }
}
