import java.net.URL;
import java.io.IOException;
import java.util.List;
import java.util.ArrayList;
import java.util.Map;

public class URLProcessor {

    public static List<Map<String, String>> processURLs(List<String> urls) {
        List<Map<String, String>> result = new ArrayList<>();
        for (String url : urls) {
            try {
                URL targetUrl = new URL(url);
                if (targetUrl.getProtocol().equals("http") || targetUrl.getProtocol().equals("https")) {
                    Map<String, String> headers = getHTTPHeaders(targetUrl);
                    if (headers != null && isAccessibleURL(targetUrl)) {
                        result.add(headers);
                    }
                }
            } catch (IOException e) {
                // handle IO exception
            } catch (Exception e) {
                // handle other exceptions
            }
        }
        return result;
    }

    private static Map<String, String> getHTTPHeaders(URL url) throws IOException {
        java.net.URLConnection connection = url.openConnection();
        connection.connect();
        Map<String, String> headers = new HashMap<>();
        for (String key : connection.getHeaderKeys()) {
            headers.put(key, connection.getHeaderField(key));
        }
        return headers;
    }

    private static boolean isAccessibleURL(URL url) throws IOException {
        java.net.URLConnection connection = url.openConnection();
        int responseCode = ((java.net.HttpURLConnection) connection).getResponseCode();
        return (responseCode >= 200 && responseCode < 300) || responseCode == 404;
    }
}
