        return -1; // File not found or unable to open
    }

    int num_stats = 0;
    while (!feof(file)) {
        TCP_CONNECTION_STATS_T stat;
        fread(&stat, sizeof(TCP_CONNECTION_STATS_T), 1, file);

        if (ferror(file) || feof(file)) {
            break; // End of file reached or error occurred
        }

