        // Connection key is empty or NULL
        return -2; // Error code for this issue
    }

    if (!stat->connection_title) {
        // Connection title is not set
        return -3; // Error code for this issue
    }

    if (stat->callback_func == NULL) {
        // Callback function is NULL
        return -4; // Error code for this issue
    }

    return 0; // Success
}

