import java.util.*;

public class NetworkProcessor {

    private static final int MAX_EVENTS = 1_000_000;
    private static final int MAX_NFAPI_PDU_COUNT = 1000;

    public static List<NetworkEventRecord> processNetworkEvents(int M, long seed, Map<String, Double> simulationProfile) {
        List<NetworkEventRecord> eventRecords = new ArrayList<>();
        NetworkEventRecord[] buffer = new NetworkEventRecord[MAX_EVENTS];

        // Pre-populate the buffer with dummy events
        for (int i = 0; i < MAX_EVENTS; i++) {
            buffer[i] = new NetworkEventRecord();
        }

        int currentBufferSize = 0;

        // Process M events
        for (int i = 0; i < M; i++) {
            // Simulate network event based on the simulation profile
            double randomValue = Math.random() * 100;
            String eventType = getEventType(randomValue, simulationProfile);

            if (eventType == null) {
                continue;
            }

            buffer[currentBufferSize++] = new NetworkEventRecord(eventType, System.currentTimeMillis(), getRandomSourceID(seed));
        }

        // Trim the buffer
        List<NetworkEventRecord> trimmedBuffer = eventRecords.subList(0, currentBufferSize);

        return trimmedBuffer;
    }

    private static String getEventType(double randomValue, Map<String, Double> simulationProfile) {
        // Simulate network event type based on the given probability profile
        double sum = 0.0;
        for (String eventType : simulationProfile.keySet()) {
            sum += simulationProfile.get(eventType);
            if (randomValue <= sum) {
                return eventType;
            }
        }

        return null; // Handle this case based on your specific requirements
    }

    private static int getRandomSourceID(long seed) {
        Random random = new Random(seed);
        return random.nextInt(1000); // Generate a random source ID within the range 0-999
    }

    public class NetworkEventRecord {
        String eventType;
        long timestamp;
        int sourceID;

        public NetworkEventRecord() {}

        public NetworkEventRecord(String eventType, long timestamp, int sourceID) {
            this.eventType = eventType;
            this.timestamp = timestamp;
            this.sourceID = sourceID;
        }
    }
}
