import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.DualAddress;
import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.*;

public class URLProcessor {

    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final Map<String, HttpResponse> cache = new ConcurrentHashMap<>();
    private static final Map<String, String> locationCache = new ConcurrentHashMap<>();

    public static List<URLReport> process(List<String> urls) {
        List<URLReport> reports = new ArrayList<>();
        for (String url : urls) {
            try {
                HttpResponse response = getHttpResponse(url);
                if (response.getStatusCode() >= 200 && response.getStatusCode() < 300) {
                    String location = getLocation(response.getHeaders());
                    reports.add(new URLReport(url, response.getStatusCode(), location));
                } else {
                    reports.add(new URLReport(url, response.getStatusCode()));
                }
            } catch (IOException | UnknownHostException e) {
                reports.add(new URLReport(url, -1, null));
            }
        }
        return reports;
    }

    private static HttpResponse getHttpResponse(String url) throws IOException, InterruptedException {
        Future<HttpResponse> future = executor.submit(() -> {
            HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
            connection.setRequestMethod("HEAD");
            int responseCode = connection.getResponseCode();
            Map<String, List<String>> headers = new HashMap<>();
            BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split(": ");
                if (parts.length == 2) {
                    headers.put(parts[0], Arrays.asList(parts[1]));
                }
            }
            return new HttpResponse(responseCode, headers);
        });
        HttpResponse response;
        try {
            response = future.get(5000, TimeUnit.MILLISECONDS); // timeout after 5 seconds
        } catch (TimeoutException e) {
            throw new IOException("Request timed out");
        } catch (InterruptedException | ExecutionException e) {
            throw new IOException("Failed to retrieve HTTP headers", e);
        }
        return response;
    }

    private static String getLocation(Map<String, List<String>> headers) throws UnknownHostException {
        String location = null;
        for (Map.Entry<String, List<String>> entry : headers.entrySet()) {
            if ("Location".equalsIgnoreCase(entry.getKey())) {
                location = entry.getValue().get(0);
                break;
            }
        }
        if (location == null || location.isEmpty()) {
            try {
                InetAddress address = InetAddress.getByName(new URL(location).getHost());
                DualAddress dualAddress = new DualAddress(address);
                String country = dualAddress.getCountry();
                return country;
            } catch (UnknownHostException e) {
                // handle DNS resolution failure
            }
        }
        return location;
    }

    public static class HttpResponse {
        private int statusCode;
        private Map<String, List<String>> headers;

        public HttpResponse(int statusCode, Map<String, List<String>> headers) {
            this.statusCode = statusCode;
            this.headers = headers;
        }

        public int getStatusCode() {
            return statusCode;
        }

        public Map<String, List<String>> getHeaders() {
            return headers;
        }
    }

    public static class URLReport {
        private String url;
        private int status;
        private String location;

        public URLReport(String url, int status) {
            this.url = url;
            this.status = status;
            this.location = null;
        }

        public URLReport(String url, int status, String location) {
            this.url = url;
            this.status = status;
            this.location = location;
        }

        public String getUrl() {
            return url;
        }

        public int getStatus() {
            return status;
        }

        public String getLocation() {
            return location;
        }
    }
}
