    double correction_factor_tag;
} TAIPEX_TIME_SYNC_PDU_T;

// Function prototype for logging framework
void log_event(const char* message);

// Function to create a new TAIPEX_TIME_SYNC_PDU_T structure and populate it with given input parameters and an external time synchronization service.
TAIPEX_TIME_SYNC_PDU_T* create_pdu_t(struct timespec* timestamp, double correction_factor) {
    // Allocate memory for the new structure
    TAIPEX_TIME_SYNC_PDU_T* pdu = (TAIPEX_TIME_SYNC_PDU_T*)malloc(sizeof(TAIPEX_TIME_SYNC_PDU_T));

    if (!pdu) {
        log_event("Memory allocation failed");
        return NULL;
    }

    // Generate a unique ID for the structure based on UTC_TIMESTAMP and TIME_OFFSET_TAG
    int id = (int)timestamp->tv_sec * 1000000 + (int)timestamp->tv_nsec / 1000;

    pdu->utc_timestamp = timestamp->tv_sec;
    strcpy(pdu->time_offset_tag, "TIME OFFSET TAG");
    pdu->correction_factor_tag = correction_factor;

    // Log the creation of the new structure
    log_event("Created a new TAIPEX_TIME_SYNC_PDU_T structure with ID %d", id);

    return pdu;
}

// Function to merge two lists of structures
void merge_lists(TAIPEX_TIME_SYNC_PDU_T** primary_list, int* primary_count, TAIPEX_TIME_SYNC_PDU_T** secondary_list, int* secondary_count) {
    // Allocate memory for the merged list
    *primary_count += *secondary_count;
    *primary_list = (TAIPEX_TIME_SYNC_PDU_T**)realloc(*primary_list, (*primary_count + 1) * sizeof(TAIPEX_TIME_SYNC_PDU_T*));

    if (!*primary_list) {
        log_event("Memory allocation failed");
        return;
    }

    // Merge the two lists
    for (int i = 0; i < *secondary_count; i++) {
        *primary_list[*primary_count - 1] = (*secondary_list)[i];
        (*primary_count)++;
    }

    free(*secondary_list);
    *secondary_list = NULL;
}

// Function to compress the list of structures
void compress_list(TAIPEX_TIME_SYNC_PDU_T** primary_list, int count) {
    // Initialize compression threshold and mode
    double threshold = 0.5; // configurable
    int mode = Z_DEFAULT_COMPRESSION; // configurable

