    unsigned char* compressed_data = (unsigned char*)malloc(count * sizeof(TAIPEX_TIME_SYNC_PDU_T) + 1);

    if (!compressed_data) {
        log_event("Memory allocation failed");
        return;
    }

    // Compress the list of structures
    deflateInit2(&deflate_data, mode, Z_DEFAULT_COMPRESSION, Z_DEFAULT_STRATEGY, 8, 8);
    deflate(compressed_data, count * sizeof(TAIPEX_TIME_SYNC_PDU_T), NULL);

    free(compressed_data);
}

