// Define structure types
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char CRCFLAG[1];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int PDCP_SN;
    int TX_RLC SDSN;
    int RX_RLC SDSN;
} LTE_PDCP_STATS_T;

// Define the dynamic list type
typedef struct {
    int capacity;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    LTE_PDCP_STATS_T* statsData;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int cacheSize;
    LTE_PDCP_STATS_T** cache;
} DynamicList;

// Function to manage the dynamic list
DynamicList* createDynamicList(int capacity) {
    DynamicList* dl = (DynamicList*)malloc(sizeof(DynamicList));
    dl->capacity = capacity;
    dl->size = 0;
    dl->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dl->statsData = (LTE_PDCP_STATS_T*)calloc(capacity, sizeof(LTE_PDCP_STATS_T));
    pthread_mutex_init(&dl->mutex, NULL);
    pthread_cond_init(&dl->cond, NULL);
    dl->cacheSize = 0;
    dl->cache = (LTE_PDCP_STATS_T**)malloc(sizeof(LTE_PDCP_STATS_T*) * capacity);
    return dl;
}

void destroyDynamicList(DynamicList* dl) {
    if (!dl) return;
    free(dl->data);
    free(dl->statsData);
    pthread_mutex_destroy(&dl->mutex);
    pthread_cond_destroy(&dl->cond);
    free(dl->cache);
    free(dl);
}

int addElement(DynamicList* dl, NFAPI_CRC_INDICATION_PDU_T element) {
    if (dl->size == dl->capacity) {
        // Dynamically resize the list
        dl->capacity *= 2;
        dl->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dl->data, dl->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        dl->statsData = (LTE_PDCP_STATS_T*)realloc(dl->statsData, dl->capacity * sizeof(LTE_PDCP_STATS_T));
    }
    dl->data[dl->size] = element;
    dl->statsData[dl->size] = (LTE_PDCP_STATS_T){0};  // Initialize stats data with default values
    dl->size++;
    return 0;
}

int getRNTI(int rnti) {
    int i;
    for (i = 0; i < dl->cacheSize; i++) {
        if (dl->cache[i]->RNTI == rnti) {
            // Cache hit!
            return i;
        }
    }
    // Cache miss
    if (dl->cacheSize >= dl->capacity / 2) {
        // Reshape the cache array
        LTE_PDCP_STATS_T** newCache = (LTE_PDCP_STATS_T**)realloc(dl->cache, sizeof(LTE_PDCP_STATS_T*) * dl->cacheSize);
        for (i = 0; i < dl->cacheSize; i++) {
            newCache[i] = dl->cache[i];
        }
        free(dl->cache);
        dl->cache = newCache;
    }
    if (dl->size <= dl->capacity / 2) {
        // Resize the cache array
        dl->cacheSize *= 2;
    }
    // Insert into cache and return the index
    int idx = dl->cacheSize++;
    dl->cache[idx] = &dl->statsData[dl->size - 1];
    return idx;
}

void freeCache() {
    for (int i = 0; i < dl->cacheSize; i++) {
        if (dl->cache[i]) {
            free(dl->cache[i]);
        }
    }
    free(dl->cache);
}
