    int i;
    for (i = 0; i < rnti_cache_size; i++) {
        if (rnti_cache[i] == rnti) {
            return &rnti_cache[i];
        }
    }
    return NULL;
}

void set_rnti(int rnti, int RX_UE_INFORMATION_TAG, int CRC_INDICATION_REL8_TAG) {
    int* cache_entry = (int*)malloc(sizeof(int) * 3);
    cache_entry[0] = rnti;
    cache_entry[1] = RX_UE_INFORMATION_TAG;
    cache_entry[2] = CRC_INDICATION_REL8_TAG;
    if (rnti_cache_size >= MAX_CACHE_SIZE) {
        // Cache is full, remove the least recently used entry
        int lru_index = 0;
        for (int i = 1; i < rnti_cache_size; i++) {
            if (rnti_cache[i] == rnti_cache[lru_index]) {
                lru_index = i;
            }
        }
        free(rnti_cache[lru_index]);
        memmove(rnti_cache + lru_index, rnti_cache + lru_index + 1, sizeof(int) * (rnti_cache_size - lru_index));
        rnti_cache_size--;
    } else {
        rnti_cache[rnti_cache_size++] = rnti;
    }
}

