#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t PDCP_SN;
    uint32_t TX_RLC SDSN;
    uint32_t RX_RLC SDSN;
} LTE_PDCP_STATS_T;

// Dynamic list structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* nfa_pdu_list;
    LTE_PDCP_STATS_T* pdc_stats_list;
    int size;
    int capacity;
    // Caching mechanism
    void** rnti_cache;
    int rnti_cache_size;
    int rnti_cache_hits;
    int rnti_cache_misses;

} DynamicList;

// Function to manage dynamic list
DynamicList* create_dynamic_list(int initial_capacity) {
    DynamicList* dl = (DynamicList*)malloc(sizeof(DynamicList));
    if (!dl) return NULL;

    dl->nfa_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dl->nfa_pdu_list) {
        free(dl);
        return NULL;
    }

    dl->pdc_stats_list = (LTE_PDCP_STATS_T*)calloc(initial_capacity, sizeof(LTE_PDCP_STATS_T));
    if (!dl->pdc_stats_list) {
        free(dl->nfa_pdu_list);
        free(dl);
        return NULL;
    }

    dl->size = 0;
    dl->capacity = initial_capacity;

    // Initialize caching mechanism
    dl->rnti_cache_size = 100; // Default cache size
    dl->rnti_cache = (void*)calloc(dl->rnti_cache_size, sizeof(void*));
    if (!dl->rnti_cache) {
        free(dl->nfa_pdu_list);
        free(dl->pdc_stats_list);
        free(dl);
        return NULL;
    }

    dl->rnti_cache_hits = 0;
    dl->rnti_cache_misses = 0;

    return dl;
}

// Function to add an NFAPI CRC indication PDU to the dynamic list
void add_nfa_pdu(DynamicList* dl, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (dl->size >= dl->capacity) {
        // Resize the dynamic list if it reaches capacity
        dl->nfa_pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(dl->nfa_pdu_list, (dl->capacity * 2 + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        dl->pdc_stats_list = (LTE_PDCP_STATS_T*)realloc(dl->pdc_stats_list, (dl->capacity * 2 + 1) * sizeof(LTE_PDCP_STATS_T));

        dl->capacity *= 2;
    }

    // Add the PDU to the dynamic list
    dl->nfa_pdu_list[dl->size] = *pdu;

    dl->size++;
}

// Function to get an LTE PDCP stats from the dynamic list by RNTI
LTE_PDCP_STATS_T* get_pdc_stats_by_rnti(DynamicList* dl, uint32_t rnti) {
    // Check if the RNTI is already cached
    void** cache_iter = dl->rnti_cache;
    for (int i = 0; i < dl->rnti_cache_size; i++) {
        if (*((uint32_t*)cache_iter == rnti) {
            // Cache hit, return the corresponding PDCP stats
            int idx = (int)((cache_iter - dl->rnti_cache) / sizeof(void*));
            return &dl->pdc_stats_list[idx];
        }
        cache_iter++;
    }

    // Cache miss, linearly search for RNTI in dynamic list
    for (int i = 0; i < dl->size; i++) {
        if (dl->nfa_pdu_list[i].RNTI == rnti) {
            // Update the cache
            for (int j = 0; j < dl->rnti_cache_size; j++) {
                if (!*(void**)(dl->rnti_cache + j)) {
                    *(void**)(dl->rnti_cache + j) = &dl->pdc_stats_list[i];
                    break;
                }
            }

            return &dl->pdc_stats_list[i];
        }
    }

    // RNTI not found, return NULL
    return NULL;
}

// Function to free the dynamic list
void destroy_dynamic_list(DynamicList* dl) {
    if (!dl) return;

    // Free the NFAPI CRC indication PDU and LTE PDCP stats arrays
    free(dl->nfa_pdu_list);
    free(dl->pdc_stats_list);

    // Free the caching mechanism
    free(dl->rnti_cache);

    // Free the dynamic list structure itself
    free(dl);
}
