import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class FileMetadataProcessor {

    public static String processFileList(List<String> filePaths, int sizeThreshold, int depth) {
        List<FileMetadata> metadataList = new ArrayList<>();
        try {
            for (String filePath : filePaths) {
                File file = new File(filePath);
                if (file.isDirectory()) {
                    if (depth > 0) {
                        File[] files = file.listFiles();
                        if (files != null) {
                            for (File f : files) {
                                if (!f.isFile() && f.isDirectory()) {
                                    FileMetadata metadata = processDirectory(f, sizeThreshold, depth - 1);
                                    metadataList.add(metadata);
                                }
                            }
                        }
                    } else {
                        continue;
                    }
                } else if (file.isFile()) {
                    long fileSize = file.length();
                    long lastModified = file.lastModified();
                    if (fileSize > sizeThreshold) {
                        FileMetadata metadata = new FileMetadata(filePath, fileSize, lastModified);
                        metadataList.add(metadata);
                    }
                }
            }
        } catch (IOException e) {
            // log exception
            return "Error processing files: " + e.getMessage();
        }

        StringBuilder report = new StringBuilder();
        for (FileMetadata metadata : metadataList) {
            report.append("File: ").append(metadata.getFilePath()).append("\n");
            report.append("Size: ").append(metadata.getFileSize()).append("\n");
            report.append("Last Modified: ").append(metadata.getLastModified()).append("\n\n");
        }
        return report.toString();
    }

    private static FileMetadata processDirectory(File dir, int sizeThreshold, int depth) {
        List<FileMetadata> metadataList = new ArrayList<>();
        try {
            for (File file : dir.listFiles()) {
                if (!file.isFile() && file.isDirectory()) {
                    FileMetadata metadata = processDirectory(file, sizeThreshold, depth - 1);
                    metadataList.add(metadata);
                } else if (file.isFile()) {
                    long fileSize = file.length();
                    long lastModified = file.lastModified();
                    if (fileSize > sizeThreshold) {
                        FileMetadata metadata = new FileMetadata(file.getPath(), fileSize, lastModified);
                        metadataList.add(metadata);
                    }
                }
            }
        } catch (IOException e) {
            // log exception
            return null;
        }

        if (!metadataList.isEmpty()) {
            FileMetadata metadata = new FileMetadata(dir.getAbsolutePath(), 0, System.currentTimeMillis());
            metadataList.add(0, metadata);
        }
        return metadataList.size() > 1 ? metadataList.get(0) : null;
    }

    public static class FileMetadata {
        private String filePath;
        private long fileSize;
        private long lastModified;

        public FileMetadata(String filePath, long fileSize, long lastModified) {
            this.filePath = filePath;
            this.fileSize = fileSize;
            this.lastModified = lastModified;
        }

        public String getFilePath() {
            return filePath;
        }

        public long getFileSize() {
            return fileSize;
        }

        public long getLastModified() {
            return lastModified;
        }
    }
}
