    z_stream strm;
    char in[1024], out[1024];

    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    deflateInit2(&strm, compression_algorithm == LZW ? Z_DEFAULT_COMPRESSION : Z_BEST_SPEED, 31, 8, 8, Z_DEFAULT_BLOCK);

    while (read(file, in, 1024) > 0) {
        strm.avail_in = strlen(in);
        strm.next_in = (Bytef*)in;

        do {
            strm.avail_out = sizeof(out);
            strm.next_out = (Bytef*)out;
            deflate(&strm, Z_FINISH);

            if (strm.total_out >= sizeof(out)) {
                fprintf(stderr, "Output buffer too small\n");
                break;
            }

            fwrite(out, 1, strm.total_out, file);
        } while (strm.avail_in == 0 && strm.total_out < 1024);
    }

    deflateEnd(&strm);

    // Close the file
    fclose(file);
}

// Deserialize the data
void deserialize_data(void* data_ptr, FILE* file) {
    // Read the compressed data from the file
    z_stream strm;
    char in[1024], out[1024];

    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;

    inflateInit2(&strm, 31, 8, 8, 8, Z_DEFAULT_BLOCK);

    while (fread(in, 1, 1024, file) > 0) {
        strm.avail_in = strlen(in);
        strm.next_in = (Bytef*)in;

        do {
            strm.avail_out = sizeof(out);
            strm.next_out = (Bytef*)out;
            inflate(&strm, Z_FINISH);

            if (strm.total_out >= sizeof(out)) {
                fprintf(stderr, "Output buffer too small\n");
                break;
            }

            // Add the deserialized element to the array
            add_element(data_ptr, *(NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        } while (strm.avail_in == 0 && strm.total_out < 1024);
    }

    inflateEnd(&strm);

    // Close the file
    fclose(file);
}

