void* tx_power_report_array_malloc(size_t size) {
    return malloc(size);
}

void tx_power_report_array_free(void* ptr) {
    free(ptr);
}

double average_power_level(TX_POWER_REPORT** reports, int start_idx, int end_idx) {
    if (start_idx < 0 || end_idx > array_size - 1 || start_idx >= end_idx)
        return -1.0;

    pthread_mutex_lock(&mutex);

    double sum = 0;
    for (int i = start_idx; i <= end_idx; i++) {
        sum += (*reports)[i].power_level;
    }

    pthread_mutex_unlock(&mutex);

    return (double)sum / (end_idx - start_idx + 1);
}

void tx_power_report_array_add(TX_POWER_REPORT** reports, TX_POWER_REPORT* report) {
    if (!report)
        return;

    pthread_mutex_lock(&mutex);

    int new_size = array_size + 1;
    *reports = realloc(*reports, new_size * sizeof(TX_POWER_REPORT));

    if (*reports == NULL) {
        free(*reports);
        *reports = NULL;
    } else {
        memcpy(&(*reports)[array_size], report, sizeof(TX_POWER_REPORT));
        array_size = new_size;
    }

    pthread_mutex_unlock(&mutex);
}

void tx_power_report_array_free_reports(TX_POWER_REPORT** reports) {
    if (!*reports)
        return;

    for (int i = 0; i < array_size; i++) {
        tx_power_report_array_free(&((*reports)[i]));
    }

    free(*reports);
    *reports = NULL;
}

