#include <stdlib.h>
#include <stdio.h>

typedef struct {
    int power_level;
} TX_POWER_REPORT;

void* operator new(size_t size) throw() {
    return malloc(size);
}

void operator delete(void* ptr) throw() {
    free(ptr);
}

class TxPowerReportArray {
private:
    TX_POWER_REPORT** array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;

public:
    TxPowerReportArray(size_t initialCapacity = 10) : 
        capacity(initialCapacity), size(0), array(new TX_POWER_REPORT*[capacity]) {
        pthread_mutex_init(&mutex, NULL);
    }

    ~TxPowerReportArray() {
        for (size_t i = 0; i < size; ++i)
            delete[] array[i];
        delete[] array;
        pthread_mutex_destroy(&mutex);
    }

    void add(TX_POWER_REPORT* report, size_t index) {
        pthread_mutex_lock(&mutex);

        if (size >= capacity) {
            TX_POWER_REPORT** newArray = new TX_POWER_REPORT*[capacity * 2];
            memcpy(newArray, array, capacity * sizeof(TX_POWER_REPORT*));
            delete[] array;
            array = newArray;
            capacity *= 2;
        }

        for (size_t i = size; i > index; --i)
            array[i] = array[i - 1];

        array[index] = new TX_POWER_REPORT(*report);
        ++size;

        pthread_mutex_unlock(&mutex);
    }

    void remove(size_t index) {
        pthread_mutex_lock(&mutex);

        if (index >= size || index < 0) {
            perror("Invalid index");
            return;
        }

        delete[] array[index];
        for (size_t i = index; i < size - 1; ++i)
            array[i] = array[i + 1];

        --size;

        pthread_mutex_unlock(&mutex);
    }

    double averagePowerLevel(size_t start, size_t end) {
        if (start >= size || end > size || start < 0 || end < 0) {
            perror("Invalid index range");
            return -1.0;
        }

        double sum = 0;
        for (size_t i = start; i <= end; ++i)
            sum += array[i]->power_level;

        if (end - start + 1 == 0)
            return 0.0;

        return sum / (end - start + 1);
    }
};
