typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_entries, int seed) {
    if (num_entries > MAX_LIST_SIZE || seed < 0) {
        printf("Invalid input parameters. Maximum list size: %d, Minimum seed value: 1\n", MAX_LIST_SIZE);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_list = NULL;

    for (int i = 0; i < num_entries; i++) {
        if ((crc_pdu_list = realloc(crc_pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1))) == NULL) {
            printf("Memory allocation failed. Error code: %d\n", errno);
            return NULL;
        }

        crc_pdu_list[i].RX_UE_INFORMATION_TAG = rand_r(&seed) % 1000; // add your randomization logic
        crc_pdu_list[i].RNTI = (i + 1) % 512;
        crc_pdu_list[i].CRC_INDICATION_REL8_TAG = i % 1024;

        if (sysconf(_SC_PAGESIZE) * (i + 2) > SYSTEM_MAX_MEMORY) {
            printf("List size exceeded system-defined maximum. Trimming the list...\n");
            for (int j = i; j >= 0; j--) {
                free(crc_pdu_list);
                crc_pdu_list = NULL;
            }
            return NULL;
        }
    }

    return crc_pdu_list;
}
