#include <unordered_map>

struct USER_SESSION {
    int userId;
    std::time_t startTime;
    std::time_t lastActivity;
    bool isActive;

    USER_SESSION(int _userId, bool _isActive)
        : userId(_userId), isActive(_isActive) {
        startTime = std::time(nullptr);
        lastActivity = startTime;
    }
};

class SessionManager {
private:
    std::map<int, USER_SESSION> sessions;
    std::mutex sessionMutex;
    std::unordered_map<int, std::string> identityMap;

public:
    void addUserSession(int userId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (!identityMap.count(userId)) {
            // Integrate with external identity management system to retrieve user info
            identityMap[userId] = "John Doe"; // sample user info
        }
        sessions[userId].lastActivity = std::time(nullptr);
    }

    void removeUserSession(int userId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessions.count(userId)) {
            sessions.erase(userId);
            identityMap.erase(userId);
        }
    }

    void login(int userId, bool isActive) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (!sessions.count(userId)) {
            addUserSession(userId);
        }
        sessions[userId].isActive = isActive;
        sessions[userId].lastActivity = std::time(nullptr);
    }

    void logout(int userId) {
        std::lock_guard<std::mutex> lock(sessionMutex);
        if (sessions.count(userId)) {
            removeUserSession(userId);
        }
    }

    void simulateActivity() {
        // Simulate concurrent login and logout operations from multiple threads
        std::thread thread1([&]() {
            for (int i = 0; i < 10; ++i) {
                int userId = rand() % 100;
                if (!sessions.count(userId)) {
                    addUserSession(userId);
                }
                login(userId, true);
                std::this_thread::sleep_for(std::chrono::seconds(1));
                logout(userId);
            }
        });

        std::thread thread2([&]() {
            for (int i = 0; i < 10; ++i) {
                int userId = rand() % 100;
                if (!sessions.count(userId)) {
                    addUserSession(userId);
                }
