public class ServiceManagementModule {
    private static final Logger logger = LoggerFactory.getLogger(ServiceManagementModule.class);
    private Map<String, Service> services = new HashMap<>();
    private Map<String, Integer> resourceUsage = new HashMap<>();
    private int loggingRateLimit = 10; // adjust as needed
    private boolean simulateNetworkIssues = false;

    public void startService(String serviceName) {
        if (!services.containsKey(serviceName)) {
            Service service = new Service(serviceName);
            services.put(serviceName, service);
            service.start();
            logger.info("Service '{}' started", serviceName);
        } else {
            logger.warn("Service '{}' is already running", serviceName);
        }
    }

    public void stopService(String serviceName) {
        if (services.containsKey(serviceName)) {
            Service service = services.get(serviceName);
            service.stop();
            resourceUsage.remove(serviceName);
            StringBuilder report = new StringBuilder();
            report.append("Service '{}' stopped due to ").append(getReportReason()).append("\n");
            report.append("CPU usage: ").append(resourceUsage.getOrDefault(serviceName, 0)).append("%\n");
            report.append("Memory usage: ").append(resourceUsage.getOrDefault(serviceName, 0)).append("%\n");
            report.append("Disk I/O: ").append(resourceUsage.getOrDefault(serviceName, 0)).append("\n");
            logger.error(report.toString(), new StopServiceEvent(serviceName));
        } else {
            logger.warn("Service '{}' is not running", serviceName);
        }
    }

    private String getReportReason() {
        // implement your stop reason logic here
        return "unknown";
    }

