struct FSA* update_state_list(int* state_array, int num_states, struct FSA* current_fsa, int last_state) {
    struct FSA* new_fsa = (struct FSA*)malloc(sizeof(struct FSA));
    if (!new_fsa) return NULL;

    new_fsa->states = (int*)calloc((num_states + 1), sizeof(int));
    if (!new_fsa->states) {
        free(new_fsa);
        return NULL;
    }

    memcpy(new_fsa->states, state_array, num_states * sizeof(int));

    new_fsa->num_states = num_states;
    new_fsa->next = current_fsa->next;
    current_fsa->next = new_fsa;

    return new_fsa;
}
