class UserSession {
public:
    int userId;
    time_t startTime;
    time_t lastActivityTime;
    enum class State { Active, Idle, Terminated };
    State state;

    UserSession(int userId) : userId(userId), startTime(time(nullptr)), lastActivityTime(time(nullptr)), state(State::Active) {}
};

class SessionManager {
public:
    std::mutex mutex;
    std::condition_variable cv;
    std::deque<UserSession> sessions;
    std::map<int, std::shared_ptr<UserSession>> sessionMap;

    void addSession(int userId) {
        std::unique_lock<std::mutex> lock(mutex);
        sessions.emplace_back(userId);
        sessionMap[userId] = sessions.back().get();
        lock.unlock();
        cv.notify_all();
    }

    void removeSession(int userId) {
        std::unique_lock<std::mutex> lock(mutex);
        if (sessionMap.find(userId) != sessionMap.end()) {
            sessions.erase(std::remove_if(sessions.begin(), sessions.end(),
                                            [&](const auto& session) { return session.userId == userId; }),
                           sessions.end());
            sessionMap.erase(userId);
        }
    }

    void updateSession(int userId, UserSession::State newState) {
        std::unique_lock<std::mutex> lock(mutex);
        if (sessionMap.find(userId) != sessionMap.end()) {
            auto& session = *sessionMap[userId];
            session.state = newState;
            session.lastActivityTime = time(nullptr);
        }
    }

    void logSessionEvent(int userId, UserSession::State state) {
        std::unique_lock<std::mutex> lock(mutex);
        if (sessionMap.find(userId) != sessionMap.end()) {
