    SessionManager sessionManager;
    std::thread loginThread([&sessionManager]() {
        for (int i = 0; i < 100; ++i) {
            int userId = i + 1;
            sessionManager.addSession(userId);
            // Simulate user activity
            std::this_thread::sleep_for(std::chrono::seconds(1));
            sessionManager.updateSession(userId, UserSession::State::Idle);
        }
    });

    std::thread logoutThread([&sessionManager]() {
