#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

struct lte_ue_context {
    int ue_id;
    struct bearer_info *bearer;
    int qos_settings;
    pthread_mutex_t lock; // for thread safety
    time_t timestamp;
};

// Doubly-linked list node structure for UE contexts
typedef struct lte_ue_context_list_node {
    struct lte_ue_context *context;
    struct lte_ue_context_list_node *prev;
    struct lte_ue_context_list_node *next;
} lte_ue_context_list_node;

// Function to initialize and manage LTE UE Contexts
void init_lte_ue_contexts(int num_contexts, int time_threshold, pthread_mutex_t* mutex) {
    // Initialize the head of the doubly-linked list
    lte_ue_context_list_node *head = NULL;
    lte_ue_context_list_node *tail = NULL;

    for (int i = 0; i < num_contexts; i++) {
        struct lte_ue_context *context = (struct lte_ue_context *)malloc(sizeof(struct lte_ue_context));
        if (!context) {
            // Handle memory allocation failure
            printf("Memory allocation failed\n");
            return;
        }

        context->ue_id = i;
        context->bearer = NULL; // Initialize bearer info later
        context->qos_settings = 0; // Initialize QoS settings later
        context->timestamp = time(NULL); // Initialize timestamp to current time

        pthread_mutex_init(&context->lock, NULL);

        if (!head) {
            head = tail = &((lte_ue_context_list_node *)malloc(sizeof(lte_ue_context_list_node)));
        } else {
            tail->next = (lte_ue_context_list_node *)malloc(sizeof(lte_ue_context_list_node));
            tail = tail->next;
        }

        context->prev = tail;
        tail->context = context;
    }

    // Periodic purging of inactive contexts
    pthread_mutex_lock(mutex);
    while (1) {
        // Traverse the list to find inactive contexts
        lte_ue_context_list_node *current = head;
        while (current) {
            if (is_inactive(current->context->timestamp, time_threshold)) {
                // Purge inactive context
                struct lte_ue_context_list_node *next = current->next;
                free(current);
                head = next;
                if (!head) {
                    tail = NULL;
                } else {
                    tail = head;
                }
            } else {
                current = current->next;
            }
        }

        // Update QoS settings dynamically based on network load conditions
        update_qos_settings(head, time_threshold);

        pthread_mutex_unlock(mutex);
        sleep(1); // Periodic purging interval
    }
}

// Helper function to update QoS settings dynamically
void update_qos_settings(struct lte_ue_context_list_node *head, int time_threshold) {
    // Implement dynamic QoS setting updates based on network load conditions
}

// Helper function to check if a context is inactive
int is_inactive(time_t timestamp, int time_threshold) {
    // Check if the context has been inactive for the specified duration
    return (time(NULL) - timestamp > time_threshold);
}
```']

