#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    uint32_t ip_address;
    uint16_t port_number;
    uint16_t checksum;
    bool check_sum_valid;
} UDP_HEADER;

UDP_HEADER* generate_udp_headers(int count) {
    // Initialize memory pool with a default size
    size_t total_size = 1024 * 1024; // 1MB
    void* mem_pool = malloc(total_size);

    if (!mem_pool) return NULL;

    int* free_blocks = (int*)mem_pool;
    mem_pool += sizeof(int);
    void* current_block = mem_pool;
    size_t block_size = total_size / 1024; // assume 1KB blocks

    UDP_HEADER* headers = NULL;
    for (int i = 0; i < count; ++i) {
        // Allocate a new structure from the memory pool
        size_t header_size = sizeof(UDP_HEADER);
        if (!current_block || free_blocks[0] < header_size) {
            // If there's no available block or it's too small, reallocate the memory pool
            total_size += 1024 * 1024; // add another 1MB to the memory pool
            mem_pool = realloc(mem_pool, total_size);
            free_blocks = (int*)mem_pool;
            mem_pool += sizeof(int);
            block_size = total_size / 1024; // assume 1KB blocks

            current_block = mem_pool;
        }

        UDP_HEADER* header = current_block;
        current_block += header_size;

        // Initialize the structure
        srand(time(NULL) + i); // seed random number generator for each new structure
        header->ip_address = (rand() % 0x100000000);
        header->port_number = rand() % 0x10000;
        header->checksum = rand() % 0xFFFF;
        if (rand() % 2) {
            header->check_sum_valid = true;
        } else {
            header->check_sum_valid = false;
        }

        // Update the memory pool
        free_blocks[0] -= header_size;

        // Add the structure to the array of headers
        if (!headers) {
            headers = header;
        } else {
            UDP_HEADER* prev_header = headers + i - 1;
            if (prev_header->check_sum_valid != header->check_sum_valid) {
                // Checksum values changed, need to reallocate and update previous checksum
                int prev_checksum = prev_header->checksum;
                for (; i < count; ++i) {
                    if (!current_block || free_blocks[0] < header_size) {
                        break;
                    }

                    UDP_HEADER* new_header = current_block;
                    current_block += header_size;

                    // Initialize the structure
                    srand(time(NULL) + i); // seed random number generator for each new structure
                    new_header->ip_address = (rand() % 0x100000000);
                    new_header->port_number = rand() % 0x10000;
                    new_header->checksum = prev_checksum;
                    if (rand() % 2) {
                        new_header->check_sum_valid = true;
                    } else {
                        new_header->check_sum_valid = false;
                    }

                    // Update the memory pool
                    free_blocks[0] -= header_size;

                    headers = realloc(headers, sizeof(UDP_HEADER) * i);
                    memcpy(headers + i - 1, &new_header, sizeof(UDP_HEADER));
                }
            } else {
                headers = realloc(headers, sizeof(UDP_HEADER) * (i + 1));
