#define MAX_PACKETS 1000
#define MAX_PAYLOAD_SIZE 1024 * 1024 // 1MB

typedef struct UDP_PACKET_PDU_T {
    int packet_id;
    char* payload;
} UDP_PACKET_PDU_T;

void processDynamicDataWithConcurrencyAndCompression(int numPackets, UDP_PACKET_PDU_T packets[]) {
    // Initialize thread-safe buffer and memory pool
    pthread_mutex_init(&buffer_lock, NULL);
    pthread_cond_init(&buffer_not_empty, NULL);

    size_t capacity = 0;
    void** packet_pointers = NULL;

    for (int i = 0; i < numPackets && i < MAX_PACKETS; i++) {
        UDP_PACKET_PDU_T* current_packet = &packets[i];
        size_t payload_size = strlen(current_packet->payload) + 1;

        // Check if packet exceeds maximum allowed payload size
        if (payload_size > MAX_PAYLOAD_SIZE) {
            printf("Packet %d: Payload size exceeded. Truncating to %ld bytes.\n", current_packet->packet_id, MAX_PAYLOAD_SIZE);
            payload_size = MAX_PAYLOAD_SIZE;
        }

        // Handle dynamic memory allocation and deallocation for packet headers
        void* header = malloc(payload_size + sizeof(UDP_PACKET_PDU_T));
        if (header == NULL) {
            LOG_ERROR("Failed to allocate memory for packet header");
            continue;
        }

        // Initialize thread-safe buffer with updated capacity
        pthread_mutex_lock(&buffer_lock);
        if (capacity < i + 1) {
            capacity = i + 1;
            pthread_cond_broadcast(&buffer_not_empty);
        }
        pthread_mutex_unlock(&buffer_lock);

        // Store packet in dynamic array or thread-safe buffer
        if (i >= MAX_PACKETS) {
            void** temp = realloc(packet_pointers, sizeof(void*) * (i + 1));
            if (temp == NULL) {
                LOG_ERROR("Failed to allocate memory for packet array");
                break;
            }
            packet_pointers = temp;
            packet_pointers[i] = header;
        } else {
            packet_pointers[i] = header;
        }

        // Compress packet payload if necessary
        char* compressed_payload = NULL;
        size_t compressed_size = 0;

        // Identify largest payload size and print result
        size_t max_payload_size = 0;
        pthread_mutex_lock(&buffer_lock);
        for (int j = 0; j < i + 1; j++) {
            UDP_PACKET_PDU_T* current_packet = packet_pointers[j];
            size_t payload_size = strlen(current_packet->payload) + 1;

            if (payload_size > max_payload_size)
                max_payload_size = payload_size;
        }
        pthread_mutex_unlock(&buffer_lock);

        LOG_INFO("Largest payload size: %ld bytes", max_payload_size);
    }

    // Clean up and deallocate memory
    for (int i = 0; i < numPackets && i < MAX_PACKETS; i++) {
        void* header = packet_pointers[i];
        if (header != NULL) {
            free(header);
        }
    }

    free(packet_pointers);

    pthread_cond_destroy(&buffer_not_empty);
    pthread_mutex_destroy(&buffer_lock);
}
