['Here is the Rust code block:

```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use rand::Rng;
use reqwest;
use log;

struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: String,
    rnti: u32,
    crc_indication_rel8_tag: String,
    crcflag: bool,
}

impl Default for NFAPI_CRC_INDICATION_PDU_T {
    fn default() -> Self {
        NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag: "".to_string(),
            rnti: 0,
            crc_indication_rel8_tag: "".to_string(),
            crcflag: false,
        }
    }
}

struct DynamicArray<T> {
    vec: Vec<T>,
    map: HashMap<u32, T>,
    size: usize,
    log_count: Arc<Mutex<usize>>,
    request_builder: Option<reqwest::blocking::RequestBuilder>,
}

impl<T> DynamicArray<T>
where
    T: Clone + std::fmt::Debug,
{
    fn new() -> Self {
        DynamicArray {
            vec: Vec::new(),
            map: HashMap::new(),
            size: 0,
            log_count: Arc::new(Mutex::new(0)),
            request_builder: None,
        }
    }

    fn add(&mut self, t: T) -> Result<(), String> {
        let rnti = rand::thread_rng().gen_range(0..u32::MAX);
        if self.map.contains_key(&rnti) {
            return Err("RNTI already exists in the map".to_string());
        }
        self.map.insert(rnti, t.clone());
        self.vec.push(t);
        *self.log_count.lock() = *self.log_count.get_mut().unwrap() + 1;
        log::info!("Added {} to the dynamic array", rnti);
        Ok(())
    }

    fn get(&self, rnti: &u32) -> Option<&T> {
        self.map.get(rnti)
    }

    fn remove(&mut self, rnti: &u32) -> Result<(), String> {
        if let Some(t) = self.map.remove(rnti) {
            self.vec.retain(|x| x != t);
            *self.log_count.lock() = *self.log_count.get_mut().unwrap() - 1;
            log::info!("Removed {} from the dynamic array", rnti);
            Ok(())
        } else {
            Err("RNTI not found in the map".to_string())
        }
    }

    fn resize(&mut self, new_size: usize) -> Result<(), String> {
        if new_size < self.size {
            return Err("Cannot shrink the dynamic array. Use clear() instead.".to_string());
        }
        let mut request_builder = reqwest::blocking::RequestBuilder::new();
        *self.request_builder = Some(request_builder);
        Ok(())
    }

    fn http_client(&self) -> Option<reqwest::blocking::RequestBuilder> {
        self.request_builder.clone()
    }
}
