} NAS_Message_Type;

typedef struct {
    NAS_Message_Type type;
    char* content;
} LTE_RRC_NAS_Message;

void lte_rrc_nas_message_array_init(LTE_RRC_NAS_Message** array, int initial_size) {
    *array = (LTE_RRC_NAS_Message*)malloc(initial_size * sizeof(LTE_RRC_NAS_Message));
}

int lte_rrc_nas_message_array_resize(LTE_RRC_NAS_Message* array, int new_size) {
    LTE_RRC_NAS_Message* new_array = (LTE_RRC_NAS_Message*)realloc(array, new_size * sizeof(LTE_RRC_NAS_Message));
    if (new_array == NULL) {
        return -1; // error allocating memory
    }
    free(array);
    array = new_array;
    return 0;
}

void lte_rrc_nas_message_array_add(LTE_RRC_NAS_Message* array, int size, LTE_RRC_NAS_Message new_message) {
    if (lte_rrc_nas_message_array_resize(array, size + 1) != 0) {
        return; // error resizing array
    }
    array[size].type = new_message.type;
    array[size].content = strdup(new_message.content);
}

void lte_rrc_nas_message_array_update(LTE_RRC_NAS_Message* array, int index, LTE_RRC_NAS_Message updated_message) {
    if (index < 0 || index >= array[0].type) {
        return; // error: out-of-bounds update
    }
    array[index].type = updated_message.type;
    free(array[index].content);
    array[index].content = strdup(updated_message.content);
}

void lte_rrc_nas_message_array_iterate(const LTE_RRC_NAS_Message* array, int size) {
    for (int i = 0; i < size; i++) {
        printf("Message %d: type=%d, content='%s'\n", i, array[i].type, array[i].content);
    }
}

void lte_rrc_nas_message_array_free(LTE_RRC_NAS_Message* array, int size) {
    for (int i = 0; i < size; i++) {
        free(array[i].content);
    }
    free(array);
}
