typedef struct {
    int session_id;
    char name[50];
    char* log_buffer;
} UserSession;

// Function to initialize and manage dynamic list of UserSessions
void* user_sessions = NULL; // Global variable for dynamic list

// Helper function to dynamically allocate memory for a new UserSession
UserSession* create_user_session() {
    UserSession* session = (UserSession*)malloc(sizeof(UserSession));
    if (!session) return NULL;
    session->session_id = 0; // Initialize with default value
    strcpy(session->name, ""); // Default name
    session->log_buffer = NULL;
    return session;
}

// Function to add a new user session to the dynamic list
int add_user_session(int id, const char* name) {
    UserSession* session = create_user_session();
    if (!session) return -1; // Failed to allocate memory

    session->session_id = id;
    strcpy(session->name, name);

    // Add new session to the global dynamic list
    user_sessions = (void*)realloc(user_sessions, sizeof(UserSession*) * (strlen((char*)user_sessions) + 2));
    ((UserSession**)user_sessions)[strlen((char*)user_sessions)] = session;

    return 0;
}

// Function to update the name of an existing user session
int update_user_name(int id, const char* new_name) {
    UserSession** sessions = (UserSession**)user_sessions;
    int i;
    for (i = 0; i < strlen((char*)user_sessions); i++) {
        if (((UserSession*)sessions[i])->session_id == id) {
            strcpy(((UserSession*)sessions[i])->name, new_name);
            return 0;
        }
    }
    return -1; // Session not found
}

// Function to iterate over all active user sessions
void iterate_user_sessions() {
    UserSession** sessions = (UserSession**)user_sessions;
    int i;
    for (i = 0; i < strlen((char*)user_sessions); i++) {
        printf("Session ID: %d, Name: %s\n", ((UserSession*)sessions[i])->session_id, ((UserSession*)sessions[i])->name);
    }
}

// Function to clear inactive user sessions based on inactivity threshold
void clear_inactive_sessions(int threshold) {
    UserSession** sessions = (UserSession**)user_sessions;
    int i, j;
    for (i = 0; i < strlen((char*)user_sessions); i++) {
        if (((UserSession*)sessions[i])->log_buffer && ((UserSession*)sessions[i])->log_buffer[threshold] == '\0') { // Check inactivity
            free(((UserSession*)sessions[i])->log_buffer);
            free(sessions[i]);
            for (j = i; j < strlen((char*)user_sessions) - 1; j++) {
                sessions[j] = sessions[j + 1];
            }
            i--;
        }
    }
}
