#define MAX_RESOURCES 1000
#define TIMEOUT_MAX 10000 // in milliseconds

typedef struct ResourceAllocation {
    int id;
    int timeout;
    char* metrics;
} ResourceAllocation;

ResourceAllocation* resources[MAX_RESOURCES];
int resource_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
char* temp_metrics = NULL;

void add_resource(ResourceAllocation* allocation) {
    pthread_mutex_lock(&mutex);
    resources[resource_count] = allocation;
    resource_count++;
    pthread_mutex_unlock(&mutex);
}

void update_timeout(int id, int new_timeout) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < resource_count; i++) {
        if (resources[i]->id == id) {
            resources[i]->timeout = new_timeout;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void update_metrics(int id, char* metrics) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < resource_count; i++) {
        if (resources[i]->id == id) {
            free(resources[i]->metrics);
            resources[i]->metrics = malloc(strlen(metrics) + 1);
            strcpy(resources[i]->metrics, metrics);
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void* iterate_resources(void* arg) {
    for (int i = 0; i < resource_count; i++) {
        ResourceAllocation* allocation = resources[i];
        if (allocation->timeout > 0) {
            // do something with the metrics
            printf("Resource ID: %d, Timeout: %d, Metrics: %s\n", 
                   allocation->id, allocation->timeout, allocation->metrics);
        }
    }
    return NULL;
}

void reclaim_expired_resources() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < resource_count; i++) {
        ResourceAllocation* allocation = resources[i];
        if (allocation->timeout == 0) {
            free(allocation->metrics);
            free(resources[i]);
            resource_count--;
            i--; // iterate over the remaining resources
        }
    }
    pthread_mutex_unlock(&mutex);
}

void print_resources() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < resource_count; i++) {
        ResourceAllocation* allocation = resources[i];
        printf("Resource ID: %d, Timeout: %d, Metrics: %s\n", 
               allocation->id, allocation->timeout, allocation->metrics);
    }
    pthread_mutex_unlock(&mutex);
}

int main() {
    // test the functions
    add_resource((ResourceAllocation*)malloc(sizeof(ResourceAllocation)));
    update_timeout(1, 5000);
    update_metrics(1, "metric1");
    print_resources();

    // simulate concurrent access
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, iterate_resources, NULL);
        usleep(10000); // wait a bit before creating the next thread
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    reclaim_expired_resources();

    return 0;
}

