#include <pthread.h>

typedef enum {
    MESSAGE_TYPE_UNSPECIFIED,
    MESSAGE_TYPE_NAS_REQUEST,
    MESSAGE_TYPE_NAS_RESPONSE
} NAS_Message_Type;

typedef struct {
    NAS_Message_Type type;
    char* content;
} LTE_RRC_NAS_Message;

// Thread-safe queue for incoming message requests
typedef struct {
    LTE_RRC_NAS_Message* messages;
    int size, capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} MessageQueue;

MessageQueue* create_message_queue(int initial_capacity) {
    MessageQueue* queue = (MessageQueue*)malloc(sizeof(MessageQueue));
    queue->messages = (LTE_RRC_NAS_Message*)calloc(initial_capacity, sizeof(LTE_RRC_NAS_Message));
    queue->size = 0;
    queue->capacity = initial_capacity;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

void destroy_message_queue(MessageQueue* queue) {
    for (int i = 0; i < queue->size; i++) {
        free(queue->messages[i].content);
    }
    free(queue->messages);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}

void enqueue_message(MessageQueue* queue, LTE_RRC_NAS_Message message) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size >= queue->capacity) {
        // Reallocating the array to increase its capacity
        int new_capacity = queue->capacity * 2;
        LTE_RRC_NAS_Message* new_messages = (LTE_RRC_NAS_Message*)realloc(queue->messages, new_capacity * sizeof(LTE_RRC_NAS_Message));
        if (!new_messages) {
            // Handle memory allocation failure
        }
        queue->messages = new_messages;
        queue->capacity = new_capacity;
    }
    queue->messages[queue->size] = message;
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
}

LTE_RRC_NAS_Message* dequeue_message(MessageQueue* queue) {
    pthread_mutex_lock(&queue->mutex);
    LTE_RRC_NAS_Message* message = NULL;
    if (queue->size > 0) {
        message = &queue->messages[0];
        memmove(queue->messages, &queue->messages[1], (queue->size - 1) * sizeof(LTE_RRC_NAS_Message));
        queue->size--;
        pthread_cond_signal(&queue->cond);
    }
    pthread_mutex_unlock(&queue->mutex);
    return message;
}

void print_message_queue(MessageQueue* queue) {
    for (int i = 0; i < queue->size; i++) {
        printf("Message Type: %d, Content: %s\n", queue->messages[i].type, queue->messages[i].content);
    }
}
