#define MAX_FORMATS 3
#define MAX_BUNDLE_SIZE (1024*1024) // 1MB

typedef enum {
    JSON, XML, CSV,
} BundleFormat;

typedef struct {
    void *data;
    size_t size;
} BundleItem;

// Bundle structure to hold all items and their formats
typedef struct {
    int itemCount;
    BundleItem **items;
} ResourceBundle;

BundleResource* loadBundle(const char* filePath) {
    ResourceBundle *bundle = (ResourceBundle*)malloc(sizeof(ResourceBundle));
    bundle->itemCount = 0;
    bundle->items = NULL;

    // Determine file format based on extension
    char ext[4];
    strncpy(ext, &filePath[strlen(filePath)-3], 3);
    BundleFormat format = JSON; // Default to JSON

    if (strcmp(ext, "json") == 0) {
        format = JSON;
    } else if (strcmp(ext, "xml") == 0) {
        format = XML;
    } else if (strcmp(ext, "csv") == 0) {
        format = CSV;
    }

    // Parse the content based on the determined format
    FILE *file = fopen(filePath, "r");
    if (!file) {
        free(bundle);
        return NULL;
    }
    struct stat sb;
    fstat(fileno(file), &sb);
    size_t fileSize = sb.st_size;

    void *bundleData = malloc(MAX_BUNDLE_SIZE);
    int bytesRead = fread(bundleData, 1, fileSize, file);

    fclose(file);

    // Track the number of failed parse attempts for each format
    int failedAttempts[3] = {0};
    if (format == JSON) {
        BundleItem* item = (BundleItem*)malloc(sizeof(BundleItem));
        item->data = bundleData;
        item->size = bytesRead;
        bundle->items = (BundleItem**)realloc(bundle->items, sizeof(BundleItem*)*(bundle->itemCount+1));
        bundle->items[bundle->itemCount++] = item;

        if (failedAttempts[0] > 0) {
            free(item);
        } else {
            // Handle JSON parsing error
            // ...
        }
    } else if (format == XML) {
        BundleItem* item = (BundleItem*)malloc(sizeof(BundleItem));
        item->data = bundleData;
        item->size = bytesRead;
        bundle->items = (BundleItem**)realloc(bundle->items, sizeof(BundleItem*)*(bundle->itemCount+1));
        bundle->items[bundle->itemCount++] = item;

        if (failedAttempts[1] > 0) {
            free(item);
        } else {
            // Handle XML parsing error
            // ...
        }
    } else if (format == CSV) {
        BundleItem* item = (BundleItem*)malloc(sizeof(BundleItem));
        item->data = bundleData;
        item->size = bytesRead;
        bundle->items = (BundleItem**)realloc(bundle->items, sizeof(BundleItem*)*(bundle->itemCount+1));
        bundle->items[bundle->itemCount++] = item;

        if (failedAttempts[2] > 0) {
            free(item);
        } else {
            // Handle CSV parsing error
            // ...
        }
    }

    return bundle;
}

void freeBundle(BundleResource* bundle) {
    for (int i = 0; i < bundle->itemCount; i++) {
        BundleItem *item = bundle->items[i];
        if (item) {
            free(item->data);
            free(item);
        }
    }
    free(bundle->items);
    free(bundle);
}

