char* process_string(const char* str, size_t limit, int trim, char sep) {
    if (str == NULL || sep == NULL) return NULL;

    size_t len = strlen(str);
    if (len <= limit) {
        char* ret = malloc(len + 3); // account for "/ " and null-terminator
        strcpy(ret, str);
        strcat(ret, "/");
        strcat(ret, &sep);
        return ret;
    }

    if (!trim) return NULL;

    size_t new_len = len > limit ? limit : len;
    char* ret = malloc(new_len + 2); // account for sep and null-terminator
    strncpy(ret, str, new_len);
    ret[new_len] = sep;
    ret[new_len + 1] = '\0';
    return ret;
}
