typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_nfa_pi_crc_indication_pdu_t(int num_puds) {
    NFAPI_CRC_INDICATION_PDU_T* puds = (NFAPI_CRC_INDICATION_PDU_T*)calloc(num_puds, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < num_puds; i++) {
        puds[i].RX_UE_INFORMATION_TAG = rand() % 256;
