typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
    int key;
    record_t *record;
} memory_block_t;

memory_block_t **memory_blocks = NULL;
int num_memory_blocks = 0;
int max_memory_blocks = 0;
int initial_capacity = 10; // default capacity
int random_range = 100; // default range

void init_memory_manager(int initial_size, int max_random) {
    initial_capacity = initial_size;
    random_range = max_random;

    memory_blocks = (memory_block_t **)malloc(initial_capacity * sizeof(memory_block_t *));
    for (int i = 0; i < initial_capacity; i++) {
        memory_blocks[i] = NULL;
    }

    max_memory_blocks = initial_capacity;
}

void free_memory_manager() {
    for (int i = 0; i < num_memory_blocks; i++) {
        if (memory_blocks[i]) {
            free(memory_blocks[i]->record);
        }
    }
    free(memory_blocks);
}

void* malloc_record(int key) {
    int block_idx = key % max_memory_blocks;
    memory_block_t *block = memory_blocks[block_idx];
    if (!block || block->key == -1) {
        // Reallocate a new block
        block = (memory_block_t *)malloc(sizeof(memory_block_t));
        block->record = (record_t *)malloc(RECORD_SIZE);
        memory_blocks[block_idx] = block;
    }
    return block->record;
}

void record_insert(record_t *new_record, int key) {
    int block_idx = key % max_memory_blocks;
    memory_block_t *block = memory_blocks[block_idx];
    if (!block || block->key == -1) {
        // Reallocate a new block
        block = (memory_block_t *)malloc(sizeof(memory_block_t));
        block->record = (record_t *)malloc(RECORD_SIZE);
        memory_blocks[block_idx] = block;
    }
    block->key = key;
    memcpy(block->record, new_record, RECORD_SIZE);
}

void record_delete(int key) {
    int block_idx = key % max_memory_blocks;
    memory_block_t *block = memory_blocks[block_idx];
    if (block && block->key == key) {
        free(block->record);
        block->record = NULL;
        block->key = -1; // mark as deleted
    }
}

int record_exists(int key) {
    int block_idx = key % max_memory_blocks;
    memory_block_t *block = memory_blocks[block_idx];
    if (block && block->key == key) {
        return 1;
    } else {
        return 0;
    }
}

void log_message(const char* message, int level) {
    // Implement logging mechanism
    printf("Log: %s (level: %d)\n", message, level);
}
