from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad

def config_network_settings_file(params):
    # Load the initial settings file
    with open('settings.json', 'r') as f:
        settings = json.load(f)

    # Replace placeholders with actual values using subprocess module to execute iproute2 commands
    for key, value in params.items():
        if key.startswith('placeholder_'):
            command = f'ip link set dev {key[10:]} mtu {value}'
            try:
                subprocess.run(command.split(), check=True)
            except subprocess.CalledProcessError as e:
                raise Exception(f"Failed to execute command '{command}': {e}")

    # Add a new line with an encrypted network key
    key = params['network_key']
    cipher = AES.new(b'secret_key', AES.MODE_ECB)
    encrypted_key = pad(key.encode(), AES.block_size).hex()
    settings.append({'key': encrypted_key, 'decrypted_key': None})

    # Save the updated settings file
    with open('settings.json', 'w') as f:
        json.dump(settings, f)

def main():
    params = {'network_key': 'my_secret_key'}
    config_network_settings_file(params)

if __name__ == '__main__':
    main()
