```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int SEQUENCE_NUMBER;
    char FRAME_TYPE;
    char* DATA_PAYLOAD;
} MAC_FRAME;

void initMACFrame(MAC_FRAME* frame) {
    // Initialize each frame structure
    frame->SEQUENCE_NUMBER = 0;
    frame->FRAME_TYPE = '\0';
    frame->DATA_PAYLOAD = NULL;
}

int addFrameToList(MAC_FRAME** frames, int* framesCount, MAC_FRAME newFrame) {
    // Dynamically allocate memory for the new frame
    *frames = realloc(*frames, (*framesCount + 1) * sizeof(MAC_FRAME));

    // Copy the new frame to the list
    (*frames)[*framesCount] = newFrame;

    // Increment the frames count
    (*framesCount)++;

    return 0; // Success
}

int getFrameBySeqNumber(MAC_FRAME** frames, int seqNum, MAC_FRAME* retrievedFrame) {
    for (int i = 0; i < *framesCount; i++) {
        if ((*frames)[i].SEQUENCE_NUMBER == seqNum) {
            *retrievedFrame = (*frames)[i];
            return 1; // Found
        }
    }

    return -1; // Not found
}

int removeFrameFromList(MAC_FRAME** frames, int* framesCount, MAC_FRAME targetFrame) {
    for (int i = 0; i < *framesCount; i++) {
        if ((*frames)[i].SEQUENCE_NUMBER == targetFrame.SEQUENCE_NUMBER) {
            // Shift the remaining frames up to fill the gap
            memmove(&(*frames)[i], &(*frames)[i+1], (*framesCount - i - 1) * sizeof(MAC_FRAME));

            // Decrement the frame count
            (*framesCount]--;

            return 0; // Success
        }
    }

    return -1; // Not found
}

int main() {
    int framesCount = 0;
    MAC_FRAME* frames = NULL;

    // Initialize the first frame
    MAC_FRAME initialFrame;
    initMACFrame(&initialFrame);

    // Add the initial frame to the list
    addFrameToList(&frames, &framesCount, initialFrame);

    // ... handle real-time frame updates ...

    return 0; // Success
}
