int main(int argc, char **argv) {
    if (parse_args(argc, argv) == 0) {
        return 1;
    }
    return 0;
}

// Parse command line arguments
int parse_args(int argc, char **argv) {
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            output_file = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage();
            return 0;
        } else if (strlen(argv[i]) > 0 && argv[i][0] != '-') {
            input_file = argv[i];
        }
    }
    if (!input_file) {
        print_usage();
        return 0;
    }
    // Validate input file
    struct stat sb;
    if (stat(input_file, &sb) == -1 || !S_ISREG(sb.st_mode)) {
        fprintf(stderr, "Error: %s is not a valid file.\n", input_file);
        return 1;
    }
    if (!access(input_file, R_OK)) {
        fprintf(stderr, "Error: %s is not readable.\n", input_file);
        return 1;
    }
    return 1;
}

// Process the input file
void process_file(char *input_file, char *output_file) {
    pthread_t thread;
    pthread_create(&thread, NULL, process_file_threaded, (void *)input_file);
    pthread_join(thread, NULL);
}

// Threaded function to process the input file
void *process_file_threaded(void *arg) {
    // Read and process the file
    FILE *file = fopen(input_file, "r");
    if (!file) {
        return NULL;
    }
    char line[1024];
    int line_count = 0;
    long total_chars = 0;
    char *longest_line = "";
    while (fgets(line, sizeof(line), file)) {
        line_count++;
        total_chars += strlen(line);
        if (strlen(line) > strlen(longest_line)) {
            longest_line = line;
        }
    }
    fclose(file);

    // Calculate average word length
    int word_count = 0;
    char *word = strtok(line, " ");
    while (word) {
        word_count++;
        word = strtok(NULL, " ");
    }
    double avg_word_length = (double)total_chars / line_count;

    // Print results
    printf("Line count: %d\n", line_count);
    printf("Average word length: %.2f\n", avg_word_length);
    printf("Longest line: '%s'\n", longest_line);

    if (output_file) {
        FILE *output = fopen(output_file, "w");
        if (!output) {
            return NULL;
        }
        fprintf(output, "Line count: %d\n", line_count);
        fprintf(output, "Average word length: %.2f\n", avg_word_length);
        fprintf(output, "Longest line: '%s'\n", longest_line);
        fclose(output);
    }

    pthread_exit(NULL);
}

// Print usage information
void print_usage() {
    printf("Usage: %s [options] <input_file>\n", argv[0]);
    printf("Options:\n");
    printf("-o output_file  Specify the output file\n");
    printf("--help         Display this help message and exit\n");
}

