#include <unistd.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 1024
#define MAX_CONCURRENT_THREADS 10

typedef struct {
    char *file_path;
    int max_threads;
} opts_t;

opts_t opts;

void print_usage() {
    printf("Usage: %s [-o output_file] [input_file]\n", argv[0]);
}

int process_file(char *file_path) {
    // Read file line by line
    FILE *fp = fopen(file_path, "r");
    if (!fp) {
        perror("Error opening file");
        return -1;
    }

    int line_count = 0;
    int longest_line_len = 0;
    double avg_word_len = 0.0;

    pthread_t threads[MAX_CONCURRENT_THREADS];
    int thread_count = 0;

    char line[MAX_LINE_LENGTH];

    while (fgets(line, sizeof(line), fp)) {
        line_count++;

        // Calculate average word length
        int words = 0;
        char *word = strtok(line, " ");
        while (word) {
            words++;
            word = strtok(NULL, " ");
        }
        avg_word_len += (double)words / strlen(line);

        if (strlen(line) > longest_line_len)
            longest_line_len = strlen(line);
    }

    fclose(fp);

    printf("Line count: %d\n", line_count);
    printf("Average word length: %.2f\n", avg_word_len / line_count);
    printf("Longest line: %s (%d characters)\n", file_path, longest_line_len);

    return 0;
}

int main(int argc, char *argv[]) {
    int c;

    while ((c = getopt(argc, argv, "ho:")) != -1) {
        switch (c) {
            case 'h':
                print_usage();
                return 0;
            case 'o':
                opts.file_path = optarg;
                break;
            default:
                return -1;
        }
    }

    if (argc < 2) {
        print_usage();
        return 0;
    }

    for (int i = 1; i < argc; i++) {
        char *file_path = argv[i];
        // Validate file existence and readability
        struct stat sb;
        if (stat(file_path, &sb) == -1 || !S_ISREG(sb.st_mode)) {
            perror("Error checking file");
            return -1;
        }

        pthread_create(&threads[thread_count++], NULL, process_file, file_path);
    }

    for (int i = 0; i < thread_count; i++)
        pthread_join(threads[i], NULL);

    return 0;
}
