void process_sensor_data_stream(NFAPI_CRC_INDICATION_PDU_T** data_stream, int* stream_size) {
    // Initialize memory pool
    void* memory_pool = malloc(1024 * 1024);
    size_t memory_pool_size = 1024 * 1024;

    // Initialize list of allocated structures
    NFAPI_CRC_INDICATION_PDU_T** allocated_data_stream = NULL;
    int allocated_stream_size = 0;

    // Process sensor data stream
    for (int i = 0; i < *stream_size; i++) {
        if (!data_stream[i]) continue;

        // Allocate new structure from memory pool
        NFAPI_CRC_INDICATION_PDU_T* new_structure = malloc_or_die(memory_pool, memory_pool_size);

        // Copy data to allocated structure
        memcpy(new_structure, data_stream[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Add to list of allocated structures
        if (allocated_stream_size == 0) {
            allocated_data_stream = &new_structure;
            allocated_stream_size = 1;
        } else {
            allocated_data_stream = realloc_or_die(allocated_data_stream, allocated_stream_size + 1, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
            allocated_data_stream[allocated_stream_size++] = new_structure;
        }
    }

    // Free memory pool and allocated structures
    free(memory_pool);
    for (int i = 0; i < allocated_stream_size; i++) {
        free(allocated_data_stream[i]);
    }
    free(allocated_data_stream);
}

void* malloc_or_die(void* memory_pool, size_t memory_pool_size) {
    void* result = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return result;
}

void* realloc_or_die(void* pointer, size_t old_size, size_t new_size) {
    void* result = realloc(pointer, new_size);
    if (!result) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(1);
    }
    return result;
}
