#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_FRAME_REQUESTS 1000

typedef struct {
    int valid_RF_CHAIN;
    int OFDM_SYMBOL_INDEX;
    int RF_RX_PATH;
} LTE_PHY_RX_FRAME;

typedef struct {
    int PHY_SERVICE_REQUEST;
    int NODEB_ID;
    char DOWNLINK_FRAME[256]; // dynamically generated DL MAC PDU with variable payload sizes
} LTE_DL_FRAME_BUFFER;

void* allocate_frame_request(int num_entries, int seed, int time_window) {
    void *frames = malloc(num_entries * sizeof(LTE_PHY_RX_FRAME));
    if (!frames) {
        return NULL;
    }

    for (int i = 0; i < num_entries; i++) {
        LTE_PHY_RX_FRAME* frame = (LTE_PHY_RX_FRAME*) frames + i;
        frame->valid_RF_CHAIN = rand_r(&seed) % 256;
        frame->OFDM_SYMBOL_INDEX = rand_r(&seed) % 1024;
        frame->RF_RX_PATH = rand_r(&seed) % 16;

        // allocate array of LTE_DL_FRAME_BUFFER structures
        void *dl_frames = malloc(time_window * sizeof(LTE_DL_FRAME_BUFFER));
        if (!dl_frames) {
            free(frames);
            return NULL;
        }

        for (int j = 0; j < time_window; j++) {
            LTE_DL_FRAME_BUFFER* dl_frame = (LTE_DL_FRAME_BUFFER*) dl_frames + j;
            dl_frame->PHY_SERVICE_REQUEST = rand_r(&seed) % 16;
            dl_frame->NODEB_ID = rand_r(&seed) % 256;
            sprintf(dl_frame->DOWNLINK_FRAME, "Payload %d", j);
        }

        frame->dl_frames = dl_frames;
    }

    return frames;
}

void free_frame_request(void *frames) {
    if (!frames) {
        return;
