#include <unistd.h>
#include <pthread.h>

#define MAX_FILE_NAME 256
#define MAX_OUTPUT_FILE 256
#define VERBOSE 0
#define DEBUG 1

typedef struct {
    char *input_file;
    char *output_file;
    int verbose;
    int debug;
} Config;

void print_usage() {
    printf("Usage: program [options] [file/directory]\n");
    printf("Options:\n");
    printf("-h, --help\tDisplay this help message and exit\n");
    printf("-v, --verbose\tEnable verbose logging\n");
    printf("-d, --debug\tEnable debugging mode\n");
}

Config parse_args(int argc, char *argv[]) {
    Config config;
    config.input_file = NULL;
    config.output_file = NULL;
    config.verbose = 0;
    config.debug = 0;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            print_usage();
            exit(0);
        } else if (strcmp(argv[i], "-v") == 0 || strcmp(argv[i], "--verbose") == 0) {
            config.verbose = VERBOSE;
        } else if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "--debug") == 0) {
            config.debug = DEBUG;
        } else if (strstr(argv[i], ".") != NULL) {
            // Process file/directory
            char *file_path = strdup(argv[i]);
            char *input_file = basename(file_path);
            config.input_file = input_file;
            free(file_path);
        }
    }

    return config;
}

int main(int argc, char *argv[]) {
    Config config = parse_args(argc, argv);

    if (config.input_file == NULL) {
        print_usage();
        exit(1);
    }

    // Process files asynchronously
    int num_threads = 4; // Adjust based on available CPU cores
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, process_file, config.input_file);
    }
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void* process_file(void* file_path) {
    // Process the file
    FILE *file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", file_path);
        return NULL;
    }
    // Read and process file contents
    fclose(file);

    return NULL;
}
