#include <pthread.h>

#define MAX_THREADS 10

typedef struct {
    int id;
    pthread_t thread_id;
} thread_data;

int main(int argc, char *argv[]) {
    int c, opt, lines = 0;
    char *output_file = NULL, *input_file = NULL;
    thread_data threads[MAX_THREADS];
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"output-file", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, "ho:", long_options)) != -1) {
        switch (c) {
            case 'h':
                printf("Usage: %s [-h] [-o output_file] input_file\n", argv[0]);
                exit(EXIT_SUCCESS);
            case 'o':
                output_file = optarg;
                break;
            default:
                fprintf(stderr, "Invalid command-line option: -%c\n", optopt);
                return 1;
        }
    }

    if (argc <= optind) {
        printf("Usage: %s [-h] [-o output_file] input_file\n", argv[0]);
        exit(EXIT_SUCCESS);
    }

    input_file = argv[optind];

    // Check if file exists and is readable
    struct stat sb;
    if (stat(input_file, &sb) == -1 || !S_ISREG(sb.st_mode)) {
        perror("Error");
        return 1;
    }

    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Error");
        return 1;
    }

    // Read file line by line
    while (fgets(buffer, sizeof buffer, fp)) {
        // Count the number of lines
        lines++;

        // Calculate the average word length for each line
        int words = 0;
        char *token = strtok(buffer, " ");
        while (token) {
            words++;
            token = strtok(NULL, " ");
        }

        // Identify and report the longest line based on character count
        if (strlen(buffer) > max_length) {
            max_length = strlen(buffer);
        }
    }

    fclose(fp);

    // Process file using multi-threading
    pthread_t threads[MAX_THREADS];
    int thread_count = 0;
    while (pthread_create(&threads[thread_count], NULL, process_file, (void *)input_file)) {
        thread_count++;
        if (thread_count >= MAX_THREADS) {
            break;
        }
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

void *process_file(void *input_file_void) {
    // Process file line by line using the file pointer
    FILE *fp = fopen(input_file_void, "r");
    if (!fp) {
        perror("Error");
        return NULL;
    }

    // Read file line by line
    while (fgets(buffer, sizeof buffer, fp)) {
        // Count the number of lines
        pthread_mutex_lock(&mutex);
        lines++;
        pthread_mutex_unlock(&mutex);

        // Calculate the average word length for each line
        int words = 0;
        char *token = strtok(buffer, " ");
        while (token) {
            words++;
            token = strtok(NULL, " ");
        }

        // Identify and report the longest line based on character count
        if (strlen(buffer) > max_length) {
            max_length = strlen(buffer);
        }
    }

    fclose(fp);

    return NULL;
}

