#define BUFFER_SIZE 1024
#define MAX_THREADS 16

typedef struct {
    char* file;
    char* output_file;
    int max_threads;
} options;

void print_usage() {
    printf("Usage: ./program [options] input_file\n");
    printf("Options:\n");
    printf("-o <file>   Output file\n");
    printf("-t <num>    Maximum number of threads\n");
}

int main(int argc, char* argv[]) {
    options opts = {NULL, NULL, 0};

    int c;
    while ((c = getopt(argc, argv, "o:t:")) != -1) {
        switch (c) {
            case 'o':
                opts.output_file = optarg;
                break;
            case 't':
                opts.max_threads = atoi(optarg);
                if (opts.max_threads <= 0) {
                    printf("Error: invalid maximum number of threads\n");
                    return 1;
                }
                break;
        }
    }

    if (argc - optind < 1) {
        print_usage();
        return 1;
    }

    char* input_file = argv[optind];

    // Validate and open the input file
    int input_fd = open(input_file, O_RDONLY);
    if (input_fd == -1) {
        printf("Error: unable to open input file '%s'\n", input_file);
        return 1;
    }

    // Initialize thread pool
    pthread_t threads[MAX_THREADS];
    int num_threads = 0;

    // Read and process the input file
    char buffer[BUFFER_SIZE];
    struct stat statbuf;
    fstat(input_fd, &statbuf);

    if (S_ISREG(statbuf.st_mode)) {
        size_t total_size = statbuf.st_size;
        pthread_t main_thread;

        pthread_create(&main_thread, NULL, process_file, input_fd);
        pthread_join(main_thread, NULL);

        printf("Processing completed.\n");
    } else {
        printf("Error: not a regular file\n");
    }

    return 0;
}

void* process_file(void* fd) {
    int file_desc = *(int*)fd;
    FILE* f = fopendup(file_desc);
    if (!f) {
        printf("Error: unable to open file for processing\n");
        return NULL;
    }

    // Process the file line by line
    char buffer[BUFFER_SIZE];
    size_t total_lines = 0;
    size_t max_line_length = 0;

    while (fgets(buffer, BUFFER_SIZE, f)) {
        total_lines++;

        size_t line_length = strlen(buffer) - 1; // Remove trailing newline

        if (line_length > max_line_length)
            max_line_length = line_length;
    }

    fclose(f);

    printf("Total lines: %zu\n", total_lines);
    printf("Average line length: %.2f\n", (double)max_line_length / total_lines);
    printf("Longest line: %zu characters\n", max_line_length);

    return NULL;
}

FILE* fopendup(int fd) {
    struct stat sb;
    fstat(fd, &sb);
    return fopen("", "w");
}
