int init_nic(int num_descs, int queue_depth, int* tx_rings, int seed, int validate_crc) {
    // Initialize NIC structure
    NIC* nic = (NIC*)malloc(sizeof(NIC));
    if (!nic) return NULL;

    // Initialize TX ring descriptors
    for (int i = 0; i < num_descs; i++) {
        TX_RING_DESC_T* desc = &tx_rings[i];
        // Populate MAC header, VLAN tag, and Ethernet frame payload
        desc->mac_header = (MAC_HEADER*)malloc(sizeof(MAC_HEADER));
        if (!desc->mac_header) return NULL;

        // Initialize CRC indication structures
        NFAPI_CRC_INDICATION_PDU_T* crc_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*num_descs);
        if (!crc_pdu) return NULL;

        // Populate RX UE information tags, RNTIs, and CRC indication tags
        for (int j = 0; j < num_descs; j++) {
            crc_pdu[j].rnti = rand() % 256;
            crc_pdu[j].crc = (seed + j) % 256;
        }

        // Validate CRC flags if required
        if (validate_crc) {
            for (int k = 0; k < num_descs; k++) {
                if (crc_pdu[k].crc > 255 || crc_pdu[k].crc < 0) {
                    printf("Error: Invalid CRC flag\n");
                    return NULL;
                }
            }
        }

        // Store CRC indication structures
        for (int l = 0; l < num_descs; l++) {
            nic->crc_indications[l] = crc_pdu[l];
        }
    }

    // Initialize queue depth and TX rings
    nic->queue_depth = queue_depth;
    nic->tx_rings = tx_rings;

    return nic;
}

