typedef struct {
    int TX_UE_INFORMATION_TAG;
    int RNTI;
    char UL_AZT_PDU[10];
} NFAPI_UL_AZT_pdu;

NFAPI_UL_AZT_pdu* generate_array(int n) {
    // Initialize array with initial allocation size
    NFAPI_UL_AZT_pdu* array = (NFAPI_UL_AZT_pdu*)malloc(n * sizeof(NFAPI_UL_AZT_pdu));

    if (!array) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    int priority_max = 10; // Set the maximum priority level
    int priority_min = 1;   // Set the minimum priority level

    for (int i = 0; i < n; i++) {
        array[i].TX_UE_INFORMATION_TAG = rand() % 10000;
        array[i].RNTI = rand() % 1000;

        sprintf(array[i].UL_AZT_PDU, "Tag_%d_RNTI_%d", array[i].TX_UE_INFORMATION_TAG, array[i].RNTI);

        // Randomly assign a priority level to each structure
        int priority_level = (rand() % (priority_max - priority_min)) + 1;

        if (i == 0) {
            // If this is the first element, set it as the average priority level
            array[i].priority_level = priority_level;
        } else {
            // Calculate the average priority level for each subsequent element
            array[i].priority_level = (array[i-1].priority_level * i + priority_level) / (i+1);
        }
    }

    return array;
}

void free_array(NFAPI_UL_AZT_pdu* array, int n) {
    // Free the allocated memory
    free(array);
}

int main() {
    int n = 10; // Set the number of structures to generate

    NFAPI_UL_AZT_pdu* array = generate_array(n);

    if (array == NULL) {
        printf("Error: Generation failed.\n");
    } else {
        // Print the generated array
        for (int i = 0; i < n; i++) {
            printf("TX_UE_INFORMATION_TAG: %d, RNTI: %d, Priority Level: %d\n", array[i].TX_UE_INFORMATION_TAG, array[i].RNTI, array[i].priority_level);
        }

        // Free the allocated memory
        free_array(array, n);
    }

    return 0;
}
