#include <string.h>
#include <getopt.h>

#define MAX_CONFIG_FILE_NAME 1024
#define MAX_ERROR_MESSAGE 2048

typedef struct {
    int some_setting;
} Config;

Config read_config_file(const char *config_file_path) {
    FILE *fp = fopen(config_file_path, "r");
    if (fp == NULL) {
        return (Config){0}; // default settings
    }

    Config config;
    fscanf(fp, "%d\n", &config.some_setting);
    fclose(fp);

    return config;
}

void print_help_message() {
    printf("Usage: app_name [options]\n");
    printf("  --help         display this help message and exit\n");
    printf("  --version      display version information and exit\n");
    printf("  --config-file <file>  specify configuration file path\n");
}

int main(int argc, char *argv[]) {
    Config config;
    int some_setting = 0; // default value

    while (1) {
        static struct option long_options[] = {
            {"help",      no_argument,       0, 'h'},
            {"version",   no_argument,       0, 'v'},
            {"config-file", required_argument, 0, 'c'}
        };

        int c;
        int option_index = 0;

        c = getopt_long(argc, argv, "+:hvc:", long_options, &option_index);
        if (c == -1) {
            break;
        }

        switch (c) {
            case 'h':
                print_help_message();
                return 0;
            case 'v':
                printf("App version: 1.0\n");
                return 0;
            case 'c':
                char *config_file_path = optarg;
                config = read_config_file(config_file_path);
                some_setting = config.some_setting;
                break;
        }
    }

    // parse environment variables
    char *env_var = getenv("SOME_SETTING");
    if (env_var != NULL) {
        some_setting = atoi(env_var);
    }

    printf("some_setting: %d\n", some_setting);

    return 0;
}
