public static byte[] decryptAES_CBC(byte[] cipherText, byte[] encryptionKey, byte[] initializationVector, int blockSize)
{
    using (var aes = Aes.Create())
    {
        aes.Key = encryptionKey;
        aes.IV = initializationVector;

        using (var decryptor = aes.CreateDecryptor())
        {
            using (var ms = new MemoryStream(cipherText))
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var plainBytes = new byte[cipherText.Length];
                    int decryptedByteCount = cs.Read(plainBytes, 0, plainBytes.Length);
                    return plainBytes.Take(decryptedByteCount).ToArray();
                }
            }
        }
    }
}
