#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

typedef struct MeasurementReport {
    int signalStrength;
    int frequency;
    struct MeasurementReport* next;
} MeasurementReport;

typedef struct UEStats {
    int ueId;
    MeasurementReport* measurementReports;
    time_t lastUpdated;
} UEStats;

UEStats** initializeUEStats(int numUE, int minSignal, int maxSignal, int minFreq, int maxFreq) {
    UEStats** ueStats = (UEStats**)malloc(numUE * sizeof(UEStats*));
    if (!ueStats) return NULL;

    for (int i = 0; i < numUE; i++) {
        UEStats* ueStat = (UEStats*)malloc(sizeof(UEStats));
        if (!ueStat) return NULL;

        srand(time(NULL) + i);
        int ueId = rand() % 10000;
        while (ueId == 0) {
            ueId = rand() % 10000;
        }

        MeasurementReport* measurementReports = NULL;
        for (int j = 0; j < 10; j++) {
            MeasurementReport* report = (MeasurementReport*)malloc(sizeof(MeasurementReport));
            if (!report) return NULL;

            int signal = (rand() % (maxSignal - minSignal + 1)) + minSignal;
            int frequency = (rand() % (maxFreq - minFreq + 1)) + minFreq;
            report->signalStrength = signal;
            report->frequency = frequency;
            report->next = measurementReports;

            measurementReports = report;
        }

        ueStat->ueId = ueId;
        ueStat->measurementReports = measurementReports;
        ueStat->lastUpdated = time(NULL);

        ueStats[i] = ueStat;
    }

    return ueStats;
}

void cleanupUEStats(UEStats** ueStats, int numUE) {
    for (int i = 0; i < numUE; i++) {
        UEStats* ueStat = ueStats[i];
        MeasurementReport* measurementReports = ueStat->measurementReports;

        while (measurementReports) {
            MeasurementReport* next = measurementReports->next;
            free(measurementReports);
            measurementReports = next;
        }

        free(ueStat);
    }
    free(ueStats);
}

