void initializeUEStats(UEStats** ueStatsArray, int* size, int minSignal, int maxSignal, int minFreq, int maxFreq) {
    // Initialize the ID generator
    srand(time(NULL));
    int ueId = 0;

    // Allocate memory for the UE stats array
    *ueStatsArray = (UEStats*)malloc(*size * sizeof(UEStats));

    // Populate the UE stats array
    for (int i = 0; i < *size; i++) {
        (*ueStatsArray)[i].ueId = ueId++;
        int signalStrength = round(minSignal + (double)(maxSignal - minSignal) * rand() / RAND_MAX);
        int frequency = round(minFreq + (double)(maxFreq - minFreq) * rand() / RAND_MAX);

        // Dynamically allocate memory for the measurement reports
        (*ueStatsArray)[i].measurementReports = (struct {
            int signalStrength;
            int frequency;
        }*)malloc(sizeof(struct {
            int signalStrength;
            int frequency;
        }) * 10); // Assume a maximum of 10 measurement reports per UE

        // Initialize the last updated timestamp
        (*ueStatsArray)[i].lastUpdated = time(NULL);

        // Log the initialization
        printf("UE %d initialized with signal strength %d and frequency %d.\n", i, signalStrength, frequency);
    }
}

void cleanupUEStats(UEStats** ueStatsArray, int* size) {
    for (int i = 0; i < *size; i++) {
        // Free the measurement reports
        free((*ueStatsArray)[i].measurementReports);

        // Reset the UE stats struct to avoid memory leaks
        (*ueStatsArray)[i].ueId = -1;
        (*ueStatsArray)[i].measurementReports = NULL;
        (*ueStatsArray)[i].lastUpdated = 0;
    }

    // Free the UE stats array
    free(*ueStatsArray);
}

void updateUEStats(UEStats** ueStatsArray, int* size) {
    // Update the last updated timestamp
    for (int i = 0; i < *size; i++) {
        (*ueStatsArray)[i].lastUpdated = time(NULL);
    }
