```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct Node {
    int nodeId;
    struct Connection* connections;
    time_t lastHeartbeat;
} Node;

typedef struct Connection {
    int latency;
    int bandwidth;
    struct Connection* next;
} Connection;

Node* setupNetworkMonitor(int minLatency, int maxLatency, int minBandwidth, int maxBandwidth) {
    srand(time(NULL)); // Seed the random number generator
    Node* network = NULL;
    for (int i = 0; i < 10000; i++) { // Generate up to 10,000 unique node IDs
        Node* newNode = malloc(sizeof(Node));
        newNode->nodeId = i + 1; // Start from 1
        if (!newNode) {
            printf("Memory allocation failed.\n");
            return NULL;
        }
        newNode->connections = NULL;
        newNode->lastHeartbeat = time(NULL);
        network = realloc(network, sizeof(Node*) * (i + 2)); // Make room for the new node and a sentinel
        network[i] = newNode;
    }
    // Populating Connection records with random latency and bandwidth values
    for (int i = 0; i < 10000; i++) {
        Node* node = &network[i];
        if (!node) continue;
        for (Connection* conn = malloc(sizeof(Connection)); conn; ) {
            conn->latency = round((double)(rand() % (maxLatency - minLatency)) + minLatency);
            conn->bandwidth = round((double)(rand() % (maxBandwidth - minBandwidth)) + minBandwidth);
            conn->next = node->connections;
            node->connections = conn;
        }
    }
    return network;
}

void cleanupNetworkMonitor(Node* network) {
    for (int i = 0; i < 10000; i++) {
        Node* node = &network[i];
        if (!node) continue;
        Connection* curr = node->connections;
        while (curr) {
            Connection* next = curr->next;
            free(curr);
            curr = next;
        }
    }
    free(network);
}

