}

void freeNetworkMonitor(Node* node) {
    Connection* currentConnection = node->connections;
    Connection* previousConnection = NULL;

    while (currentConnection != NULL) {
        Connection* nextConnection = currentConnection->next;

        if (previousConnection != NULL) {
            free(previousConnection);
        }

        previousConnection = currentConnection;
        currentConnection = nextConnection;
    }

    free(node);
}
