UEStats* initializeGraphWithStatsAndTransform(const char* inputFile, const char* outputFile, const char* transformationRules, int seed) {
    srand(seed);

    FILE* file = fopen(inputFile, "rb");
    if (file == NULL)
        return NULL; // error opening input file

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    UEStats* ueStats = (UEStats*)malloc((int)ceil((double)fileSize / sizeof(UEStats)) * sizeof(UEStats));
    if (ueStats == NULL)
        return NULL; // error allocating memory

    for (int i = 0; i < fileSize / sizeof(UEStats); i++) {
        UEStats* ueStat = &ueStats[i];
        int ueId;
        fread(&ueId, sizeof(int), 1, file);
        ueStat->ueId = ueId;

        MeasurementReport* measurement = (MeasurementReport*)malloc(sizeof(MeasurementReport));
        if (measurement == NULL)
            return NULL; // error allocating memory
        measurement->signalStrength = rand() % (int)(MAX_SIGNAL - MIN_SIGNAL) + MIN_SIGNAL;
