typedef struct {
    int signalStrength;
    int frequency;
} MeasurementReport;

void initializeGraphWithStatsAndTransform(char* inputFile, char* outputFile, char* transformationRules, unsigned int minSignal, unsigned int maxSignal, unsigned int minFreq, unsigned int maxFreq) {
    srand(time(NULL));

    FILE* file = fopen(inputFile, "rb");
    if (file == NULL) {
        printf("Error opening input file.\n");
        return;
    }

    UEStats** statsArray = (UEStats**)malloc(10000 * sizeof(UEStats*));
    for (int i = 0; i < 10000; i++) {
        UEStats* stats = (UEStats*)malloc(sizeof(UEStats));
        stats->ueId = rand() % 10000;
        stats->measurements = NULL;
        stats->lastUpdated = time(NULL);

        MeasurementReport* measurement = (MeasurementReport*)malloc(sizeof(MeasurementReport));
        measurement->signalStrength = round(rand() * ((double)(maxSignal - minSignal)) / RAND_MAX + minSignal);
        measurement->frequency = round(rand() * ((double)(maxFreq - minFreq)) / RAND_MAX + minFreq);

        if (stats->measurements == NULL) {
            stats->measurements = measurement;
        } else {
            MeasurementReport* current = stats->measurements;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = measurement;
        }

        statsArray[i] = stats;
    }

    // Apply transformation rules
    // ...

    FILE* outputFileHandle = fopen(outputFile, "wb");
    if (outputFileHandle == NULL) {
        printf("Error opening output file.\n");
        return;
    }

    for (int i = 0; i < 10000; i++) {
        UEStats* stats = statsArray[i];
        fwrite(&stats->ueId, sizeof(int), 1, outputFileHandle);
        fwrite(&stats->measurements, sizeof(MeasurementReport), 1, outputFileHandle);
        fwrite(&stats->lastUpdated, sizeof(time_t), 1, outputFileHandle);
    }

    for (int i = 0; i < 10000; i++) {
        free(statsArray[i]->measurements);
        free(statsArray[i]);
    }
    free(statsArray);

    fclose(file);
    fclose(outputFileHandle);
}
