    // Initialize structures
    int maxStructures = atoi(getenv("MAX_STRUCTURES"));
    int numInterfaces = rand() % maxStructures + 1;
    NetworkInterfaceStatistics** interfaces = (NetworkInterfaceStatistics**)malloc(numInterfaces * sizeof(NetworkInterfaceStatistics*));

    for (int i = 0; i < numInterfaces; i++) {
        interfaces[i] = (NetworkInterfaceStatistics*)malloc(sizeof(NetworkInterfaceStatistics));
        interfaces[i]->interfaceId = rand();
        int numPackets = rand() % 100 + 1;
        interfaces[i]->numPackets = numPackets;
        interfaces[i]->packetInfo = (char**)malloc(numPackets * sizeof(char*));

        for (int j = 0; j < numPackets; j++) {
            char packetInfo[50];
            sprintf(packetInfo, "Packet %d: Size=%d, Type=%c", j+1, rand() % 100 + 1, 'A' + rand() % 26);
            interfaces[i]->packetInfo[j] = (char*)malloc(strlen(packetInfo) + 1);
            strcpy(interfaces[i]->packetInfo[j], packetInfo);
        }
    }

    // Simulate network conditions
    int packetLossRate = atoi(getenv("PACKET_LOSS_RATE"));
    for (int i = 0; i < numInterfaces; i++) {
        for (int j = 0; j < interfaces[i]->numPackets; j++) {
            if (rand() % 100 > packetLossRate) {
                free(interfaces[i]->packetInfo[j]);
                interfaces[i]->packetInfo[j] = NULL;
            }
        }
    }

    // Simulate real-world usage patterns
    int delayProbability = atoi(getenv("DELAY_PROBABILITY"));
    for (int i = 0; i < numInterfaces; i++) {
