            sleep(rand() % 10 + 1);
        }
    }

    // Validate integrity of generated structures
    for (int i = 0; i < numInterfaces; i++) {
        for (int j = 0; j < interfaces[i]->numPackets; j++) {
            if (!interfaces[i]->packetInfo[j]) {
                printf("Error: Packet transmission record %d on interface %d is missing!\n", j+1, i);
            }
        }
    }

    // Free allocated resources
    for (int i = 0; i < numInterfaces; i++) {
        free(interfaces[i]->packetInfo);
        free(interfaces[i]);
    }
    free(interfaces);

    return NULL;
