// Add a new document to the collection
void addDocument(Document** documents, int maxDocuments) {
    // Check if we've reached the maximum number of documents
    if (*documents == NULL && *documents != NULL) {
        printf("Error: Maximum number of documents exceeded.\n");
        return;
    }

    // Allocate space for a new document
    Document* doc = initializeDocument();

    // Add the document to the collection
    int len = 0;
    for (int i = 0; *documents[i] != NULL; i++) {
        len++;
    }
    (*documents) = realloc(*documents, (len + 1) * sizeof(Document*));
    (*documents)[len] = doc;
}

// Search for documents containing a specific phrase
Document** searchDocuments(Document** documents, int maxDocuments, char* query) {
    // Initialize an array to hold the matching documents
    Document** matches = malloc((maxDocuments + 1) * sizeof(Document*));
    int matchCount = 0;

    for (int i = 0; i < maxDocuments; i++) {
        if (*documents[i] != NULL && strstr((*documents[i])->docId, query) != NULL) {
            matches[matchCount++] = *documents[i];
        }
    }

    // Return the matching documents
    return matches;
}

int main() {
    int maxDocuments = 10; // Maximum number of documents allowed

    Document* documents = NULL;
    addDocument(&documents, maxDocuments);

    char* query = "Doc_5";
    Document** matches = searchDocuments(&documents, maxDocuments, query);

    for (int i = 0; i < matchCount; i++) {
        printf("Match: %s\n", matches[i]->docId);
    }

    return 0;
}
