// Function to initialize and populate UEStats array
UEStats** initUEStats(int numEntries, int measurementReportCount, double minSignalStrength, double maxSignalStrength, double minFrequency, double maxFrequency) {
    // Initialize UEStats array with dynamically allocated memory
    UEStats** ueStatsArray = (UEStats**)calloc(numEntries, sizeof(UEStats*));
    srand(time(NULL));  // Seed random number generator

    for (int i = 0; i < numEntries; i++) {
        UEStats* ueStats = (UEStats*)malloc(sizeof(UEStats));
        ueStats->ueId = rand() % (i + 1);  // Ensure unique ueId
        ueStats->measurementReports = (MeasurementReport*)calloc(measurementReportCount, sizeof(MeasurementReport));

        for (int j = 0; j < measurementReportCount; j++) {
            MeasurementReport* report = &ueStats->measurementReports[j];
            report->signalStrength = minSignalStrength + (rand() / (RAND_MAX / (maxSignalStrength - minSignalStrength)));
            report->frequency = minFrequency + (rand() / (RAND_MAX / (maxFrequency - minFrequency)));
        }

        ueStats->lastUpdated = time(NULL);
        ueStatsArray[i] = ueStats;
    }

    return ueStatsArray;
}

// Function to prune old UEStats entries based on age threshold
void pruneUEStats(UEStats** ueStatsArray, int numEntries, int ageThreshold) {
    // Iterate over UEStats array and free entries older than age threshold
    for (int i = 0; i < numEntries; i++) {
        if ((time(NULL) - ueStatsArray[i]->lastUpdated) > ageThreshold) {
            free(ueStatsArray[i]);
            ueStatsArray[i] = NULL;
        }
    }

    // Reallocate memory to compact the array
    int newNumEntries = 0;
    for (int i = 0; i < numEntries; i++) {
        if (ueStatsArray[i]) {
            newNumEntries++;
        } else {
            free(ueStatsArray[i]);
        }
    }

    // Resize UEStats array to new number of entries
    ueStatsArray = (UEStats**)realloc(ueStatsArray, sizeof(UEStats*) * newNumEntries);
}

// Function to update MeasurementReport records asynchronously
void updateMeasurementReports(UEStats** ueStatsArray, int numEntries) {
