    pthread_t thread;
    pthread_create(&thread, NULL, (void (*)(void*))updateMeasurementReportsThread, ueStatsArray);
}

// Thread function to update MeasurementReport records asynchronously
void* updateMeasurementReportsThread(void* arg) {
