void scaleUEStats(UEStats** ueStatsArray, int numEntries, int workerCount) {
    // Distribute UEStats array among multiple worker threads for concurrent processing
    pthread_t* workerThreads = (pthread_t*)calloc(workerCount, sizeof(pthread_t));
