        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand();

        int random_CRCFLAG = rand() % 2;
        if ((total_CRCFLAGS + random_CRCFLAG) % 2 == 0)
