#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct MeasurementReport {
    int signalStrength;
    int frequency;
    char RX_UE_INFORMATION_TAG[10];
    char RNTI[4];
    char CRC_INDICATION_REL8_TAG[12];
    unsigned int CRCFLAG;
} MeasurementReport;

typedef struct UEStats {
    int ueId;
    MeasurementReport* measurementReports;
    time_t lastUpdated;
} UEStats;

void initializeUEStatsDatabase(int numUEs) {
    // Initialize the database with a dynamic array of UEStats structures
    UEStats** ueStats = (UEStats**)malloc(numUEs * sizeof(UEStats*));

    if (!ueStats) {
        return NULL;  // Error: unable to allocate memory
    }

    for (int i = 0; i < numUEs; i++) {
        UEStats* currentUE = (UEStats*)malloc(sizeof(UEStats));
        if (!currentUE) {
            free((void*)ueStats);
            return NULL;  // Error: unable to allocate memory
        }

        // Initialize the measurement reports for each UEStats structure
        int numReports = rand() % 10 + 1;
        currentUE->measurementReports = (MeasurementReport*)malloc(numReports * sizeof(MeasurementReport));
        if (!currentUE->measurementReports) {
            free((void*)ueStats);
            free((void*)currentUE);
            return NULL;  // Error: unable to allocate memory
        }

        for (int j = 0; j < numReports; j++) {
            MeasurementReport* report = &currentUE->measurementReports[j];
            report->signalStrength = rand() % 100;
            report->frequency = rand() % 10 + 1;
            sprintf(report->RX_UE_INFORMATION_TAG, "RX_UE_INFO_%d", i);
            sprintf(report->RNTI, "RNTI_%02X", (i & 0xFF));
            sprintf(report->CRC_INDICATION_REL8_TAG, "CRC_INDREL8TAG_%04X", rand() % 0xFFFF);
            report->CRCFLAG = rand() % 2;

        }

        // Initialize the lastUpdated timestamp and ueId for each UEStats structure
        currentUE->lastUpdated = time(NULL) - (rand() % 3600);  // Set lastUpdated to a random value between 1-60 minutes ago
        currentUE->ueId = i;

        ueStats[i] = currentUE;
    }

    return ueStats;  // Return the managed UEStats array
}

void UEStatsDatabaseGarbageCollection(UEStats** ueStats, int numUEs) {
    time_t currentTime = time(NULL);
    int thresholdMinutes = 30;  // Default inactivity threshold (30 minutes)

    for (int i = 0; i < numUEs; i++) {
        if (ueStats[i]->lastUpdated + thresholdMinutes * 60 <= currentTime) {
            // Remove the UEStats entry based on the configurable inactivity threshold
            free((void*)ueStats[i]->measurementReports);
            free((void*)ueStats[i]);
            ueStats[i] = NULL;
        }
    }

}

int main() {
    int numUEs = 100;  // Initialize with a specific number of UE stats

    UEStats** ueStats = initializeUEStatsDatabase(numUEs);

    if (!ueStats) {
        printf("Error: unable to initialize UEStats database.\n");
        return -1;
    }

    // Perform garbage collection periodically based on network load and traffic patterns
    while (1) {
        UEStatsDatabaseGarbageCollection(ueStats, numUEs);
        sleep(60);  // Simulate a 1-minute interval for demonstration purposes

        // Update the lastUpdated timestamp to simulate recent activity
        for (int i = 0; i < numUEs; i++) {
            ueStats[i]->lastUpdated = time(NULL);
        }
    }

    return 0;
}

