import subprocess
import json
import os
from cryptography.fernet import Fernet

def replace_placeholders(config_file, placeholders_dict):
    # Read the configuration file
    with open(config_file, 'r') as f:
        config = f.read()

    # Replace placeholders with actual values
    for placeholder, value in placeholders_dict.items():
        config = config.replace(f'{{{placeholder}}}', str(value))

    # Write the updated configuration file
    with open(config_file, 'w') as f:
        f.write(config)

    return

def add_encrypted_password(config_file, password):
    # Read the configuration file
    with open(config_file, 'r') as f:
        config = f.read()

    # Encrypt the password using Fernet
    cipher_suite = Fernet(os.urandom(32))
    encrypted_password = cipher_suite.encrypt(password.encode())

    # Add the encrypted password to the configuration file
    config += f'\n{{"encrypted_password": "{encrypted_password.decode()}"}}'

    # Write the updated configuration file
    with open(config_file, 'w') as f:
        f.write(config)

    return

if __name__ == '__main__':
    config_file = 'config.json'
    placeholders_dict = {'<RX_UE_INFORMATION_TAG>': 1234, '<RNTI>': 5678}
    password = 'my_secret_password'

    try:
        replace_placeholders(config_file, placeholders_dict)
        add_encrypted_password(config_file, password)
    except Exception as e:
        print(f"Error: {e}")
        # Attempt to roll back changes
        if os.path.exists(config_file):
            os.remove(config_file)
        raise

    print("Configuration file updated successfully!")
