import yaml
import os
import logging
from cryptography.fernet import Fernet

class ConfigManager:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config_data = None
        self.fernet_key = None

    def load_config(self):
        try:
            with open(self.config_file, 'r') as file:
                self.config_data = yaml.safe_load(file)
        except Exception as e:
            logging.error(f"Error loading config: {e}")
            raise

    def update_config(self, updates):
        try:
            updated_config = self.config_data.copy()
            for key, value in updates.items():
                updated_config[key] = value
            with open(self.config_file, 'w') as file:
                yaml.dump(updated_config, file)
        except Exception as e:
            logging.error(f"Error updating config: {e}")
            raise

    def encrypt_field(self, field_name, value):
        if self.fernet_key is None:
            self.fernet_key = Fernet.generate_key()
        cipher_suite = Fernet(self.fernet_key)
        encrypted_value = cipher_suite.encrypt(value.encode())
        return encrypted_value.decode()

    def decrypt_field(self, field_name, encrypted_value):
        if self.fernet_key is None:
            self.fernet_key = Fernet.generate_key()
        cipher_suite = Fernet(self.fernet_key)
        decrypted_value = cipher_suite.decrypt(encrypted_value.encode())
        return decrypted_value.decode()

if __name__ == "__main__":
    config_manager = ConfigManager("config.yaml")
    try:
        config_manager.load_config()
        updates = {"field1": "value1", "field2": "value2"}
        config_manager.update_config(updates)
    except Exception as e:
        logging.error(f"Error handling configuration: {e}")
