import subprocess
import json
import base64

def replace_placeholders(config_file, placeholder_dict):
    # Read the configuration file
    with open(config_file, 'r') as f:
        config_text = f.read()

    for placeholder, value in placeholder_dict.items():
        # Replace placeholders with actual values using sed commands
        command = f"sed -i 's/{placeholder}/{value}/g' {config_file}"
        try:
            subprocess.run(command.split(), check=True)
        except subprocess.CalledProcessError as e:
            print(f"Error replacing {placeholder} with {value}: {e}")
            # Roll back changes to the configuration file
            command = f"sed -i 's/{value}/{placeholder}/g' {config_file}"
            try:
                subprocess.run(command.split(), check=True)
            except subprocess.CalledProcessError as e:
                print(f"Error rolling back {placeholder} replacement: {e}")

    # Add a new line with an encrypted password
    password = "my_secret_password"
    encrypted_password = base64.b64encode(password.encode()).decode()
    config_text += f"\n{encrypted_password}\n"

    with open(config_file, 'w') as f:
        f.write(config_text)

if __name__ == "__main__":
    config_file = "config.txt"
    placeholder_dict = {"<username>": "johndoe", "<password>": "my_secret_password"}
    replace_placeholders(config_file, placeholder_dict)
