        crc_indications[i].rnti = 0;
    }
}

void NFapiRxFrameConfig(int n, NFAPI_RX_FRAME_T** rx_frames, NFAPI_CRC_INDICATION_PDU_T** crc_indications) {
    initializeNFapiRxFrames(n, rx_frames);
    initializeNFapiCrcIndications(n, crc_indications, *rx_frames);
    validateNFapiRxFrames(*rx_frames, n);
    validateNFapiCrcIndications(*crc_indications, n);
    deallocateNFapiRxFrames(*rx_frames, n);
    deallocateNFapiCrcIndications(*crc_indications, n);
}
