    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_RX_FRAME_T* nfapi_rx_frame_init(int n) {
    NFAPI_RX_FRAME_T* frames = (NFAPI_RX_FRAME_T*)malloc(n * sizeof(NFAPI_RX_FRAME_T));
    if (!frames) return NULL;
    for (int i = 0; i < n; i++) {
        frames[i].rrc_rx_frame_tag = i;
        frames[i].rx_stream_tag = malloc(10);
        strcpy(frames[i].rx_stream_tag, "StreamTag");
        frames[i].snr = (float)rand() / RAND_MAX;
    }
    return frames;
}

NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication_pdu_init(int n) {
    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_frames = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_pdu_frames) return NULL;
    for (int i = 0; i < n; i++) {
        crc_pdu_frames[i].rx_ue_information_tag = i;
        crc_pdu_frames[i].rnti = i;
        crc_pdu_frames[i].crc_indication_rel8_tag = i;
        // Parity check on rx_stream_tag
        char parity = 'x';
        for (char c : frames[i].rx_stream_tag) {
            if (c % 2 == 0) {
                parity ^= c;
            }
        }
        crc_pdu_frames[i].crc_indication_rel8_tag &= ~CRCFLAG;
    }
    return crc_pdu_frames;
}

void nfapi_rx_frame_deinit(NFAPI_RX_FRAME_T* frames, int n) {
    for (int i = 0; i < n; i++) {
        if (frames[i].rx_stream_tag) free(frames[i].rx_stream_tag);
    }
    free(frames);
}

void nfapi_crc_indication_pdu_deinit(NFAPI_CRC_INDICATION_PDU_T* crc_pdu_frames, int n) {
    free(crc_pdu_frames);
}

int main() {
    NFAPI_RX_FRAME_T* frames = nfapi_rx_frame_init(10);
    if (!frames) return -1;
    for (NFAPI_RX_FRAME_T frame : frames) {
        printf("RRC RX Frame Tag: %d, SNR: %.2f\n", frame.rrc_rx_frame_tag, frame.snr);
    }
    nfapi_rx_frame_deinit(frames, 10);

    NFAPI_CRC_INDICATION_PDU_T* crc_pdu_frames = nfapi_crc_indication_pdu_init(5);
    if (!crc_pdu_frames) return -1;
    for (NFAPI_CRC_INDICATION_PDU_T crc_pdu_frame : crc_pdu_frames) {
        printf("RX UE Information Tag: %d, RNTI: %d, CRC Indication Rel8 Tag: %d\n", crc_pdu_frame.rx_ue_information_tag, crc_pdu_frame.rnti, crc_pdu_frame.crc_indication_rel8_tag);
    }
    nfapi_crc_indication_pdu_deinit(crc_pdu_frames, 5);

    return 0;
}
