#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/shm.h>
#include <sys/ipc.h>
#include <unistd.h>

#define MAX_COLLECTION_SIZE 1024
#define SHM_KEY 0x12345678
#define SHM_PERMISSIONS (IPC_CREAT | IPC_EXCL | S_IRUSR | S_IWUSR)
#define CRCFLAG_VALIDATION 0x01

typedef struct {
    RX_UE_INFORMATION_TAG;
    RNTI;
    CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    RRC_RX_FRAME_TAG;
    char* RX_STREAM_TAG;
    double SNR;
} NFAPI_RX_FRAME_T;

void* custom_allocator(size_t size) {
    return malloc(size);
}

void custom_deallocator(void* ptr) {
    free(ptr);
}

int main() {
    // Initialize collections
    NFAPI_CRC_INDICATION_PDU_T** crc_indications = (NFAPI_CRC_INDICATION_PDU_T**)custom_allocator(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * MAX_COLLECTION_SIZE);
    NFAPI_RX_FRAME_T* rx_frames = (NFAPI_RX_FRAME_T*)custom_allocator(sizeof(NFAPI_RX_FRAME_T) * MAX_COLLECTION_SIZE);

    // Initialize shared memory segment
    int shm_id = shmget(SHM_KEY, sizeof(int), SHM_PERMISSIONS);
    void* shm_addr = shmat(shm_id, NULL, 0);
    if (shm_addr == (void*)-1) {
        perror("shmat");
        exit(EXIT_FAILURE);
