char *trim_string(char *str, int size_limit, int trim) {
    if (!str || strlen(str) > size_limit) {
        // Handle null pointer and buffer overflow
        return NULL;
    }

    char *trimmed = NULL;
    if (strlen(str) <= size_limit && !trim) {
        // Append slash to the end
        trimmed = malloc(size_limit + 2);
        strcpy(trimmed, str);
        strcat(trimmed, "/");
    } else if (strlen(str) > size_limit && trim) {
        // Truncate the string to fit within the limit
        trimmed = malloc(size_limit + 1);
        strncpy(trimmed, str, size_limit);
        trimmed[size_limit] = '\0';
    }

    // Log the length of the input string and action taken
    if (trimmed) {
        printf("Length: %d, Action: %s\n", strlen(str), trimmed);
    } else {
        printf("String exceeds limit, returning NULL\n");
    }

    return trimmed;
}
