    return 0;
}

int phy_channel_statistics_export(PHY_CHANNEL_STATISTICS_T *statistics, size_t size) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080); // change the port number as needed
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    for (size_t i = 0; i < size; i++) {
        if (statistics[i].snr >= SNR_THRESHOLD) {
            char buffer[1024];
            sprintf(buffer, "{\"timestamp\": %"PRItime_t", \"rb_id\": %d, \"snr\": %.2f}", statistics[i].timestamp, statistics[i].rb_id, statistics[i].snr);

            sendto(sock, buffer, strlen(buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        }
    }

    close(sock);

    return 0;
}

int phy_channel_statistics_filter_and_export(PHY_CHANNEL_STATISTICS_T **statistics, size_t *size) {
    for (size_t i = 0; i < *size; i++) {
        if (statistics[i]->snr < SNR_THRESHOLD) {
            memmove(&((*statistics)[i]), &((*statistics)[i + 1]), (*size - i - 1) * sizeof(PHY_CHANNEL_STATISTICS_T));
            (*size]--;
            i--;
        }
    }

    phy_channel_statistics_export(*statistics, *size);

    return 0;
}

int main() {
    PHY_CHANNEL_STATISTICS_T *statistics = NULL;
    size_t statistics_size = 0;

    phy_channel_statistics_init(&statistics, &statistics_size);

    for (int i = 0; i < 10; i++) {
        PHY_CHANNEL_STATISTICS_T statistic;
        statistic.timestamp = time(NULL) + i;
        statistic.rb_id = i;
        statistic.snr = -i * 2.0;

        phy_channel_statistics_add(&statistics, &statistics_size, &statistic);
    }

    for (int i = 0; i < 10; i++) {
        sleep(EXPORT_INTERVAL); // simulate processing time

        phy_channel_statistics_filter_and_export(&statistics, &statistics_size);
    }

    return 0;
}

