void initialize_and_configure(int num_frames, int** frames_array) {
    RRC_RX_FRAME_T* frames = (RRC_RX_FRAME_T*)malloc(num_frames * sizeof(RRC_RX_FRAME_T));

    for (int i = 0; i < num_frames; i++) {
        frames[i].unique_tag = i;
        frames[i].rx_stream_tag = (char*)malloc(16);
        sprintf(frames[i].rx_stream_tag, "RX_STREAM_TAG_%d", i);
        frames[i].snr = (float)rand() / RAND_MAX;
    }

    // Create list of RRC_RX_HEADER_T structures
    int num_headers = 5;
    RRC_RX_HEADER_T* headers = (RRC_RX_HEADER_T*)malloc(num_headers * sizeof(RRC_RX_HEADER_T));

    for (int i = 0; i < num_headers; i++) {
        headers[i].ue_info_tag = i;
        headers[i].rai = i % 10;
        char header_tag[16];
        sprintf(header_tag, "RX_HEADER_TAG_%d", i);
        headers[i].rx_header_tag = (char*)malloc(16);
        strcpy(headers[i].rx_header_tag, header_tag);
    }

    *frames_array = frames;
}

int main() {
    int num_frames = 10;
    RRC_RX_FRAME_T* frames_array;
    initialize_and_configure(num_frames, &frames_array);

    // Process frames and headers
    for (int i = 0; i < num_frames; i++) {
        printf("Frame %d: SNR = %.2f\n", frames[i].unique_tag, frames[i].snr);

        RRC_RX_HEADER_T* header = &headers[frames[i].unique_tag % num_headers];
        printf("Header for Frame %d: UE Info Tag = %d, RAI = %d, Header Tag = %s\n",
               frames[i].unique_tag, header->ue_info_tag, header->rai, header->rx_header_tag);

        free(frames[i].rx_stream_tag);
    }

    // Free allocated memory
    for (int i = 0; i < num_frames; i++) {
        free(frames[i].rx_stream_tag);
    }
    free(frames);
    for (int i = 0; i < num_headers; i++) {
        free(headers[i].rx_header_tag);
    }
    free(headers);

    return 0;
}
