#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>

struct LTE_PHY_MEASUREMENTS {
    int timestamp;
    int cellID;
    std::vector<int> RSSI;
};

const int M = 10;

std::vector<LTE_PHY_MEASUREMENTS> measurements(M);

std::mutex mtx;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(10, 20);
int serviceStarts = 0;

void startService() {
    while (true) {
        std::this_thread::sleep_for(std::chrono::milliseconds((int)(dis(gen))));
        if (serviceStarts >= 10)
            break;
        {
            std::lock_guard<std::mutex> lock(mtx);
            for (LTE_PHY_MEASUREMENTS &measurement : measurements) {
                measurement.timestamp = gen();
                measurement.cellID = gen() % 1000;
                measurement.RSSI.resize(5, gen() % 20 - 10);
            }
        }
        std::this_thread::sleep_for(std::chrono::milliseconds((int)(dis(gen))));
    }
}

void stopService(int windowSize) {
    int sumRssi[5] = {0};
    while (true) {
        for (LTE_PHY_MEASUREMENTS &measurement : measurements) {
            for (int i = 0; i < measurement.RSSI.size(); ++i) {
                sumRssi[i] += measurement.RSSI[i];
            }
        }
        if (serviceStarts >= 10)
            break;
        std::this_thread::sleep_for(std::chrono::milliseconds(windowSize * 1000));
    }
    for (int i = 0; i < 5; ++i) {
        double averageRssi = static_cast<double>(sumRssi[i]) / (windowSize * serviceStarts);
        // Log the average RSSI
        std::cout << "Average RSSI for channel " << i << ": " << averageRssi << std::endl;
    }
}

int main() {
    std::thread serviceThread(startService);
    std::thread loggingThread(stopService, 5);

    serviceThread.join();
    loggingThread.join();

    return 0;
}
