    UEStats* ueStatsArray[numComputeNodes];
    for (int i = 0; i < numComputeNodes; i++) {
        ueStatsArray[i] = malloc(sizeof(UEStats) * UE_STATS_MAX / numComputeNodes);
    }

    // Periodically synchronize UEStats arrays across compute nodes
    for (int i = 0; i < numComputeNodes; i++) {
        UEStats* ueStatsEntry;
        // Synchronize UEStats entries and update lastUpdated timestamps
    }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    initLTEPHYControlPDU(argv[1]);

    manageUEStats();

