typedef struct LTEPHY_CONTROL_PDU {
    int RNTI;
    char *dl_transport_channel_config;
    char *power_control_settings[3];
} LTEPHY_CONTROL_PDU;

void init_LTEPHY_CONTROL_PDU(LTEPHY_CONTROL_PDU **pdus, int *num_pdus) {
    // Initialize the dynamic array of PDUs
    *num_pdus = 0;
    *pdus = (LTEPHY_CONTROL_PDU *)malloc(sizeof(LTEPHY_CONTROL_PDU));
}

int load_config_from_json(const char *json_file, LTEPHY_CONTROL_PDU **pdus, int *num_pdus) {
    json_object *config = json_object_from_file(json_file);
    if (!config) return -1;

    // Parse the JSON config and allocate memory for PDUs
    int num_entries = json_object_get_int(config, "num_entries");
    *num_pdus = num_entries;
    *pdus = (LTEPHY_CONTROL_PDU *)realloc(*pdus, sizeof(LTEPHY_CONTROL_PDU) * num_entries);

    // Loop through each entry and initialize PDU structs
    for (int i = 0; i < num_entries; i++) {
        json_object *entry = json_object_get_object(config, "entries", i);
        if (!entry) continue;

        LTEPHY_CONTROL_PDU *pdu = &(*pdus)[i];
        pdu->RNTI = json_object_get_int(entry, "RNTI");
        pdu->dl_transport_channel_config = (char *)malloc(strlen(json_object_get_string(entry, "dl_transport_channel_config")) + 1);
        strcpy(pdu->dl_transport_channel_config, json_object_get_string(entry, "dl_transport_channel_config"));
        pdu->power_control_settings[0] = (char *)malloc(strlen(json_object_get_string(entry, "power_control_settings[0]")) + 1);
        strcpy(pdu->power_control_settings[0], json_object_get_string(entry, "power_control_settings[0]"));
        pdu->power_control_settings[1] = (char *)malloc(strlen(json_object_get_string(entry, "power_control_settings[1]")) + 1);
        strcpy(pdu->power_control_settings[1], json_object_get_string(entry, "power_control_settings[1]"));
        pdu->power_control_settings[2] = (char *)malloc(strlen(json_object_get_string(entry, "power_control_settings[2]")) + 1);
        strcpy(pdu->power_control_settings[2], json_object_get_string(entry, "power_control_settings[2]"));
    }

    return 0;
}

void free_LTEPHY_CONTROL_PDU(LTEPHY_CONTROL_PDU **pdus, int *num_pdus) {
    for (int i = 0; i < *num_pdus; i++) {
        free((*pdus)[i].dl_transport_channel_config);
        free((*pdus)[i].power_control_settings[0]);
        free((*pdus)[i].power_control_settings[1]);
        free((*pdus)[i].power_control_settings[2]);
    }
    free(*pdus);
}

int main() {
    int num_pdus;
    LTEPHY_CONTROL_PDU *pdus;

    init_LTEPHY_CONTROL_PDU(&pdus, &num_pdus);

    if (load_config_from_json("config.json", &pdus, &num_pdus) != 0) {
        printf("Error loading config from JSON file\n");
    } else {
        // Process the configured PDUs
        for (int i = 0; i < num_pdus; i++) {
            printf("PDU %d: RNTI=%d, dl_transport_channel_config='%s', power_control_settings=['%s', '%s', '%s']\n",
                   i, pdus[i].RNTI, pdus[i].dl_transport_channel_config,
                   pdus[i].power_control_settings[0], pdus[i].power_control_settings[1], pdus[i].power_control_settings[2]);
        }
    }

    free_LTEPHY_CONTROL_PDU(&pdus, &num_pdus);

    return 0;
}
