typedef struct {
    int RNTI;
    char dlChan[50];
    float powerControl;
} LTEPHY_CONTROL_PDU;

void initLTEPHYCTRL(json_object *config) {
    json_object_iter iter;
    json_object_iter_tmp tmp_iter;
    int numPDUs = 0;

    // Parse config file
    while (json_object_iter_init(&iter, config)) {
        if (!strcmp("RNTI", json_object_iter_key(&iter))) {
            numPDUs = json_object_get_int(iter.value);
        } else if (!strcmp("dlChanConfig", json_object_iter_key(&iter))) {
            for (tmp_iter = iter; tmp_iter; tmp_iter = json_object_iter_next(tmp_iter)) {
                if (!strcmp("transportChannel", json_object_iter_key(&tmp_iter))) {
                    // Validate and store transport channel config
                    char* dlChan = malloc(50);
                    strcpy(dlChan, json_object_get_string(tmp_iter.value));
                    // Store in PDU structure
                    LTEPHY_CONTROL_PDU* pdus = (LTEPHY_CONTROL_PDU*)malloc(numPDUs * sizeof(LTEPHY_CONTROL_PDU));
                    for (int i = 0; i < numPDUs; i++) {
                        pdus[i].RNTI = json_object_get_int(config_object_iter_value(&iter));
                        strcpy(pdus[i].dlChan, dlChan);
                        pdus[i].powerControl = json_object_get_double(config_object_iter_value(&tmp_iter));
                    }
                    // Initialize and configure PDU structures
                    for (int i = 0; i < numPDUs; i++) {
                        // Validate and store power control settings
                        if (pdus[i].powerControl > 1.0 || pdus[i].powerControl < 0.0) {
                            printf("Power Control out of range: %f\n", pdus[i].powerControl);
                        }
                    }
                } else {
                    printf("Invalid config key: %s\n", json_object_iter_key(&tmp_iter));
                }
            }
        }
    }

    free(pdus);
}
