NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int n, pthread_mutex_t *mutex) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc((n+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        srand(time(NULL)); // generate random seed
        pdu->RX_UE_INFORMATION_TAG = rand() % 256;
        pdu->RNTI = rand() % 1024;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 16;
        int crcflag = (rand() % 2) << 1 | (rand() % 2);
        if (crcflag != 0 && crcflag != 3) {
            free(list); return NULL; // invalid CRCFLAG combination
        }
        pdu->CRCFLAG = crcflag;
    }

    pthread_mutex_lock(mutex);
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];
        if (!pdu) return NULL; // error allocating memory
    }
    pthread_mutex_unlock(mutex);

    return list;
}
