typedef struct {
    int id;
    char ip[16];
    int port;
} TCPConnection;

typedef struct {
    TCPConnection* connections;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} TCPCollection;

TCPCollection* tcpcollection_create() {
    TCPCollection* collection = (TCPCollection*)malloc(sizeof(TCPCollection));
    collection->connections = NULL;
    collection->size = 0;
    collection->capacity = 4; // initial capacity
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

void tcpcollection_add(TCPCollection* collection, TCPConnection* connection) {
    if (collection->size >= collection->capacity) {
        collection->connections = (TCPConnection*)realloc(collection->connections,
                sizeof(TCPConnection) * (collection->capacity *= 2));
    }
    memcpy(&collection->connections[collection->size], connection, sizeof(TCPConnection));
    collection->size++;
}

void tcpcollection_remove(TCPCollection* collection, int id) {
    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].id == id) {
            memmove(&collection->connections[i], &collection->connections[i + 1],
                    sizeof(TCPConnection) * (collection->size - i - 1));
            collection->size--;
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
}

TCPConnection* tcpcollection_get_by_id(TCPCollection* collection, int id) {
    pthread_mutex_lock(&collection->mutex);
    TCPConnection* result = NULL;
    for (int i = 0; i < collection->size; i++) {
        if (collection->connections[i].id == id) {
            result = &collection->connections[i];
            break;
        }
    }
    pthread_mutex_unlock(&collection->mutex);
    return result;
}

void tcpcollection_destroy(TCPCollection* collection) {
    free(collection->connections);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
