// Structure representing a TCP Connection
typedef struct {
    int id;
    char remote_ip[16];
    int port;
    int is_busy;
} tcp_connection;

// Dynamic array of TCP connections
tcp_connection** connection_pool = NULL;
int connection_pool_size = 0;
int max_connections = 1000000; // Default maximum connections

// Statistics for active, busy, and inactive connections
int active_connections = 0;
int busy_connections = 0;
int inactive_connections = 0;

// Inactivity timeout in seconds
int inactivity_timeout = 60; // Default inactivity timeout

// Connection-pooling mechanism flags
int connection_pool_enabled = 1;
int reuse_idle_connections = 1;

// Throttling mechanism flags
int throttling_enabled = 1;
int max_new_connections_per_second = 100;

// Duplicate connection detection hash table
unsigned int* duplicate_connection_map = NULL;
int duplicate_connection_map_size = 0;

void initialize_connection_pool() {
    // Initialize the dynamic array of TCP connections
    connection_pool = (tcp_connection**)malloc(max_connections * sizeof(tcp_connection*));
    connection_pool_size = 0;
}

void add_new_connection(int id, char* remote_ip, int port) {
    // Create a new TCP connection structure and initialize its fields
    tcp_connection* new_conn = (tcp_connection*)malloc(sizeof(tcp_connection));
    new_conn->id = id;
    strcpy(new_conn->remote_ip, remote_ip);
    new_conn->port = port;
    new_conn->is_busy = 0;

    // Add the new connection to the dynamic array and update statistics
    if (connection_pool_size < max_connections) {
        connection_pool[connection_pool_size] = new_conn;
        active_connections++;
        connection_pool_size++;
    } else {
        printf("Connection pool is full. Cannot add new connections.\n");
    }
}

void remove_connection(int id) {
    // Find the TCP connection with the given ID
    for (int i = 0; i < connection_pool_size; i++) {
        if (connection_pool[i]->id == id) {
            // Mark the connection as inactive and update statistics
            connection_pool[i]->is_busy = 2;
            inactive_connections++;
            break;
        }
    }
}

tcp_connection* get_connection(int id) {
    // Find the TCP connection with the given ID
    for (int i = 0; i < connection_pool_size; i++) {
        if (connection_pool[i]->id == id) {
            return connection_pool[i];
        }
    }
    return NULL;
}

void periodic_cleanup() {
    // Periodically clean up inactive connections based on inactivity timeout
    for (int i = 0; i < connection_pool_size; i++) {
        if (connection_pool[i]->is_busy == 2) {
            // Remove the inactive connection and update statistics
            free(connection_pool[i]);
            connection_pool[i] = NULL;
            inactive_connections--;
        }
    }
}

void set_inactivity_timeout(int timeout) {
    inactivity_timeout = timeout;
}

