#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

// Structure for TCP Connection
typedef struct {
    int id;
    char remote_ip[16];
    uint16_t port;
    int is_busy;
} TCPConnection;

// Dynamic array of TCP Connections
TCPConnection **connections = NULL;
int num_connections = 0;

// Inactivity timeout in seconds
int inactivity_timeout = 60;

// Function to handle HTTP POST requests
void HandleHTTPPostRequest(int page_section_id, char* element_id, char* html_content) {
    // Update the element's HTML content using a service class
    update_element_html(html_content);

    // Indicate that the page should be refreshed in the response
    printf("Page should be refreshed.\n");
}

// Function to add a new TCP Connection
int AddTCPConnection(int id, char* remote_ip, uint16_t port) {
    TCPConnection *new_connection = (TCPConnection*)malloc(sizeof(TCPConnection));
    new_connection->id = id;
    strcpy(new_connection->remote_ip, remote_ip);
    new_connection->port = port;
    new_connection->is_busy = 0;

    // Add the new connection to the dynamic array
    connections[num_connections] = new_connection;
    num_connections++;

    return 1; // Successful addition
}

// Function to remove a TCP Connection by ID
int RemoveTCPConnection(int id) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->id == id) {
            free(connections[i]);
            memmove(&connections[i], &connections[i + 1], sizeof(TCPConnection*) * (num_connections - i - 1));
            num_connections--;
            return 1; // Successful removal
        }
    }

    return 0; // Not found
}

// Function to get a TCP Connection by ID
TCPConnection* GetTCPConnection(int id) {
    for (int i = 0; i < num_connections; i++) {
        if (connections[i]->id == id) {
            return connections[i];
        }
    }

    return NULL; // Not found
}

// Function to periodically clean up inactive connections
void CleanUpConnections() {
    for (int i = 0; i < num_connections; i++) {
        TCPConnection *connection = connections[i];

        if (!connection->is_busy && time(NULL) - connection->last_active > inactivity_timeout) {
            RemoveTCPConnection(connection->id);
            i--;
            num_connections--;
        }
    }
}

// Function to mark a connection as "busy"
void MarkBusy(int id) {
