    TCPConnection* connections;
    int inactivity_timeout; // seconds
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    bool is_shutdown;
} ConnectionManager;

// Function to initialize and manage the dynamic array of TCP Connections
void* connection_manager_init(int capacity, int inactivity_timeout) {
    ConnectionManager* manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));

    // Initialize attributes
    manager->size = 0;
    manager->capacity = capacity;
    manager->connections = (TCPConnection*)malloc(capacity * sizeof(TCPConnection));
    manager->inactivity_timeout = inactivity_timeout;
    pthread_mutex_init(&manager->mutex, NULL);
    pthread_cond_init(&manager->cond, NULL);
    manager->is_shutdown = false;

    return manager;
}

// Function to add a new TCP Connection
void connection_manager_add(ConnectionManager* manager, int connection_id, char* remote_ip, int port_number) {
    if (manager == NULL || connection_id < 0 || strlen(remote_ip) > 15) {
        return;
    }

    pthread_mutex_lock(&manager->mutex);

    // Check if the array needs resizing
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->connections = (TCPConnection*)realloc(manager->connections, manager->capacity * sizeof(TCPConnection));
    }

    // Add new connection
    TCPConnection* new_conn = &manager->connections[manager->size++];
    new_conn->connection_id = connection_id;
    strcpy(new_conn->remote_ip, remote_ip);
    new_conn->port_number = port_number;

    pthread_mutex_unlock(&manager->mutex);
}

// Function to remove a TCP Connection by ID
void connection_manager_remove(ConnectionManager* manager, int connection_id) {
    if (manager == NULL || connection_id < 0) {
        return;
    }

    pthread_mutex_lock(&manager->mutex);

    // Find and remove the connection with the specified ID
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i].connection_id == connection_id) {
            // Update connections array without shifting elements
            for (int j = i + 1; j < manager->size; j++) {
                manager->connections[j - 1] = manager->connections[j];
            }
            manager->size--;
            break;
        }
    }

    pthread_mutex_unlock(&manager->mutex);
}

// Function to retrieve connection details by ID
TCPConnection* connection_manager_get(ConnectionManager* manager, int connection_id) {
    if (manager == NULL || connection_id < 0) {
        return NULL;
    }

    pthread_mutex_lock(&manager->mutex);

    // Find the connection with the specified ID
    for (int i = 0; i < manager->size; i++) {
        if (manager->connections[i].connection_id == connection_id) {
            TCPConnection* conn = &manager->connections[i];
            pthread_mutex_unlock(&manager->mutex);
            return conn;
        }
    }

    pthread_mutex_unlock(&manager->mutex);

    return NULL;
}

