void* create_and_populate_linked_list(int num_elements) {
    // Initialize the head of the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    for (int i = 0; i < num_elements; i++) {
        // Allocate memory for each structure
        NFAPI_CRC_INDICATION_PDU_T* new_element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
