        new_element->rx_ue_info.field1 = i;
        new_element->rnti = i;

        // Add the new element to the linked list
        new_element->next = NULL;
        if (!head) {
            head = new_element;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_element;
