    request_pool[pool_size++] = req;
    active_requests++;
    pthread_mutex_unlock(&mutex);
}

// Function to update an existing request by ID
void update_request(int id, int status_code) {
    for (int i = 0; i < pool_size; i++) {
        if (request_pool[i]->id == id) {
            request_pool[i]->status_code = status_code;
            break;
        }
    }
}

// Function to retrieve request details by ID
HttpRequest* get_request(int id) {
    for (int i = 0; i < pool_size; i++) {
        if (request_pool[i]->id == id) {
            return request_pool[i];
        }
    }
    return NULL;
}

// Function to clean up stale requests based on inactivity timeout
void clean_up_stale_requests() {
    int i, j = 0;
    for (i = 0; i < pool_size; i++) {
        HttpRequest* req = request_pool[i];
        if ((time(NULL) - req->last_modified) > inactivity_timeout) {
            // Update stats
            active_requests--;
            completed_requests++;

            // Move the stale request to the end of the array
            request_pool[j++] = req;
        }
    }

    pool_size -= (pool_size - j);
    request_pool += j;
}

// Function to batch update requests based on filter criteria
void batch_update_requests(char* filter) {
    int i, j = 0;
    for (i = 0; i < pool_size; i++) {
        HttpRequest* req = request_pool[i];
        if (filter_matches(filter, req)) {
            // Update the request
            req->status_code = new_status_code;

            // Move the updated request to the front of the array
            request_pool[j++] = req;
        }
    }

    pool_size -= (pool_size - j);
    request_pool += j;
}

// Function to log request events with timestamps and details
void log_request_event(int id, char* client_ip, int status_code) {
    // Log the event using an external logging system
}

int main() {
    init_request_pool();

    // Add some requests
    add_request(1, "192.168.1.100", "GET", "/index.html", 200);
    add_request(2, "192.168.1.101", "POST", "/login", 201);

    // Update a request
    update_request(1, 301);

    // Get the details of a request
    HttpRequest* req = get_request(2);
    printf("%d - %s\n", req->id, req->url);

    // Clean up stale requests
    clean_up_stale_requests();

    // Batch update requests based on filter criteria
    char* filter = "status_code = 200";
    batch_update_requests(filter);

    return 0;
}
