#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_CONNECTIONS 1000000
#define INACTIVITY_TIMEOUT 300 // seconds
#define BUSY_THRESHOLD 50 // seconds
#define CONNECTION_STATS_INTERVAL 60 // seconds

typedef struct {
    int id;
    char remote_ip[16];
    unsigned short port;
    int busy;
    time_t last_active;
} TcpConnection;

typedef struct {
    TcpConnection* connections;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionManager;

void connection_init(ConnectionManager* cm) {
    cm->connections = (TcpConnection*)malloc(sizeof(TcpConnection)*MAX_CONNECTIONS);
    cm->size = 0;
    pthread_mutex_init(&cm->lock, NULL);
    pthread_cond_init(&cm->cond, NULL);
}

int add_connection(ConnectionManager* cm, int id, const char* remote_ip, unsigned short port) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if (!cm->connections[i].id) {
            memcpy(&cm->connections[i], &(TcpConnection){.id=id, .remote_ip=remote_ip, .port=port, .busy=0}, sizeof(TcpConnection));
            cm->connections[i].last_active = time(NULL);
            cm->size++;
            pthread_cond_signal(&cm->cond);
            pthread_mutex_unlock(&cm->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cm->lock);
    return 0;
}

int remove_connection(ConnectionManager* cm, int id) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if (cm->connections[i].id == id) {
            memset(&cm->connections[i], 0, sizeof(TcpConnection));
            memmove(&cm->connections[i], &cm->connections[i+1], (cm->size-i)*sizeof(TcpConnection));
            cm->size--;
            pthread_cond_signal(&cm->cond);
            pthread_mutex_unlock(&cm->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cm->lock);
    return 0;
}

int mark_connection_busy(ConnectionManager* cm, int id) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if (cm->connections[i].id == id) {
            cm->connections[i].busy = 1;
            cm->connections[i].last_active = time(NULL);
            pthread_cond_signal(&cm->cond);
            pthread_mutex_unlock(&cm->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cm->lock);
    return 0;
}

int get_connection(ConnectionManager* cm, int id) {
    pthread_mutex_lock(&cm->lock);
    for (int i = 0; i < cm->size; i++) {
        if (cm->connections[i].id == id) {
            // Return connection details
            pthread_mutex_unlock(&cm->lock);
            return 1;
        }
    }
    pthread_mutex_unlock(&cm->lock);
    return 0;
}

void cleanup_inactive_connections(ConnectionManager* cm) {
    time_t now = time(NULL);
    for (int i = 0; i < cm->size; i++) {
        if ((now - cm->connections[i].last_active) > INACTIVITY_TIMEOUT) {
            remove_connection(cm, cm->connections[i].id);
        }
    }
}

void connection_stats(ConnectionManager* cm) {
    int active = 0;
    int busy = 0;
    for (int i = 0; i < cm->size; i++) {
        if (!cm->connections[i].busy && cm->connections[i].id) active++;
        else if (cm->connections[i].busy) busy++;
    }
    // Log connection stats
}

void* thread_loop(void* arg) {
    ConnectionManager* cm = (ConnectionManager*)arg;
    while(1) {
        pthread_mutex_lock(&cm->lock);
        for (int i = 0; i < cm->size; i++) {
            if (!cm->connections[i].busy && cm->connections[i].id) {
                // Process connection
                cm->connections[i].last_active = time(NULL);
            }
        }
        pthread_cond_wait(&cm->cond, &cm->lock);
        pthread_mutex_unlock(&cm->lock);
    }
}

void connection_manager_start(ConnectionManager* cm) {
    pthread_t threads[MAX_CONNECTIONS];
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        pthread_create(&threads[i], NULL, thread_loop, cm);
    }
}
