        // Allocate memory for dynamic collection of LTEPHY CONTROL PDU structures
        LTEPDU **pdus = (LTEPDU **)malloc(pdu_count * sizeof(LTEPDU *));

        // Iterate through configuration source and populate pdus array
        for (int i = 0; i < pdu_count; i++) {
            json_object *pdu_config = json_object_array_get_idx(json_pdu_list, i);

            if (json_object_object_get_ex(pdu_config, "RNTI", &json_rnti) != NULL) {
                int rnti = json_object_get_int(json_rnti);

                if (json_object_object_get_ex(pdu_config, "dl_transport", &json_dl_transport) != NULL) {
                    char *dl_transport_config = json_object_get_string(json_dl_transport);

