import yaml
from cryptography.fernet import Fernet

class NetworkDeviceConfig:
    def __init__(self, filename):
        self.filename = filename
        self.configs = self.read_configs()

    def read_configs(self):
        try:
            with open(self.filename, 'r') as file:
                return yaml.safe_load(file)
        except FileNotFoundError:
            return {}

    def write_config(self, device_id, config):
        self.configs[device_id] = config
        with open(self.filename, 'w') as file:
            yaml.dump(self.configs, file)

    def encrypt_config(self, device_id, config):
        key = Fernet.generate_key()
        cipher_text = Fernet(key).encrypt(config.encode())
        return cipher_text

    def decrypt_config(self, device_id, config):
        key = Fernet.generate_key()
        plain_text = Fernet(key).decrypt(config)
        return plain_text.decode()

    def rollback_config(self, device_id):
        try:
            with open(self.filename + '.rollback', 'r') as file:
                self.configs[device_id] = yaml.safe_load(file)
        except FileNotFoundError:
            pass

# Example usage
