    cJSON *pdu;
    for (int i = 0; i < cJSON_GetArraySize(pdu_list); i++) {
        pdu = cJSON_GetArrayItem(pdu_list, i);
        if (!pdu) continue;
        // Validate RNTI, downlink transport channel configuration parameters, and power control settings
        int rnti = cJSON_GetIntValue(cJSON_GetObjectItem(pdu, "RNTI"));
        int dl_transport_channel_config = cJSON_GetIntValue(cJSON_GetObjectItem(pdu, "DownlinkTransportChannelConfig"));
        int power_control_settings = cJSON_GetIntValue(cJSON_GetObjectItem(pdu, "PowerControlSettings"));

        // Allocate memory for new PDU structure
        struct LTEPHY_CONTROL_PDU *new_pdu = (struct LTEPHY_CONTROL_PDU *)malloc(sizeof(struct LTEPHY_CONTROL_PDU));
        if (!new_pdu) {
            printf("Error: unable to allocate memory for PDU\n");
            return;
        }

        // Initialize PDU structure fields
        new_pdu->rnti = rnti;
        new_pdu->downlink_transport_channel_config = dl_transport_channel_config;
        new_pdu->power_control_settings = power_control_settings;

        // Add new PDU to collection
        if (!*pdu) {
            *pdu = new_pdu;
            num_pdu_config++;
        } else {
            struct LTEPHY_CONTROL_PDU *temp = *pdu;
            while (temp->next) temp = temp->next;
            temp->next = new_pdu;
            new_pdu = NULL; // Mark as already added
        }
    }

    fclose(file);

    // Update local copy of configuration
    if (*num_pdu) free(*num_pdu);
    *pdu = new_pdu;
