void init_ltephy_pdu_collection(int *pdu_count, LTEPHY_CONTROL_PDU **pdu_array) {
    json_object *config = json_object_from_file("config.json");
    if (!config) {
        printf("Error loading configuration file\n");
        return;
    }

    // Initialize the PDU array with a default size
    *pdu_count = 0;
    *pdu_array = (LTEPHY_CONTROL_PDU *)malloc(sizeof(LTEPHY_CONTROL_PDU) * 10);
    for (int i = 0; i < 10; i++) {
        (*pdu_array)[i].RNTI = -1; // Initialize with invalid RNTI value
    }

    // Loop through the configuration data and populate the PDU array
    json_object_iter *iter;
    json_object_iter_init(config, NULL);
    while ((iter = json_object_iterate(config))) {
        const char *key = iter->key;
        if (strcmp(key, "RNTI") == 0) {
            int rnti = json_object_get_int(iter->value);
            (*pdu_array)[(*pdu_count)].RNTI = rnti;
        } else if (strcmp(key, "dl_transport_channel") == 0) {
            const char *channel = json_object_get_string(iter->value);
            strcpy((*pdu_array)[(*pdu_count)].dl_transport_channel, channel);
        } else if (strcmp(key, "power_control_settings") == 0) {
            double settings[4];
            for (int i = 0; i < 4; i++) {
                settings[i] = json_object_get_double(iter->value);
            }
            memcpy((*pdu_array)[(*pdu_count)].power_control_settings, settings, sizeof(double) * 4);
        }
        (*pdu_count)++;
