    // power control settings for various modulation schemes
    int PWR_A;
    int PWR_B;
    int PWR_C;
} LTEPHYCONTROLPDU;

void* ltephy_pdu_init(size_t count) {
    void *pdu = malloc(count * sizeof(LTEPHYCONTROLPDU));
    if (!pdu) {
        return NULL;
    }
    memset(pdu, 0, count * sizeof(LTEPHYCONTROLPDU));
    return pdu;
}

void ltephy_pdu_free(void *pdu) {
    free(pdu);
}

int ltephy_pdu_load_json_file(const char *filename, void **pdu, size_t *count) {
    json_object *root = NULL;
    json_object *json_pdu = NULL;
    int rnti = 0;
    int tbs = 0;
    int mcs = 0;
    int nlp = 0;
    int nss = 0;
    int pwr_a = 0;
    int pwr_b = 0;
    int pwr_c = 0;

    FILE *file = fopen(filename, "r");
    if (!file) {
        return -1; // error opening file
    }

    root = json_object_from_file(file);
    fclose(file);

    if (!root) {
        return -2; // error parsing JSON
    }

    for (json_object_iterator it = json_object_iterate(root); it; it = json_object_iterate(root)) {
        json_object *json_pdu_obj = it->value;
        rnti = json_object_get_int(json_pdu_obj, "RNTI");
        tbs = json_object_get_int(json_pdu_obj, "TBS");
        mcs = json_object_get_int(json_pdu_obj, "MCS");
        nlp = json_object_get_int(json_pdu_obj, "NLP");
        nss = json_object_get_int(json_pdu_obj, "NSS");
        pwr_a = json_object_get_int(json_pdu_obj, "PWR_A");
        pwr_b = json_object_get_int(json_pdu_obj, "PWR_B");
        pwr_c = json_object_get_int(json_pdu_obj, "PWR_C");

        // check if pdu is valid
        if (rnti < 0 || tbs < 0 || mcs < 0 || nlp < 0 || nss < 0 || pwr_a < 0 || pwr_b < 0 || pwr_c < 0) {
            printf("Invalid PDU configuration: %s\n", json_object_to_json_string(json_pdu_obj));
            continue;
        }

        // add pdu to the collection
        *pdu = realloc(*pdu, (*count + 1) * sizeof(LTEPHYCONTROLPDU));
        if (!*pdu) {
            return -3; // out of memory
        }
        ((LTEPHYCONTROLPDU *)*pdu)[*count] = (LTEPHYCONTROLPDU){rnti, tbs, mcs, nlp, nss, pwr_a, pwr_b, pwr_c};
        (*count)++;
    }

    json_object_free(root);
    return 0;
}

int main() {
    void *pdu = NULL;
    size_t count = 0;

    ltephy_pdu_init(10);

    if (ltephy_pdu_load_json_file("config.json", &pdu, &count) < 0) {
        printf("Error loading configuration\n");
        return -1;
    }

    // use pdu data here...

    ltephy_pdu_free(pdu);
    return 0;
}
