    json_object* root = json_object_from_file(filename);
    if (!root) return NULL;

    json_object_iter* iter;
    json_object_iter_init(&iter, root);
    while (json_object_iter_has_next(&iter)) {
        json_object* pdu_obj = json_object_iter_value(&iter);

        LTEPHY_CONTROL_PDU* pdu = (LTEPHY_CONTROL_PDU*)malloc(sizeof(LTEPHY_CONTROL_PDU));
        if (!pdu) return NULL;

        int RNTI = json_object_get_int(pdu_obj, "RNTI");
        pdu->RNTI = RNTI;

        const char* downlink_transport_channel_config = json_object_get_string(pdu_obj, "downlink_transport_channel_config");
        strcpy(pdu->downlink_transport_channel_config, downlink_transport_channel_config);

        const char* power_control_settings = json_object_get_string(pdu_obj, "power_control_settings");
        strcpy(pdu->power_control_settings, power_control_settings);

        free(pdu_obj);
    }

    *pdu_count = json_object_get_array_size(root);
    return root;
}

