#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* trim_or_truncate_string(const char* str, int size_limit, int trim) {
    if (!str) return NULL;

    int len = strlen(str);
    if (len <= size_limit) {
        char* result = (char*)malloc((len + 2) * sizeof(char));
        strcpy(result, str);
        strcat(result, "/");
        return result;
    }

    if (trim) {
        char* result = (char*)malloc((size_limit + 1) * sizeof(char));
        strncpy(result, str, size_limit);
        result[size_limit] = '\0';
        return result;
    } else {
        return NULL;
    }
}
