        free((*pdus)[i]);
    }
    free(*pdus);
}

char* trim_or_truncate_string(char* str, int size_limit, int trim_flag) {
    if (!str || strlen(str) > size_limit) {
        char* trimmed_str = NULL;
        if (trim_flag && strlen(str) > size_limit) {
            trimmed_str = (char*)malloc((size_limit + 1) * sizeof(char));
            strncpy(trimmed_str, str, size_limit);
            trimmed_str[size_limit] = '\0';
        }
        else if (!trim_flag && strlen(str) > size_limit) {
            return NULL;
        }
        else {
            char* appended_str = (char*)malloc((size_limit + 2) * sizeof(char));
            strncpy(appended_str, str, size_limit);
            appended_str[size_limit] = '/';
            appended_str[size_limit + 1] = '\0';
            free(str);
            return appended_str;
        }
        if (trimmed_str) {
            printf("Length: %d\n", strlen(trimmed_str));
            log_message("Trimmed string");
        }
        else {
            log_message("Original string");
        }
        return str ? str : trimmed_str;
    }
    else {
        char* appended_str = (char*)malloc((size_limit + 2) * sizeof(char));
        strncpy(appended_str, str, size_limit);
        appended_str[size_limit] = '/';
        appended_str[size_limit + 1] = '\0';
        return appended_str;
    }
}
