    for(int i = 0; i < N; i++) {
        // Initialize a new structure
        NFAPI_CRC_INDICATION_PDU_T temp;
        temp.RX_UE_INFORMATION_TAG = ...; // Initialize RX_UE_INFORMATION_TAG
        temp.RNTI = ...; // Initialize RNTI
