#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

void* nfa_pi_crc_indication_pdu_list_new(int size) {
    return calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void nfa_pi_crc_indication_pdu_free(void** list, int size) {
    for (int i = 0; i < size; i++) {
        free((*list + i));
    }
    free(*list);
    *list = NULL;
}

NFAPI_CRC_INDICATION_PDU_T* nfa_pi_crc_indication_pdu_new(int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return NULL;

    pdu->RX_UE_INFORMATION_TAG = rand() % 1000;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
    pdu->CRCFLAG = rand() & 1; // Randomly set CRCFLAG
    pdu->timestamp = time(NULL);

    return pdu;
}

void nfa_pi_crc_indication_pdu_validate(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->RNTI < 0 || pdu->RNTI > 65535) {
        // Handle invalid RNTI
        char suffix[10];
        sprintf(suffix, "_%d", rand() % 100);
        strncat((char*)malloc(strlen("Invalid_RNTI") + strlen(suffix)), "Invalid_RNTI", strlen("Invalid_RNTI"));
    }
}

int main() {
    // Initialize configuration options
    int max_retries = 5;
    srand(time(NULL)); // Seed random number generator

    NFAPI_CRC_INDICATION_PDU_T* list = NULL;

    for (int i = 0; i < 10000; i++) {
        // Create a new PDU structure and validate the RNTI
        NFAPI_CRC_INDICATION_PDU_T* pdu = nfa_pi_crc_indication_pdu_new(i);
        if (!pdu) continue;

        // Append to list, handling memory management efficiently
        void** temp_list = (void**)realloc(list, sizeof(void*) * (i + 1));
        if (!temp_list) {
            printf("Error: Memory allocation failed. Retrying...\n");
            sleep(1); // Retry after a delay
            continue;
        }
        list = temp_list;

        for (int j = 0; j < i; j++) {
            if (pdu->RNTI == ((NFAPI_CRC_INDICATION_PDU_T*)list[j])->RNTI) {
                // Handle duplicate RNTI
                printf("Error: Duplicate RNTI. Retrying...\n");
                sleep(1); // Retry after a delay
                free(pdu);
                pdu = NULL;
                break;
            }
        }

        if (pdu) {
            // Append the PDU to the list and validate it
            *(list + i) = pdu;
            nfa_pi_crc_indication_pdu_validate(*(list + i));
        }
    }

    // Free memory efficiently, handling concurrent access safely
    for (int i = 0; i < 10000; i++) {
        nfa_pi_crc_indication_pdu_free(&*(list + i), 1);
    }

    return 0;
}
