// Define a custom locking mechanism using atomic operations
typedef struct {
    int lock;
} Lock;

void lock(Lock* lk) {
    while (__atomic_exchange_n(&lk->lock, 1, __ATOMIC_EXCHANGE) != 0);
}

void unlock(Lock* lk) {
    __atomic_store_n(&lk->lock, 0, __ATOMIC_RELEASE);
}

// Define a custom memory allocation function that logs failures
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failure\n");
        return NULL;
    }
    return ptr;
}

void* my_realloc(void* ptr, size_t size) {
    void* new_ptr = realloc(ptr, size);
    if (new_ptr == NULL) {
        fprintf(stderr, "Memory reallocation failure\n");
        free(ptr);
        return NULL;
    }
    return new_ptr;
}

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    char RX_UE_INFORMATION_TAG[16];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node for the dynamic list
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Initialize the head of the list and set the initial count to 0
Node* nfa_list = NULL;
int nfa_count = 0;

// Function to add a new structure to the list
void add_node(NFAPI_CRC_INDICATION_PDU_T* p) {
    Lock lk;
    lock(&lk);
    Node* new_node = (Node*)my_malloc(sizeof(Node));
    if (!new_node) return; // allocation failure, exit

    new_node->data = *p;
    new_node->next = nfa_list;
    nfa_list = new_node;
    if (nfa_count == 0) {
        nfa_count++;
    }
    unlock(&lk);
}

// Function to remove a structure from the list by RNTI
void remove_node(int rnti) {
    Lock lk;
    lock(&lk);
    Node* current = nfa_list;
    Node* previous = NULL;

    while (current && current->data.RNTI != rnti) {
        previous = current;
        current = current->next;
    }

    if (!current) {
        unlock(&lk);
        return; // structure not found, exit
    }

    if (previous) {
        previous->next = current->next;
    } else {
        nfa_list = current->next;
    }

    free(current);
    if (--nfa_count == 0) {
        nfa_list = NULL;
    }
    unlock(&lk);
}

// Function to iterate over the list in reverse order
void traverse_reverse() {
    Node* current = nfa_list;

    while (current) {
        printf("%s RNTI: %d CRC_INDICATION_REL8_TAG: %s\n", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

// Function to serialize the list to a binary file
void serialize() {
    FILE* file = fopen("nfa_list.bin", "wb");

    if (file == NULL) {
        fprintf(stderr, "Failed to open serialization file\n");
        return;
    }

    Node* current = nfa_list;

    while (current) {
        fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }

    fclose(file);
}

// Function to deserialize the list from a binary file
void deserialize() {
    FILE* file = fopen("nfa_list.bin", "rb");

    if (file == NULL) {
        fprintf(stderr, "Failed to open deserialization file\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T p;

    while (fread(&p, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file)) {
        add_node(&p);
    }

    fclose(file);
}

int main() {
    // Initialize the list and count
    nfa_list = NULL;
    nfa_count = 0;

    // Add structures to the list
    NFAPI_CRC_INDICATION_PDU_T p1 = {"RX_UE_INFORMATION_TAG1", 1, "CRC_INDICATION_REL8_TAG1"};
    NFAPI_CRC_INDICATION_PDU_T p2 = {"RX_UE_INFORMATION_TAG2", 2, "CRC_INDICATION_REL8_TAG2"};
    NFAPI_CRC_INDICATION_PDU_T p3 = {"RX_UE_INFORMATION_TAG3", 3, "CRC_INDICATION_REL8_TAG3"};

    add_node(&p1);
    add_node(&p2);
    add_node(&p3);

    // Remove a structure from the list
    remove_node(2);

    // Iterate over the list in reverse order
    traverse_reverse();

    // Serialize the list to a binary file
    serialize();

    // Deserialize the list from a binary file
    deserialize();

    return 0;
}
