    char *source_ip;
    char *destination_ip;
    int protocol_type;
} NIC_CFG;

void nic_config_init(NIC_CFG *cfg, int num_packets) {
    cfg->num_packets = num_packets;
    cfg->max_packets = num_packets;
    cfg->packet_pool = (TX_PACKET **)malloc(num_packets * sizeof(TX_PACKET *));
    for (int i = 0; i < num_packets; i++) {
        cfg->packet_pool[i] = (TX_PACKET *)malloc(sizeof(TX_PACKET));
    }
}

void nic_config_set_metadata(NIC_CFG *cfg, int enable) {
    if (enable) {
        // Initialize metadata fields
        cfg->metadata_fields_enabled = 1;
        cfg->source_ip = (char *)malloc(16);
        strcpy(cfg->source_ip, "192.168.0.1");
        cfg->destination_ip = (char *)malloc(16);
        strcpy(cfg->destination_ip, "192.168.0.2");
        cfg->protocol_type = 0x06; // TCP
    } else {
        free(cfg->source_ip);
        free(cfg->destination_ip);
        cfg->metadata_fields_enabled = 0;
        cfg->protocol_type = 0; // No protocol specified
    }
}

void nic_config_free(NIC_CFG *cfg) {
    for (int i = 0; i < cfg->num_packets; i++) {
        free(cfg->packet_pool[i]);
    }
    free(cfg->packet_pool);
    if (!cfg->metadata_fields_enabled) {
        free(cfg->source_ip);
        free(cfg->destination_ip);
    }
}
