#define MAX_ELEMENTS 5000
#define NETWORK_API_TIMEOUT 1000 // in milliseconds
#define CACHE_SIZE 1024

typedef struct LTE_PAGING_MESSAGE_T {
    int paging_indication_tag;
    char mme_id[16];
    char cell_id[16];
} LTE_PAGING_MESSAGE_T;

typedef struct {
    LTE_PAGING_MESSAGE_T* messages;
    size_t num_elements;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} PagingMessageArray;

PagingMessageArray* paging_message_array = NULL;

void initialize_paging_message_array() {
    if (paging_message_array != NULL) return;

    paging_message_array = (PagingMessageArray*)malloc(sizeof(PagingMessageArray));
    if (paging_message_array == NULL) exit(1);

    pthread_mutex_init(&paging_message_array->lock, NULL);
    pthread_cond_init(&paging_message_array->cond, NULL);

    paging_message_array->messages = (LTE_PAGING_MESSAGE_T*)calloc(MAX_ELEMENTS, sizeof(LTE_PAGING_MESSAGE_T));
    if (paging_message_array->messages == NULL) exit(1);

    paging_message_array->num_elements = 0;
}

int add_paging_message(LTE_PAGING_MESSAGE_T* message) {
    pthread_mutex_lock(&paging_message_array->lock);

    if (paging_message_array->num_elements >= MAX_ELEMENTS) {
        fprintf(stderr, "Error: Array is full.\n");
        pthread_mutex_unlock(&paging_message_array->lock);
        return -1;
    }

    paging_message_array->messages[paging_message_array->num_elements++] = *message;

    pthread_cond_signal(&paging_message_array->cond);
    pthread_mutex_unlock(&paging_message_array->lock);

    return 0;
}

void* signaling_network_api_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&paging_message_array->lock);

        if (paging_message_array->num_elements > 0) {
            LTE_PAGING_MESSAGE_T message = paging_message_array->messages[0];

            // Simulate network API call with varying response times and reliability issues
            int response_code = rand() % 3;
            if (response_code == 1) {
                printf("Error: Network API failed.\n");
            } else if (response_code == 2) {
                printf("Warning: Network API timed out.\n");
            }

            // Update UE location and cache if response is successful
            if (response_code == 0) {
                // Simulate caching mechanism to reduce repeated network requests
                int cached = rand() % 2;
                if (cached) {
                    printf("Info: Cached UE location updated.\n");
                } else {
                    printf("Info: Network API updated UE location.\n");
                }
            }

            // Remove processed message from array
            memmove(paging_message_array->messages, &paging_message_array->messages[1], (paging_message_array->num_elements - 1) * sizeof(LTE_PAGING_MESSAGE_T));
            paging_message_array->num_elements--;
        }

        pthread_mutex_unlock(&paging_message_array->lock);
    }
}

int main() {
    initialize_paging_message_array();

    // Create signaling network API threads
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, signaling_network_api_thread, NULL);
    }

    // Add paging messages to array and process concurrently
    int i;
    for (i = 0; i < MAX_ELEMENTS; i++) {
        LTE_PAGING_MESSAGE_T message;
        message.paging_indication_tag = i;
        strcpy(message.mme_id, "MME_ID");
        strcpy(message.cell_id, "CELL_ID");

        add_paging_message(&message);
    }

    // Wait for signaling network API threads to finish
    for (i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
