} NFAPI_L2_RX_PDU_T;

// List node structure
typedef struct _node {
    NFAPI_L2_RX_PDU_T data;
    struct _node* next;
} Node;

// Thread-safe list structure
typedef struct {
    Node* head;
    pthread_mutex_t lock;
    size_t count;
} NFAPI_L2_RX_PDU_T_List;

void nfa_pi_l2_rx_pdu_list_init(NFAPI_L2_RX_PDU_T_List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
}

void nfa_pi_l2_rx_pdu_list_add(NFAPI_L2_RX_PDU_T_List* list, NFAPI_L2_RX_PDU_T* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        // Handle memory allocation failure
        return;
    }

    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
