class DynamicRandomValueGenerator {
public:
    // Constructor with default ranges
    DynamicRandomValueGenerator();

    // Constructor with custom ranges
    DynamicRandomValueGenerator(const std::map<std::type_index, std::pair<int64_t, int64_t>>& customRanges);

    // Generate random integer value within range [min, max]
    int getRandomInt(int min, int max);

    // Generate random float value within range [min, max]
    float getRandomFloat(float min, float max);

    // Generate random double value within range [min, max]
    double getRandomDouble(double min, double max);

    // Generate random custom user-defined type value within range [min, max]
    template<typename T>
    T getRandomValue(const std::function<T(int64_t)>& seedFunc, int64_t min, int64_t max);

    // Reset range for specific data type
    void resetRange(std::type_index typeId, int64_t newMin, int64_t newMax);

    // Display current ranges for each data type
    std::string toString();

private:
    struct Generator {
        std::mt19937 engine;
        int64_t min;
        int64_t max;

        Generator(int64_t min, int64_t max) : min(min), max(max) {}

        template<typename T>
        T generate(const std::function<T(int64_t)>& seedFunc) {
            return seedFunc(engine() % (max - min + 1) + min);
        }
    };

    std::map<std::type_index, Generator> generators;
    std::atomic<int64_t> nextSeed = 0;

    // Initialize random number generators with default ranges
    void initialize();

    // Handle invalid range for specific data type
    void handleInvalidRange(std::type_index typeId);

    // Generate random value based on provided seed function and constraints
    template<typename T>
    T generateValue(const std::function<T(int64_t)>& seedFunc, int64_t min, int64_t max);
};

// Initialize random number generators with default ranges if not provided
void DynamicRandomValueGenerator::initialize() {
    // Add code to initialize generators with default ranges
}

// Handle invalid range for specific data type
void DynamicRandomValueGenerator::handleInvalidRange(std::type_index typeId) {
    // Add code to handle invalid range gracefully
}

// Generate random value based on provided seed function and constraints
template<typename T>
T DynamicRandomValueGenerator::generateValue(const std::function<T(int64_t)>& seedFunc, int64_t min, int64_t max) {
    return seedFunc(nextSeed++);
}
