// Define the maximum buffer queue size
#define BUFFER_QUEUE_MAX_SIZE 1000

// Define the structure to store RX frame info, UE context and buffer pointers
typedef struct {
    RX_FRAME_INFO* frame_info;
    RX_UE_CONTEXT* ue_context;
    PHY_RX_BUFFER** buffers;
} NFAPI_RX_PDU_T;

// Define the doubly-linked list node
typedef struct Node {
    NFAPI_RX_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Function to initialize and populate the doubly-linked list
void init_and_populate_list(int n, int max_queue_size) {
    // Initialize the head and tail of the linked list
    Node* head = NULL;
    Node* tail = NULL;

    // Initialize the buffer queue and its size
    pthread_mutex_t buffer_queue_lock = PTHREAD_MUTEX_INITIALIZER;
    int buffer_queue_size = 0;
    NFAPI_RX_PDU_T** buffer_queue = (NFAPI_RX_PDU_T**)malloc(BUFFER_QUEUE_MAX_SIZE * sizeof(NFAPI_RX_PDU_T*));

    // Iterate through the frames and populate the list
    for (int i = 0; i < n; i++) {
        NFAPI_RX_PDU_T* pdu = (NFAPI_RX_PDU_T*)malloc(sizeof(NFAPI_RX_PDU_T));
        pdu->frame_info = malloc(sizeof(RX_FRAME_INFO));
        pdu->ue_context = malloc(sizeof(RX_UE_CONTEXT));
        int buffer_count = 0;
        pdu->buffers = (PHY_RX_BUFFER**)malloc(BUFFER_QUEUE_MAX_SIZE * sizeof(PHY_RX_BUFFER*));

        // Initialize the frame and UE context
        // ...

        // Add the PDU to the list
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->data = pdu;
        new_node->prev = NULL;
        new_node->next = NULL;

        if (head == NULL) {
            head = tail = new_node;
        } else {
            tail->next = new_node;
            new_node->prev = tail;
            tail = new_node;
        }

        // Add the buffer to the queue
        pthread_mutex_lock(&buffer_queue_lock);
        if (buffer_queue_size < max_queue_size) {
            buffer_queue[buffer_queue_size] = pdu->buffers;
            buffer_queue_size++;
        } else {
            printf("Buffer queue exceeded maximum size.\n");
            free(buffer_queue[0]);
            free(pdu->buffers);
        }
        pthread_mutex_unlock(&buffer_queue_lock);

        // Check for errors and deallocate resources
        if (pdu == NULL || pdu->frame_info == NULL || pdu->ue_context == NULL) {
            printf("Error: PDU initialization failed.\n");
            return;
        }
    }

    // Clear the list and buffer queue when requested
    void clear_list_and_queue() {
        Node* current = head;
        while (current != NULL) {
            Node* next = current->next;
            free(current->data);
            free(current);
            current = next;
        }

        pthread_mutex_lock(&buffer_queue_lock);
        for (int i = 0; i < buffer_queue_size; i++) {
            free(buffer_queue[i]);
        }
        free(buffer_queue);
        buffer_queue_size = 0;
        pthread_mutex_unlock(&buffer_queue_lock);
    }
}

// Function to handle concurrent access
void* concurrent_access(void* args) {
    // ...
}

int main() {
    int n = 100; // Number of frames
    int max_queue_size = BUFFER_QUEUE_MAX_SIZE; // Maximum buffer queue size

    init_and_populate_list(n, max_queue_size);

    return 0;
}
