        current = next;
    }
    head = tail = NULL;
    queue_size = 0;
}

int get_queue_size() {
    return queue_size;
}

void add_pdu_to_list(NFAPI_RX_PDU_T pdu) {
    DLLNode* new_node = (DLLNode*)malloc(sizeof(DLLNode));
    if (new_node == NULL || new_node->pdu.phy_rx_buffer == NULL) {
        // Handle error
        printf("Error allocating memory for new node\n");
        return;
    }
    new_node->pdu = pdu;
    new_node->prev = tail;
    new_node->next = NULL;
    if (tail != NULL)
        tail->next = new_node;
    else
        head = new_node;
    tail = new_node;
    queue_size++;
}

void drop_oldest_pdu() {
    if (head == NULL) return;
    DLLNode* oldest = head;
    head = head->next;
    if (head != NULL)
        head->prev = NULL;
    else
        tail = NULL;
    free(oldest);
    queue_size--;
}

void log_message(char* message, int level) {
    if (level <= LOG_LEVEL) {
        fprintf(log_file, "%s\n", message);
    }
}
