#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARN 2
#define LOG_LEVEL_ERROR 3

typedef struct {
    char* name;
    void (*function)(void* param);
    void* param;
} TRANSPORT_PROTOCOL;

typedef struct {
    TCP_STATE_INFO state_info;
    TCP_SESSION_CONTEXT session_context;
    NETWORK_BUFFER* buffer;
} TCP_PACKET;

typedef struct {
    int size;
    TCP_PACKET** packets;
    pthread_mutex_t lock;
} CIRCULAR_BUFFER;

CIRCULAR_BUFFER* circular_buffer_init(int max_size) {
    CIRCULAR_BUFFER* buffer = (CIRCULAR_BUFFER*)malloc(sizeof(CIRCULAR_BUFFER));
    buffer->size = 0;
    buffer->packets = (TCP_PACKET**)malloc(max_size * sizeof(TCP_PACKET*));
    pthread_mutex_init(&buffer->lock, NULL);
    return buffer;
}

void circular_buffer_free(CIRCULAR_BUFFER* buffer) {
    for(int i = 0; i < buffer->size; i++) {
        free(buffer->packets[i]->buffer);
        free(buffer->packets[i]);
    }
    free(buffer->packets);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

TCP_PACKET* tcp_packet_alloc() {
    TCP_PACKET* packet = (TCP_PACKET*)malloc(sizeof(TCP_PACKET));
    packet->state_info = NULL;
    packet->session_context = NULL;
    packet->buffer = NULL;
    return packet;
}

void tcp_packet_free(TCP_PACKET* packet) {
    free(packet);
}

void circular_buffer_add_packet(CIRCULAR_BUFFER* buffer, TCP_PACKET* packet) {
    pthread_mutex_lock(&buffer->lock);
    if(buffer->size >= MAX_BUFFER_POOL_SIZE) {
        // Drop the oldest buffer
        free(buffer->packets[0]->buffer);
        free(buffer->packets[0]);
        memmove(buffer->packets, buffer->packets + 1, (buffer->size - 1) * sizeof(TCP_PACKET*));
        buffer->size--;
    }
    packet->buffer = malloc(1024); // Dynamic allocation
    packet->state_info = malloc(sizeof(TCP_STATE_INFO)); // Dynamic allocation
    packet->session_context = malloc(sizeof(TCP_SESSION_CONTEXT)); // Dynamic allocation
    if(packet->buffer == NULL || packet->state_info == NULL || packet->session_context == NULL) {
        LOG_LEVEL_ERROR("Failed to allocate buffer");
        return;
    }
    buffer->packets[buffer->size++] = packet;
    pthread_mutex_unlock(&buffer->lock);
}

void circular_buffer_clear(CIRCULAR_BUFFER* buffer) {
    for(int i = 0; i < buffer->size; i++) {
        tcp_packet_free(buffer->packets[i]);
    }
    free(buffer->packets);
    pthread_mutex_destroy(&buffer->lock);
    free(buffer);
}

