void txPduCollectionInitialize(struct TX_API_TX_PDU_T** pduCollection, int* capacity) {
    *pduCollection = (struct TX_API_TX_PDU_T*)malloc(sizeof(struct TX_API_TX_PDU_T) * 1);
    *capacity = 1;
}

int txPduCollectionAdd(struct TX_API_TX_PDU_T** pduCollection, int* capacity, struct TX_FRAME_INFO* frameInfo, struct TX_CELL_CONTEXT* cellContext, uint8_t** phyTxBuffer, int size) {
    if (*pduCollection == NULL || *capacity == 0) return -1;
    if (frameInfo == NULL || cellContext == NULL || phyTxBuffer == NULL) return -2;

    struct TX_API_TX_PDU_T* pdu = (struct TX_API_TX_PDU_T*)malloc(sizeof(struct TX_API_TX_PDU_T));
    pdu->frameInfo = frameInfo;
    pdu->cellContext = cellContext;
    pdu->phyTxBuffer = (uint8_t**)malloc((size + 1) * sizeof(uint8_t*));
    pdu->phyTxBufferSize = size;

    for (int i = 0; i <= size; i++) {
        pdu->phyTxBuffer[i] = phyTxBuffer[i];
    }

    if (*pduCollection == NULL) {
        *pduCollection = pdu;
    } else {
        struct TX_API_TX_PDU_T** tempPduCollection = (struct TX_API_TX_PDU_T**)malloc(sizeof(struct TX_API_TX_PDU_T*) * (*capacity + 1));
        for (int i = 0; i < *capacity; i++) {
            tempPduCollection[i] = (*pduCollection)[i];
        }
        free(*pduCollection);
        *pduCollection = tempPduCollection;
    }

    (*capacity)++;
}

void txPduCollectionResize(struct TX_API_TX_PDU_T** pduCollection, int* capacity) {
    if (*capacity == 0) return;

    struct TX_API_TX_PDU_T** tempPduCollection = (struct TX_API_TX_PDU_T**)malloc(sizeof(struct TX_API_TX_PDU_T*) * (*capacity + 1));
    for (int i = 0; i < *capacity; i++) {
        tempPduCollection[i] = (*pduCollection)[i];
    }
    free(*pduCollection);
    *pduCollection = tempPduCollection;
}

void txPduCollectionFree(struct TX_API_TX_PDU_T** pduCollection, int* capacity) {
    for (int i = 0; i < *capacity; i++) {
        if ((*pduCollection)[i]->phyTxBuffer != NULL) {
            for (int j = 0; j <= (*pduCollection)[i]->phyTxBufferSize; j++) {
                free(((*pduCollection)[i])->phyTxBuffer[j]);
            }
            free((*pduCollection)[i]->phyTxBuffer);
        }
        free((*pduCollection)[i]);
    }
    free(*pduCollection);
}
