#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <json-c/json.h>

#define MAX_CITY_NAME_LENGTH 50
#define MAX_API_REQUESTS_PER_SECOND 5
#define API_ENDPOINT "https://api.weather.com/city/temperature"
#define LOG_FILE "weather_api.log"

float getWeatherTemperature(const char* city_name) {
    CURL *curl;
    CURLcode res;
    FILE *fp = fopen(LOG_FILE, "a");
    int retry_count = 0;

    // Create a CURL session
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (!curl) return -1.0; // Error in creating the CURL session

    // Set API endpoint and city name query parameter
    char* url = malloc(strlen(API_ENDPOINT) + strlen(city_name) + 20);
    sprintf(url, "%s?city=%s", API_ENDPOINT, city_name);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    free(url);

    do {
        // Set rate limiting mechanism (5 requests per second)
        struct timespec timeout = {0, 1000000000 / MAX_API_REQUESTS_PER_SECOND};
        nanosleep(&timeout, NULL);

        res = curl_easy_perform(curl, NULL); // Perform the API request

        if (res == CURLE_OK) {
            // Parse JSON response
            json_object *json = json_object_from_file("response.json");
            if (json) {
                float temperature = json_object_get_number(json, "temperature");
                fclose(fp);
                free(curl);
                curl_global_cleanup();
                return temperature;
            } else {
                fprintf(fp, "JSON parsing failed\n");
                retry_count++;
            }
        } else {
            // Log non-fatal errors and handle network issues
            if (res == CURLE_COULDNT_CONNECT || res == CURLE_BAD_ADDRESS) {
                fprintf(fp, "Network error: %s\n", curl_easy_strerror(res));
            } else if (res != CURLE_OK) {
                fprintf(fp, "API request failed with code %d: %s\n", res, curl_easy_strerror(res));
            }
            retry_count++;
        }

    } while (retry_count < 3); // Retry up to 2 times in case of errors

    fclose(fp);
    free(curl);
    curl_global_cleanup();
    return -1.0; // API request failed after retries
}

int main() {
    const char* city_name = "New York";
    float temperature = getWeatherTemperature(city_name);
    printf("The current temperature in %s is %.2f°C\n", city_name, temperature);

    return 0;
}
