    // Method to generate random float value within range
    float getFloatRandom() {
        return (float)UnityEngine::Random.Range((double)_min, (double)_max);
    }

    // Method to generate random integer value within range
    int getIntRandom() {
        return UnityEngine::Random.Range(_min, _max + 1);
    }

    // Override ToString method for displaying the range of values
