        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return NULL;
        }

        // Handle API response format based on Content-Type header
        std::string responseStr;
        {
            struct MemoryStruct chunk;
            cJSON *root = cJSON_Parse(curl_easy_getinfo(curlHandle, CURLINFO_RESPONSE_CODE));
            if (root == NULL) {
                fprintf(stderr, "Error parsing JSON\n");
                return NULL;
            }
            char* data = cJSON_Print(root);
            chunk.memory = malloc(strlen(data) + 1);
            strcpy(chunk.memory, data);
            cJSON_Delete(root);
            free(data);

            // Fetch the API response
            curl_easy_setopt(curlHandle, CURLOPT_WRITEFUNCTION, writeMemoryCallback);
            curl_easy_setopt(curlHandle, CURLOPT_WRITEDATA, &chunk);
            res = curl_easy_perform(curlHandle);
            if (res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                return NULL;
            }

            responseStr = chunk.memory;

            free(chunk.memory);

        }
    }

    // Extract temperature value from API response
    WeatherData* weatherData = malloc(sizeof(WeatherData));
    if (json_error) {
        json_object_free(obj);
    }
    cJSON *tempObj = cJSON_GetObjectItem(root, "main");
