        cJSON *temperatureObj = cJSON_GetObjectItem(tempObj, "temp");
        weatherData->temperature = (float)cJSON_GetNumberValue(temperatureObj);

        // Close and clean up curl handle
        curl_easy_cleanup(curlHandle);
        curl_global_cleanup();
    }
    return weatherData;
}

