// Structure to represent a DNS query result
typedef struct {
    char* hostname;
    u_char* ip_address;
    int result_code;
} dns_query_result;

// Function to perform DNS resolution and filter IP addresses based on allowed ranges
u_char* perform_dns_resolution(char* hostname, int* ip_addresses, int num_ip_addresses) {
    // Initialize the query result structure
    dns_query_result query_result;

    // Initialize the timeout timer
    struct timespec timeout_timer;
    clock_gettime(CLOCK_REALTIME, &timeout_timer);
    timeout_timer.tv_sec += MIN_INTERVAL;  // Set the minimum interval

    while (1) {
        // Check if the rate limiter has expired
        clock_gettime(CLOCK_REALTIME, &timeout_timer);
        if (timeout_timer.tv_nsec > 0 && !clock_nanosleep(0, 0)) {
            return NULL;
        }

        // Perform DNS resolution using getaddrinfo()
        struct addrinfo hints = { .ai_family = AF_INET };
        struct addrinfo* result = NULL;
        int err_code = getaddrinfo(hostname, NULL, &hints, &result);
        if (err_code != 0) {
            query_result.result_code = -1;  // Error code for DNS resolution failure
            return NULL;
        }

        // Filter IP addresses based on allowed ranges
        int i = 0;
        for (; i < num_ip_addresses && i < result->ai_addr->ai_addrlen / sizeof(struct in_addr); i++) {
            struct in_addr* ip_address = (struct in_addr*)result->ai_addr->ai_addrlen - i * sizeof(struct in_addr);
            if (!allowed_ip_range(ip_address->s_addr)) {
                freeaddrinfo(result);
                return NULL;
            }
        }

        // Copy the filtered IP addresses to the output array
        for (; i < num_ip_addresses; i++) {
            char buffer[INET6_ADDRSTRLEN];
            inet_ntop(AF_INET, &((struct in_addr*)result->ai_addr->ai_addrlen - i * sizeof(struct in_addr)), buffer, sizeof(buffer));
            // Store the IP address and hostname in the query result structure
            query_result.ip_address = (u_char*)malloc(strlen(buffer) + 1);
            strcpy((char*)query_result.ip_address, buffer);
            query_result.hostname = strdup(hostname);

            // Log the successful DNS request to a file
            log_dns_request(query_result.hostname, query_result.ip_address, 0);

            freeaddrinfo(result);
            return query_result.ip_address;
        }

        // If no valid IP addresses are found, continue querying until the rate limiter expires
    }
}

