#define MAX_CONCURRENT_SESSIONS 500
#define LOG_FILE_MAX_SIZE (1024 * 1024 * 100) // 100MB
#define LOAD_BALANCER_STRATEGY "ROUND_ROBIN"

typedef struct {
    int socket;
    time_t last_active_time;
    char username[32];
} Connection;

Connection* connections[MAX_CONCURRENT_SESSIONS];
int current_connections = 0;

void init_connections() {
    for (int i = 0; i < MAX_CONCURRENT_SESSIONS; i++) {
        connections[i] = NULL;
    }
}

void add_connection(int sock, char* username) {
    if (current_connections >= MAX_CONCURRENT_SESSIONS) {
        // Handle max concurrent sessions exceeded
        return;
    }

    Connection* new_conn = malloc(sizeof(Connection));
    new_conn->socket = sock;
    strcpy(new_conn->username, username);
    new_conn->last_active_time = time(NULL);

    connections[current_connections] = new_conn;
    current_connections++;
}

void remove_connection(int sock) {
    for (int i = 0; i < current_connections; i++) {
        if (connections[i]->socket == sock) {
            free(connections[i]);
            memmove(&connections[i], &connections[i+1], sizeof(Connection*) * (current_connections - i));
            current_connections--;
            return;
        }
    }
}

void health_check() {
    for (int i = 0; i < current_connections; i++) {
        if (time(NULL) - connections[i]->last_active_time > 60) { // 1 minute idle
            remove_connection(connections[i]->socket);
        }
    }
}

void load_balance(char* message) {
    int next_index = 0;
    for (int i = 0; i < current_connections; i++) {
        if (!connections[i]) continue;

        if (next_index % current_connections == i) { // round-robin strategy
            write(connections[i]->socket, message, strlen(message));
        }

        next_index++;
    }
}

void log_session(Connection* conn, char* message) {
    FILE* log_file = fopen("session.log", "a");
    if (!log_file) return;

    fprintf(log_file, "%s - %s\n", conn->username, message);
    fclose(log_file);

    if (fstat(fileno(log_file), &stbuf) || stbuf.st_size > LOG_FILE_MAX_SIZE) {
        rename("session.log", "session.log.1");
        fopen("session.log", "w").close();
    }
}

int main() {
    init_connections();

    // ... WebSocket server implementation ...

    return 0;
}
