// Function to manage a queue of TX_API_MESSAGE_T structures
void* enqueue(TX_API_MESSAGE_T** queue, TX_API_MESSAGE_T* message) {
    if (!queue || !(*queue = (TX_API_MESSAGE_T**)realloc((*queue), ((*queue)?sizeof(void*)*(size_t)(*queue)+1:size_t(1)))));
        return NULL; // Memory allocation failed

    *queue = (void**)(((char*)*queue)+sizeof(void*)-((size_t)&((*queue)[0])-1));
    *((TX_API_MESSAGE_T**)*queue)=message;
    return (*queue)++;
}

TX_API_MESSAGE_T* dequeue(TX_API_MESSAGE_T** queue) {
    if (!queue || !(*queue)) {
        return NULL; // Queue is empty
    }

    TX_API_MESSAGE_T* message = *--queue;
    free(message);

    return message;
}
