#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CLOUD_PROVIDERS 5
#define MAX_DIRECTORIES 1000
#define MAX_FILES_PER_DIRECTORY 10000
#define BUFFER_SIZE 1024

typedef struct {
    char *directory;
    char *cloud_provider;
    int files_to_backup;
} directory_config;

typedef enum {START, WAIT, COMPLETE} backup_state;

void cloud_backup(directory_config *directories, int num_directories);
void validate_directory(char *directory);

int main() {
    // Read configuration file
    FILE *config_file = fopen("config.txt", "r");
    if (config_file == NULL) {
        printf("Error opening config file.\n");
        return -1;
    }

    directory_config directories[MAX_DIRECTORIES];
    int num_directories = 0;

    char buffer[BUFFER_SIZE];
    while (!feof(config_file)) {
        fgets(buffer, BUFFER_SIZE, config_file);
        if (buffer[0] != '#') { // Ignore comments
            sscanf(buffer, "%s %s %d", &directories[num_directories].directory, &directories[num_directories].cloud_provider, &directories[num_directories].files_to_backup);
            num_directories++;
        }
    }

    fclose(config_file);

    if (num_directories > 0) {
        cloud_backup(directories, num_directories);
    } else {
        printf("No directories configured for backup.\n");
    }

    return 0;
}

void cloud_backup(directory_config *directories, int num_directories) {
    // Initialize backup state
    backup_state state = START;

    // Start backup process
    for (int i = 0; i < num_directories; i++) {
        if (state == START) {
            state = WAIT;
        }

        // Validate directory and start uploading files
        validate_directory(directories[i].directory);
        // Upload files to cloud storage...
        printf("Backing up %s to %s...\n", directories[i].directory, directories[i].cloud_provider);

        if (state == WAIT) {
            state = COMPLETE;
        }
    }

    if (state == COMPLETE) {
        printf("Backup complete.\n");
    } else {
        printf("Backup failed.\n");
    }
}

void validate_directory(char *directory) {
    // Validate directory existence and access
    struct stat sb;
    if (stat(directory, &sb) != 0) {
        printf("Error: Directory %s not found or inaccessible.\n", directory);
        exit(1);
    }
}
