import subprocess
import json

def modify_config_file(file_path, params):
    try:
        with open(file_path, 'r') as f:
            config = f.read()
    except Exception as e:
        raise Exception(f"Failed to read file: {str(e)}")

    for key, value in params.items():
        awk_cmd = f"awk '{{print $0}}' >> {file_path}"
        if not subprocess.run(awk_cmd, shell=True).returncode == 0:
            raise Exception("Awk command failed")

        config = config.replace(f"${{{key}}}", str(value))

    with open(file_path, 'w') as f:
        f.write(config)
