#include <stdlib.h>
#include <stdio.h>

typedef struct {
    TASK_ID id;
    DATA_SIZE size;
    PRIORITY_LEVEL priority;
} QUEUE_ITEM_T;

QUEUE_ITEM_T* queue_init(size_t max_size) {
    QUEUE_ITEM_T* queue = (QUEUE_ITEM_T*)malloc(max_size * sizeof(QUEUE_ITEM_T));
    if (!queue) {
        return NULL; // memory allocation failed
    }
    for (size_t i = 0; i < max_size; i++) {
        queue[i].id = -1; // initialize with invalid ID
        queue[i].size = 0;
        queue[i].priority = LOW_PRIORITY;
    }
    return queue;
}
