        fprintf(stderr, "Memory allocation failure: %s\n", message);
        return NULL;
    }

    // LRU caching mechanism for frequently accessed TX_API_RX_PDU_T instances
    int lru_cache(TX_API_RX_PDU_T** ptx_api_rx_pdu_collection, int size, TX_API_RX_PDU_T* new_pdu) {
        // Evict least recently used entry to make space for the new one
        if (size >= 2) {
