    USER_PROFILE_T *user_profiles = (USER_PROFILE_T *)malloc(MAX_USER_PROFILE * sizeof(USER_PROFILE_T));
    UEStats *ue_stats = (UEStats *)malloc(MAX_UESTATS * sizeof(UEStats));

    // Initialize measurement report array
    MeasurementReport *measurement_reports = (MeasurementReport *)malloc(MAX_MEASUREMENT_REPORTS * sizeof(MeasurementReport));

