        MeasurementReport measurement_report = {rand() % ((MAX_SIGNAL - MIN_SIGNAL) + 1) + MIN_SIGNAL, rand() % ((MAX_FREQ - MIN_FREQ) + 1) + MIN_FREQ};

        // Add measurement report to UE stats linked list
