        ue_stats[ue_stats_index].measurement_reports[ue_stats[ue_stats_index].measurement_reports_count - 1] = measurement_report;

        // Update last updated timestamp
        time_t current_time = time(NULL);
        ue_stats[ue_stats_index].last_updated = current_time;

        // Increment UE stats index and user profile index if necessary
        if (i % MAX_UESTATS == 0) {
            ue_stats_index++;
        }
        if (user_profile_index < i) {
            user_profiles[user_profile_index] = (USER_PROFILE_T){ "username", "email_address", current_time, current_time };
            user_profile_index++;
        }
    }

    // Clean up allocated resources
    free(measurement_reports);
    for (int i = 0; i < ue_stats_index; i++) {
        free(ue_stats[i].measurement_reports);
    }
    free(user_profiles);
    free(ue_stats);

    // Log data population and cleanup
