    NFAPI_CRC_INDICATION_PDU_T* structures = NULL;
    int struct_count = 0;
    int memory_pool_index = 0;

    // Initialize the memory pool
    char* memory_pool = (char*) malloc(MEMORY_POOL_SIZE);
    if (!memory_pool) return NULL;

    for (int i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*) (memory_pool + memory_pool_index);

        // Set random values
