import csv

def update_profiles(input_file, output_file):
    with open(input_file, 'r') as f:
        reader = csv.DictReader(f)
        profiles = {}

        for row in reader:
            username = row['username']
            email = row['email']
            phone_number = row['phone_number']
            last_login_time = int(row['last_login_time'])

            if username not in profiles:
                profiles[username] = {'email': None, 'phone_number': None, 'last_login_time': 0}

            profiles[username]['email'] = email
            profiles[username]['phone_number'] = phone_number
            profiles[username]['last_login_time'] = last_login_time

        with open(output_file, 'w') as f:
            writer = csv.DictWriter(f, fieldnames=['username', 'email', 'phone_number', 'last_login_time'])
            writer.writeheader()

            for username in profiles:
                row = {'username': username, 'email': profiles[username]['email'], 'phone_number': profiles[username]['phone_number'], 'last_login_time': profiles[username]['last_login_time']}
                writer.writerow(row)

