void convert_image(const char* input_file_path, const char* output_directory_path, int conversion_type) {
    // Initialize error handling and logging mechanisms
    init_error_handling();
    set_log_level(LOG_LEVEL_INFO);

    // Load external configuration files for dynamic reconfiguration of logging levels
    load_config_files();

    // Open the input file
    FILE *input_file = fopen(input_file_path, "rb");
    if (input_file == NULL) {
        log_error("Failed to open input file.");
        return;
    }

    // Get the input file size
    fseek(input_file, 0, SEEK_END);
    long input_file_size = ftell(input_file);
    rewind(input_file);

    // Create a buffer for reading and processing data
    char *buffer = (char*)malloc(input_file_size + 1);
    if (buffer == NULL) {
        log_error("Failed to allocate memory for file processing.");
        fclose(input_file);
        return;
    }

    // Read the input file into the buffer
    fread(buffer, 1, input_file_size, input_file);
    buffer[input_file_size] = '\0';

    // Close the input file
    fclose(input_file);

    // Perform the image conversion based on the specified type
    switch (conversion_type) {
        case CONVERSION_TYPE_PNG_TO_JPEG:
            // Use the third-party library to convert the image
            lib_function(buffer, input_file_size);
            break;
        default:
            log_error("Unsupported conversion type.");
            free(buffer);
            return;
    }

    // Generate a unique output file name within the specified directory
    char output_file_name[1024];
    sprintf(output_file_name, "%s/image_%d.%s", output_directory_path, time(NULL), "jpg");

    // Create the output file
    FILE *output_file = fopen(output_file_name, "wb");
    if (output_file == NULL) {
        log_error("Failed to create output file.");
        free(buffer);
        return;
    }

    // Write the converted image data to the output file
    fwrite(buffer, 1, input_file_size, output_file);

    // Close the output file and release resources
    fclose(output_file);
    free(buffer);
}
