NFAPI_CRC_INDICATION_PDU_T* nfaPiInit(int n) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (node == NULL) {
            printf("Memory allocation failed\n");
            return head;
        }
        strcpy(node->RX_UE_INFORMATION_TAG, getUeInfoFromExternalApi());
        node->RNTI = rand() % 1000;
        node->CRCFLAG = rand() % 2;
        node->next = NULL;

        if (head == NULL) {
            head = node;
        } else {
            NFAPI_CRC_INDICATION_PDU_T* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }
    return head;
}

char* getUeInfoFromExternalApi() {
    // implement your UE information API call here
    return "Example UE Information";
}

void nfaPiFree(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    NFAPI_CRC_INDICATION_PDU_T* next = NULL;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

