#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MEMORY_SIZE (1024 * 1024) // 1MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

int callback_function(void* pdu) {
    printf("New pdu added: %d, %d\n", ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RX_UE_INFORMATION_TAG, ((NFAPI_CRC_INDICATION_PDU_T*)pdu)->RNTI);
}

void* create_and_populate_nfa_pi_crc_indication_pdu_list(int num_elements, int max_memory_size, int (*callback)(void*)) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T** pdu_list = NULL;

    // Check if memory size is sufficient
    if (max_memory_size < sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements) {
        fprintf(stderr, "Out of memory. Cannot create list.\n");
        return NULL;
    }

    // Create and initialize the list
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_elements);
    if (!pdu_list) {
        fprintf(stderr, "Memory allocation failed. Cannot create list.\n");
        return NULL;
    }

    int i;
    for (i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(stderr, "Memory allocation failed. Cannot create list.\n");
            // Free any allocated resources and return an error code
            for (int j = 0; j < i; j++) {
                free(pdu_list[j]);
            }
            free(pdu_list);
            return NULL;
        }

        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        ((pdu->CRCFLAG) & 1); // Set CRCFLAG randomly

        if (callback) {
            pthread_mutex_lock(&lock);
            callback((void*)pdu);
            pthread_mutex_unlock(&lock);
        }

        pdu_list[i] = pdu;
    }

    return (void*)pdu_list;
}

void* iterate_over_nfa_pi_crc_indication_pdu_list(void* list) {
    NFAPI_CRC_INDICATION_PDU_T** pdus = (NFAPI_CRC_INDICATION_PDU_T**)list;

