    deviceSession->deviceId = rand();
    deviceSession->transmissionCount = 0;
    deviceSession->transmissions = NULL;

    pthread_mutex_lock(&deviceManager.lock);
    if (deviceManager.deviceSessionCount < MAX_DEVICE_SESSION) {
        deviceManager.deviceSessions[deviceManager.deviceSessionCount++] = *deviceSession;
    } else {
        // Handle device session count exceeded error
