        uint8_t hash_value[20];
        password_hash(crcflag, strlen(crcflag), hash_value);
        memcpy(result[i].CRC_INDICATION_REL8_TAG.CRCFLAG, crcflag, 30);
        result[i].CRC_INDICATION_REL8_TAG.hash_value = hash_value;

        if (i % 2 == 1) {
            uint8_t* ptr = (uint8_t*)&result[i].RNTI;
            *ptr ^= 0x01; // Ensure sum of all CRCFLAGS is odd
        }
    }

    return result;
}
