#include <string.h>
#include <time.h>

typedef struct {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
    struct {
        unsigned char CRCFLAG[16];
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateCRCIndications(int N) {
    srand(time(NULL)); // seed random number generator
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        return NULL; // out of memory
    }

    for (int i = 0; i < N; i++) {
        crc_indications[i].RNTI = rand() % 100;

        char random_string[16];
        sprintf(random_string, "%x", rand());
        memcpy(crc_indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG, random_string, 16);

        // ensure sum of all CRCFLAGS is odd
        int crc_sum = 0;
        for (int j = 0; j < 16; j++) {
            crc_sum += crc_indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG[j];
        }
        if (!(crc_sum & 1)) {
            crc_sum++;
            int carry = 0;
            for (int j = 15; j >= 0; j--) {
                crc_indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG[j] += carry;
                if (crc_indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG[j] > 0x9f) {
                    crc_indications[i].CRC_INDICATION_REL8_TAG.CRCFLAG[j] -= 0xa0;
                    carry = 1;
                } else {
                    carry = 0;
                }
            }
        }
    }

    return crc_indications;
}
