void initialize_lte_phy_pdu(int max_size) {
    if (max_size < 1) {
        printf("Invalid max size\n");
        return;
    }

    int* pool_sizes = (int*)malloc(max_size * sizeof(int));
    for (int i = 0; i < max_size; i++) {
        pool_sizes[i] = 1 << (i % 4); // 2^0, 2^1, 2^2, ...
    }

    ltephy_pdu_pool = (LTEPHY_PDU_T**)malloc(max_size * sizeof(LTEPHY_PDU_T*));
    for (int i = 0; i < max_size; i++) {
        ltephy_pdu_pool[i] = (LTEPHY_PDU_T*)calloc(pool_sizes[i], sizeof(LTEPHY_PDU_T));
    }

    num_pdu = max_size;
}

void free_lte_phy_pdu() {
    for (int i = 0; i < num_pdu; i++) {
        free(ltephy_pdu_pool[i]);
    }
    free(ltephy_pdu_pool);
}
