typedef struct {
    uint8_t TX_ANTENNA_ID;
    uint8_t RX_ANTENNA_ID;
    uint16_t RB_START;
} LTE_PHY_RX_CONFIG_T;

// Cache structure to store and manage cached data
typedef struct {
    LTE_PHY_RX_CONFIG_T config;
    int expires_at;
} CacheEntry;

// Thread-safe cache management functions
CacheEntry* cache[ CACHE_SIZE ];
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

void cache_add(LTE_PHY_RX_CONFIG_T config) {
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (cache[i]->expires_at == 0 || cache[i]->config.TX_ANTENNA_ID == config.TX_ANTENNA_ID && 
            cache[i]->config.RX_ANTENNA_ID == config.RX_ANTENNA_ID) {
            // Update existing cache entry
            memcpy(&cache[i]->config, &config, sizeof(LTE_PHY_RX_CONFIG_T));
            break;
        }
    }
    if (cache_size < CACHE_SIZE) {
        CacheEntry* new_entry = malloc(sizeof(CacheEntry));
        memcpy(&new_entry->config, &config, sizeof(LTE_PHY_RX_CONFIG_T));
        cache[cache_size++] = new_entry;
    }
    pthread_mutex_unlock(&cache_lock);
}

LTE_PHY_RX_CONFIG_T cache_get(uint8_t TX_ANTENNA_ID, uint8_t RX_ANTENNA_ID) {
    LTE_PHY_RX_CONFIG_T config;
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (cache[i]->config.TX_ANTENNA_ID == TX_ANTENNA_ID && 
            cache[i]->config.RX_ANTENNA_ID == RX_ANTENNA_ID) {
            config = cache[i]->config;
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return config;
}

void process_config_array(LTE_PHY_RX_CONFIG_T* config_array, int size) {
    for (int i = 0; i < size; i++) {
        LTE_PHY_RX_CONFIG_T config = cache_get(config_array[i].TX_ANTENNA_ID, config_array[i].RX_ANTENNA_ID);
        if (config.TX_ANTENNA_ID == 0) {
            // Handle default configuration
            printf("Default configuration used for TX_ANTENNA_ID %d and RX_ANTENNA_ID %d\n", 
                   config_array[i].TX_ANTENNA_ID, config_array[i].RX_ANTENNA_ID);
        } else {
            // Process cached configuration
            printf("Processed configuration: TX_ANTENNA_ID %d, RX_ANTENNA_ID %d, RB_START %d\n", 
                   config.TX_ANTENNA_ID, config.RX_ANTENNA_ID, config.RB_START);
        }
    }
}

int main() {
