    // Implement garbage collection mechanism
    time_t inactivityThreshold = time(NULL) - 60; // 1 minute

    void collectGarbage() {
        pthread_mutex_lock(&mutex);

        for (int i = 0; i < capacity; i++) {
            if (ueStatsArray[i] != NULL && ueStatsArray[i]->lastUpdated < inactivityThreshold) {
                free(ueStatsArray[i]->measurementReports);
