```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t TX_PDU_TAG;
    uint16_t RB_ID;
    uint32_t TRANSMISSION_CONFIGURE_TAG;
} NFAPI_PDU_T;

// Custom memory pool structure
typedef struct {
    void **free_list;
    size_t capacity;
    pthread_mutex_t mutex;
    size_t used;
    size_t max_used;
} MemoryPool;

MemoryPool *create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->capacity = initial_capacity;
    pool->free_list = malloc(pool->capacity * sizeof(void *));
    for (size_t i = 0; i < pool->capacity; i++) {
        pool->free_list[i] = NULL;
    }
    pthread_mutex_init(&pool->mutex, NULL);
    pool->used = 0;
    pool->max_used = 0;
    return pool;
}

void *allocate_pdu(MemoryPool *pool) {
    void **free_list = pool->free_list;
    size_t used = pool->used;

    pthread_mutex_lock(&pool->mutex);

    if (used < pool->capacity) {
        void *pdu = free_list[used];
        free_list[used] = NULL;
        pool->used++;
        return pdu;
    }

    // If no PDUs are available, grow the memory pool
    size_t new_capacity = pool->capacity + 10; // arbitrary growth factor
    void **new_free_list = realloc(pool->free_list, new_capacity * sizeof(void *));
    for (size_t i = pool->capacity; i < new_capacity; i++) {
        new_free_list[i] = NULL;
    }
    pool->capacity = new_capacity;
    free_list = new_free_list;

    // Re-try allocation
    if (used < pool->capacity) {
        void *pdu = free_list[used];
        free_list[used] = NULL;
        pool->used++;
        return pdu;
    }

    pthread_mutex_unlock(&pool->mutex);
    return NULL; // memory exhaustion
}

void deallocate_pdu(MemoryPool *pool, void *pdu) {
    pthread_mutex_lock(&pool->mutex);

    if (pool->used > 0) {
        size_t used = --pool->used;
        pool->free_list[used] = pdu;
    }

    pthread_mutex_unlock(&pool->mutex);
}

// Thread-safe function to generate PDUs
void *generate_pdu(int N, MemoryPool *pool) {
    void *pdu;
    for (int i = 0; i < N; i++) {
        pdu = allocate_pdu(pool);
        if (!pdu) {
            // Handle memory allocation failure
            return NULL;
        }
    }

    return pdu;
}

// Thread-safe function to release PDUs
void release_pdu(int N, MemoryPool *pool, void *pdus[]) {
    for (int i = 0; i < N; i++) {
        deallocate_pdu(pool, pdus[i]);
    }
}

int main() {
    // Initialize memory pool with initial capacity of 10 PDUs
    MemoryPool *pool = create_memory_pool(10);

    int N = 5;
    void *pdus[N];

    // Generate PDUs concurrently using multiple threads
    pthread_t threads[N];
    for (int i = 0; i < N; i++) {
        pdus[i] = generate_pdu(1, pool);
        if (!pdus[i]) {
            printf("Memory allocation failed\n");
            return -1;
        }
        pthread_create(&threads[i], NULL, &generate_pdu, (void *)pool);
    }

    // Wait for all threads to finish
    for (int i = 0; i < N; i++) {
        pthread_join(threads[i], NULL);
    }

    release_pdu(N, pool, pdus);

    return 0;
}

