        return;
    }

    pthread_mutex_lock(&pool.lock);
    pool.contexts[pool.count++] = context;
    pthread_mutex_unlock(&pool.lock);
}

int remove_transport_context(int index) {
    int result = -1;

    if (index >= 0 && index < pool.count) {
        pthread_mutex_lock(&pool.lock);
        if (pool.contexts[index] != NULL) {
            // Handle memory deallocation failure
            result = 0;
        }
        else {
            // Context not found, return error
            result = -1;
        }
        pthread_mutex_unlock(&pool.lock);
    }

    return result;
}

void update_transport_context_config(int index, int config_field1, int config_field2) {
    if (index >= 0 && index < pool.count) {
        pthread_mutex_lock(&pool.lock);
        pool.contexts[index]->config_field1 = config_field1;
        pool.contexts[index]->config_field2 = config_field2;
        pthread_mutex_unlock(&pool.lock);
    }
}

void update_transport_context_state(int index, int state_field1, int state_field2) {
    if (index >= 0 && index < pool.count) {
        pthread_mutex_lock(&pool.lock);
        pool.contexts[index]->state_field1 = state_field1;
        pool.contexts[index]->state_field2 = state_field2;
        pthread_mutex_unlock(&pool.lock);
    }
}

int main() {
    // Initialize the transport context pool
    pthread_mutex_init(&pool.lock, NULL);

    // Add transport contexts as needed
    add_transport_context(NULL);  // Example usage

    // Update configurations and states
    update_transport_context_config(0, 1, 2);
    update_transport_context_state(0, 3, 4);

    return 0;
}
