    int size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY;

NFAPI_CRC_ARRAY* nfaPiCrcArray = NULL;

void initNfaPiCrcArray(int capacity) {
    if (nfaPiCrcArray == NULL) {
        nfaPiCrcArray = malloc(sizeof(NFAPI_CRC_ARRAY));
        if (!nfaPiCrcArray) {
            fprintf(stderr, "Failed to allocate memory for NFAPI CRC array\n");
            return;
        }
        pthread_mutex_init(&nfaPiCrcArray->mutex, NULL);
        nfaPiCrcArray->size = 0;
    }
}

void* allocNfaPiStructure(int capacity) {
    if (capacity > MAX_STRUCTURES) {
        fprintf(stderr, "Requesting structure allocation beyond maximum capacity\n");
        return NULL;
    }
    void* ptr = malloc(MIN_STRUCTURE_SIZE);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory for NFAPI CRC structure\n");
        return NULL;
    }
    return ptr;
}

void freeNfaPiStructure(void* ptr) {
    free(ptr);
}

int addStructureToNfaPiArray(NFAPI_CRC_INDICATION_PDU_T** structures, int size, FILE* logFile) {
    if (size < 0 || size > MAX_STRUCTURES) {
        fprintf(stderr, "Requesting array size beyond maximum capacity\n");
        return -1;
    }
    NFAPI_CRC_ARRAY* array = nfaPiCrcArray;
    pthread_mutex_lock(&array->mutex);
    if (size > array->size) {
        for (int i = 0; i < size - array->size; i++) {
            void* ptr = allocNfaPiStructure(size);
            if (!ptr) {
                fprintf(stderr, "Failed to allocate memory for NFAPI CRC structure\n");
                pthread_mutex_unlock(&array->mutex);
                return -1;
            }
            memcpy(ptr, &structures[i], MIN_STRUCTURE_SIZE);
        }
    }
    array->size = size;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void logErrorReason(const char* reason) {
    fprintf(stderr, "Error reason: %s\n", reason);
}
