#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to hold NFAPI_CRC_INDICATION_PDU_T information
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} PDU_T;

// Function to dynamically generate and manage a list of PDU structures
void* generate_and_manage_pdu_list(int N, pthread_mutex_t *mutex) {
    // Create an array to hold the PDU structures
    PDU_T **pdu_list = (PDU_T **)malloc(N * sizeof(PDU_T *));

    // Initialize each PDU structure with random values
    for (int i = 0; i < N; i++) {
        pdu_list[i] = (PDU_T *)malloc(sizeof(PDU_T));
        pdu_list[i]->RX_UE_INFORMATION_TAG = rand();
        pdu_list[i]->RNTI = rand();
        pdu_list[i]->CRC_INDICATION_REL8_TAG = rand();
        pdu_list[i]->CRCFLAG = rand() % 2;
    }

    // Serialize the PDU list to a binary file
    FILE *file = fopen("pdu_list.bin", "wb");
    if (file == NULL) {
        printf("Error: Unable to open file for writing.\n");
        return NULL;
    }
    pthread_mutex_lock(mutex);
    fwrite(pdu_list, sizeof(PDU_T *), N, file);
    pthread_mutex_unlock(mutex);

    // Close the file
    fclose(file);

    // Deserialize the PDU list from a binary file
    FILE *file2 = fopen("pdu_list.bin", "rb");
    if (file2 == NULL) {
        printf("Error: Unable to open file for reading.\n");
        return NULL;
    }
    pthread_mutex_lock(mutex);
    fread(pdu_list, sizeof(PDU_T *), N, file2);
    pthread_mutex_unlock(mutex);

    // Close the file
    fclose(file2);

    // Return the PDU list
    return pdu_list;
}

// Function to serialize a PDU list to a binary file
int serialize_pdu_list(void **pdu_list, int N) {
    FILE *file = fopen("pdu_list.bin", "wb");
    if (file == NULL) {
        printf("Error: Unable to open file for writing.\n");
        return 1;
    }

    // Write the PDU list to the file
    fwrite(pdu_list, sizeof(void *), N, file);

    // Close the file
    fclose(file);

    return 0;
}

// Function to deserialize a PDU list from a binary file
int deserialize_pdu_list(void ***pdu_list) {
    FILE *file = fopen("pdu_list.bin", "rb");
    if (file == NULL) {
        printf("Error: Unable to open file for reading.\n");
        return 1;
    }

    // Read the PDU list from the file
    fread(pdu_list, sizeof(void *), N, file);

    // Close the file
    fclose(file);

    return 0;
}

// Function to periodically checkpoint a PDU list to disk
void* periodic_checkpoint_pdu_list(int N, pthread_mutex_t *mutex) {
    int i = 0;
    while (1) {
        // Serialize the PDU list to a binary file
        serialize_pdu_list(pdu_list, N);

        // Sleep for some time before the next checkpoint
        sleep(10);
    }
}

int main() {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    int N = 100; // Number of PDU structures

    void *pdu_list = generate_and_manage_pdu_list(N, &mutex);

    // Perform concurrent read and write operations
    pthread_t thread1;
    pthread_create(&thread1, NULL, periodic_checkpoint_pdu_list, (void *)N);

    pthread_join(thread1, NULL);

    return 0;
}

