    int rnti;
    char crc_indication_rel8_tag[64];
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initialize_array(int n) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for (int i = 0; i < n; i++) {
        array[i].rnti = rand() % 100;

        if (rand() % 2) {
            strcpy(array[i].rx_ue_information_tag, "RX_UE_INFORMATION_TAG_VALID");
        } else {
            strcpy(array[i].rx_ue_information_tag, "RX_UE_INFORMATION_TAG_INVALID");
        }

        array[i].crcflag = rand() % 2;
    }

    return array;
}

void process_directory(const char* directory_path) {
    DIR* dir = opendir(directory_path);

    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return;
    }

    struct dirent* entry;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char file_path[1024];
        sprintf(file_path, "%s/%s", directory_path, entry->d_name);

        FILE* file = fopen(file_path, "r");

        if (file != NULL) {
            rewind(file);

            char metadata[256] = {0};
            fread(metadata, 1, sizeof(metadata), file);

            // Parse metadata
            int category = atoi(strtok(metadata, "_"));
            int priority = atoi(strtok(NULL, "_"));
            char* custom_attribute = strtok(NULL, ".");

            // Generate new filename
            time_t current_time = time(NULL);
            struct tm* time_info = localtime(&current_time);
            char new_file_name[MAX_FILE_NAME_LENGTH];
            sprintf(new_file_name, "category_%d_priority_%d_custom_attribute_%s_%ld", category, priority, custom_attribute, (long)time_info->tm_sec);

            printf("New file name: %s\n", new_file_name);
        } else {
            printf("Error opening file: %s\n", strerror(errno));
        }

        fclose(file);
    }

    closedir(dir);
}

int main() {
    int array_size = 100;
    NFAPI_CRC_INDICATION_PDU_T* array = initialize_array(array_size);

    for (int i = 0; i < array_size; i++) {
        printf("RX_UE_INFORMATION_TAG: %s\nRNTI: %d\nCRCFLAG: %u\n", array[i].rx_ue_information_tag, array[i].rnti, array[i].crcflag);
    }

    process_directory("/path/to/directory");

    return 0;
}
