pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T* array[MAX_ELEMS];
int active_crc_indications = 0;

void addElement(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&lock);
    if (active_crc_indications < MAX_CRC_INDICATIONS && !array[active_crc_indications]) {
        array[active_crc_indications] = element;
        active_crc_indications++;
    }
    pthread_mutex_unlock(&lock);
}

void removeElement(int idx) {
    pthread_mutex_lock(&lock);
    for (int i = idx; i < active_crc_indications - 1; i++) {
        array[i] = array[i + 1];
    }
    array[active_crc_indications - 1] = NULL;
    active_crc_indications--;
    pthread_mutex_unlock(&lock);
}

void updateCRCFlags(int idx, int new_flags) {
    pthread_mutex_lock(&lock);
    if (idx < active_crc_indications) {
        array[idx]->crc_indication_rel8_tag.flags = new_flags;
    }
    pthread_mutex_unlock(&lock);
}

NFAPI_CRC_INDICATION_PDU_T* getElement(int idx) {
    pthread_mutex_lock(&lock);
    if (idx < active_crc_indications) {
        return array[idx];
    } else {
        pthread_mutex_unlock(&lock);
        return NULL; // out of bounds
    }
}
