#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONCURRENT_TRANSMISSIONS 5
#define MIN_PRIORITIZED_PDU_TYPE 1
#define MAX_PRIORITIZED_PDU_TYPE 3
#define LOG_DUPLICATE_PDUS 1

typedef struct {
    MAC_HEADER header;
    PDU_TYPE type;
    SNDCP_DATA data;
} MAC_PDU;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
MAC_PDU **pdus = NULL;
int numPDUs = 0;
int maxConcurrentTransmissions = MAX_CONCURRENT_TRANSMISSIONS;
int minPrioritizedPduType = MIN_PRIORITIZED_PDU_TYPE;
int maxPrioritizedPduType = MAX_PRIORITIZED_PDU_TYPE;
int logDuplicatePdus = LOG_DUPLICATE_PDUS;

void addPdu(MAC_PDU *pdu) {
    pthread_mutex_lock(&lock);
    if (numPDUs >= maxConcurrentTransmissions) {
        // Wait for a transmission to complete
        while (numPDUs >= maxConcurrentTransmissions) {
            usleep(1000);  // wait for 1ms
        }
    }

    pdu->sequenceNumber = numPDUs++;
    pdus = realloc(pdus, (numPDUs + 1) * sizeof(MAC_PDU *));
    pdus[numPDUs - 1] = pdu;
    pthread_mutex_unlock(&lock);
}

void removePdu(int sequenceNumber) {
    pthread_mutex_lock(&lock);
    if (sequenceNumber < numPDUs) {
        for (int i = sequenceNumber; i < numPDUs - 1; i++) {
            pdus[i] = pdus[i + 1];
        }
        free(pdus[--numPDUs]);
    }
    pthread_mutex_unlock(&lock);
}

void updateSequenceNumbers(int sequenceNumber, int newSequenceNumber) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < numPDUs; i++) {
        if (pdus[i]->sequenceNumber >= sequenceNumber) {
            pdus[i]->sequenceNumber += newSequenceNumber - sequenceNumber;
        }
    }
    pthread_mutex_unlock(&lock);
}

void prioritizePdus() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < numPDUs; i++) {
        if (pdus[i]->type >= minPrioritizedPduType && pdus[i]->type <= maxPrioritizedPduType) {
            // Move prioritized PDUs to the front of the list
            MAC_PDU *tmp = pdus[0];
            for (int j = 1; j < numPDUs; j++) {
                pdus[j - 1] = pdus[j];
            }
            pdus[--numPDUs] = tmp;
        }
    }
    pthread_mutex_unlock(&lock);
}

void detectDuplicates() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < numPDUs; i++) {
        // Check if the PDU has already been transmitted
        for (int j = 0; j < i; j++) {
            if (pdus[i]->header.equals(pdus[j]->header)) {
                if (logDuplicatePdus) {
                    printf("Duplicate PDU detected: %x\n", pdus[i]->header);
                }
                free(pdus[i]);
                for (int k = i; k < numPDUs - 1; k++) {
                    pdus[k] = pdus[k + 1];
                }
                numPDUs--;
                i--;
            }
        }
    }
    pthread_mutex_unlock(&lock);
}

void managePdus() {
    // Priority and duplicate detection
    prioritizePdus();
    detectDuplicates();

    // Update sequence numbers based on conditions...
}
