    long* offset_values = (long*)malloc(M * sizeof(long));
    int* keys = (int*)malloc(M * sizeof(int));
    float* measurements = (float*)malloc(M * sizeof(float));

    // Populate array of sensor_data structures
    sensor_data* sensor_data_array = (sensor_data*)malloc(M * sizeof(sensor_data));

    // Initialize and manage dynamic array of TCP Connection structures
    TCP_Connection* tcp_connections = (TCP_Connection*)malloc(MAX_CONNECTIONS * sizeof(TCP_Connection));
    int active_connections = 0;
    int busy_connections = 0;
    int inactive_connections = 0;

    // Validate integrity of populated structures and handle errors
    if (!nfaapi_crc_indications || !offset_values || !keys || !measurements || !sensor_data_array || !tcp_connections) {
        printf("Memory allocation failed.\n");
        return;
