    // ...

    // Filter and aggregate sensor data based on specific criteria
    // ...
}

void add_connection(int connection_id) {
    // Add new TCP Connection to the dynamic array
    if (active_connections < MAX_CONNECTIONS) {
        tcp_connections[active_connections].id = connection_id;
        active_connections++;
    } else {
        printf("Maximum number of connections reached.\n");
        return;
    }
}

void remove_connection(int connection_id) {
    // Find and remove TCP Connection by ID from the dynamic array
    for (int i = 0; i < active_connections; i++) {
        if (tcp_connections[i].id == connection_id) {
            // Mark as inactive
            inactive_connections++;
            break;
        }
    }
}

TCP_Connection* get_connection(int connection_id) {
    // Retrieve TCP Connection details by ID from the dynamic array
    for (int i = 0; i < active_connections; i++) {
        if (tcp_connections[i].id == connection_id) {
            return &tcp_connections[i];
        }
    }
    return NULL;
}

void clean_up_inactive_connections() {
    // Periodically remove inactive connections based on inactivity timeout
    for (int i = 0; i < inactive_connections; i++) {
        // Mark as removed
        inactive_connections--;
    }
}
