crypto_info* list = NULL;

int add_crypto(char* name, void (*function)(void*, int), void* params) {
    crypto_info* new_node = (crypto_info*)malloc(sizeof(crypto_info));
    new_node->name = name;
    new_node->function = function;
    new_node->params = params;
    if (!list) {
        list = new_node;
    } else {
        crypto_info* current = list;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
}

int print_cryptos() {
    crypto_info* current = list;
    while (current) {
        printf("%s\n", current->name);
        current = current->next;
    }
}

