#include <vector>
#include <memory>
#include <algorithm>

bool insertAfterOrAppend(std::vector<std::unique_ptr<CustomObject>>& vec, const CustomObject* obj1, const CustomObject* obj2) {
    auto it = std::find_if(vec.begin(), vec.end(), [obj1](const std::unique_ptr<CustomObject>& ptr) { return *ptr.get() == *obj1; });
    if (it != vec.end()) {
        // Insert after the first occurrence of obj1
        vec.insert(it + 1, std::make_unique<CustomObject>(*obj2));
        return true;
    } else {
        // Append to the end if obj1 is not found
        vec.emplace_back(std::make_unique<CustomObject>(*obj2));
        return false;
    }
}

void consolidateSimilarObjects(std::vector<std::unique_ptr<CustomObject>>& vec) {
    std::unordered_map<CustomObject*, size_t> occurrences;
    for (const auto& ptr : vec) {
        if (occurrences.find(ptr.get()) == occurrences.end()) {
            occurrences[ptr.get()] = 1;
        } else {
            occurrences[ptr.get()]++;
        }
    }

    // Group instances with identical data fields into a single instance
    std::vector<std::unique_ptr<CustomObject>> consolidatedVec;
    for (const auto& pair : occurrences) {
        if (pair.second == 1) {
            consolidatedVec.push_back(std::make_unique<CustomObject>(*pair.first));
        } else {
            size_t idx = 0;
            bool found = false;
            for (const auto& ptr : vec) {
                if (*ptr.get() == *pair.first && !found) {
                    found = true;
                    idx = vec.indexOf(ptr);
                }
            }
            // Replace all occurrences with the consolidated instance
            while (found) {
                vec.erase(vec.begin() + idx);
                found = false;
                for (const auto& ptr : vec) {
                    if (*ptr.get() == *pair.first && !found) {
                        found = true;
                        idx = vec.indexOf(ptr);
                    }
                }
            }
        }
    }

    // Swap the consolidated vector with the original one
    std::swap(vec, consolidatedVec);

    return;
}
