using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;

public class AsyncHttpClient
{
    private readonly HttpClient _httpClient;
    private readonly CancellationTokenSource _cts;

    public AsyncHttpClient(HttpClient httpClient, CancellationTokenSource cts)
    {
        _httpClient = httpClient;
        _cts = cts;
    }

    public async Task<List<Task>> ProcessAsyncRequests(List<HttpRequestMessage> requests, int connectionTimeout, int maxConcurrencyLevel, RetryPolicy retryPolicy, LoggingLevels loggingLevel)
    {
        var results = new List<Task>();

        foreach (var request in requests)
        {
            // Create a cancellation token
            var token = CancellationToken.None;

            // Add the task to the list of results
            results.Add(ProcessRequestAsync(request, connectionTimeout, maxConcurrencyLevel, retryPolicy, loggingLevel, token));
        }

        return results;
    }

    private async Task ProcessRequestAsync(HttpRequestMessage request, int connectionTimeout, int maxConcurrencyLevel, RetryPolicy retryPolicy, LoggingLevels loggingLevel, CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                using (var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead, token))
                {
                    // Handle request success or failure
                    if (response.IsSuccessStatusCode)
                    {
                        Console.WriteLine($"Request {request.RequestUri} completed successfully");
                    }
                    else
                    {
                        Console.WriteLine($"Request {request.RequestUri} failed with status code {response.StatusCode}");
                    }

                    // Log the request result
                    LogResult(request, response.IsSuccessStatusCode, loggingLevel);

                    return;
                }
            }
            catch (OperationCanceledException)
            {
                Console.WriteLine($"Request {request.RequestUri} canceled");
                return;
            }
            catch (HttpRequestException ex)
            {
                if (retryPolicy.ShouldRetry(ex))
                {
                    // Retry the request
                    await Task.Delay(500); // Simulate a delay for demonstration purposes
                    await ProcessRequestAsync(request, connectionTimeout, maxConcurrencyLevel, retryPolicy, loggingLevel, token);
                }
                else
                {
                    Console.WriteLine($"Request {request.RequestUri} failed with exception: {ex.Message}");
                    LogResult(request, false, loggingLevel);

                    return;
                }
            }
        }

        // Cancel the request if it's not completed
        _cts.Cancel();
    }

    private void LogResult(HttpRequestMessage request, bool isSuccess, LoggingLevels loggingLevel)
    {
        switch (loggingLevel)
        {
            case LoggingLevels.Debug:
                Console.WriteLine($"DEBUG: Request {request.RequestUri} {(isSuccess ? "succeeded" : "failed")}");
                break;
            case LoggingLevels.Info:
                Console.WriteLine($"INFO: Request {request.RequestUri} {(isSuccess ? "succeeded" : "failed")}");
                break;
            case LoggingLevels.Warn:
                Console.WriteLine($"WARN: Request {request.RequestUri} {(isSuccess ? "succeeded" : "failed")}");
                break;
        }
    }

    public enum LoggingLevels
    {
        Debug,
        Info,
        Warn
    }

