sessions = {}

def update_session(session_token):
    if session_token not in sessions:
        return {"error": "Session not found"}, 404

    updated_attributes = request.get_json()
    sessions[session_token] = {**sessions[session_token], **updated_attributes}

    if 'valid_until' in updated_attributes:
        valid_until = datetime.datetime.strptime(updated_attributes['valid_until'], '%Y-%m-%dT%H:%M:%S')
        if valid_until < datetime.datetime.now():
            return {"error": "Session has expired"}, 401

    return jsonify(sessions[session_token]), 200

def log_out(session_token):
    if session_token not in sessions:
        return {"error": "Session not found"}, 404

    del sessions[session_token]

    return jsonify({"message": "Session terminated"}), 200
