using System;
using System.Xml;
using System.Xml.XPath;

public class XmlProcessor
{
    public List<XElement> GetPrioritizedElements(string xmlDocument, string elementName)
    {
        XmlDocument xmlDoc = new XmlDocument();
        xmlDoc.LoadXml(xmlDocument);

        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathExpression expression = navigator.Compile($"//{elementName}");
        XPathNodeIterator nodes = expression.Evaluate();

        List<XElement> prioritizedElements = new List<XElement>();
        foreach (XPathNode node in nodes)
        {
            if (!node.NodeType.HasFlag(XmlNodeType.Element)) continue;

            string metadata = GetMetadataFromApi(node.Name);
            XElement element = new XElement((string)node.Name, metadata);
            prioritizedElements.Add(element);
        }

        return prioritizedElements;
    }

    private string GetMetadataFromApi(string nodeName)
    {
        // implement API call logic here
        // for demonstration purposes, assume it takes 100ms to fetch metadata
        System.Threading.Thread.Sleep(100);
        return $"Metadata fetched for {nodeName} in 0.1s";
    }
}

public class CacheManager
{
    private Dictionary<string, string> cache = new Dictionary<string, string>();

    public string GetCachedMetadata(string nodeName)
    {
        if (!cache.ContainsKey(nodeName))
            return GetMetadataFromApi(nodeName);

        return cache[nodeName];
    }

    public void UpdateCache(string nodeName, string metadata)
    {
        cache.Add(nodeName, metadata);
    }
}

public class BatchProcessor
{
    private CacheManager cache;
    private int batchSize;

    public BatchProcessor(int batchSize)
    {
        this.batchSize = batchSize;
        this.cache = new CacheManager();
    }

    public List<XElement>[] ProcessBatch(List<string> xmlDocuments, string elementName)
    {
        List<List<XElement>> results = new List<List<XElement>>();

        for (int i = 0; i < xmlDocuments.Count; i += batchSize)
        {
            int start = i;
            int end = Math.Min(start + batchSize - 1, xmlDocuments.Count - 1);

            List<string> batchXmlDocs = xmlDocuments.GetRange(start, end - start + 1);
            List<XElement>[] batchResults = new List<XElement>[batchXmlDocs.Count];

            for (int j = 0; j < batchXmlDocs.Count; j++)
            {
                string xmlDocument = batchXmlDocs[j];
                List<XElement> prioritizedElements = GetPrioritizedElements(xmlDocument, elementName);

                batchResults[j] = prioritizedElements;
            }

            results.Add(batchResults);
        }

        return results.ToArray();
    }
}
