struct linked_list_node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct linked_list_node *next;
};

typedef struct linked_list_node LinkedListNode;

LinkedListNode* create_linked_list(int num_elements);
void add_element_to_list(LinkedListNode** head_ref, int rnti, uint8_t crc_flag);

NFAPI_RSLT_STATUS create_crc_indication_pdu_list(LinkedListNode** list_head, int num_elements) {
    if (*list_head != NULL) {
        free_linked_list(*list_head);
        *list_head = NULL;
    }

    *list_head = create_linked_list(num_elements);

    return NFAPI_RSLT_SUCCESS;
}

NFAPI_RSLT_STATUS add_crc_indication_pdu_to_list(LinkedListNode** list_head, int rnti, uint8_t crc_flag) {
    if (add_element_to_list(list_head, rnti, crc_flag) == NULL) {
        return NFAPI_RSLT_FAILURE;
    }

    return NFAPI_RSLT_SUCCESS;
}

void free_linked_list(LinkedListNode* list) {
    LinkedListNode* current = list;
    LinkedListNode* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

LinkedListNode* create_linked_list(int num_elements) {
    LinkedListNode* head = NULL;
    int i;

    for (i = 0; i < num_elements; i++) {
        add_element_to_list(&head, rand(), (uint8_t)(rand() & 1));
    }

    return head;
}

void add_element_to_list(LinkedListNode** head_ref, int rnti, uint8_t crc_flag) {
    LinkedListNode* new_node = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    if (new_node == NULL) {
        // Log an error message
        printf("Memory allocation failed\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        free(new_node);
        // Log an error message
        printf("Memory allocation failed\n");
        return NFAPI_RSLT_FAILURE;
    }

    RX_UE_INFORMATION_TAG rx_ue_info_tag = {0};
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag = {0};

    data->rx_ue_info_tag = rx_ue_info_tag;
    data->rnti = rnti;
    data->crc_indication_rel8_tag = crc_indication_rel8_tag;
    data->crcflag = crc_flag;

    new_node->data = data;
    new_node->next = *head_ref;
    *head_ref = new_node;

    return;
}
