NFAPI_RX_FRAME_PDU_T* initializeNfapiFrames(size_t numFrames) {
    NFAPI_RX_FRAME_PDU_T* frames = NULL;
    size_t totalBytes = sizeof(NFAPI_RX_FRAME_PDU_T) * numFrames;

    // Allocate memory for the array of frame structures
    if (!(frames = (NFAPI_RX_FRAME_PDU_T*)malloc(totalBytes))) {
        return NULL; // Handle allocation failure
    }

    // Initialize each frame structure
    for (size_t i = 0; i < numFrames; i++) {
        frames[i].tag = malloc(sizeof(NFAPI_RX_FRAME_TAG)); // Dynamically allocate buffer for the received data
        if (!frames[i].tag) {
            free(frames);
            return NULL; // Handle allocation failure
        }

        frames[i].preamble_pdu = malloc(sizeof(NFAPI_RX_PREAMBLE_PDU_T));
        if (!frames[i].preamble_pdu) {
            free(frames[i].tag);
            free(frames);
            return NULL; // Handle allocation failure
        }

        frames[i].longTransmission = false;
    }

    return frames;
}
