import java.io.*;
import java.security.MessageDigest;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.ReentrantLock;

public class StateLoader {
    private static final int CACHE_SIZE = 1000; // Configurable cache size
    private static final String[][] APPROVED_PATHS = {{"path1"}, {"path2"}};
    private static ConcurrentHashMap<String, MoSTState> cache;
    private static ReentrantLock lock = new ReentrantLock();

    public static MoSTState loadState(String filePath) {
        MoSTState state = null;
        try {
            File file = new File(filePath);
            if (!validateDirectory(file.getParent())) {
                return null;
            }
            FileInputStream fis = new FileInputStream(file);
            ObjectInputStream ois = new ObjectInputStream(fis);
            state = (MoSTState) ois.readObject();
            ois.close();
            fis.close();

            String checksum = computeChecksum(state);
            long fileChecksum = getFileChecksum(filePath);

            if (state instanceof MoSTState && fileChecksum == Long.parseLong(checksum)) {
                return state;
            } else {
                logInfo("State object validation failed");
                return null;
            }
        } catch (IOException e) {
            // Handle I/O exceptions
            logError("I/O exception occurred while loading state", e);
        } finally {
            if (state != null) {
                try {
                    FileOutputStream fos = new FileOutputStream(filePath);
                    ObjectOutputStream oos = new ObjectOutputStream(fos);
                    oos.writeObject(state);
                    oos.close();
                    fos.close();
                } catch (IOException ex) {
                    // Handle I/O exceptions
                    logError("I/O exception occurred while writing state", ex);
                }
            }
        }

        if (cache == null || cache.size() > CACHE_SIZE) {
            evictCache();
        }

        return getFromCache(filePath, state);
    }

    private static boolean validateDirectory(String directory) {
        for (String[] path : APPROVED_PATHS) {
            if (directory.startsWith(path[0])) {
                return true;
            }
        }
        return false;
    }

    private static String computeChecksum(MoSTState state) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] bytes = state.toString().getBytes();
            byte[] checksumBytes = md.digest(bytes);
            StringBuilder sb = new StringBuilder();
            for (byte b : checksumBytes) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            // Handle exceptions
            logError("Error computing checksum", e);
        }
        return null;
    }

    private static long getFileChecksum(String filePath) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            FileInputStream fis = new FileInputStream(filePath);
            byte[] bytes = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(bytes)) != -1) {
                md.update(bytes, 0, bytesRead);
            }
            fis.close();
            return Long.parseLong(byteArrayToHexString(md.digest()));
        } catch (Exception e) {
            // Handle exceptions
            logError("Error getting file checksum", e);
        }
        return 0;
    }

    private static String byteArrayToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void logInfo(String message) {
        // Implement logging framework
        System.out.println(message);
    }

    private static void logError(String message, Exception e) {
        // Implement logging framework
        System.out.println(message);
        e.printStackTrace();
    }

    private static MoSTState getFromCache(String filePath, MoSTState state) {
        if (cache == null) {
            cache = new ConcurrentHashMap<>();
        }
        lock.lock();
        try {
            if (cache.containsKey(filePath)) {
                return cache.get(filePath);
            } else {
                cache.put(filePath, state);
                return state;
            }
        } finally {
            lock.unlock();
        }
    }

    private static void evictCache() {
        // Implement eviction strategy
        cache.clear();
    }
}
```']

