const fs = require('fs');
const path = require('path');
const os = require('os');
const { performance } = require('perf_hooks');

let config = {
  maxConcurrency: 5,
  maxBytes: 1048576, // 1 MB
  retryAttempts: 3,
  backoffDelay: 1000, // 1 second
  logLevel: 'info',
};

class FileReader {
  constructor(directory, filters) {
    this.directory = directory;
    this.filters = filters;
    this.concurrencyQueue = [];
    this.currentConcurrency = 0;
    this.totalBytesRead = 0;
    this.retries = 0;
    this.logMessages = [];
  }

  async readFiles() {
    const files = await this.getFiles();
    for (const file of files) {
      if (this.shouldFilterFile(file)) continue;
      await this.readFile(file);
    }
    console.log(this.logMessages);
  }

  shouldFilterFile(file) {
    return !this.filters.some((filter) => path.extname(file.name).toLowerCase().includes(filter));
  }

  async getFiles() {
    const files = [];
    await fs.readdir(this.directory, (err, data) => {
      if (err) throw err;
      for (const file of data) {
        const filePath = path.join(this.directory, file);
        try {
          const stats = await fs.stat(filePath);
          if (stats.isFile()) files.push({ name: file, size: stats.size });
        } catch (err) {
          console.error(`Error reading file ${file}:`, err);
        }
      }
    });
    return files;
  }

  async readFile(file) {
    const { name, size } = file;
    if (this.totalBytesRead + size > config.maxBytes) return;

    this.concurrencyQueue.push({
      name,
      size,
      read: async () => {
        try {
          const data = await fs.readFileSync(path.join(this.directory, name));
          this.logMessages.push(`Read ${name} (${size} bytes)`);
          this.totalBytesRead += size;
        } catch (err) {
          if (!this.isRetryAllowed(err)) throw err;
          await this.readFile(file);
          return;
        }
      },
    });

    while (this.currentConcurrency >= config.maxConcurrency) {
      await new Promise((resolve) => setTimeout(resolve, 10));
    }

    const currentFile = this.concurrencyQueue.shift();
    this.currentConcurrency++;
    try {
      await currentFile.read();
    } finally {
      this.currentConcurrency--;
      if (this.concurrencyQueue.length > 0) {
        setTimeout(async () => {
          await this.concurrencyQueue[0].read();
        }, config.backoffDelay);
      }
    }
  }

  isRetryAllowed(err) {
    return err.code !== 'EIO' && err.code !== 'EMFILE';
  }

  adjustConcurrency() {
    const cpuUsage = os.cpus()[0].cpu;
    if (cpuUsage > 0.7) {
      config.maxConcurrency -= Math.floor(cpuUsage * 2);
      console.log(`Adjusted concurrency to ${config.maxConcurrency} due to high CPU usage`);
    } else if (cpuUsage < 0.3) {
      config.maxConcurrency += Math.floor((1 - cpuUsage) * 2);
      console.log(`Adjusted concurrency to ${config.maxConcurrency} due to low CPU usage`);
    }
    if (this.totalBytesRead > 5242880) { // 5 MB
      config.maxConcurrency -= Math.floor((this.totalBytesRead / 1048576) * 2);
      console.log(`Adjusted concurrency to ${config.maxConcurrency} due to high memory usage`);
    }
  }

  log(message, level = 'info') {
    if (level === config.logLevel || config.logLevel === 'debug') {
      console.log(message);
    }
  }

  async run() {
    while (this.retries < config.retryAttempts) {
      try {
        await this.readFiles();
        break;
      } catch (err) {
        if (!this.isRetryAllowed(err)) throw err;
        await new Promise((resolve) => setTimeout(resolve, config.backoffDelay));
        this.retries++;
      }
    }
  }
}

const reader = new FileReader('/path/to/directory', ['txt', 'json']);
reader.run();
