function generateSidebar(widgets) {
  let html = '<div id="sidebar">';
  widgets.forEach((widget, index) => {
    const widgetId = `widget-${index}`;
    const config = widget.config ? ` data-config="${JSON.stringify(widget.config)}"` : '';
    html += `<div id="${widgetId}" ${config}>${widget.render()}</div>`;
  });
  return `${html}</div>`;
}
